class _BuyBatchFailureContext:
    """Mutable diagnostics retained across the public buy-batch boundary."""

    def __init__(self) -> None:
        self.rows: list[dict] = []
        self.current_row: dict | None = None


def _alpaca_buy_result_frame(rows: list[dict]) -> pd.DataFrame:
    result = pd.DataFrame(rows)
    if result.empty:
        return pd.DataFrame(columns=_ALPACA_BUY_RESULT_COLUMNS)
    if "_signal_index" in result:
        result = result.sort_values("_signal_index", kind="stable")
    return result.reindex(columns=_ALPACA_BUY_RESULT_COLUMNS).reset_index(drop=True)


def _require_clean_broker_side_effect_connection(
    conn: sqlite3.Connection,
    *,
    operation: str,
) -> None:
    """Keep durable broker fences from committing unrelated caller work."""
    if conn.in_transaction:
        raise ValueError(f"{operation} requires a SQLite connection with no active transaction")


def _deterministic_broker_observation_suffix(status: str | None) -> str:
    if status is None:
        return ""
    normalized_status = status.lower()
    if normalized_status not in _ALPACA_ORDER_STATUSES:
        normalized_status = "invalid"
    return f"; observed deterministic broker status={normalized_status}"


def _managed_buy_lineage_is_durably_adopted(
    *,
    conn: sqlite3.Connection,
    position_id: int,
    client_order_id: str,
    expected_symbol: str,
    expected_alpaca_asset_id: str | None,
    expected_qty: float,
    expected_limit_price: float,
    replacement_chain: list[dict],
) -> bool:
    """Prove that concurrent state already retained the exact buy exposure."""
    try:
        positions = load_alpaca_managed_positions(conn)
    except ValueError:
        # A corrupt durable intent cannot prove that a broker side effect was
        # adopted, even when the surrounding order lineage looks plausible.
        return False
    current_match = positions.loc[positions["id"].eq(position_id)]
    if current_match.empty:
        return False
    current = current_match.iloc[0].to_dict()
    leaf = replacement_chain[-1]
    persisted_status = str(current.get("buy_status") or "").lower()
    if (
        persisted_status
        in {
            "submission_pending",
            "submission_unknown",
            "pending_cancel",
            "identity_mismatch",
            "incomplete_fill_metadata",
            "fill_quantity_regression",
        }
        or persisted_status not in _ALPACA_ORDER_STATUSES
    ):
        return False
    if (
        _optional_str(current.get("closed_at")) is not None
        or _optional_str(current.get("buy_client_order_id")) != client_order_id
        or _optional_str(current.get("buy_alpaca_order_id")) != _optional_str(leaf.get("id"))
        or str(current.get("symbol") or "").upper() != expected_symbol.upper()
    ):
        return False
    if expected_alpaca_asset_id is not None and (
        _optional_str(current.get("alpaca_asset_id")) != expected_alpaca_asset_id
    ):
        return False
    persisted_order_qty = _canonical_whole_share_qty(current.get("buy_order_qty"))
    expected_order_qty = _canonical_whole_share_qty(expected_qty)
    if (
        persisted_order_qty is None
        or expected_order_qty is None
        or persisted_order_qty != expected_order_qty
        or not _limit_price_matches_frozen_intent(current.get("buy_order_limit_price"), expected_limit_price)
    ):
        return False

    observed_filled_qty, observed_avg_price, metadata_is_valid = _replacement_chain_fill_metadata(replacement_chain)
    if not metadata_is_valid:
        return False
    persisted_filled_qty = _optional_float(current.get("filled_qty")) or 0.0
    persisted_avg_price = _optional_positive_float(current.get("filled_avg_price"))
    fill_residual_mark_price = _managed_sell_residual_mark_price(
        expected_limit_price,
        current.get("buy_order_limit_price"),
        persisted_avg_price,
        observed_avg_price,
        current.get("target_sell_price"),
    )
    persisted_covers_observed_fill = bool(
        persisted_filled_qty >= observed_filled_qty
        or _managed_sell_quantities_match(
            persisted_filled_qty,
            observed_filled_qty,
            expected_qty,
            mark_price=fill_residual_mark_price,
        )
    )
    persisted_fill_is_within_intent = bool(
        persisted_filled_qty <= expected_qty
        or _managed_sell_quantities_match(
            persisted_filled_qty,
            expected_qty,
            observed_filled_qty,
            mark_price=fill_residual_mark_price,
        )
    )
    if (
        not persisted_covers_observed_fill
        or not persisted_fill_is_within_intent
        or (persisted_status == "filled" and persisted_filled_qty <= 0.0)
        or (persisted_status == "partially_filled" and persisted_filled_qty <= 0.0)
    ):
        return False
    if observed_filled_qty > 0.0:
        persisted_target = _optional_positive_float(current.get("target_sell_price"))
        profit_target_multiple = _optional_positive_float(current.get("profit_target_multiple"))
        if persisted_avg_price is None or persisted_target is None or profit_target_multiple is None:
            return False
        if (
            _managed_sell_quantities_match(
                persisted_filled_qty,
                observed_filled_qty,
                expected_qty,
                mark_price=fill_residual_mark_price,
            )
            and observed_avg_price is not None
            and abs(persisted_avg_price - observed_avg_price) > _MANAGED_PRICE_TOLERANCE
        ):
            return False
        if not _limit_price_matches_frozen_intent(
            persisted_target,
            _target_sell_price(persisted_avg_price, profit_target_multiple),
        ):
            return False
    return True


def _quarantine_managed_buy_side_effect_from_current_snapshot(
    *,
    conn: sqlite3.Connection,
    position_id: int,
    buy_status: str,
    observed_buy_alpaca_order_id: str | None,
    observed_buy_submitted_at: str | None,
    notes: str,
    observed_buy_cancellation_alpaca_order_ids: list[str] | None = None,
    required_state_revision: int | None = None,
) -> bool:
    """Persist a broker-side-effect diagnostic across concurrent lifecycle changes."""
    safe_observed_order_id = _optional_alpaca_broker_identifier(observed_buy_alpaca_order_id)
    safe_observed_cancellation_ids = {
        order_id
        for value in observed_buy_cancellation_alpaca_order_ids or []
        if (order_id := _optional_alpaca_broker_identifier(value)) is not None
    }
    for _ in range(1 if required_state_revision is not None else 3):
        row = conn.execute(
            """
            SELECT state_revision, buy_submission_attempt_count, buy_status,
                   buy_alpaca_order_id, filled_qty, filled_avg_price,
                   target_sell_price, sell_client_order_id, closed_at,
                   buy_cancellation_alpaca_order_ids
            FROM alpaca_managed_positions
            WHERE id = ?
            """,
            (position_id,),
        ).fetchone()
        if row is None:
            break
        (
            current_state_revision,
            current_attempt_count,
            current_buy_status,
            current_buy_alpaca_order_id,
            current_filled_qty,
            current_filled_avg_price,
            current_target_sell_price,
            current_sell_client_order_id,
            current_closed_at,
            current_cancellation_ids,
        ) = row
        if required_state_revision is not None and int(current_state_revision) != required_state_revision:
            break
        current_attempt_count = _optional_int(current_attempt_count)
        if current_attempt_count is None:
            break
        current_cancellation_ids_json = _optional_str(current_cancellation_ids)
        cancellation_id_set = set(_buy_cancellation_order_ids(current_cancellation_ids_json))
        if observed_buy_cancellation_alpaca_order_ids is not None:
            cancellation_id_set.update(safe_observed_cancellation_ids)
            for order_id in (
                _optional_alpaca_broker_identifier(current_buy_alpaca_order_id),
                safe_observed_order_id,
            ):
                if order_id is not None:
                    cancellation_id_set.add(order_id)
        cancellation_ids = sorted(cancellation_id_set)
        if quarantine_alpaca_managed_buy_side_effect_if_current(
            conn,
            position_id,
            expected_state_revision=int(current_state_revision),
            expected_buy_submission_attempt_count=current_attempt_count,
            expected_buy_status=str(current_buy_status or "submission_unknown"),
            expected_buy_alpaca_order_id=_optional_str(current_buy_alpaca_order_id),
            expected_filled_qty=current_filled_qty,
            expected_filled_avg_price=current_filled_avg_price,
            expected_target_sell_price=current_target_sell_price,
            expected_sell_client_order_id=_optional_str(current_sell_client_order_id),
            expected_closed_at=_optional_str(current_closed_at),
            buy_status=buy_status,
            observed_buy_alpaca_order_id=safe_observed_order_id,
            observed_buy_submitted_at=observed_buy_submitted_at,
            notes=notes,
            expected_buy_cancellation_alpaca_order_ids=current_cancellation_ids_json,
            buy_cancellation_alpaca_order_ids=(cancellation_ids if cancellation_ids else None),
        ):
            return True
    return False


def _append_accepted_buy_processing_failure(
    *,
    conn: sqlite3.Connection | None,
    client: AlpacaClient,
    rows: list[dict],
    workflow: str | None,
    signal_index: int,
    symbol: str,
    signal_date: str,
    client_order_id: str,
    notional: float,
    qty: int,
    limit_price: float,
    managed_position_id: int | None,
    managed_submission_attempt_count: int | None,
    accepted_response_payload: dict | None,
    expected_alpaca_asset_id: str | None,
    accepted_replacement_chain: list[dict] | None = None,
    additional_accepted_payloads: list[dict] | None = None,
    detail: str,
) -> str:
    """Quarantine any buy whose 2xx response cannot be safely processed."""
    accepted_payloads = [
        payload for payload in [accepted_response_payload, *(additional_accepted_payloads or [])] if payload is not None
    ]
    accepted_order_ids = {
        order_id
        for payload in accepted_payloads
        if (order_id := _optional_alpaca_broker_identifier(payload.get("id"))) is not None
    }
    accepted_order_id = next(iter(accepted_order_ids)) if len(accepted_order_ids) == 1 else None
    accepted_submitted_at = (
        _optional_alpaca_datetime_str(accepted_response_payload.get("submitted_at"))
        if accepted_response_payload is not None
        else None
    )
    attributed_orders: list[dict] = []
    unresolved_successor_ids: list[str] = []
    for payload_index, payload in enumerate(accepted_payloads):
        safely_attributed_lineage = _safely_attributed_buy_order_lineage(
            payload,
            expected_client_order_id=client_order_id,
            expected_symbol=symbol,
            expected_alpaca_asset_id=expected_alpaca_asset_id,
            replacement_chain=(
                accepted_replacement_chain if payload_index == 0 and payload is accepted_response_payload else None
            ),
        )
        if safely_attributed_lineage:
            attributed_orders.extend(safely_attributed_lineage)
        successor_id = _optional_alpaca_broker_identifier(payload.get("replaced_by"))
        resolved_ids = {_optional_alpaca_broker_identifier(node.get("id")) for node in safely_attributed_lineage or []}
        if successor_id is not None and successor_id not in resolved_ids:
            unresolved_successor_ids.append(successor_id)
    cancellation_required = bool(
        _attributed_lineage_requires_cancellation(attributed_orders) or unresolved_successor_ids
    )
    cancellation_order_ids = sorted(
        accepted_order_ids
        | {
            order_id
            for order in attributed_orders
            if (order_id := _optional_alpaca_broker_identifier(order.get("id"))) is not None
        }
        | set(unresolved_successor_ids)
    )
    quarantine_status = "pending_cancel" if cancellation_required else "submission_unknown"
    ownership_message = (
        "broker cancellation awaits durable local quarantine ownership"
        if cancellation_required
        else "broker cancellation was not requested because no safely attributed active order was found"
    )
    accepted_message = (
        "Alpaca accepted the buy, but its response could not be safely processed; "
        f"the possible broker exposure is quarantined for reconciliation: {detail}; {ownership_message}"
    )
    if unresolved_successor_ids:
        accepted_message += (
            "; replacement successor IDs could not be resolved, so authoritative lineage follow-up is required: "
            + ", ".join(sorted(set(unresolved_successor_ids)))
        )
    status_updated = True
    if managed_position_id is not None:
        assert conn is not None
        assert managed_submission_attempt_count is not None
        status_updated = _quarantine_managed_buy_side_effect_from_current_snapshot(
            conn=conn,
            position_id=managed_position_id,
            buy_status=quarantine_status,
            observed_buy_alpaca_order_id=accepted_order_id,
            observed_buy_submitted_at=accepted_submitted_at,
            notes=_alpaca_durable_diagnostic_note(
                accepted_message,
                cfg=client.cfg,
                client=client,
            ),
            observed_buy_cancellation_alpaca_order_ids=cancellation_order_ids,
        )
    cancellation_message = ownership_message
    if status_updated and attributed_orders and cancellation_required:
        _pending, cancellation_message = _request_safely_attributed_lineage_cancellations(
            client,
            attributed_orders,
        )
        if unresolved_successor_ids:
            cancellation_message += "; unresolved replacement successors still require follow-up"
    elif not status_updated and cancellation_required:
        cancellation_message = (
            "broker cancellation was not requested because durable local quarantine ownership changed"
        )
    accepted_message = (
        "Alpaca accepted the buy, but its response could not be safely processed; "
        f"the possible broker exposure is quarantined for reconciliation: {detail}; {cancellation_message}"
    )
    if unresolved_successor_ids:
        accepted_message += "; unresolved replacement successors require authoritative follow-up: " + ", ".join(
            sorted(set(unresolved_successor_ids))
        )
    rows.append(
        {
            "Workflow": workflow,
            "Asset": symbol,
            "Date": signal_date,
            "Client Order ID": client_order_id,
            "Notional": notional,
            "Qty": qty,
            "Limit Price": limit_price,
            "Status": quarantine_status,
            "Alpaca Order ID": accepted_order_id,
            "Message": (
                accepted_message
                if status_updated
                else f"{accepted_message}; durable local quarantine persistence also requires retry"
            ),
            "_signal_index": signal_index,
        }
    )
    return accepted_message


class SellFillMetadataError(ValueError):
    def __init__(self, observed_qty: float) -> None:
        super().__init__("filled Alpaca sell order has invalid fill metadata")
        self.observed_qty = observed_qty


class SellOrderIdentityError(ValueError):
    pass


class BuyOrderIdentityError(ValueError):
    pass


class _BuySubmissionWindowElapsedError(RuntimeError):
    """The broker POST was withheld because its pre-open deadline elapsed."""


class _BuySubmissionNotDispatchedError(OSError):
    """A local mutation fence failed before the broker request could begin."""


_ALPACA_REQUEST_WRITE_DEADLINE_MONOTONIC: ContextVar[float | None] = ContextVar(
    "alpaca_request_write_deadline_monotonic",
    default=None,
)
_ALPACA_PUBLIC_DURABLE_DIAGNOSTIC_CFG: ContextVar[AlpacaOrderConfig | None] = ContextVar(
    "alpaca_public_durable_diagnostic_cfg",
    default=None,
)
_ALPACA_PUBLIC_DURABLE_SENSITIVE_VALUES: ContextVar[tuple[str, ...] | None] = ContextVar(
    "alpaca_public_durable_sensitive_values",
    default=None,
)


class _AlpacaSensitiveValueAccumulator:
    """Share exact credential snapshots across copied workflow contexts."""

    def __init__(self, values: Collection[str] = ()) -> None:
        self._lock = threading.Lock()
        self._values: set[str] = set()
        self.add(values)

    def add(self, values: Collection[str]) -> None:
        normalized = {value.strip(" ") for value in values if type(value) is str and value.strip(" ")}
        if not normalized:
            return
        with self._lock:
            self._values.update(normalized)

    def snapshot(self) -> tuple[str, ...]:
        with self._lock:
            values = tuple(self._values)
        return tuple(sorted(values, key=lambda value: (-len(value), value)))


_ALPACA_PUBLIC_DURABLE_SENSITIVE_VALUE_ACCUMULATOR: ContextVar[_AlpacaSensitiveValueAccumulator | None] = ContextVar(
    "alpaca_public_durable_sensitive_value_accumulator",
    default=None,
)


def _monotonic_now() -> float:
    return time.monotonic()


def _remaining_alpaca_request_write_seconds() -> float | None:
    deadline = _ALPACA_REQUEST_WRITE_DEADLINE_MONOTONIC.get()
    if deadline is None:
        return None
    remaining = deadline - _monotonic_now()
    if not math.isfinite(remaining) or remaining <= 0:
        raise _BuySubmissionWindowElapsedError(
            "market submission window elapsed before the broker POST could be written"
        )
    return remaining


@contextmanager
def _alpaca_request_write_deadline(deadline_monotonic: float | None):
    if deadline_monotonic is not None and not math.isfinite(deadline_monotonic):
        raise ValueError("Alpaca request-write deadline must be finite")
    token = _ALPACA_REQUEST_WRITE_DEADLINE_MONOTONIC.set(deadline_monotonic)
    try:
        yield
    finally:
        _ALPACA_REQUEST_WRITE_DEADLINE_MONOTONIC.reset(token)


def _alpaca_request_exception_from_process(name: str, message: str) -> BaseException:
    exception_type = {
        "AlpacaRequestWriteDeadlineElapsed": _BuySubmissionWindowElapsedError,
        "HttpRequestDeadlineElapsed": requests.exceptions.Timeout,
        "ConnectTimeout": requests.exceptions.ConnectTimeout,
        "ConnectionError": requests.exceptions.ConnectionError,
        "ContentDecodingError": requests.exceptions.ContentDecodingError,
        "InvalidHeader": requests.exceptions.InvalidHeader,
        "InvalidURL": requests.exceptions.InvalidURL,
        "ReadTimeout": requests.exceptions.ReadTimeout,
        "SSLError": requests.exceptions.SSLError,
        "Timeout": requests.exceptions.Timeout,
        "TooManyRedirects": requests.exceptions.TooManyRedirects,
        "TypeError": TypeError,
        "ValueError": ValueError,
    }.get(name, requests.exceptions.RequestException)
    return exception_type(message)


def _validated_alpaca_request_timeout_seconds(value: object) -> int:
    if (
        type(value) is not int
        or not _ALPACA_REQUEST_TIMEOUT_MIN_SECONDS <= value <= _ALPACA_REQUEST_TIMEOUT_MAX_SECONDS
    ):
        raise ValueError(
            "Alpaca timeout_seconds must be an integer between "
            f"{_ALPACA_REQUEST_TIMEOUT_MIN_SECONDS} and {_ALPACA_REQUEST_TIMEOUT_MAX_SECONDS}."
        )
    return value


def _alpaca_http_request(
    method: str,
    url: str,
    *,
    cfg: AlpacaOrderConfig,
    _allow_loopback_test_origin: bool = False,
    **request_kwargs: object,
) -> requests.Response:
    """Acquire one complete, bounded Alpaca response under a hard deadline."""
    timeout_seconds = _validated_alpaca_request_timeout_seconds(cfg.timeout_seconds)
    request_callable = {
        "DELETE": requests.delete,
        "GET": requests.get,
        "POST": requests.post,
    }.get(method)
    if request_callable is None:
        raise ValueError("Unsupported Alpaca HTTP method")
    _validate_alpaca_request_target(
        method,
        url,
        allow_loopback_test_origin=_allow_loopback_test_origin,
    )
    if _allow_loopback_test_origin and "proxies" in request_kwargs:
        raise requests.exceptions.InvalidURL("Alpaca loopback test requests must not use a proxy.")
    # Response doubles used throughout the broker tests need not be pickleable.
    # Restrict the compatibility path to explicit unittest.mock callables so
    # ordinary production wrappers cannot silently bypass the process boundary.
    if isinstance(request_callable, Mock):
        return request_callable(url, **request_kwargs)

    deadline = _monotonic_now() + timeout_seconds
    request_write_deadline = _ALPACA_REQUEST_WRITE_DEADLINE_MONOTONIC.get()
    if request_write_deadline is not None:
        _remaining_alpaca_request_write_seconds()

    worker_request_kwargs = dict(request_kwargs)
    raw_headers = worker_request_kwargs.get("headers")
    headers = dict(raw_headers) if isinstance(raw_headers, Mapping) else {}
    headers = {
        name: value
        for name, value in headers.items()
        if not isinstance(name, str) or name.casefold() != "accept-encoding"
    }
    headers["Accept-Encoding"] = "identity"
    worker_request_kwargs["headers"] = headers
    worker_request_kwargs["allow_redirects"] = False
    worker_request_kwargs["stream"] = True
    payload = run_http_request_with_deadline(
        url,
        worker_request_kwargs,
        mode="alpaca",
        method=method,
        request_write_deadline=request_write_deadline,
        allow_loopback_test_origin=_allow_loopback_test_origin,
        deadline=deadline,
        max_body_bytes=_ALPACA_RESPONSE_MAX_BYTES,
        result_max_bytes=_ALPACA_WORKER_RESULT_MAX_BYTES,
        timeout_message="Alpaca response exceeded its overall deadline.",
        connection_error_message="Alpaca request worker exited without a complete response.",
    )
    return response_from_http_worker_payload(
        payload,
        max_body_bytes=_ALPACA_RESPONSE_MAX_BYTES,
        invalid_response_message="Alpaca request worker returned an invalid response.",
        exception_from_process=_alpaca_request_exception_from_process,
    )


def _deadline_bounded_socket_timeout(configured_timeout: object, remaining: float) -> float:
    if configured_timeout is None:
        return remaining
    try:
        timeout = float(configured_timeout)
    except (TypeError, ValueError):
        return remaining
    if not math.isfinite(timeout) or timeout <= 0:
        return remaining
    return min(timeout, remaining)


def _resolve_socket_addresses_before_alpaca_deadline(
    host: str,
    port: int,
    family: socket.AddressFamily,
) -> list[tuple]:
    """Resolve without allowing a blocked resolver to authorize a late POST."""
    remaining = _remaining_alpaca_request_write_seconds()
    if remaining is None:
        return socket.getaddrinfo(host, port, family, socket.SOCK_STREAM)

    result_queue: queue.Queue[tuple[bool, object]] = queue.Queue(maxsize=1)

    def resolve() -> None:
        try:
            result_queue.put(
                (True, socket.getaddrinfo(host, port, family, socket.SOCK_STREAM)),
                block=False,
            )
        except BaseException as exc:
            with suppress(queue.Full):
                result_queue.put((False, exc), block=False)

    threading.Thread(
        target=resolve,
        name="alpaca-order-dns-deadline",
        daemon=True,
    ).start()
    try:
        succeeded, result = result_queue.get(timeout=remaining)
    except queue.Empty as exc:
        raise _BuySubmissionWindowElapsedError(
            "market submission window elapsed during Alpaca order DNS resolution"
        ) from exc
    _remaining_alpaca_request_write_seconds()
    if not succeeded:
        assert isinstance(result, BaseException)
        raise result
    assert isinstance(result, list)
    return result


def _connect_alpaca_socket_before_write_deadline(
    address: tuple[str, int],
    configured_timeout: object,
    *,
    source_address: tuple[str, int] | None,
    socket_options: list[tuple[int, int, int]] | None,
) -> socket.socket:
    """Apply one absolute deadline across DNS and every candidate address."""
    host, port = address
    if host.startswith("["):
        host = host.strip("[]")
    host.encode("idna")
    family = _urllib3_connection.allowed_gai_family()
    addresses = _resolve_socket_addresses_before_alpaca_deadline(host, port, family)
    error: OSError | None = None
    for address_info in addresses:
        remaining = _remaining_alpaca_request_write_seconds()
        if remaining is None:
            raise RuntimeError("Alpaca deadline-aware connection requires an active write deadline")
        af, socktype, proto, _canonname, socket_address = address_info
        candidate: socket.socket | None = None
        try:
            candidate = socket.socket(af, socktype, proto)
            for option in socket_options or ():
                candidate.setsockopt(*option)
            candidate.settimeout(_deadline_bounded_socket_timeout(configured_timeout, remaining))
            if source_address:
                candidate.bind(source_address)
            candidate.connect(socket_address)
            remaining = _remaining_alpaca_request_write_seconds()
            assert remaining is not None
            # TLS setup reuses this socket timeout. Rebase it after TCP connect
            # so connection time cannot be borrowed a second time by the
            # handshake before the absolute request-write cutoff.
            candidate.settimeout(_deadline_bounded_socket_timeout(configured_timeout, remaining))
            return candidate
        except _BuySubmissionWindowElapsedError:
            if candidate is not None:
                candidate.close()
            raise
        except OSError as exc:
            error = exc
            if candidate is not None:
                candidate.close()
    if error is not None:
        raise error
    raise OSError("getaddrinfo returned an empty address list")


class _DeadlineAwareAlpacaHTTPSConnection(_Urllib3HTTPSConnection):
    """Prevent Alpaca order bytes from starting after their absolute cutoff."""

    _alpaca_request_write_started = False
    _alpaca_connection_setup_in_progress = False

    def _new_conn(self) -> socket.socket:
        if _ALPACA_REQUEST_WRITE_DEADLINE_MONOTONIC.get() is None:
            return super()._new_conn()
        try:
            sock = _connect_alpaca_socket_before_write_deadline(
                (self._dns_host, self.port),
                self.timeout,
                source_address=self.source_address,
                socket_options=self.socket_options,
            )
        except _BuySubmissionWindowElapsedError:
            raise
        except socket.gaierror as exc:
            raise NewConnectionError(self, f"Failed to resolve {self.host}: {exc}") from exc
        except TimeoutError as exc:
            raise ConnectTimeoutError(
                self,
                f"Connection to {self.host} timed out. (connect timeout={self.timeout})",
            ) from exc
        except OSError as exc:
            raise NewConnectionError(self, f"Failed to establish a new connection: {exc}") from exc
        sys.audit("http.client.connect", self, self.host, self.port)
        return sock

    def connect(self) -> None:
        self._alpaca_connection_setup_in_progress = True
        try:
            super().connect()
            _remaining_alpaca_request_write_seconds()
        except _BuySubmissionWindowElapsedError:
            if self.sock is not None:
                self.sock.close()
                self.sock = None
            raise
        except Exception as exc:
            deadline = _ALPACA_REQUEST_WRITE_DEADLINE_MONOTONIC.get()
            if deadline is not None and _monotonic_now() >= deadline:
                if self.sock is not None:
                    self.sock.close()
                    self.sock = None
                raise _BuySubmissionWindowElapsedError(
                    "market submission window elapsed during Alpaca order connection or TLS setup"
                ) from exc
            raise
        finally:
            self._alpaca_connection_setup_in_progress = False

    def request(self, *args: object, **kwargs: object) -> None:
        self._alpaca_request_write_started = False
        super().request(*args, **kwargs)

    def send(self, data: object) -> None:
        if _ALPACA_REQUEST_WRITE_DEADLINE_MONOTONIC.get() is None:
            super().send(data)
            return
        try:
            remaining = _remaining_alpaca_request_write_seconds()
        except _BuySubmissionWindowElapsedError:
            if self._alpaca_request_write_started:
                raise TimeoutError("Alpaca request-write deadline elapsed after request transmission began") from None
            raise
        assert remaining is not None
        if self.sock is None:
            self.connect()
            remaining = _remaining_alpaca_request_write_seconds()
            assert remaining is not None
        self.sock.settimeout(_deadline_bounded_socket_timeout(self.timeout, remaining))
        try:
            # Setting the socket timeout and rescheduling this process can consume
            # the last part of the absolute budget. Recheck at the byte boundary
            # rather than treating the earlier timeout calculation as authority
            # to begin a late broker mutation.
            _remaining_alpaca_request_write_seconds()
        except _BuySubmissionWindowElapsedError:
            request_write_started = self._alpaca_request_write_started
            sock = self.sock
            self.sock = None
            with suppress(OSError):
                sock.close()
            if request_write_started:
                raise TimeoutError("Alpaca request-write deadline elapsed after request transmission began") from None
            raise
        # A tunnelling proxy's CONNECT bytes are part of connection setup,
        # not evidence that the broker POST itself could have reached Alpaca.
        if not self._alpaca_connection_setup_in_progress:
            self._alpaca_request_write_started = True
        super().send(data)


# Requests constructs a fresh urllib3 pool for each module-level call. The
# subclass is inert without the context-local deadline, so unrelated and
# concurrent HTTPS requests retain urllib3's normal behavior.
_Urllib3HTTPSConnectionPool.ConnectionCls = _DeadlineAwareAlpacaHTTPSConnection


class _OrderLookupIdentityError(ValueError):
    def __init__(self, payload: dict) -> None:
        super().__init__("Alpaca order lookup returned a different order ID")
        self.payload = payload


class _OpenOrderSnapshotError(ValueError):
    """Retain every observed row when a complete account snapshot cannot be proven."""

    def __init__(self, message: str, observed_rows: list[object]) -> None:
        super().__init__(message)
        self.observed_rows = list(observed_rows)
        self.observed_orders = [row for row in observed_rows if isinstance(row, dict)]
        # Compatibility for callers and tests that consumed the original
        # incomplete-page exception. ``page`` is now deliberately cumulative.
        self.page = self.observed_orders


class _IncompleteOpenOrderPayloadError(_OpenOrderSnapshotError):
    """Retain all observed rows when one open-order page is incomplete."""

    def __init__(self, observed_rows: list[object]) -> None:
        super().__init__(
            "Alpaca open-orders endpoint returned an incomplete order payload",
            observed_rows,
        )


@dataclass
class _ReconciliationOrderSnapshot:
    attempted: bool = False
    orders_by_id: dict[str, dict] | None = None


class _DuplicateAlpacaJsonKeyError(ValueError):
    """Raised when an authoritative Alpaca object has ambiguous keys."""


class _InvalidAlpacaJsonConstantError(ValueError):
    """Raised when authoritative JSON contains a non-standard numeric constant."""


class _ExcessiveAlpacaJsonNestingError(ValueError):
    """Raised before an authoritative body exceeds supported JSON depth."""


class _ExcessiveAlpacaJsonStructureError(ValueError):
    """Raised before compact JSON can expand into too many Python objects."""


class _InvalidAlpacaOrderTimestampError(ValueError):
    """Retain the rejected order so reconciliation can fail closed contextually."""

    def __init__(self, payload: dict, field: str) -> None:
        super().__init__(f"Alpaca order response contains an invalid or timezone-naive {field} timestamp")
        self.payload = payload
        self.field = field


class AlpacaBuyBatchError(RuntimeError):
    """A systemic buy-batch failure with all completed per-signal results attached."""

    def __init__(
        self,
        message: str,
        results: pd.DataFrame,
        *,
        broker_side_effects_possible: bool | None = None,
    ) -> None:
        super().__init__(message)
        self.results = results.copy()
        if broker_side_effects_possible is None:
            observed_statuses = (
                {str(status).lower() for status in self.results["Status"].dropna()}
                if "Status" in self.results
                else set()
            )
            broker_side_effects_possible = bool(observed_statuses.intersection(BUY_RESULTS_REQUIRING_RECONCILIATION))
        self.broker_side_effects_possible = bool(broker_side_effects_possible)


class AlpacaReconciliationError(RuntimeError):
    """A required reconciliation failure with all completed position rows attached."""

    def __init__(self, message: str, results: pd.DataFrame) -> None:
        super().__init__(message)
        self.results = results.copy()


_BUY_BATCH_CASH_FRACTION_MAX = 0.50


def _alpaca_headers(cfg: AlpacaOrderConfig) -> dict[str, str]:
    api_key_id, api_secret_key = validate_alpaca_paper_credentials(cfg)
    return {
        "APCA-API-KEY-ID": api_key_id,
        "APCA-API-SECRET-KEY": api_secret_key,
        "Content-Type": "application/json",
    }


def _canonical_alpaca_paper_base_url(cfg: AlpacaOrderConfig) -> str:
    """Validate the configured origin and return its immutable canonical form."""
    validate_alpaca_paper_endpoint(cfg, unconditional=True)
    return ALPACA_PAPER_BASE_URL


def _alpaca_client_order_id(side: str, symbol: str, signal_date: str) -> str:
    # Dots and hyphens are both valid in the public equity-symbol grammar and
    # in Alpaca client-order IDs. Preserve them so distinct tickers such as
    # BRK.B and BRK-B cannot collapse onto the same broker idempotency key.
    safe_symbol = re.sub(r"[^A-Za-z0-9.-]", "-", symbol.upper())
    safe_date = re.sub(r"[^0-9]", "", signal_date)
    return f"rsi-{side}-{safe_symbol}-{safe_date}"


def _legacy_alpaca_client_order_id(side: str, symbol: str, signal_date: str) -> str:
    """Return the pre-dot-preservation ID used by already-durable positions."""
    safe_symbol = re.sub(r"[^A-Za-z0-9-]", "-", symbol.upper())
    safe_date = re.sub(r"[^0-9]", "", signal_date)
    return f"rsi-{side}-{safe_symbol}-{safe_date}"


def _collision_safe_alpaca_buy_client_order_id(symbol: str, signal_date: str) -> str:
    """Return an injective ID outside the ambiguous legacy symbol namespace."""
    encoded_symbol = symbol.upper().encode("ascii").hex().upper()
    safe_date = re.sub(r"[^0-9]", "", signal_date)
    # ``~`` is accepted by the broker ID grammar but not by the public equity
    # symbol grammar, keeping this namespace disjoint from current and legacy
    # IDs rather than relying on hashes or case distinctions.
    client_order_id = f"rsi-buy-v2~{encoded_symbol}-{safe_date}"
    if len(client_order_id) > 128 or _ALPACA_BROKER_IDENTIFIER_PATTERN.fullmatch(client_order_id) is None:
        raise ValueError("Alpaca buy signal cannot be represented by a deterministic client order ID")
    return client_order_id


def _alpaca_buy_client_order_id_for_signal(
    conn: sqlite3.Connection | None,
    symbol: str,
    signal_date: str,
) -> str:
    """Use an existing durable legacy ID, otherwise the injective current ID."""
    current_id = _alpaca_client_order_id("buy", symbol, signal_date)
    legacy_id = _legacy_alpaca_client_order_id("buy", symbol, signal_date)
    if conn is None:
        return current_id

    if current_id != legacy_id:
        rows = conn.execute(
            """
            SELECT buy_client_order_id
            FROM alpaca_managed_positions
            WHERE UPPER(symbol) = UPPER(?)
              AND buy_signal_date = ?
              AND buy_client_order_id IN (?, ?)
            ORDER BY (buy_client_order_id = ?) DESC, id DESC
            """,
            (symbol, signal_date, current_id, legacy_id, current_id),
        ).fetchall()
        if rows:
            return str(rows[0][0])
        return current_id

    # A valid hyphenated symbol can have the same current ID as a legacy dotted
    # symbol (BRK-B versus the former BRK.B encoding). Reuse the ordinary ID
    # only when it is unowned or durably belongs to this exact signal. Otherwise
    # move the new signal into a reversible, versioned namespace so retries are
    # deterministic without borrowing or mutating the legacy owner's row.
    collision_safe_id = _collision_safe_alpaca_buy_client_order_id(symbol, signal_date)
    ownership_rows = conn.execute(
        """
        SELECT symbol, buy_signal_date, buy_client_order_id
        FROM alpaca_managed_positions
        WHERE buy_client_order_id IN (?, ?)
        ORDER BY id DESC
        """,
        (current_id, collision_safe_id),
    ).fetchall()
    ids_for_signal = {
        str(row[2]) for row in ownership_rows if str(row[0]).upper() == symbol.upper() and str(row[1]) == signal_date
    }
    if current_id in ids_for_signal:
        return current_id
    if collision_safe_id in ids_for_signal:
        return collision_safe_id

    owners_by_id = {str(row[2]) for row in ownership_rows}
    if current_id not in owners_by_id:
        return current_id
    if collision_safe_id not in owners_by_id:
        return collision_safe_id
    raise ValueError("Deterministic Alpaca buy client-order namespaces are owned by unrelated managed signals")


def _alpaca_exit_client_order_id(
    symbol: str,
    position_id: int,
    renewal_count: int = 0,
    *,
    order_namespace: str | None = None,
) -> str:
    safe_symbol = re.sub(r"[^A-Za-z0-9-]", "-", symbol.upper())
    identity = order_namespace or str(position_id)
    base_id = f"rsi-exit-{safe_symbol}-{identity}"
    if renewal_count <= 0:
        return base_id
    return f"{base_id}-r{renewal_count}"


def _alpaca_exit_client_order_generation(
    symbol: str,
    position_id: int,
    client_order_id: str,
    *,
    order_namespace: str | None = None,
    allow_legacy_position_id: bool = False,
) -> int | None:
    identity = order_namespace or str(position_id)
    base_id = _alpaca_exit_client_order_id(
        symbol,
        position_id,
        order_namespace=order_namespace,
    )
    if client_order_id == base_id:
        return 0
    match = re.fullmatch(rf"{re.escape(base_id)}-r([1-9][0-9]*)", client_order_id)
    if match is not None:
        return int(match.group(1))
    # Existing client IDs retain the ticker that was current when the order was
    # submitted.  The durable namespace and renewal suffix remain stable across
    # renames.
    alias_match = re.fullmatch(
        rf"rsi-exit-.+-{re.escape(identity)}(?:-r([1-9][0-9]*))?",
        client_order_id,
    )
    if alias_match is not None:
        return 0 if alias_match.group(1) is None else int(alias_match.group(1))
    if order_namespace is not None and not allow_legacy_position_id:
        return None
    legacy_match = re.fullmatch(
        rf"rsi-exit-.+-{position_id}(?:-r([1-9][0-9]*))?",
        client_order_id,
    )
    if legacy_match is None:
        return None
    return 0 if legacy_match.group(1) is None else int(legacy_match.group(1))


def _format_order_number(value: float, places: int) -> str:
    formatted = f"{value:.{places}f}".rstrip("0").rstrip(".")
    return formatted or "0"


def _alpaca_limit_price_tick(price: Decimal) -> Decimal:
    return _ALPACA_SUBDOLLAR_PRICE_TICK if price < Decimal("1") else _ALPACA_DOLLAR_PRICE_TICK


def _quantize_alpaca_limit_price(value: float | Decimal, *, rounding: str) -> Decimal:
    """Round a positive price to Alpaca's valid limit-price increment."""
    try:
        price = Decimal(str(value))
    except InvalidOperation as exc:
        raise ValueError(f"Alpaca limit price must be numeric; got {value!r}.") from exc
    if not price.is_finite() or price <= 0:
        raise ValueError(f"Alpaca limit price must be positive; got {value!r}.")
    try:
        with localcontext(_isolated_price_context(price)):
            if price.adjusted() > _ALPACA_MAX_PRICE_ADJUSTED_EXPONENT:
                raise ValueError("Alpaca limit price cannot be represented at tick precision.")
            quantized = price.quantize(_alpaca_limit_price_tick(price), rounding=rounding)
            # A sub-dollar value can round upward across $1.  Re-quantize it
            # using the dollar-or-more tick so the serialized order is valid.
            if quantized >= Decimal("1"):
                quantized = quantized.quantize(_ALPACA_DOLLAR_PRICE_TICK, rounding=rounding)
    except DecimalException as exc:
        raise ValueError("Alpaca limit price cannot be represented at tick precision.") from exc
    return quantized


def _format_alpaca_limit_price(value: float | Decimal, *, rounding: str) -> str:
    quantized = _quantize_alpaca_limit_price(value, rounding=rounding)
    formatted = format(quantized, "f").rstrip("0").rstrip(".")
    return formatted or "0"


def _target_sell_price(filled_avg_price: float, profit_target_multiple: float) -> float:
    return target_sell_price(filled_avg_price, profit_target_multiple)


def _alpaca_limit_price_tolerance(value: float) -> float:
    return float(_alpaca_limit_price_tick(Decimal(str(value))) / Decimal("2"))


def _is_whole_share_qty(value: float) -> bool:
    try:
        qty = Decimal(str(canonical_alpaca_order_quantity(value)))
    except (InvalidOperation, TypeError, ValueError):
        return False
    return qty == qty.to_integral_value()


def _alpaca_dynamic_batch_cash_fraction(eligible_buy_signal_count: int) -> float:
    if eligible_buy_signal_count < 1:
        raise ValueError(f"Eligible buy signal count must be positive; got {eligible_buy_signal_count}.")
    return min(
        eligible_buy_signal_count * _BUY_BATCH_CASH_FRACTION_PER_ELIGIBLE_SIGNAL,
        _BUY_BATCH_CASH_FRACTION_MAX,
    )


def _alpaca_cash_notional(
    cfg: AlpacaOrderConfig,
    headers: dict[str, str],
    *,
    eligible_buy_signal_count: int,
) -> float:
    base_url = _canonical_alpaca_paper_base_url(cfg)
    account_resp = _alpaca_http_request(
        "GET",
        f"{base_url}/v2/account",
        cfg=cfg,
        headers=headers,
        timeout=cfg.timeout_seconds,
        allow_redirects=False,
    )
    _require_2xx_response(account_resp)
    account = _strict_alpaca_response_json(account_resp)
    if not isinstance(account, dict):
        raise ValueError("Alpaca account endpoint returned an invalid response")
    try:
        cash = _finite_float(account["cash"])
    except (KeyError, TypeError, ValueError) as exc:
        raise ValueError("Alpaca account cash is missing or is not a finite number") from exc
    cash_fraction = _alpaca_dynamic_batch_cash_fraction(eligible_buy_signal_count)
    notional = round(cash * cash_fraction, 2)
    if notional <= 0:
        raise ValueError(f"Alpaca account cash must be positive to submit buy orders; got {cash}.")
    return notional


def _latest_market_price(
    symbol: str,
    *,
    timeout_seconds: int,
    expected_session: date | None = None,
) -> float:
    """Fetch a recent close and optionally prove which exchange session supplied it."""
    if isinstance(yf.Ticker, Mock):
        # Preserve deterministic test doubles without allowing ordinary
        # production callables to bypass the killable process boundary.
        history = execute_yfinance_ticker_history(
            symbol,
            request_timeout_seconds=float(timeout_seconds),
        )
    else:
        deadline = time.monotonic() + timeout_seconds
        payload = run_yfinance_ticker_history_with_deadline(
            symbol,
            request_timeout_seconds=float(timeout_seconds),
            deadline=deadline,
        )
        worker_error = exception_from_yfinance_worker_error(payload)
        if worker_error is not None:
            raise worker_error
        if type(payload) is not tuple or not payload:
            raise requests.exceptions.ConnectionError("Yahoo Finance worker returned an invalid response.")
        if type(payload[0]) is not str or payload[0] != "yfinance_ticker_history_response" or len(payload) != 2:
            raise requests.exceptions.ConnectionError("Yahoo Finance worker returned an invalid response.")
        history = payload[1]
        if not isinstance(history, pd.DataFrame):
            raise requests.exceptions.ConnectionError("Yahoo Finance worker returned an invalid recent-history frame.")
    if history.empty or "Close" not in history:
        raise ValueError(f"Could not determine latest market price for {symbol}.")

    close = history["Close"].dropna()
    if close.empty:
        raise ValueError(f"Could not determine latest market price for {symbol}.")
    try:
        latest_close = _finite_float(close.iloc[-1])
    except (TypeError, ValueError) as exc:
        raise ValueError(f"Could not determine latest market price for {symbol}.") from exc
    if latest_close <= 0:
        raise ValueError(f"Could not determine latest market price for {symbol}.")
    if expected_session is not None:
        try:
            observed_timestamp = pd.Timestamp(close.index[-1])
            if pd.isna(observed_timestamp):
                raise ValueError
            observed_session = (
                observed_timestamp.tz_localize(None).date()
                if observed_timestamp.tzinfo is None
                else observed_timestamp.tz_convert(_NEW_YORK).date()
            )
        except (TypeError, ValueError, OverflowError) as exc:
            raise ValueError(f"Latest market price for {symbol} has no valid exchange session.") from exc
        if observed_session != expected_session:
            raise ValueError(
                f"Latest market price for {symbol} is from {observed_session}, not the "
                f"authorized prior session {expected_session}."
            )
    return latest_close


def _alpaca_position_qty(symbol_or_asset_id: str, cfg: AlpacaOrderConfig, headers: dict[str, str]) -> float:
    base_url = _canonical_alpaca_paper_base_url(cfg)
    position_path = _alpaca_broker_identifier_path(
        symbol_or_asset_id,
        label="Alpaca position symbol or asset ID",
    )
    position_resp = _alpaca_http_request(
        "GET",
        f"{base_url}/v2/positions/{position_path}",
        cfg=cfg,
        headers=headers,
        timeout=cfg.timeout_seconds,
        allow_redirects=False,
    )
    if position_resp.status_code == 404:
        return 0.0
    _require_2xx_response(position_resp)
    position = _strict_alpaca_response_json(position_resp)
    if not isinstance(position, dict):
        raise ValueError("Alpaca position endpoint returned an invalid response")
    if position.get("asset_class") != _ALPACA_US_EQUITY_ASSET_CLASS:
        raise ValueError("Alpaca position endpoint returned a missing, invalid, or non-US-equity asset class")
    observed_asset_id = _optional_alpaca_broker_identifier(position.get("asset_id"))
    observed_symbol = _optional_alpaca_equity_symbol(position.get("symbol"))
    requested_identity = _optional_str(symbol_or_asset_id)
    if (
        observed_asset_id is None
        or observed_symbol is None
        or requested_identity is None
        or (observed_asset_id != requested_identity and observed_symbol.upper() != requested_identity.upper())
    ):
        raise ValueError("Alpaca position lookup did not return the requested stable asset identity")
    return _validated_alpaca_position_qty(position, label="Alpaca position endpoint")


def _alpaca_asset(symbol: str, cfg: AlpacaOrderConfig, headers: dict[str, str]) -> dict:
    base_url = _canonical_alpaca_paper_base_url(cfg)
    asset_path = _alpaca_broker_identifier_path(
        symbol,
        label="Alpaca asset symbol or ID",
    )
    asset_resp = _alpaca_http_request(
        "GET",
        f"{base_url}/v2/assets/{asset_path}",
        cfg=cfg,
        headers=headers,
        timeout=cfg.timeout_seconds,
        allow_redirects=False,
    )
    _require_2xx_response(asset_resp)
    asset = _strict_alpaca_response_json(asset_resp)
    if not isinstance(asset, dict):
        raise ValueError("Alpaca asset endpoint returned an invalid response")
    if asset.get("id") is not None and _optional_alpaca_broker_identifier(asset.get("id")) is None:
        raise ValueError("Alpaca asset endpoint returned an invalid stable asset identity")
    if asset.get("symbol") is not None and _optional_alpaca_equity_symbol(asset.get("symbol")) is None:
        raise ValueError("Alpaca asset endpoint returned a non-canonical equity symbol")
    _require_alpaca_us_equity_asset_class(asset)
    return asset


def _require_alpaca_us_equity_asset_class(asset: dict) -> None:
    """Reject asset identities outside this strategy's US-equity scope."""
    if asset.get("class") != _ALPACA_US_EQUITY_ASSET_CLASS:
        raise ValueError("Alpaca asset endpoint returned a missing, invalid, or non-US-equity asset class")


def _validated_alpaca_asset_id(asset: dict, *, expected_symbol: str) -> str:
    asset_id = _optional_alpaca_broker_identifier(asset.get("id"))
    observed_symbol = _optional_alpaca_equity_symbol(asset.get("symbol"))
    if asset_id is None or observed_symbol is None or observed_symbol.upper() != expected_symbol.upper():
        raise ValueError(
            f"Alpaca asset lookup did not return the requested stable asset identity for {expected_symbol}"
        )
    _require_alpaca_us_equity_asset_class(asset)
    return asset_id


def _validated_alpaca_position_qty(position: dict, *, label: str) -> float:
    """Return a finite signed quantity whose sign agrees with Position.side."""
    raw_side = position.get("side")
    if not isinstance(raw_side, str) or raw_side not in {"long", "short"}:
        raise ValueError(f"{label} returned a missing or invalid position side")
    try:
        qty = _finite_float(position["qty"])
    except (KeyError, TypeError, ValueError) as exc:
        raise ValueError(f"{label} position quantity is missing or is not a finite number") from exc
    if qty == 0.0 or (raw_side == "long") != (qty > 0.0):
        raise ValueError(f"{label} returned a position side inconsistent with its signed quantity")
    return qty


def _managed_live_position_identity_and_qty(
    positions: list[dict],
    *,
    symbol: str,
    expected_alpaca_asset_id: str | None,
    symbol_aliases: set[str],
) -> tuple[str | None, float]:
    """Return the matched stable identity and holdings used to bound exits.

    Reconciliation verifies same-asset open-order conflicts before a new sell.
    Total ``qty`` is therefore the correct ceiling; ``qty_available`` can be
    zero solely because the current protective order reserves the shares that
    a safe cancellation/replacement is intended to keep protected.
    """
    aliases = {symbol.upper(), *(alias.upper() for alias in symbol_aliases)}
    matches: list[dict] = []
    for position in positions:
        observed_asset_id = _optional_alpaca_broker_identifier(position.get("asset_id"))
        observed_symbol = _optional_alpaca_equity_symbol(position.get("symbol"))
        if observed_asset_id is None or observed_symbol is None:
            raise ValueError("Alpaca live position has incomplete stable asset identity")
        if expected_alpaca_asset_id is not None:
            identity_matches = observed_asset_id == expected_alpaca_asset_id
        else:
            identity_matches = observed_symbol.upper() in aliases
        if identity_matches:
            matches.append(position)
    if len(matches) > 1:
        raise ValueError("Alpaca returned multiple live positions for the managed stable asset")
    if not matches:
        return None, 0.0
    observed_asset_id = _optional_alpaca_broker_identifier(matches[0].get("asset_id"))
    if observed_asset_id is None:
        raise ValueError("Alpaca live position has incomplete stable asset identity")
    if matches[0].get("asset_class") != _ALPACA_US_EQUITY_ASSET_CLASS:
        raise ValueError("Alpaca live managed position has a missing, invalid, or non-US-equity asset class")
    qty = _validated_alpaca_position_qty(matches[0], label="Alpaca live position")
    if matches[0]["side"] != "long":
        raise ValueError("Alpaca live managed position is not a long holding")
    return observed_asset_id, qty


def _managed_live_position_qty(
    positions: list[dict],
    *,
    symbol: str,
    expected_alpaca_asset_id: str | None,
    symbol_aliases: set[str],
) -> float:
    return _managed_live_position_identity_and_qty(
        positions,
        symbol=symbol,
        expected_alpaca_asset_id=expected_alpaca_asset_id,
        symbol_aliases=symbol_aliases,
    )[1]


def _alpaca_account_asset_class(payload: dict, *, label: str) -> str | None:
    """Decode an optional canonical asset class from an account-wide row."""
    raw_asset_class = payload.get("asset_class")
    if raw_asset_class is None or raw_asset_class == "":
        return None
    if (
        not isinstance(raw_asset_class, str)
        or raw_asset_class != raw_asset_class.strip()
        or raw_asset_class not in _ALPACA_ASSET_CLASSES
    ):
        raise ValueError(f"{label} returned an invalid or unsupported asset class")
    return raw_asset_class


def _account_open_order_is_us_equity(order: dict) -> bool:
    """Classify one account-wide order without guessing malformed asset metadata."""
    asset_class = _alpaca_account_asset_class(order, label="Alpaca open-orders endpoint")
    raw_order_class = order.get("order_class")

    # Alpaca omits asset_id, symbol, and asset_class from the top-level object
    # for an options multi-leg order. OrderClass.mleg is options-only, so it
    # remains safely outside this equity strategy even when the asset class is
    # omitted exactly as documented.
    if raw_order_class == "mleg":
        if asset_class not in {None, "us_option"}:
            raise ValueError("Alpaca open-orders endpoint returned contradictory multi-leg asset metadata")
        return False
    if asset_class in _ALPACA_UNRELATED_ASSET_CLASSES:
        if raw_order_class not in {None, "", "simple"}:
            raise ValueError("Alpaca open-orders endpoint returned an invalid non-equity order class")
        return False
    if asset_class != _ALPACA_US_EQUITY_ASSET_CLASS:
        raise ValueError("Alpaca open-orders endpoint returned a missing US-equity asset class")
    return True


def _alpaca_has_open_order(
    symbol: str,
    side: str,
    cfg: AlpacaOrderConfig,
    headers: dict[str, str],
) -> bool:
    return _orders_have_open_order(_alpaca_open_orders(cfg, headers), symbol, side)


def _alpaca_account_orders(
    cfg: AlpacaOrderConfig,
    headers: dict[str, str],
    *,
    status: str,
    equity_scope_asset_ids: Collection[str] = (),
) -> list[dict]:
    if status not in {"open", "closed", "all"}:
        raise ValueError("Alpaca account-order status must be 'open', 'closed', or 'all'.")
    base_url = _canonical_alpaca_paper_base_url(cfg)
    transmitted_sensitive_values = _merged_alpaca_sensitive_values(
        tuple(headers.get(header_name, "") for header_name in ("APCA-API-KEY-ID", "APCA-API-SECRET-KEY"))
    )
    normalized_equity_scope_asset_ids = _canonical_alpaca_asset_id_scope(equity_scope_asset_ids)
    orders: list[dict] = []
    orders_by_id: dict[str, dict] = {}
    asset_classes_by_asset_id: dict[str, str] = {}
    observed_rows: list[object] = []
    seen_page_cursors: set[str] = set()
    before_order_id: str | None = None

    for _ in range(_ALPACA_OPEN_ORDER_MAX_PAGES):
        params: dict[str, object] = {
            "status": status,
            "asset_class": _ALPACA_US_EQUITY_ASSET_CLASS,
            "limit": _ALPACA_OPEN_ORDER_PAGE_LIMIT,
            "direction": "desc",
        }
        if before_order_id is not None:
            params["before_order_id"] = before_order_id
        try:
            orders_resp = _alpaca_http_request(
                "GET",
                f"{base_url}/v2/orders",
                cfg=cfg,
                headers=headers,
                params=params,
                timeout=cfg.timeout_seconds,
                allow_redirects=False,
            )
            _require_2xx_response(orders_resp)
            page = _strict_alpaca_response_json(orders_resp)
        except Exception as exc:
            if not observed_rows:
                raise
            detail = _alpaca_exception_diagnostic(
                exc,
                cfg=cfg,
                sensitive_values=transmitted_sensitive_values,
            )
            raise _OpenOrderSnapshotError(
                f"Alpaca open-orders pagination failed after a partial account snapshot: {detail}",
                observed_rows,
            ) from exc
        if not isinstance(page, list):
            raise _OpenOrderSnapshotError(
                "Alpaca open-orders endpoint returned an invalid response",
                observed_rows,
            )
        observed_rows.extend(page)
        if not all(isinstance(order, dict) for order in page):
            raise _OpenOrderSnapshotError(
                "Alpaca open-orders endpoint returned an invalid response",
                observed_rows,
            )
        try:
            equity_scope = [_account_open_order_is_us_equity(order) for order in page]
        except ValueError as exc:
            raise _IncompleteOpenOrderPayloadError(observed_rows) from exc
        if not all(
            _open_order_payload_is_complete(order) if is_us_equity else _unrelated_open_order_payload_is_complete(order)
            for order, is_us_equity in zip(page, equity_scope, strict=True)
        ):
            raise _IncompleteOpenOrderPayloadError(observed_rows)

        for order, is_us_equity in zip(page, equity_scope, strict=True):
            # Completeness validation above proves this is one canonical broker
            # path token. Pagination overlap may repeat an equivalent object,
            # but a repeated ID with changed content makes the account snapshot
            # contradictory and cannot authorize a later broker mutation.
            order_id = _optional_alpaca_broker_identifier(order.get("id"))
            if order_id is None:
                raise _IncompleteOpenOrderPayloadError(observed_rows)
            asset_id = _optional_alpaca_broker_identifier(order.get("asset_id"))
            if asset_id is not None:
                asset_class = (
                    _ALPACA_US_EQUITY_ASSET_CLASS
                    if is_us_equity
                    else _alpaca_account_asset_class(order, label="Alpaca open-orders endpoint")
                )
                if asset_class is None:
                    raise _IncompleteOpenOrderPayloadError(observed_rows)
                prior_asset_class = asset_classes_by_asset_id.get(asset_id)
                if prior_asset_class is not None and prior_asset_class != asset_class:
                    raise _OpenOrderSnapshotError(
                        "Alpaca open-orders endpoint returned conflicting asset classes for one stable asset ID",
                        observed_rows,
                    )
                asset_classes_by_asset_id[asset_id] = asset_class
                if not is_us_equity and asset_id in normalized_equity_scope_asset_ids:
                    raise _OpenOrderSnapshotError(
                        "Alpaca open-orders endpoint returned a non-equity order for an equity-scope stable asset ID",
                        observed_rows,
                    )
            prior_order = orders_by_id.get(order_id)
            if prior_order is None:
                orders_by_id[order_id] = order
                if is_us_equity:
                    orders.append(order)
            elif not _alpaca_json_values_are_equivalent(prior_order, order):
                raise _OpenOrderSnapshotError(
                    f"Alpaca open-orders pagination returned conflicting payloads for order ID {order_id}",
                    observed_rows,
                )

        if len(page) < _ALPACA_OPEN_ORDER_PAGE_LIMIT:
            return orders

        next_before_order_id = _optional_alpaca_broker_identifier(page[-1].get("id"))
        if next_before_order_id is None:
            raise _OpenOrderSnapshotError(
                "Alpaca returned a full open-order page without an order-ID cursor; "
                "refusing to treat the account order list as complete",
                observed_rows,
            )
        if next_before_order_id == before_order_id or next_before_order_id in seen_page_cursors:
            raise _OpenOrderSnapshotError(
                "Alpaca open-order pagination made no progress; refusing to treat the account order list as complete",
                observed_rows,
            )
        # Timestamp cursors are exclusive and can omit orders when more than
        # one order shares the boundary timestamp. Alpaca's stable order-ID
        # cursor advances past exactly the final row on the page.
        seen_page_cursors.add(next_before_order_id)
        before_order_id = next_before_order_id

    raise _OpenOrderSnapshotError(
        f"Alpaca open-order pagination exceeded {_ALPACA_OPEN_ORDER_MAX_PAGES} pages; "
        "refusing to perform conflict checks on an incomplete order list",
        observed_rows,
    )


def _alpaca_open_orders(
    cfg: AlpacaOrderConfig,
    headers: dict[str, str],
    *,
    equity_scope_asset_ids: Collection[str] = (),
) -> list[dict]:
    return _alpaca_account_orders(
        cfg,
        headers,
        status="open",
        equity_scope_asset_ids=equity_scope_asset_ids,
    )


def _open_order_common_payload_is_complete(order: dict) -> bool:
    status = _broker_order_status(order)
    return bool(
        _optional_alpaca_broker_identifier(order.get("id"))
        and _optional_str(order.get("client_order_id"))
        and all(
            order.get(field) is None or _optional_alpaca_broker_identifier(order.get(field)) is not None
            for field in ("replaces", "replaced_by")
        )
        and _optional_str(order.get("time_in_force"))
        and status in _ALPACA_ORDER_STATUSES
        and _broker_nonnegative_number_is_valid(order.get("filled_qty"))
        and (
            _optional_positive_float(order.get("qty")) is not None
            or _optional_positive_float(order.get("notional")) is not None
        )
        and isinstance(order.get("extended_hours"), bool)
        and all(
            order.get(field) is None or _parse_alpaca_broker_datetime(order.get(field)) is not None
            for field in ("submitted_at", "updated_at", "filled_at", "expires_at")
        )
    )


def _open_order_payload_is_complete(order: dict) -> bool:
    side = (_optional_str(order.get("side")) or "").lower()
    return bool(
        _open_order_common_payload_is_complete(order)
        and _optional_alpaca_broker_identifier(order.get("asset_id"))
        and _optional_alpaca_equity_symbol(order.get("symbol"))
        and side in {"buy", "sell"}
        and _alpaca_order_type(order)
    )


def _unrelated_open_order_payload_is_complete(order: dict) -> bool:
    if not _open_order_common_payload_is_complete(order):
        return False
    if order.get("order_class") == "mleg":
        raw_side = order.get("side")
        side_is_complete = raw_side is None or (isinstance(raw_side, str) and raw_side in {"", "buy", "sell"})
        return bool(
            all(order.get(field) in (None, "") for field in ("asset_id", "symbol"))
            and side_is_complete
            and _alpaca_order_type(order)
        )
    side = (_optional_str(order.get("side")) or "").lower()
    return bool(
        _optional_alpaca_broker_identifier(order.get("asset_id"))
        and _optional_alpaca_unrelated_symbol(order.get("symbol"))
        and side in {"buy", "sell"}
        and _alpaca_order_type(order)
    )


def _orders_have_open_order(
    orders: list[dict],
    symbol: str,
    side: str,
    *,
    expected_alpaca_asset_id: str | None = None,
    symbol_aliases: set[str] | None = None,
) -> bool:
    aliases = {symbol.upper(), *(alias.upper() for alias in symbol_aliases or set())}
    side = side.lower()
    for order in orders:
        if (_optional_str(order.get("side")) or "").lower() != side:
            continue
        observed_asset_id = _optional_str(order.get("asset_id"))
        observed_symbol = _optional_str(order.get("symbol"))
        if expected_alpaca_asset_id is not None and observed_asset_id is not None:
            identity_matches = observed_asset_id == expected_alpaca_asset_id
        else:
            identity_matches = observed_symbol is not None and observed_symbol.upper() in aliases
        if identity_matches:
            return True
    return False


def _alpaca_order_type(order: dict) -> str | None:
    """Use Alpaca's legacy type alias only when the primary field is omitted."""
    raw_type = order.get("type")
    if raw_type is None or (isinstance(raw_type, str) and not raw_type.strip()):
        raw_type = order.get("order_type")
    return _optional_str(raw_type)


def _matching_managed_open_sell_orders(
    orders: list[dict],
    symbol: str,
    position_id: int,
    *,
    sell_order_namespace: str | None = None,
    legacy_sell_client_order_id: str | None = None,
    expected_alpaca_asset_id: str | None = None,
    excluded_client_order_id: str | None = None,
    excluded_alpaca_order_id: str | None = None,
) -> list[dict]:
    """Return immutable-identity candidates for strict recovery validation."""
    symbol = symbol.upper()
    matches: list[dict] = []
    for order in orders:
        if not _order_matches_core_intent(
            order,
            expected_symbol=symbol,
            expected_alpaca_asset_id=expected_alpaca_asset_id,
            expected_side="sell",
            expected_order_type="limit",
            expected_time_in_force="gtc",
            require_complete=True,
        ):
            continue
        order_asset_id = _optional_str(order.get("asset_id"))
        if expected_alpaca_asset_id is not None and order_asset_id is not None:
            identity_matches = order_asset_id == expected_alpaca_asset_id
        else:
            identity_matches = str(order.get("symbol", "")).upper() == symbol
        if not identity_matches:
            continue
        client_order_id = _optional_str(order.get("client_order_id"))
        alpaca_order_id = _optional_str(order.get("id"))
        if client_order_id == excluded_client_order_id or (
            excluded_alpaca_order_id is not None and alpaca_order_id == excluded_alpaca_order_id
        ):
            continue
        legacy_generation_is_expected = bool(
            legacy_sell_client_order_id
            and _alpaca_exit_client_order_generation(
                symbol,
                position_id,
                legacy_sell_client_order_id,
            )
            is not None
        )
        if (
            client_order_id is not None
            and _alpaca_exit_client_order_generation(
                symbol,
                position_id,
                client_order_id,
                order_namespace=sell_order_namespace,
                allow_legacy_position_id=legacy_generation_is_expected,
            )
            is not None
        ):
            matches.append(order)
    return matches


def _optional_number_is_missing(value: object) -> bool:
    if value is None or (isinstance(value, str) and value == ""):
        return True
    try:
        missing = pd.isna(value)
    except (TypeError, ValueError):
        return False
    return bool(missing) if isinstance(missing, (bool, np.bool_)) else False


def _broker_number_is_omitted(value: object) -> bool:
    """Recognize only wire-level omission, not non-finite numeric payloads."""
    return value is None or (isinstance(value, str) and value == "")


def _finite_float(value: object) -> float:
    """Decode a broker number without Python's boolean or infinity coercions."""
    if isinstance(value, (bool, np.bool_)) or not np.isscalar(value):
        raise ValueError("boolean or container values are not valid broker numbers")
    try:
        parsed = float(value)
    except (TypeError, ValueError, OverflowError) as exc:
        raise ValueError("broker number is not numeric") from exc
    if not isfinite(parsed):
        raise ValueError("broker number is not finite")
    return parsed


def _broker_nonnegative_number_is_valid(value: object) -> bool:
    if _broker_number_is_omitted(value):
        return False
    try:
        return _finite_float(value) >= 0
    except (TypeError, ValueError):
        return False


def _optional_float(value: object) -> float | None:
    if _optional_number_is_missing(value):
        return None
    return _finite_float(value)


def _optional_positive_float(value: object) -> float | None:
    try:
        parsed = _optional_float(value)
    except (TypeError, ValueError):
        return None
    return parsed if parsed is not None and isfinite(parsed) and parsed > 0 else None


def _optional_positive_decimal(value: object) -> Decimal | None:
    """Decode an exact positive broker number without binary-float rounding."""
    if _broker_number_is_omitted(value) or isinstance(value, (bool, np.bool_)) or not np.isscalar(value):
        return None
    try:
        parsed = Decimal(str(value))
        parsed_float = _finite_float(value)
    except (InvalidOperation, TypeError, ValueError):
        return None
    return parsed if parsed.is_finite() and parsed > 0 and parsed_float > 0 else None


def _optional_nonnegative_decimal(value: object) -> Decimal | None:
    """Decode an exact nonnegative broker number usable by float accounting."""
    if _broker_number_is_omitted(value) or isinstance(value, (bool, np.bool_)) or not np.isscalar(value):
        return None
    try:
        parsed = Decimal(str(value))
        parsed_float = _finite_float(value)
    except (InvalidOperation, TypeError, ValueError):
        return None
    if not parsed.is_finite() or parsed < 0 or parsed_float < 0:
        return None
    if parsed != 0 and parsed_float == 0:
        return None
    return parsed


def _broker_order_quantity_is_wire_canonical(
    value: object,
    *,
    allow_zero: bool,
) -> bool:
    """Require exact persistence and Alpaca's nine-decimal quantity format."""
    parsed = _optional_nonnegative_decimal(value)
    if parsed is None or (parsed == 0 and not allow_zero):
        return False
    if parsed == 0:
        return True
    try:
        canonical_alpaca_order_quantity(value)
    except ValueError:
        return False
    return True


def _exact_decimal_difference(left: Decimal, right: Decimal) -> Decimal:
    """Subtract bounded broker decimals without context-induced rounding."""
    precision = (
        max(left.adjusted(), right.adjusted(), 0)
        - min(
            left.as_tuple().exponent,
            right.as_tuple().exponent,
        )
        + 2
    )
    with localcontext() as context:
        context.prec = max(34, precision)
        return left - right


def _exact_decimal_sum(values: Collection[Decimal]) -> Decimal:
    """Add bounded broker decimals without binary-float or context rounding."""
    total = Decimal(0)
    for value in values:
        total = _exact_decimal_difference(total, value.copy_negate())
    return total


def _canonical_whole_share_qty(value: object) -> Decimal | None:
    qty = _optional_positive_decimal(value)
    return qty if qty is not None and qty == qty.to_integral_value() else None


def _canonical_alpaca_limit_price(value: object) -> Decimal | None:
    """Return an exact price only when it already lies on an Alpaca tick."""
    price = _optional_positive_decimal(value)
    if price is None or price.adjusted() > _ALPACA_MAX_PRICE_ADJUSTED_EXPONENT:
        return None
    try:
        with localcontext(_isolated_price_context(price)):
            quantized = price.quantize(_alpaca_limit_price_tick(price), rounding=ROUND_FLOOR)
    except DecimalException:
        return None
    return quantized if price == quantized else None


def _limit_price_matches_frozen_intent(observed: object, expected: object) -> bool:
    observed_price = _canonical_alpaca_limit_price(observed)
    expected_price = _canonical_alpaca_limit_price(expected)
    return observed_price is not None and expected_price is not None and observed_price == expected_price


def _optional_str(value: object) -> str | None:
    """Decode a wire/storage string without coercing other JSON scalar types."""
    if not isinstance(value, str):
        return None
    text = value.strip()
    return text if text else None


def _optional_alpaca_position_intent_matches(value: object, *, expected: str) -> bool:
    """Accept an omitted response field, but never an incompatible explicit intent."""
    return value is None or (type(value) is str and value == expected)


def _broker_order_status(order: dict, *, default: str = "") -> str:
    """Decode one broker lifecycle status with canonical comparison semantics."""
    return (_optional_str(order.get("status")) or default).lower()


def _reject_duplicate_alpaca_json_keys(pairs: list[tuple[str, object]]) -> dict[str, object]:
    decoded: dict[str, object] = {}
    for key, value in pairs:
        if key in decoded:
            raise _DuplicateAlpacaJsonKeyError(f"duplicate JSON object key {key!r}")
        decoded[key] = value
    return decoded


def _reject_nonstandard_alpaca_json_constant(value: str) -> object:
    raise _InvalidAlpacaJsonConstantError(f"Alpaca response contains non-standard JSON numeric constant {value}")


def _reject_excessive_alpaca_json_structure(value: str) -> None:
    """Bound JSON depth and node-like tokens before allocating containers."""
    depth = 0
    structural_tokens = 0
    in_string = False
    escaped = False
    for character in value:
        if in_string:
            if escaped:
                escaped = False
            elif character == "\\":
                escaped = True
            elif character == '"':
                in_string = False
            continue
        if character == '"':
            in_string = True
        elif character in "[{":
            structural_tokens += 1
            if structural_tokens > _ALPACA_JSON_MAX_STRUCTURAL_TOKENS:
                raise _ExcessiveAlpacaJsonStructureError(
                    "Alpaca response exceeded the supported JSON structural limit of "
                    f"{_ALPACA_JSON_MAX_STRUCTURAL_TOKENS} tokens"
                )
            depth += 1
            if depth > _ALPACA_JSON_MAX_NESTING_DEPTH:
                raise _ExcessiveAlpacaJsonNestingError(
                    f"Alpaca response exceeded the supported JSON nesting depth of {_ALPACA_JSON_MAX_NESTING_DEPTH}"
                )
        elif character in ",:":
            structural_tokens += 1
            if structural_tokens > _ALPACA_JSON_MAX_STRUCTURAL_TOKENS:
                raise _ExcessiveAlpacaJsonStructureError(
                    "Alpaca response exceeded the supported JSON structural limit of "
                    f"{_ALPACA_JSON_MAX_STRUCTURAL_TOKENS} tokens"
                )
        elif character in "]}":
            # Leave structural validity to json.loads while preventing malformed
            # leading closers from concealing later excessive nesting.
            depth = max(0, depth - 1)


def _validate_finite_alpaca_json_values(value: object) -> object:
    """Reject decoded non-finite floats recursively, including from test clients."""
    if isinstance(value, (float, np.floating)) and not isfinite(float(value)):
        raise _InvalidAlpacaJsonConstantError("Alpaca response contains a non-finite JSON numeric value")
    if isinstance(value, Decimal) and not value.is_finite():
        raise _InvalidAlpacaJsonConstantError("Alpaca response contains a non-finite JSON numeric value")
    if isinstance(value, dict):
        for nested in value.values():
            _validate_finite_alpaca_json_values(nested)
    elif isinstance(value, list):
        for nested in value:
            _validate_finite_alpaca_json_values(nested)
    return value


def _alpaca_json_values_are_equivalent(first: object, second: object) -> bool:
    """Compare decoded JSON structurally without Python scalar coercions.

    Pagination overlap may repeat the exact same order object.  Mapping order is
    irrelevant in JSON, but a changed scalar type/value, list order, field set,
    or nested value means the account snapshot changed or contradicted itself.
    In particular, keep booleans distinct from integers and do not normalize
    broker numeric spellings that arrived as strings.
    """
    if type(first) is not type(second):
        return False
    if isinstance(first, dict):
        if not isinstance(second, dict) or first.keys() != second.keys():
            return False
        return all(_alpaca_json_values_are_equivalent(value, second[key]) for key, value in first.items())
    if isinstance(first, list):
        if not isinstance(second, list) or len(first) != len(second):
            return False
        return all(
            _alpaca_json_values_are_equivalent(first_value, second_value)
            for first_value, second_value in zip(first, second, strict=True)
        )
    return bool(first == second)


def _strict_alpaca_response_json(resp: requests.Response) -> object:
    """Decode authoritative HTTP JSON without silent last-key-wins behavior.

    Real ``requests.Response`` objects expose the original response text, which
    is required to detect duplicate keys at every nesting level. Lightweight
    injected clients and test doubles commonly expose only ``json()``; retain
    that response-like protocol instead of interpreting their diagnostic
    ``text`` attribute as an HTTP body.
    """
    if isinstance(resp, requests.Response):
        response_text = resp.text
        _reject_excessive_alpaca_json_structure(response_text)
        payload = json.loads(
            response_text,
            object_pairs_hook=_reject_duplicate_alpaca_json_keys,
            parse_constant=_reject_nonstandard_alpaca_json_constant,
            parse_float=Decimal,
        )
    else:
        payload = resp.json()
    return _validate_finite_alpaca_json_values(payload)


def _optional_alpaca_broker_identifier(value: object) -> str | None:
    """Decode a canonical broker ID that is also safe as one URL path token."""
    if not isinstance(value, str) or value != value.strip():
        return None
    if _ALPACA_BROKER_IDENTIFIER_PATTERN.fullmatch(value) is None:
        return None
    return value


def _canonical_alpaca_asset_id_scope(asset_ids: Collection[str]) -> frozenset[str]:
    normalized: set[str] = set()
    for asset_id in asset_ids:
        normalized_asset_id = _optional_alpaca_broker_identifier(asset_id)
        if normalized_asset_id is None:
            raise ValueError("Alpaca equity scope contains an invalid stable asset identity")
        normalized.add(normalized_asset_id)
    return frozenset(normalized)


def _optional_alpaca_equity_symbol(value: object) -> str | None:
    """Decode the canonical equity/ETF ticker grammar accepted for new buys."""
    if not isinstance(value, str) or len(value) > _ALPACA_EQUITY_SYMBOL_MAX_CHARS:
        return None
    return value if _ALPACA_EQUITY_SYMBOL_PATTERN.fullmatch(value) is not None else None


def _optional_alpaca_unrelated_symbol(value: object) -> str | None:
    """Decode a printable option/crypto symbol without applying equity grammar."""
    if (
        not isinstance(value, str)
        or not value
        or len(value) > _ALPACA_UNRELATED_SYMBOL_MAX_CHARS
        or value != value.strip()
        or any(character.isspace() or not character.isprintable() for character in value)
    ):
        return None
    return value


def _canonical_alpaca_signal_date(value: object, *, field: str) -> str:
    """Require an unambiguous built-in YYYY-MM-DD value at the broker boundary."""
    if type(value) is not str or len(value) != 10:
        raise ValueError(f"Alpaca buy signal {field} values must be built-in YYYY-MM-DD strings")
    try:
        parsed = date.fromisoformat(value)
    except ValueError as exc:
        raise ValueError(f"Alpaca buy signal {field} values must be built-in YYYY-MM-DD strings") from exc
    if parsed.isoformat() != value:
        raise ValueError(f"Alpaca buy signal {field} values must be built-in YYYY-MM-DD strings")
    return value


def _validate_alpaca_managed_buy_signal_metadata(buy_signals: pd.DataFrame) -> None:
    """Reject incomplete or unsafe managed economics before broker observation."""
    present_fields = _ALPACA_MANAGED_BUY_SIGNAL_FIELDS.intersection(buy_signals.columns)
    if present_fields and present_fields != _ALPACA_MANAGED_BUY_SIGNAL_FIELDS:
        missing_fields = ", ".join(sorted(_ALPACA_MANAGED_BUY_SIGNAL_FIELDS - present_fields))
        raise ValueError(
            "Managed Alpaca buy signals must provide RSI Symbol, Buy RSI, and Sell Return Multiple together; "
            f"missing {missing_fields}."
        )
    if not present_fields:
        return

    for signal_symbol, buy_rsi, profit_target_multiple in buy_signals[
        ["RSI Symbol", "Buy RSI", "Sell Return Multiple"]
    ].itertuples(index=False, name=None):
        if (
            type(signal_symbol) is not str
            or not signal_symbol
            or signal_symbol != signal_symbol.strip()
            or any(character.isspace() or not character.isprintable() for character in signal_symbol)
        ):
            raise ValueError("Managed Alpaca buy signal RSI Symbol values must be canonical non-empty strings")
        try:
            normalized_buy_rsi = _finite_float(buy_rsi)
        except (TypeError, ValueError) as exc:
            raise ValueError(
                "Managed Alpaca buy signal Buy RSI values must be finite numbers between 0 and 100"
            ) from exc
        if not 0 <= normalized_buy_rsi <= 100:
            raise ValueError("Managed Alpaca buy signal Buy RSI values must be finite numbers between 0 and 100")
        try:
            normalized_profit_target = _finite_float(profit_target_multiple)
        except (TypeError, ValueError) as exc:
            raise ValueError(
                "Managed Alpaca buy signal Sell Return Multiple values must be finite numbers greater than 1 and "
                "at most 100"
            ) from exc
        if not 1 < normalized_profit_target <= 100:
            raise ValueError(
                "Managed Alpaca buy signal Sell Return Multiple values must be finite numbers greater than 1 and "
                "at most 100"
            )


def _validate_alpaca_order_payload_identifiers(
    payload: dict,
    *,
    validate_timestamps: bool = True,
) -> None:
    """Reject non-canonical broker IDs before an order payload is trusted."""
    for field in ("id", "asset_id", "replaces", "replaced_by"):
        value = payload.get(field)
        if value is not None and _optional_alpaca_broker_identifier(value) is None:
            raise ValueError(f"Alpaca order response contains an invalid {field} identifier")
    if validate_timestamps:
        for field in ("submitted_at", "updated_at", "filled_at", "expires_at"):
            value = payload.get(field)
            if value is not None and _parse_alpaca_broker_datetime(value) is None:
                raise _InvalidAlpacaOrderTimestampError(payload, field)
    if payload.get("symbol") is not None and _optional_alpaca_equity_symbol(payload.get("symbol")) is None:
        raise ValueError("Alpaca order response contains a non-canonical equity symbol")


def _alpaca_broker_identifier_path(value: object, *, label: str) -> str:
    """Validate and encode an Alpaca order, asset, or equity-symbol path ID."""
    identifier = _optional_alpaca_broker_identifier(value)
    if identifier is None:
        raise ValueError(f"{label} must be a canonical Alpaca identifier safe for a URL path")
    # The allowlist above already excludes separators and URL delimiters. Keep
    # explicit encoding at the request boundary as defense in depth if the
    # accepted broker-token alphabet is extended later.
    return quote(identifier, safe="")


def _buy_cancellation_order_ids(value: object) -> list[str]:
    """Decode the durable set of buy roots retained for cancellation follow-up."""
    if value is None or (isinstance(value, float) and np.isnan(value)):
        return []
    if not isinstance(value, str):
        raise ValueError("Managed buy cancellation order IDs must be stored as JSON text.")
    try:
        payload = json.loads(value)
    except json.JSONDecodeError as exc:
        raise ValueError("Managed buy cancellation order IDs contain invalid JSON.") from exc
    if not isinstance(payload, list):
        raise ValueError("Managed buy cancellation order IDs must be a JSON array.")
    decoded = [_optional_alpaca_broker_identifier(value) for value in payload]
    if any(order_id is None for order_id in decoded):
        raise ValueError("Managed buy cancellation order IDs must be canonical Alpaca identifiers.")
    return sorted({order_id for order_id in decoded if order_id is not None})


def _managed_buy_followup_order_ids(position: dict) -> list[str]:
    """Include the canonical buy whenever independently accepted IDs are tracked."""
    order_ids = _buy_cancellation_order_ids(position.get("buy_cancellation_alpaca_order_ids"))
    canonical_order_id = _optional_str(position.get("buy_alpaca_order_id"))
    if order_ids and canonical_order_id is not None:
        order_ids.append(canonical_order_id)
    return sorted(set(order_ids))


def _sell_status_after_pending_cancel(
    *,
    persisted_status: object,
    observed_status: object,
    observed_is_verified_replacement_successor: bool = False,
) -> str:
    """Keep local cancellation ownership until the broker proves inactivity."""
    normalized_observed_status = str(observed_status or "unknown").lower()
    if (
        str(persisted_status or "").lower() == "pending_cancel"
        and normalized_observed_status in _ORDER_MAY_BE_ACTIVE_STATUSES
        and not observed_is_verified_replacement_successor
    ):
        return "pending_cancel"
    return normalized_observed_status


def _optional_int(value: object) -> int:
    if value is None or value == "" or pd.isna(value):
        return 0
    return int(value)


def _signal_workflow(signal: dict) -> str | None:
    return _optional_str(signal.get("Workflow"))


def _managed_remaining_qty(position: dict, buy_filled_qty: float) -> float:
    sold_qty = _optional_float(position.get("sold_qty")) or 0.0
    return float(buy_filled_qty) - sold_qty


def _managed_qty_tolerance(*quantities: float) -> float:
    scale = max((abs(float(quantity)) for quantity in quantities), default=0.0)
    return managed_quantity_tolerance(scale)


def _managed_value_tolerance(*values: float) -> float:
    scale = max((abs(float(value)) for value in values), default=0.0)
    return managed_value_reconciliation_tolerance(scale)


def _managed_sell_residual_mark_price(*prices: object) -> float:
    return max(
        (normalized_price for price in prices if (normalized_price := _optional_positive_float(price)) is not None),
        default=0.0,
    )


def _managed_sell_residual_is_negligible(
    remaining_qty: float,
    *quantity_scales: float,
    mark_price: float,
) -> bool:
    quantity_scale = max(
        (abs(float(quantity)) for quantity in (remaining_qty, *quantity_scales)),
        default=0.0,
    )
    normalized_mark_price = abs(float(mark_price))
    return managed_residual_quantity_is_negligible(
        remaining_qty,
        quantity_scale=quantity_scale,
        mark_price=normalized_mark_price,
        value_scale=quantity_scale * normalized_mark_price,
    )


def _managed_sell_is_complete(
    remaining_qty: float,
    *quantity_scales: float,
    mark_price: float,
) -> bool:
    return _managed_sell_residual_is_negligible(
        remaining_qty,
        *quantity_scales,
        mark_price=mark_price,
    )


def _managed_sell_quantities_match(
    left_qty: float,
    right_qty: float,
    *quantity_scales: float,
    mark_price: float,
) -> bool:
    return _managed_sell_residual_is_negligible(
        left_qty - right_qty,
        left_qty,
        right_qty,
        *quantity_scales,
        mark_price=mark_price,
    )


def _managed_sell_is_overfilled(
    remaining_qty: float,
    *quantity_scales: float,
    mark_price: float,
) -> bool:
    return remaining_qty < 0.0 and not _managed_sell_residual_is_negligible(
        remaining_qty,
        *quantity_scales,
        mark_price=mark_price,
    )


def _managed_sell_has_shortfall(
    remaining_qty: float,
    *quantity_scales: float,
    mark_price: float,
) -> bool:
    return remaining_qty > 0.0 and not _managed_sell_residual_is_negligible(
        remaining_qty,
        *quantity_scales,
        mark_price=mark_price,
    )


def _sell_fill_metadata(sell_order: dict) -> tuple[float, float | None, bool]:
    raw_filled_qty = sell_order.get("filled_qty")
    if not _broker_order_quantity_is_wire_canonical(
        raw_filled_qty,
        allow_zero=True,
    ):
        return 0.0, None, False
    try:
        filled_qty = _finite_float(raw_filled_qty)
    except (TypeError, ValueError):
        return 0.0, None, False

    if filled_qty == 0.0:
        return filled_qty, None, True
    filled_avg_price = _optional_positive_float(sell_order.get("filled_avg_price"))
    return filled_qty, filled_avg_price, filled_avg_price is not None


def _replacement_chain_fill_metadata(chain: list[dict]) -> tuple[float, float | None, bool]:
    """Aggregate generation-local fills across a validated replacement chain."""
    total_qty = 0.0
    total_value = 0.0
    for order in chain:
        filled_qty, filled_avg_price, metadata_is_valid = _sell_fill_metadata(order)
        if not metadata_is_valid:
            return 0.0, None, False
        order_status = _broker_order_status(order)
        if order_status in {"filled", "partially_filled"} and (filled_qty == 0.0 or filled_avg_price is None):
            return 0.0, None, False
        if filled_qty == 0.0:
            continue
        assert filled_avg_price is not None
        order_value = filled_qty * filled_avg_price
        next_total_qty = total_qty + filled_qty
        next_total_value = total_value + order_value
        if not all(isfinite(value) for value in (order_value, next_total_qty, next_total_value)):
            return 0.0, None, False
        total_qty = next_total_qty
        total_value = next_total_value
    if total_qty == 0.0:
        return total_qty, None, True
    average_price = total_value / total_qty
    if not isfinite(average_price):
        return 0.0, None, False
    return total_qty, average_price, True


def _replacement_chain_latest_broker_updated_at(chain: list[dict]) -> str | None:
    """Return the latest valid broker revision across an order lineage."""
    observed_updates = [_parse_alpaca_broker_datetime(order.get("updated_at")) for order in chain]
    # The aggregate average includes every generation. A timestamp from only
    # part of the lineage cannot safely order a correction to that aggregate.
    if not observed_updates or any(parsed is None for parsed in observed_updates):
        return None
    complete_updates = [parsed for parsed in observed_updates if parsed is not None]
    return max(complete_updates).isoformat(timespec="microseconds").replace("+00:00", "Z")


def _replacement_chain_oldest_broker_updated_at(chain: list[dict]) -> str | None:
    """Return the oldest component revision in one complete order lineage."""
    observed_updates = [_parse_alpaca_broker_datetime(order.get("updated_at")) for order in chain]
    if not observed_updates or any(parsed is None for parsed in observed_updates):
        return None
    complete_updates = [parsed for parsed in observed_updates if parsed is not None]
    return min(complete_updates).isoformat(timespec="microseconds").replace("+00:00", "Z")


def _replacement_chain_broker_component_revisions(
    chain: list[dict],
) -> dict[str, object] | None:
    """Return complete per-order revision and fill accounting for a buy lineage."""
    revisions: dict[str, object] = {}
    revision_timestamps: dict[str, str] = {}
    positive_fill_observed = False
    for order in chain:
        order_id = _optional_alpaca_broker_identifier(order.get("id"))
        updated_at = _parse_alpaca_broker_datetime(order.get("updated_at"))
        if order_id is None or updated_at is None or order_id in revisions:
            return None
        filled_qty, filled_avg_price, metadata_is_valid = _sell_fill_metadata(order)
        if not metadata_is_valid:
            return None
        filled_value = filled_qty * (0.0 if filled_avg_price is None else filled_avg_price)
        if not isfinite(filled_value) or filled_value < 0:
            return None
        positive_fill_observed = positive_fill_observed or filled_qty > 0.0
        broker_updated_at = updated_at.isoformat(timespec="microseconds").replace("+00:00", "Z")
        revision_timestamps[order_id] = broker_updated_at
        revisions[order_id] = {
            "broker_updated_at": broker_updated_at,
            "filled_qty": filled_qty,
            "filled_value": filled_value,
        }
    if revisions and not positive_fill_observed:
        # A true zero-fill lineage has no positive aggregate economics to
        # reconcile. Retain its component ordering timestamps without falsely
        # presenting zero values as a completed accounting summary.
        return revision_timestamps
    return revisions or None


def _replacement_chain_stable_asset_id(chain: list[dict]) -> str | None:
    """Return one complete immutable asset identity shared by every node."""
    asset_ids = [_optional_alpaca_broker_identifier(order.get("asset_id")) for order in chain]
    if any(asset_id is None for asset_id in asset_ids):
        return None
    unique_asset_ids = {asset_id for asset_id in asset_ids if asset_id is not None}
    return next(iter(unique_asset_ids)) if len(unique_asset_ids) == 1 else None


def _replacement_chain_nonnegative_filled_qty(chain: list[dict]) -> float | None:
    """Read cumulative quantity independently of status/average price for bust detection."""
    total_qty = 0.0
    for order in chain:
        raw_qty = order.get("filled_qty")
        if _broker_number_is_omitted(raw_qty):
            return None
        try:
            observed_qty = _finite_float(raw_qty)
        except (TypeError, ValueError):
            return None
        if observed_qty < 0:
            return None
        total_qty += observed_qty
    return total_qty


def _replacement_chain_nonnegative_filled_qty_decimal(
    chain: list[dict],
) -> Decimal | None:
    """Read an exact cumulative quantity before binary-float accounting."""
    quantities: list[Decimal] = []
    for order in chain:
        observed_qty = _optional_nonnegative_decimal(order.get("filled_qty"))
        if observed_qty is None:
            return None
        quantities.append(observed_qty)
    return _exact_decimal_sum(quantities)


def _buy_replacement_chain_fill_metadata_issue(
    replacement_chain: list[dict],
    *,
    expected_buy_qty: float | None,
) -> str | None:
    """Reject contradictory or over-intent buy fills without changing sell accounting."""
    _total_filled_qty, _total_filled_avg_price, fill_metadata_is_valid = _replacement_chain_fill_metadata(
        replacement_chain
    )
    exact_filled_quantities: list[Decimal] = []
    wire_quantity_is_invalid = False
    for order in replacement_chain:
        order_qty = _optional_positive_decimal(order.get("qty"))
        order_filled_qty = _optional_nonnegative_decimal(order.get("filled_qty"))
        if order_filled_qty is None:
            return (
                "Alpaca buy replacement chain contains an order without explicit, valid fill metadata; "
                "managed fill accounting requires reconciliation"
            )
        exact_filled_quantities.append(order_filled_qty)
        wire_quantity_is_invalid = bool(
            wire_quantity_is_invalid
            or not _broker_order_quantity_is_wire_canonical(order.get("qty"), allow_zero=False)
            or not _broker_order_quantity_is_wire_canonical(
                order.get("filled_qty"),
                allow_zero=True,
            )
        )
        if order_qty is not None and order_filled_qty > order_qty:
            return (
                "Alpaca buy order reports filled quantity above its order quantity; "
                "managed fill accounting requires reconciliation"
            )
        if _broker_order_status(order) == "filled" and (order_qty is None or order_filled_qty != order_qty):
            return (
                "Alpaca buy order reports a filled status without its full order quantity; "
                "managed fill accounting requires reconciliation"
            )
    expected_buy_qty_decimal = None if expected_buy_qty is None else _optional_positive_decimal(expected_buy_qty)
    if expected_buy_qty is not None and expected_buy_qty_decimal is None:
        return (
            "Alpaca buy replacement-chain fills cannot be compared with the immutable intended buy quantity; "
            "managed fill accounting requires reconciliation"
        )
    if expected_buy_qty_decimal is not None and _exact_decimal_sum(exact_filled_quantities) > expected_buy_qty_decimal:
        return (
            "Alpaca buy replacement-chain fills exceed the immutable intended buy quantity; "
            "managed fill accounting requires reconciliation"
        )
    if wire_quantity_is_invalid:
        return (
            "Alpaca buy replacement chain contains a quantity outside supported wire precision; "
            "managed fill accounting requires reconciliation"
        )
    if not fill_metadata_is_valid:
        return (
            "Alpaca buy replacement chain contains an order without explicit, valid fill metadata; "
            "managed fill accounting requires reconciliation"
        )
    return None


def _buy_replacement_chain_position_intent_issue(
    replacement_chain: list[dict],
) -> str | None:
    """Reject an explicit non-opening intent before managed-long accounting."""
    for generation, order in enumerate(replacement_chain):
        if not _optional_alpaca_position_intent_matches(
            order.get("position_intent"),
            expected=_ALPACA_MANAGED_BUY_POSITION_INTENT,
        ):
            return f"managed buy replacement generation {generation} has an incompatible position intent"
    return None


def _sell_order_identity_is_consistent(
    sell_order: dict,
    *,
    expected_sell_client_order_id: str,
    expected_sell_alpaca_order_id: str | None = None,
    expected_symbol: str | None = None,
    expected_alpaca_asset_id: str | None = None,
    replacement_chain: list[dict] | None = None,
) -> bool:
    """Prove immutable sell-lineage ownership without adopting its semantics.

    Position intent is deliberately validated by the frozen-intent helpers
    after attribution.  Keeping it out of this destructive-action boundary
    lets an exact managed lineage with an incompatible explicit intent be
    durably fenced and canceled instead of being left executable.
    """
    observed_client_order_id = _optional_str(sell_order.get("client_order_id"))
    observed_alpaca_order_id = _optional_alpaca_broker_identifier(sell_order.get("id"))
    chain = replacement_chain or [sell_order]
    replacement_is_valid = len(chain) > 1 and _replacement_chain_is_consistent(chain)
    known_replacement_successor = (
        expected_sell_alpaca_order_id is not None
        and observed_alpaca_order_id == expected_sell_alpaca_order_id
        and _optional_alpaca_broker_identifier(sell_order.get("replaces")) is not None
    )
    client_id_matches = observed_client_order_id == expected_sell_client_order_id or known_replacement_successor
    order_id_matches = expected_sell_alpaca_order_id is None or observed_alpaca_order_id in {
        None,
        expected_sell_alpaca_order_id,
    }
    persisted_order_belongs_to_chain = expected_sell_alpaca_order_id is None or expected_sell_alpaca_order_id in {
        _optional_alpaca_broker_identifier(node.get("id")) for node in chain
    }
    replacement_root_matches = _optional_str(chain[0].get("client_order_id")) == expected_sell_client_order_id
    return bool(
        (client_id_matches and order_id_matches or replacement_is_valid)
        and persisted_order_belongs_to_chain
        and replacement_root_matches
        and all(
            _order_matches_core_intent(
                node,
                expected_symbol=expected_symbol,
                expected_alpaca_asset_id=expected_alpaca_asset_id,
                expected_side="sell",
                expected_order_type="limit",
                expected_time_in_force="gtc",
                require_complete=True,
            )
            for node in chain
        )
    )


def _order_matches_core_intent(
    order: dict,
    *,
    expected_symbol: str | None,
    expected_alpaca_asset_id: str | None,
    expected_side: str,
    expected_order_type: str,
    expected_time_in_force: str,
    expected_position_intent: str | None = None,
    require_complete: bool = False,
) -> bool:
    """Validate invariant identity fields in an authoritative Alpaca order."""
    observed_asset_class = order.get("asset_class")
    if observed_asset_class is not None and observed_asset_class != _ALPACA_US_EQUITY_ASSET_CLASS:
        return False
    if require_complete and observed_asset_class != _ALPACA_US_EQUITY_ASSET_CLASS:
        return False
    raw_order_class = order.get("order_class")
    if raw_order_class is not None:
        if not isinstance(raw_order_class, str):
            return False
        observed_order_class = raw_order_class.strip().lower()
        if observed_order_class and observed_order_class != "simple":
            return False
    companion_legs = order.get("legs")
    if companion_legs is not None and companion_legs != []:
        return False
    observed_symbol = _optional_alpaca_equity_symbol(order.get("symbol"))
    observed_asset_id = _optional_alpaca_broker_identifier(order.get("asset_id"))
    observed_order_id = _optional_alpaca_broker_identifier(order.get("id"))
    if require_complete and (observed_order_id is None or observed_symbol is None or observed_asset_id is None):
        return False
    if expected_alpaca_asset_id is not None and (
        observed_asset_id is None or observed_asset_id != expected_alpaca_asset_id
    ):
        return False
    if (
        expected_alpaca_asset_id is None
        and expected_symbol is not None
        and observed_symbol is not None
        and observed_symbol.upper() != expected_symbol.upper()
    ):
        return False

    observed_side = _optional_str(order.get("side"))
    observed_type = _alpaca_order_type(order)
    observed_tif = _optional_str(order.get("time_in_force"))
    observed_position_intent = order.get("position_intent")
    observed_status = _broker_order_status(order) or None
    if require_complete and (
        observed_side is None or observed_type is None or observed_tif is None or observed_status is None
    ):
        return False
    if observed_side is not None and observed_side.lower() != expected_side:
        return False
    if observed_type is not None and observed_type.lower() != expected_order_type:
        return False
    if observed_tif is not None and observed_tif.lower() != expected_time_in_force:
        return False
    # Alpaca equity responses can omit this request field. When the broker does
    # echo it, however, an incompatible explicit intent must never be adopted.
    if expected_position_intent is not None and not _optional_alpaca_position_intent_matches(
        observed_position_intent,
        expected=expected_position_intent,
    ):
        return False
    if observed_status is not None and observed_status not in _ALPACA_ORDER_STATUSES:
        return False
    if require_complete:
        return bool(
            order.get("extended_hours") is False
            and _optional_positive_float(order.get("qty")) is not None
            and _optional_positive_float(order.get("limit_price")) is not None
        )
    return order.get("extended_hours") in {None, False}


def _replacement_chain_is_consistent(chain: list[dict]) -> bool:
    """Validate immutable replacement linkage, independent of lifecycle state.

    Keeping structural attribution separate from lifecycle validation allows a
    contradictory but core-attributed lineage to be durably quarantined and
    safely canceled instead of becoming unowned.
    """
    if not chain:
        return False
    seen_ids: set[str] = set()
    for index, order in enumerate(chain):
        order_id = _optional_alpaca_broker_identifier(order.get("id"))
        if order_id is None or order_id in seen_ids:
            return False
        seen_ids.add(order_id)
        if index == 0:
            continue
        prior_id = _optional_alpaca_broker_identifier(chain[index - 1].get("id"))
        if _optional_alpaca_broker_identifier(chain[index - 1].get("replaced_by")) != order_id:
            return False
        if _optional_alpaca_broker_identifier(order.get("replaces")) != prior_id:
            return False
    return True


def _replacement_chain_lifecycle_issue(chain: list[dict]) -> str | None:
    """Require every generation that names a successor to be literally replaced."""
    for generation, order in enumerate(chain[:-1]):
        if _broker_order_status(order) != "replaced":
            return f"broker buy replacement generation {generation} is not marked replaced"
    return None


def _buy_order_identity_issue(
    buy_order: dict,
    *,
    expected_client_order_id: str,
    expected_symbol: str | None,
    expected_alpaca_asset_id: str | None = None,
    expected_alpaca_order_id: str | None = None,
    expected_qty: int | float | Decimal | None = None,
    expected_limit_price: float | Decimal | None = None,
    replacement_chain: list[dict] | None = None,
    require_expected_intent: bool = False,
) -> str | None:
    if require_expected_intent and (expected_qty is None or expected_limit_price is None):
        return "managed buy intent is missing its immutable original quantity or limit price"
    observed_order_id = _optional_alpaca_broker_identifier(buy_order.get("id"))
    if observed_order_id is None:
        return "broker buy response has no order ID"

    chain = replacement_chain or [buy_order]
    replacement_is_valid = len(chain) > 1 and _replacement_chain_is_consistent(chain)
    observed_client_order_id = _optional_str(buy_order.get("client_order_id"))
    known_replacement_successor = (
        expected_alpaca_order_id is not None
        and observed_order_id == expected_alpaca_order_id
        and _optional_alpaca_broker_identifier(buy_order.get("replaces")) is not None
    )
    if (
        observed_client_order_id != expected_client_order_id
        and not replacement_is_valid
        and not known_replacement_successor
    ):
        return "broker buy response has a different client order ID"
    if expected_alpaca_order_id is not None and expected_alpaca_order_id not in {
        _optional_alpaca_broker_identifier(node.get("id")) for node in chain
    }:
        return "broker buy response has a different order ID"
    if not all(
        _order_matches_core_intent(
            node,
            expected_symbol=expected_symbol,
            expected_alpaca_asset_id=expected_alpaca_asset_id,
            expected_side="buy",
            expected_order_type="limit",
            expected_time_in_force="day",
            require_complete=True,
        )
        for node in chain
    ):
        return "broker buy response conflicts with the managed symbol, asset, side, or order type"
    if not all(
        _optional_alpaca_position_intent_matches(
            node.get("position_intent"),
            expected=_ALPACA_MANAGED_BUY_POSITION_INTENT,
        )
        for node in chain
    ):
        return "broker buy response has an incompatible position intent"

    root_client_order_id = _optional_str(chain[0].get("client_order_id"))
    if root_client_order_id != expected_client_order_id:
        return "broker buy replacement root has a different or missing client order ID"

    lifecycle_issue = _replacement_chain_lifecycle_issue(chain)
    if lifecycle_issue is not None:
        return lifecycle_issue

    expected_qty_decimal = None if expected_qty is None else _canonical_whole_share_qty(expected_qty)
    for node in chain:
        observed_qty = _optional_positive_decimal(node.get("qty"))
        if observed_qty is None:
            return "broker buy response has no valid positive quantity"
        if observed_qty != observed_qty.to_integral_value() or (
            expected_qty is not None and observed_qty != expected_qty_decimal
        ):
            return "broker buy response quantity conflicts with the submitted intent"
        observed_limit_price = _optional_positive_decimal(node.get("limit_price"))
        if observed_limit_price is None:
            return "broker buy response has no valid positive limit price"
        if _canonical_alpaca_limit_price(observed_limit_price) is None or (
            expected_limit_price is not None
            and not _limit_price_matches_frozen_intent(observed_limit_price, expected_limit_price)
        ):
            return "broker buy response limit price conflicts with the submitted intent"
    return None


def _validate_buy_order_identity(**kwargs: object) -> None:
    issue = _buy_order_identity_issue(**kwargs)
    if issue is not None:
        raise BuyOrderIdentityError(issue)


def _safely_attributed_buy_order_lineage(
    buy_order: dict,
    *,
    expected_client_order_id: str,
    expected_symbol: str | None,
    expected_alpaca_asset_id: str | None,
    expected_alpaca_order_id: str | None = None,
    replacement_chain: list[dict] | None = None,
) -> list[dict] | None:
    """Return a buy lineage only when immutable core identity proves ownership.

    Quantity and limit price are intentionally excluded: those are the
    mismatches that require cancellation.  Client lineage, stable asset,
    symbol, side, type, TIF, and regular-hours intent must all match before a
    destructive broker request is allowed.
    """
    chain = replacement_chain or [buy_order]
    if not chain or (len(chain) > 1 and not _replacement_chain_is_consistent(chain)):
        return None
    if _optional_str(chain[0].get("client_order_id")) != expected_client_order_id:
        return None
    if expected_alpaca_order_id is not None and expected_alpaca_order_id not in {
        _optional_alpaca_broker_identifier(node.get("id")) for node in chain
    }:
        return None
    if not all(
        _order_matches_core_intent(
            node,
            expected_symbol=expected_symbol,
            expected_alpaca_asset_id=expected_alpaca_asset_id,
            expected_side="buy",
            expected_order_type="limit",
            expected_time_in_force="day",
            require_complete=True,
        )
        for node in chain
    ):
        return None
    return chain


def _safely_attributed_buy_order_leaf(
    buy_order: dict,
    *,
    expected_client_order_id: str,
    expected_symbol: str | None,
    expected_alpaca_asset_id: str | None,
    expected_alpaca_order_id: str | None = None,
    replacement_chain: list[dict] | None = None,
) -> dict | None:
    """Return the attributed buy leaf for callers that only need its ID."""
    lineage = _safely_attributed_buy_order_lineage(
        buy_order,
        expected_client_order_id=expected_client_order_id,
        expected_symbol=expected_symbol,
        expected_alpaca_asset_id=expected_alpaca_asset_id,
        expected_alpaca_order_id=expected_alpaca_order_id,
        replacement_chain=replacement_chain,
    )
    if not lineage:
        return None
    leaf = lineage[-1]
    return leaf if _optional_alpaca_broker_identifier(leaf.get("id")) is not None else None


def _request_safely_attributed_order_cancellation(
    client: AlpacaClient,
    order: dict,
) -> tuple[bool, str]:
    """Cancel an already-attributed active order and describe the outcome.

    ``True`` means cancellation requires an authoritative follow-up (or already
    was pending).  Any request failure is deliberately treated as ambiguous:
    Alpaca may have received the request, and a later GET must establish the
    terminal outcome.  An already-inactive broker state is not relabeled.
    """
    order_id = _optional_alpaca_broker_identifier(order.get("id"))
    status = _broker_order_status(order, default="unknown")
    if order_id is None:
        return False, "attributed broker order has no order ID to cancel"
    if status in SELL_CANCEL_PENDING_STATUSES:
        return True, "broker cancellation is already pending"
    if status not in _ORDER_MAY_BE_ACTIVE_STATUSES:
        return False, f"broker order is {status} and is not cancellable"
    try:
        response = client.cancel_order(order_id)
        _require_2xx_response(response, expected_status=204)
    except (requests.exceptions.Timeout, requests.exceptions.ConnectionError) as exc:
        detail = _alpaca_client_exception_diagnostic(exc, client=client)
        return True, f"broker cancellation outcome is ambiguous after a transport failure: {detail}"
    except HTTPError as exc:
        detail = _alpaca_client_exception_diagnostic(exc, client=client)
        return True, f"broker cancellation outcome requires refresh after: {detail}"
    except requests.RequestException as exc:
        detail = _alpaca_client_exception_diagnostic(exc, client=client)
        return True, f"broker cancellation outcome is ambiguous after a request failure: {detail}"
    return True, "broker cancellation was requested"


def _request_safely_attributed_lineage_cancellations(
    client: AlpacaClient,
    replacement_chain: list[dict],
) -> tuple[bool, str]:
    """Neutralize every distinct potentially executable attributed generation."""
    unique_orders: list[dict] = []
    seen_order_ids: set[str] = set()
    for order in replacement_chain:
        order_id = _optional_alpaca_broker_identifier(order.get("id"))
        if order_id is None or order_id in seen_order_ids:
            continue
        seen_order_ids.add(order_id)
        unique_orders.append(order)

    cancellation_pending = False
    messages: list[str] = []
    for order in unique_orders:
        order_id = _optional_alpaca_broker_identifier(order.get("id"))
        pending, message = _request_safely_attributed_order_cancellation(client, order)
        cancellation_pending = cancellation_pending or pending
        messages.append(f"broker order {order_id}: {message}")
    if not messages:
        return False, "attributed broker replacement lineage has no cancellable order IDs"
    return cancellation_pending, "; ".join(messages)


def _attributed_lineage_requires_cancellation(replacement_chain: list[dict]) -> bool:
    return any(
        _optional_alpaca_broker_identifier(order.get("id")) is not None
        and _broker_order_status(order, default="unknown")
        in {*_ORDER_MAY_BE_ACTIVE_STATUSES, *SELL_CANCEL_PENDING_STATUSES}
        for order in replacement_chain
    )


def _attributed_lineage_has_cancellable_order(replacement_chain: list[dict]) -> bool:
    return any(
        _optional_alpaca_broker_identifier(order.get("id")) is not None
        and _broker_order_status(order, default="unknown") in _ORDER_MAY_BE_ACTIVE_STATUSES
        and _broker_order_status(order, default="unknown") not in SELL_CANCEL_PENDING_STATUSES
        for order in replacement_chain
    )


def _retry_pending_buy_lineage_cancellation(
    client: AlpacaClient,
    buy_order: dict,
    *,
    expected_client_order_id: str,
    expected_symbol: str,
    expected_alpaca_asset_id: str | None,
    expected_alpaca_order_id: str | None,
    replacement_chain: list[dict],
) -> tuple[bool, str]:
    """Retry every active node of a strictly attributed pending-cancel buy."""
    lineage = _safely_attributed_buy_order_lineage(
        buy_order,
        expected_client_order_id=expected_client_order_id,
        expected_symbol=expected_symbol,
        expected_alpaca_asset_id=expected_alpaca_asset_id,
        expected_alpaca_order_id=expected_alpaca_order_id,
        replacement_chain=replacement_chain,
    )
    if lineage is None:
        raise BuyOrderIdentityError("pending-cancel buy replacement lineage could not be strictly attributed")
    active_orders = [
        order for order in lineage if _broker_order_status(order, default="unknown") in _ORDER_MAY_BE_ACTIVE_STATUSES
    ]
    if not active_orders:
        return False, "all attributed buy replacement generations are terminal"
    _cancellation_pending, cancellation_message = _request_safely_attributed_lineage_cancellations(
        client, active_orders
    )
    # Broker cancellation acceptance is not terminal proof. Retain the local
    # quarantine until a later authoritative GET shows every lineage node is
    # inactive, including when DELETE itself returned successfully.
    return True, cancellation_message


def _request_deferred_buy_cancellation_if_owned(
    *,
    durable_quarantine_owned: bool,
    cancellation_deferred: bool,
    current_message: str | None,
    identity_issue: str | None,
    client: AlpacaClient,
    buy_order: dict,
    expected_client_order_id: str,
    expected_symbol: str,
    expected_alpaca_asset_id: str | None,
    expected_alpaca_order_id: str | None,
    replacement_chain: list[dict],
) -> str | None:
    if not durable_quarantine_owned or not cancellation_deferred:
        return current_message
    _pending, requested_message = _retry_pending_buy_lineage_cancellation(
        client,
        buy_order,
        expected_client_order_id=expected_client_order_id,
        expected_symbol=expected_symbol,
        expected_alpaca_asset_id=expected_alpaca_asset_id,
        expected_alpaca_order_id=expected_alpaca_order_id,
        replacement_chain=replacement_chain,
    )
    return f"{identity_issue}; {requested_message}" if identity_issue is not None else requested_message


def _buy_identity_issue_is_attributable_cancellation_issue(identity_issue: str) -> bool:
    """Return whether core identity is intact but exposure must be neutralized."""
    return any(
        marker in identity_issue
        for marker in {
            "managed buy intent is missing its immutable original quantity or limit price",
            "quantity conflicts with the submitted intent",
            "limit price conflicts with the submitted intent",
            "incompatible position intent",
            "replacement generation",
        }
    )


def _attributed_buy_identity_mismatch_quarantine_plan(
    buy_order: dict,
    *,
    identity_issue: str,
    expected_client_order_id: str,
    expected_symbol: str | None,
    expected_alpaca_asset_id: str | None,
    expected_alpaca_order_id: str | None = None,
    replacement_chain: list[dict] | None = None,
) -> tuple[str, str | None, list[dict] | None, str]:
    """Plan a buy quarantine without causing a broker side effect."""
    if not _buy_identity_issue_is_attributable_cancellation_issue(identity_issue):
        return (
            "identity_mismatch",
            None,
            None,
            "broker cancellation was not requested because a cancellable core-identity mismatch was not proven",
        )
    lineage = _safely_attributed_buy_order_lineage(
        buy_order,
        expected_client_order_id=expected_client_order_id,
        expected_symbol=expected_symbol,
        expected_alpaca_asset_id=expected_alpaca_asset_id,
        expected_alpaca_order_id=expected_alpaca_order_id,
        replacement_chain=replacement_chain,
    )
    if not lineage:
        return (
            "identity_mismatch",
            None,
            None,
            "broker order was not canceled or bound because its core managed identity was not proven",
        )
    leaf = lineage[-1]
    if _attributed_lineage_requires_cancellation(lineage):
        return (
            "pending_cancel",
            _optional_alpaca_broker_identifier(leaf.get("id")),
            lineage,
            "broker cancellation awaits durable local quarantine ownership",
        )
    return (
        "identity_mismatch",
        _optional_alpaca_broker_identifier(leaf.get("id")),
        lineage,
        "all attributed buy replacement generations are terminal",
    )


def _quarantine_attributed_buy_identity_mismatch(
    client: AlpacaClient,
    buy_order: dict,
    *,
    identity_issue: str,
    expected_client_order_id: str,
    expected_symbol: str | None,
    expected_alpaca_asset_id: str | None,
    expected_alpaca_order_id: str | None = None,
    replacement_chain: list[dict] | None = None,
) -> tuple[str, str | None, str]:
    """Cancel a core-identity-proven buy lineage and retain its leaf ID."""
    status, leaf_id, lineage, message = _attributed_buy_identity_mismatch_quarantine_plan(
        buy_order,
        identity_issue=identity_issue,
        expected_client_order_id=expected_client_order_id,
        expected_symbol=expected_symbol,
        expected_alpaca_asset_id=expected_alpaca_asset_id,
        expected_alpaca_order_id=expected_alpaca_order_id,
        replacement_chain=replacement_chain,
    )
    if status != "pending_cancel" or lineage is None:
        return status, leaf_id, message
    cancellation_pending, cancellation_message = _request_safely_attributed_lineage_cancellations(client, lineage)
    return "pending_cancel" if cancellation_pending else "identity_mismatch", leaf_id, cancellation_message


def _sell_order_matches_submission_intent(
    sell_order: dict,
    *,
    requested_qty: float,
    target_sell_price: float,
) -> bool:
    observed_qty = _optional_positive_decimal(sell_order.get("qty"))
    expected_qty = _optional_positive_decimal(requested_qty)
    return bool(
        observed_qty is not None
        and expected_qty is not None
        and _broker_order_quantity_is_wire_canonical(
            sell_order.get("qty"),
            allow_zero=False,
        )
        and observed_qty == expected_qty
        and _limit_price_matches_frozen_intent(sell_order.get("limit_price"), target_sell_price)
        and _optional_alpaca_position_intent_matches(
            sell_order.get("position_intent"),
            expected=_ALPACA_MANAGED_SELL_POSITION_INTENT,
        )
    )


def _sell_replacement_chain_position_intent_issue(
    replacement_chain: list[dict],
) -> str | None:
    """Reject only an explicit non-closing intent, before managed fill accounting."""
    for generation, order in enumerate(replacement_chain):
        if not _optional_alpaca_position_intent_matches(
            order.get("position_intent"),
            expected=_ALPACA_MANAGED_SELL_POSITION_INTENT,
        ):
            return f"managed sell replacement generation {generation} has an incompatible position intent"
    return None


def _sell_replacement_chain_intent_issue(
    replacement_chain: list[dict],
    *,
    requested_qty: float,
    target_sell_price: float,
    validate_position_intent: bool = True,
) -> str | None:
    """Validate every broker-created successor against the frozen sell intent."""
    if not replacement_chain:
        return "Alpaca returned an empty managed sell replacement chain"
    requested_order_qty = _optional_positive_decimal(requested_qty)
    if requested_order_qty is None:
        return "managed sell intent has no valid positive submitted quantity"

    expected_generation_qty = requested_order_qty
    for generation, order in enumerate(replacement_chain):
        if validate_position_intent and not _optional_alpaca_position_intent_matches(
            order.get("position_intent"),
            expected=_ALPACA_MANAGED_SELL_POSITION_INTENT,
        ):
            return f"managed sell replacement generation {generation} has an incompatible position intent"
        observed_qty = _optional_positive_decimal(order.get("qty"))
        if observed_qty is None:
            return f"managed sell replacement generation {generation} has no valid positive quantity"
        if not _broker_order_quantity_is_wire_canonical(
            order.get("qty"),
            allow_zero=False,
        ):
            return f"managed sell replacement generation {generation} has a quantity outside supported wire precision"
        if observed_qty != expected_generation_qty:
            return (
                f"managed sell replacement generation {generation} quantity {observed_qty} "
                f"does not match the prior generation remainder {expected_generation_qty}"
            )

        observed_limit_price = _optional_positive_float(order.get("limit_price"))
        if not _limit_price_matches_frozen_intent(order.get("limit_price"), target_sell_price):
            return f"managed sell replacement generation {generation} limit price does not match the frozen target"

        generation_filled_decimal = _optional_nonnegative_decimal(order.get("filled_qty"))
        if generation_filled_decimal is None:
            return f"managed sell replacement generation {generation} has invalid fill metadata"
        if generation_filled_decimal > observed_qty:
            return f"managed sell replacement generation {generation} filled quantity exceeds its order quantity"
        if not _broker_order_quantity_is_wire_canonical(
            order.get("filled_qty"),
            allow_zero=True,
        ):
            return (
                f"managed sell replacement generation {generation} has a filled quantity "
                "outside supported wire precision"
            )
        _, generation_filled_avg_price, fill_metadata_is_valid = _sell_fill_metadata(order)
        if not fill_metadata_is_valid:
            # The reconciliation paths report this more specific condition as
            # incomplete fill metadata before acting on the intent diagnostic.
            return f"managed sell replacement generation {generation} has invalid fill metadata"
        fill_mark_price = _managed_sell_residual_mark_price(
            target_sell_price,
            generation_filled_avg_price,
            observed_limit_price,
        )
        order_status = _broker_order_status(order)
        if generation < len(replacement_chain) - 1:
            if order_status != "replaced":
                return f"managed sell replacement generation {generation} is not marked replaced"
            expected_generation_qty = _exact_decimal_difference(observed_qty, generation_filled_decimal)
            expected_generation_qty_float = float(expected_generation_qty)
            if expected_generation_qty <= 0 or _managed_sell_is_complete(
                expected_generation_qty_float,
                float(requested_order_qty),
                mark_price=fill_mark_price,
            ):
                return "managed sell replacement chain continues after the prior generation was fully filled"
    return None


def _sell_replacement_chain_non_fill_intent_issue(
    replacement_chain: list[dict],
    *,
    requested_qty: float,
    target_sell_price: float,
    validate_position_intent: bool = True,
) -> str | None:
    """Find quantity, price, or lifecycle defects despite missing fill data.

    The primary intent validator deliberately reports the first malformed fill
    so callers can produce the most specific accounting diagnostic. Recovery
    still needs to inspect the rest of an attributed live lineage before
    deciding that missing fill metadata is the *only* problem: an executable
    non-leaf or a later price mismatch must be durably fenced and canceled.
    """
    if not replacement_chain:
        return "Alpaca returned an empty managed sell replacement chain"
    expected_generation_qty = _optional_positive_decimal(requested_qty)
    if expected_generation_qty is None:
        return "managed sell intent has no valid positive submitted quantity"
    maximum_generation_qty = expected_generation_qty

    for generation, order in enumerate(replacement_chain):
        if validate_position_intent and not _optional_alpaca_position_intent_matches(
            order.get("position_intent"),
            expected=_ALPACA_MANAGED_SELL_POSITION_INTENT,
        ):
            return f"managed sell replacement generation {generation} has an incompatible position intent"
        observed_qty = _optional_positive_decimal(order.get("qty"))
        if observed_qty is None:
            return f"managed sell replacement generation {generation} has no valid positive quantity"
        if not _broker_order_quantity_is_wire_canonical(order.get("qty"), allow_zero=False):
            return f"managed sell replacement generation {generation} has a quantity outside supported wire precision"
        if expected_generation_qty is not None:
            if observed_qty != expected_generation_qty:
                return (
                    f"managed sell replacement generation {generation} quantity {observed_qty} "
                    f"does not match the prior generation remainder {expected_generation_qty}"
                )
        elif observed_qty > maximum_generation_qty:
            return (
                f"managed sell replacement generation {generation} quantity {observed_qty} "
                f"exceeds the prior generation quantity {maximum_generation_qty}"
            )
        if not _limit_price_matches_frozen_intent(order.get("limit_price"), target_sell_price):
            return f"managed sell replacement generation {generation} limit price does not match the frozen target"

        generation_filled_decimal = _optional_nonnegative_decimal(order.get("filled_qty"))
        fill_is_usable_for_lineage = bool(
            generation_filled_decimal is not None
            and generation_filled_decimal <= observed_qty
            and _broker_order_quantity_is_wire_canonical(order.get("filled_qty"), allow_zero=True)
        )
        if generation < len(replacement_chain) - 1:
            if _broker_order_status(order) != "replaced":
                return f"managed sell replacement generation {generation} is not marked replaced"
            if not fill_is_usable_for_lineage:
                expected_generation_qty = None
                maximum_generation_qty = observed_qty
                continue
            assert generation_filled_decimal is not None
            expected_generation_qty = _exact_decimal_difference(observed_qty, generation_filled_decimal)
            maximum_generation_qty = expected_generation_qty
            if expected_generation_qty <= 0 or _managed_sell_is_complete(
                float(expected_generation_qty),
                float(requested_qty),
                mark_price=target_sell_price,
            ):
                return "managed sell replacement chain continues after the prior generation was fully filled"
    return None


def _append_incomplete_sell_fill_result(
    *,
    conn: sqlite3.Connection,
    rows: list[dict],
    position_id: int,
    symbol: str,
    buy_client_order_id: str,
    sell_client_order_id: str | None,
    observed_sell_qty: float,
    target_sell_price: float,
    sell_alpaca_order_id: str | None,
    expected_renewal_snapshot: AlpacaManagedSellRenewalSnapshot | None = None,
) -> bool:
    status_updated = bool(sell_client_order_id) and update_alpaca_managed_sell_status_if_current(
        conn,
        position_id,
        expected_sell_client_order_id=sell_client_order_id or "",
        **_renewal_snapshot_cas_kwargs(expected_renewal_snapshot),
        sell_status="incomplete_fill_metadata",
        notes=_alpaca_durable_diagnostic_note(
            "Alpaca reported a partial managed sell fill without a valid average fill price; "
            "automatic renewal is blocked pending manual review",
            cfg=None,
        ),
    )
    _append_reconciliation_result(
        rows,
        position_id=position_id,
        symbol=symbol,
        action="sell",
        status="incomplete_fill_metadata" if status_updated else "superseded",
        buy_client_order_id=buy_client_order_id,
        sell_client_order_id=sell_client_order_id,
        qty=observed_sell_qty,
        limit_price=target_sell_price,
        alpaca_order_id=sell_alpaca_order_id,
        message=(
            "managed sell fill is missing a valid average price; automatic renewal is blocked for review"
            if status_updated
            else "fill observation belongs to a superseded managed GTC sell generation"
        ),
        required_failure=status_updated,
    )
    return status_updated


