def _append_active_sell_completion_mismatch_result(
    *,
    conn: sqlite3.Connection,
    client: AlpacaClient,
    rows: list[dict],
    position_id: int,
    symbol: str,
    buy_client_order_id: str,
    sell_client_order_id: str,
    observed_sell_qty: float,
    target_sell_price: float,
    sell_order: dict,
    replacement_chain: list[dict] | None = None,
    expected_renewal_snapshot: AlpacaManagedSellRenewalSnapshot | None = None,
) -> None:
    lineage = replacement_chain or [sell_order]
    sell_alpaca_order_id = _optional_str(lineage[-1].get("id"))
    if expected_renewal_snapshot is None:
        cancellation_pending = _attributed_lineage_requires_cancellation(lineage)
        cancellation_message = "broker cancellation was not requested without an exact managed-state snapshot"
        diagnostic_status = "pending_cancel" if cancellation_pending else "quantity_mismatch"
        status_updated = False
    else:
        cancellation_pending = _attributed_lineage_requires_cancellation(lineage)
        diagnostic_status = "pending_cancel" if cancellation_pending else "quantity_mismatch"
        cancellation_requested_at = _utc_now().isoformat().replace("+00:00", "Z") if cancellation_pending else None
        status_updated = update_alpaca_managed_sell_status_if_current(
            conn,
            position_id,
            expected_sell_client_order_id=sell_client_order_id,
            **_renewal_snapshot_cas_kwargs(expected_renewal_snapshot),
            sell_status=diagnostic_status,
            sell_renewal_requested_at=cancellation_requested_at,
            notes=_alpaca_durable_diagnostic_note(
                "managed sell cumulative fills cover the position but Alpaca still reports an active order; "
                "position closure is blocked pending review; cancellation ownership was fenced",
                cfg=client.cfg,
                client=client,
            ),
        )
        cancellation_message = "broker cancellation was not requested because renewal ownership changed"
        if status_updated and cancellation_pending:
            cancellation_pending, cancellation_message = _request_safely_attributed_lineage_cancellations(
                client, lineage
            )
        elif status_updated:
            cancellation_message = "attributed broker lineage has no active order to cancel"
    _append_reconciliation_result(
        rows,
        position_id=position_id,
        symbol=symbol,
        action="sell",
        status=diagnostic_status if status_updated else "superseded",
        buy_client_order_id=buy_client_order_id,
        sell_client_order_id=sell_client_order_id,
        qty=observed_sell_qty,
        limit_price=target_sell_price,
        alpaca_order_id=sell_alpaca_order_id,
        message=(
            "managed quantity is fully sold but the broker order remains active; "
            f"closure is blocked for review; {cancellation_message}"
            if status_updated
            else "active-order completion mismatch belongs to a superseded managed GTC sell generation"
        ),
        required_failure=status_updated,
    )


def _append_sell_submission_intent_mismatch_result(
    *,
    conn: sqlite3.Connection,
    client: AlpacaClient,
    rows: list[dict],
    position_id: int,
    symbol: str,
    buy_client_order_id: str,
    sell_client_order_id: str,
    requested_qty: float,
    target_sell_price: float,
    sell_order: dict,
    replacement_chain: list[dict] | None = None,
    intent_issue: str | None = None,
    expected_renewal_snapshot: AlpacaManagedSellRenewalSnapshot | None = None,
) -> None:
    lineage = replacement_chain or [sell_order]
    leaf = lineage[-1]
    sell_alpaca_order_id = _optional_str(leaf.get("id"))
    observed_order_qty = _optional_positive_float(sell_order.get("qty"))
    diagnostic = intent_issue or ("replacement order quantity or limit price conflicts with the submitted intent")
    if expected_renewal_snapshot is None:
        cancellation_pending = _attributed_lineage_requires_cancellation(lineage)
        cancellation_message = "broker cancellation was not requested without an exact managed-state snapshot"
        diagnostic_status = "pending_cancel" if cancellation_pending else "quantity_mismatch"
        status_updated = False
    else:
        cancellation_pending = _attributed_lineage_requires_cancellation(lineage)
        diagnostic_status = "pending_cancel" if cancellation_pending else "quantity_mismatch"
        cancellation_requested_at = _utc_now().isoformat().replace("+00:00", "Z") if cancellation_pending else None
        status_updated = update_alpaca_managed_sell_status_if_current(
            conn,
            position_id,
            expected_sell_client_order_id=sell_client_order_id,
            **_renewal_snapshot_cas_kwargs(expected_renewal_snapshot),
            sell_status=diagnostic_status,
            sell_alpaca_order_id=sell_alpaca_order_id,
            sell_order_qty=observed_order_qty,
            allow_diagnostic_sell_intent_mismatch=True,
            sell_renewal_requested_at=cancellation_requested_at,
            notes=_alpaca_durable_diagnostic_note(
                f"{diagnostic}; cancellation ownership was fenced before any broker request; "
                "replacement is blocked until cancellation is confirmed",
                cfg=client.cfg,
                client=client,
            ),
        )
        cancellation_message = "broker cancellation was not requested because renewal ownership changed"
        if status_updated and cancellation_pending:
            cancellation_pending, cancellation_message = _request_safely_attributed_lineage_cancellations(
                client, lineage
            )
        elif status_updated:
            cancellation_message = "attributed broker lineage has no active order to cancel"
    _append_reconciliation_result(
        rows,
        position_id=position_id,
        symbol=symbol,
        action="sell",
        status=diagnostic_status if status_updated else "superseded",
        buy_client_order_id=buy_client_order_id,
        sell_client_order_id=sell_client_order_id,
        qty=requested_qty,
        limit_price=target_sell_price,
        alpaca_order_id=sell_alpaca_order_id,
        message=(
            f"{diagnostic}; {cancellation_message}; review required"
            if status_updated
            else "submission-intent mismatch belongs to a superseded managed GTC sell generation"
        ),
        required_failure=status_updated,
    )


def _response_json(
    resp: requests.Response,
    *,
    validate_order_timestamps: bool = True,
) -> dict:
    _require_2xx_response(resp)
    try:
        payload = _strict_alpaca_response_json(resp)
    except (
        _DuplicateAlpacaJsonKeyError,
        _ExcessiveAlpacaJsonNestingError,
        _ExcessiveAlpacaJsonStructureError,
        _InvalidAlpacaJsonConstantError,
    ):
        raise
    except ValueError:
        return {}
    if not isinstance(payload, dict):
        return {}
    _validate_alpaca_order_payload_identifiers(
        payload,
        validate_timestamps=validate_order_timestamps,
    )
    return payload


def _require_2xx_response(
    resp: requests.Response,
    *,
    expected_status: int = 200,
) -> None:
    """Require one endpoint's exact successful HTTP status."""
    status_code = getattr(resp, "status_code", None)
    raw_headers = getattr(resp, "headers", None)
    has_content_range = isinstance(raw_headers, Mapping) and any(
        isinstance(name, str) and name.casefold() == "content-range" for name in raw_headers
    )
    if (type(status_code) is int and status_code == 206) or (
        type(status_code) is int and 200 <= status_code < 300 and has_content_range
    ):
        detail = (
            "partial HTTP status 206"
            if status_code == 206
            else f"unexpected Content-Range on HTTP status {status_code}"
        )
        error = HTTPError(f"Alpaca returned {detail}")
        error.response = resp
        raise error
    if type(status_code) is int and status_code == expected_status:
        return
    try:
        resp.raise_for_status()
    except HTTPError:
        raise
    error = HTTPError(f"Alpaca returned unexpected HTTP status {status_code}")
    error.response = resp
    raise error


def _utc_now() -> datetime:
    return datetime.now(UTC)


def _market_clock_now() -> datetime:
    """Return current UTC time at a broker buy-authorization boundary."""
    return _utc_now()


@dataclass(frozen=True)
class _BuySubmissionDispatchAuthorization:
    next_open: datetime
    broker_clock_timestamp: datetime
    observed_host_time: datetime
    observed_monotonic: float
    dispatch_deadline_monotonic: float
    request_write_deadline_monotonic: float
    request_timeout_seconds: int


def _buy_submission_dispatch_authorization(
    *,
    next_open: datetime,
    broker_clock_timestamp: datetime,
    request_timeout_seconds: int,
    broker_clock_request_started_monotonic: float | None = None,
) -> _BuySubmissionDispatchAuthorization:
    """Anchor broker and host time to monotonic pre-open dispatch deadlines."""
    observed_monotonic = _monotonic_now()
    if not math.isfinite(observed_monotonic):
        raise RuntimeError("Current monotonic time must be finite")
    host_now = _market_clock_now()
    if host_now.tzinfo is None or host_now.utcoffset() is None:
        raise RuntimeError("Current UTC time must be timezone-aware")
    if next_open.tzinfo is None or next_open.utcoffset() is None:
        raise ValueError("Authorized Alpaca next-open time must be timezone-aware")
    if broker_clock_timestamp.tzinfo is None or broker_clock_timestamp.utcoffset() is None:
        raise ValueError("Authorized Alpaca clock timestamp must be timezone-aware")
    if type(request_timeout_seconds) is not int or request_timeout_seconds <= 0:
        raise ValueError("Alpaca request timeout must be a positive integer")
    next_open_utc = next_open.astimezone(UTC)
    broker_now_utc = broker_clock_timestamp.astimezone(UTC)
    host_now_utc = host_now.astimezone(UTC)
    if broker_clock_request_started_monotonic is not None:
        if not math.isfinite(broker_clock_request_started_monotonic):
            raise ValueError("Alpaca clock-request monotonic time must be finite")
        if broker_clock_request_started_monotonic > observed_monotonic:
            raise ValueError("Alpaca clock-request monotonic time cannot be after authorization")
        # The broker timestamp was produced no earlier than request start. Use
        # that earliest possible instant so all clock-request latency counts
        # against the pre-open budget even when the host clock trails Alpaca.
        broker_now_utc += timedelta(seconds=observed_monotonic - broker_clock_request_started_monotonic)
    authoritative_now = max(broker_now_utc, host_now_utc)
    seconds_until_open = (next_open_utc - authoritative_now).total_seconds()
    request_write_deadline = (
        observed_monotonic + seconds_until_open - _ALPACA_BUY_REQUEST_DISPATCH_GRACE.total_seconds()
    )
    return _BuySubmissionDispatchAuthorization(
        next_open=next_open_utc,
        broker_clock_timestamp=broker_now_utc,
        observed_host_time=host_now_utc,
        observed_monotonic=observed_monotonic,
        dispatch_deadline_monotonic=request_write_deadline - request_timeout_seconds,
        request_write_deadline_monotonic=request_write_deadline,
        request_timeout_seconds=request_timeout_seconds,
    )


def _buy_submission_authorization_window_elapsed(
    authorization: _BuySubmissionDispatchAuthorization,
) -> bool:
    """Recheck the deadline without allowing wall-clock rollback or skew."""
    monotonic_now = _monotonic_now()
    if not math.isfinite(monotonic_now):
        raise RuntimeError("Current monotonic time must be finite")
    elapsed_seconds = max(monotonic_now - authorization.observed_monotonic, 0.0)
    broker_estimate = authorization.broker_clock_timestamp + timedelta(seconds=elapsed_seconds)
    host_now = _market_clock_now()
    if host_now.tzinfo is None or host_now.utcoffset() is None:
        raise RuntimeError("Current UTC time must be timezone-aware")
    authoritative_now = max(host_now.astimezone(UTC), broker_estimate)
    wall_clock_elapsed = (
        authoritative_now
        + timedelta(seconds=authorization.request_timeout_seconds)
        + _ALPACA_BUY_REQUEST_DISPATCH_GRACE
        >= authorization.next_open
    )
    return monotonic_now >= authorization.dispatch_deadline_monotonic or wall_clock_elapsed


def _buy_submission_dispatch_window_elapsed(
    now: datetime,
    authorized_next_open: datetime,
    *,
    request_timeout_seconds: int,
    broker_clock_timestamp: datetime | None = None,
) -> bool:
    """Reserve enough pre-open time for the configured request dispatch."""
    if now.tzinfo is None or now.utcoffset() is None:
        raise RuntimeError("Current UTC time must be timezone-aware")
    if authorized_next_open.tzinfo is None or authorized_next_open.utcoffset() is None:
        raise ValueError("Authorized Alpaca next-open time must be timezone-aware")
    broker_now = now if broker_clock_timestamp is None else broker_clock_timestamp
    if broker_now.tzinfo is None or broker_now.utcoffset() is None:
        raise ValueError("Authorized Alpaca clock timestamp must be timezone-aware")
    dispatch_margin = timedelta(seconds=request_timeout_seconds) + _ALPACA_BUY_REQUEST_DISPATCH_GRACE
    authoritative_now = max(now.astimezone(UTC), broker_now.astimezone(UTC))
    return authoritative_now + dispatch_margin >= authorized_next_open.astimezone(UTC)


def _parse_alpaca_datetime(value: object) -> datetime | None:
    """Parse persisted/local timestamps, including legacy timezone-naive rows."""
    text = _optional_str(value)
    if text is None:
        return None
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
        if parsed.tzinfo is None:
            return parsed.replace(tzinfo=UTC)
        return parsed.astimezone(UTC)
    except (ValueError, OverflowError):
        return None


def _parse_alpaca_broker_datetime(value: object) -> datetime | None:
    """Parse an authoritative broker timestamp without guessing its timezone."""
    text = _optional_str(value)
    if text is None:
        return None
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
        if parsed.tzinfo is None or parsed.utcoffset() is None:
            return None
        return parsed.astimezone(UTC)
    except (ValueError, OverflowError):
        return None


def _parse_alpaca_clock_datetime(value: object) -> datetime | None:
    """Decode an authoritative clock time without guessing a missing zone."""
    return _parse_alpaca_broker_datetime(value)


def _optional_alpaca_datetime_str(value: object) -> str | None:
    text = _optional_str(value)
    return text if text is not None and _parse_alpaca_broker_datetime(text) is not None else None


def _sell_order_matches_intent_chronology(
    sell_order: dict,
    intent_not_before: str | None,
) -> bool:
    if intent_not_before is None:
        return True
    intent_boundary = _parse_alpaca_datetime(intent_not_before)
    submitted_at = _parse_alpaca_broker_datetime(sell_order.get("submitted_at"))
    return bool(intent_boundary is not None and submitted_at is not None and submitted_at >= intent_boundary)


def _buy_submission_visibility_lease_active(position: dict, cfg: AlpacaOrderConfig) -> bool:
    """Keep a claimed buy intent active while Alpaca may still expose it late."""
    claimed_at = _parse_alpaca_datetime(position.get("buy_submission_claimed_at"))
    if claimed_at is None:
        claimed_at = _parse_alpaca_datetime(position.get("created_at"))
    # A row without a usable local timestamp cannot safely prove that the
    # broker has not accepted the order, so leave it active for review.
    if claimed_at is None:
        return True
    lease = max(
        _BUY_SUBMISSION_VISIBILITY_LEASE,
        timedelta(seconds=max(cfg.timeout_seconds, 0) + 60),
    )
    return _utc_now() < claimed_at + lease


def _validated_alpaca_calendar_session_dates(
    calendar: object,
    *,
    start: date | None = None,
    end: date | None = None,
    required_session: date | None = None,
) -> list[date]:
    """Decode a complete, strictly ordered authoritative calendar response."""
    if not isinstance(calendar, list) or not all(isinstance(session, dict) for session in calendar):
        raise ValueError("Alpaca calendar returned an invalid response")
    if start is not None and end is not None and start > end:
        raise ValueError("Alpaca calendar request start must not follow its end")

    session_dates: list[date] = []
    for index, session in enumerate(calendar):
        raw_date = session.get("date")
        if not isinstance(raw_date, str) or raw_date != raw_date.strip():
            raise ValueError(f"Alpaca calendar session {index} did not provide a canonical date")
        try:
            session_date = date.fromisoformat(raw_date)
        except ValueError as exc:
            raise ValueError(f"Alpaca calendar session {index} did not provide a canonical date") from exc
        if raw_date != session_date.isoformat():
            raise ValueError(f"Alpaca calendar session {index} did not provide a canonical date")
        if (start is not None and session_date < start) or (end is not None and session_date > end):
            raise ValueError("Alpaca calendar returned a session outside the requested date range")
        if session_dates and session_date <= session_dates[-1]:
            issue = "duplicate" if session_date == session_dates[-1] else "out-of-order"
            raise ValueError(f"Alpaca calendar returned {issue} session dates")
        session_dates.append(session_date)

    if required_session is not None and required_session not in session_dates:
        raise ValueError("Alpaca calendar did not cover the required next-open session")
    return session_dates


def _prior_calendar_session(calendar: list[dict], next_open: datetime) -> date | None:
    next_open_date = next_open.astimezone(_NEW_YORK).date()
    sessions = _validated_alpaca_calendar_session_dates(
        calendar,
        end=next_open_date,
        required_session=next_open_date,
    )
    prior_sessions = [session_date for session_date in sessions if session_date < next_open_date]
    return prior_sessions[-1] if prior_sessions else None


def _validated_market_clock_is_open(clock: dict) -> bool:
    is_open = clock.get("is_open")
    if type(is_open) is not bool:
        raise ValueError("Alpaca clock did not provide a literal boolean is_open value")
    return is_open


def _validated_market_clock_times(
    clock: dict,
    *,
    require_current: bool = False,
) -> tuple[datetime, datetime]:
    next_open = _parse_alpaca_clock_datetime(clock.get("next_open"))
    if next_open is None:
        raise ValueError("Alpaca clock did not provide a valid timezone-bearing next_open timestamp")
    clock_timestamp = _parse_alpaca_clock_datetime(clock.get("timestamp"))
    if clock_timestamp is None:
        raise ValueError("Alpaca clock did not provide a valid timezone-bearing timestamp")
    if next_open <= clock_timestamp:
        raise ValueError("Alpaca clock next_open must be strictly after its timestamp")
    if require_current:
        now = _market_clock_now()
        if now.tzinfo is None or now.utcoffset() is None:
            raise RuntimeError("Current UTC time must be timezone-aware")
        skew = clock_timestamp - now.astimezone(UTC)
        if abs(skew) > _ALPACA_MARKET_CLOCK_MAX_SKEW:
            direction = "future" if skew > timedelta(0) else "stale"
            raise ValueError(
                f"Alpaca clock timestamp is {direction} relative to current UTC time "
                f"by more than {_ALPACA_MARKET_CLOCK_MAX_SKEW.total_seconds():g} seconds"
            )
    return next_open, clock_timestamp


def _buy_submission_window(
    clock: dict,
    signal_date: str,
    prior_session: date | None,
) -> tuple[bool, str]:
    """Allow only the exact prior-session signal in the premarket window."""
    market_is_open = _validated_market_clock_is_open(clock)
    next_open, clock_timestamp = _validated_market_clock_times(clock, require_current=True)
    if market_is_open:
        return False, "market is open; close-based buy deferred until the next closed submission window"

    now = _market_clock_now().astimezone(UTC)
    if now >= next_open:
        raise ValueError("Alpaca clock no longer authorizes a buy before its reported next open")

    try:
        signal_session = pd.Timestamp(signal_date).date()
    except (TypeError, ValueError) as exc:
        raise ValueError(f"Buy signal has an invalid date: {signal_date!r}") from exc

    next_open_session = next_open.astimezone(_NEW_YORK).date()
    current_session = clock_timestamp.astimezone(_NEW_YORK).date()
    actual_session = now.astimezone(_NEW_YORK).date()
    if next_open_session != current_session or next_open_session != actual_session:
        return False, "buy submissions are limited to the premarket window for the next regular-session open"
    if prior_session is None:
        raise ValueError("Alpaca calendar did not provide a prior trading session")
    if signal_session != prior_session:
        return False, "signal date is not the immediately preceding trading session"
    return True, ""


def _gtc_sell_renewal_due(
    sell_order: dict,
    cfg: AlpacaOrderConfig,
    *,
    persisted_expires_at: object = None,
) -> bool:
    if not cfg.gtc_sell_renewal_enabled or cfg.gtc_sell_renewal_days_before_expiration < 0:
        return False

    sell_status = _broker_order_status(sell_order)
    if sell_status not in SELL_RENEWABLE_STATUSES:
        return False

    raw_broker_expires_at = sell_order.get("expires_at")
    expires_at = _parse_alpaca_broker_datetime(raw_broker_expires_at)
    if raw_broker_expires_at is not None and expires_at is None:
        # A present authoritative value cannot be replaced by older local
        # state. The response boundary normally raises first; direct helper
        # callers must still fail closed rather than authorizing cancellation.
        return False
    if expires_at is None:
        expires_at = _parse_alpaca_datetime(persisted_expires_at)
    if expires_at is None:
        return False

    renewal_cutoff = _utc_now() + timedelta(days=cfg.gtc_sell_renewal_days_before_expiration)
    return expires_at <= renewal_cutoff


def _sell_renewal_claim_lease_active(position: dict) -> bool:
    requested_at = _parse_alpaca_datetime(position.get("sell_renewal_requested_at"))
    if requested_at is None:
        return False
    return requested_at > _utc_now() - _SELL_RENEWAL_CLAIM_LEASE


def _renewal_snapshot_cas_kwargs(
    snapshot: AlpacaManagedSellRenewalSnapshot | None,
) -> dict[str, object]:
    if snapshot is None:
        return {}
    return {
        "expected_sell_status": snapshot.sell_status,
        "expected_sell_alpaca_order_id": snapshot.sell_alpaca_order_id,
        "expected_sell_filled_qty": snapshot.sell_filled_qty,
        "expected_sell_renewal_count": snapshot.sell_renewal_count,
        "expected_sell_renewal_requested_at": snapshot.requested_at,
        "expected_buy_status": snapshot.buy_status,
        "expected_buy_filled_qty": snapshot.filled_qty,
        "expected_buy_filled_avg_price": snapshot.filled_avg_price,
        "expected_target_sell_price": snapshot.target_sell_price,
        "expected_remaining_qty": snapshot.remaining_qty,
        "expected_state_revision": snapshot.state_revision,
    }


def _renewal_fill_snapshot_cas_kwargs(
    snapshot: AlpacaManagedSellRenewalSnapshot | None,
) -> dict[str, object]:
    if snapshot is None:
        return {}
    return {
        "expected_sell_status": snapshot.sell_status,
        "expected_sell_alpaca_order_id": snapshot.sell_alpaca_order_id,
        "expected_sell_filled_qty": snapshot.sell_filled_qty,
        "expected_sell_renewal_count": snapshot.sell_renewal_count,
        "expected_sell_renewal_requested_at": snapshot.requested_at,
        "expected_state_revision": snapshot.state_revision,
    }


def _managed_sell_snapshots_have_same_premise(
    observed: AlpacaManagedSellRenewalSnapshot,
    expected: AlpacaManagedSellRenewalSnapshot,
) -> bool:
    """Compare every semantic field while allowing known local revision bumps."""
    return bool(
        observed.buy_status == expected.buy_status
        and observed.filled_qty == expected.filled_qty
        and observed.filled_avg_price == expected.filled_avg_price
        and observed.target_sell_price == expected.target_sell_price
        and observed.remaining_qty == expected.remaining_qty
        and observed.sell_status == expected.sell_status
        and observed.sell_alpaca_order_id == expected.sell_alpaca_order_id
        and observed.sell_filled_qty == expected.sell_filled_qty
        and observed.sell_renewal_count == expected.sell_renewal_count
        and observed.requested_at == expected.requested_at
    )


def _managed_sell_replacement_snapshot_if_current(
    conn: sqlite3.Connection,
    *,
    position_id: int,
    sell_client_order_id: str | None,
    sell_alpaca_order_id: str | None,
    sell_renewal_requested_at: str | None,
    expected_buy_status: str | None,
    expected_buy_filled_qty: float,
    expected_buy_filled_avg_price: float,
    expected_target_sell_price: float,
    expected_remaining_qty: float,
    expected_sell_status: str | None,
    expected_sell_renewal_count: int,
) -> AlpacaManagedSellRenewalSnapshot | None:
    """Load an exact terminal-sell continuation without adopting new parent state."""
    snapshot = alpaca_managed_sell_renewal_snapshot_if_current(
        conn,
        position_id,
        expected_sell_client_order_id=sell_client_order_id,
        expected_sell_alpaca_order_id=sell_alpaca_order_id,
        expected_sell_renewal_requested_at=sell_renewal_requested_at,
    )
    if snapshot is None:
        return None
    observed_sell_filled_qty = snapshot.sell_filled_qty or 0.0
    expected_sell_filled_qty = max(expected_buy_filled_qty - expected_remaining_qty, 0.0)
    residual_mark_price = _managed_sell_residual_mark_price(
        snapshot.filled_avg_price,
        expected_buy_filled_avg_price,
        snapshot.target_sell_price,
        expected_target_sell_price,
    )
    premise_is_current = bool(
        snapshot.buy_status == expected_buy_status
        and snapshot.filled_qty is not None
        and _managed_sell_quantities_match(
            snapshot.filled_qty,
            expected_buy_filled_qty,
            mark_price=residual_mark_price,
        )
        and snapshot.filled_avg_price is not None
        and abs(snapshot.filled_avg_price - expected_buy_filled_avg_price) <= _MANAGED_PRICE_TOLERANCE
        and snapshot.target_sell_price is not None
        and abs(snapshot.target_sell_price - expected_target_sell_price)
        <= _alpaca_limit_price_tolerance(expected_target_sell_price)
        and snapshot.remaining_qty is not None
        and _managed_sell_quantities_match(
            snapshot.remaining_qty,
            expected_remaining_qty,
            mark_price=residual_mark_price,
        )
        and snapshot.sell_status == expected_sell_status
        and snapshot.sell_alpaca_order_id == sell_alpaca_order_id
        and snapshot.sell_renewal_count == expected_sell_renewal_count
        # ``expected_sell_filled_qty`` is reconstructed by subtracting two
        # nearly equal binary64 quantities. Compare this internal algebraic
        # identity in shares; economic residual decisions use the original
        # authoritative quantities and conservative mark separately.
        and abs(observed_sell_filled_qty - expected_sell_filled_qty)
        <= _managed_qty_tolerance(observed_sell_filled_qty, expected_sell_filled_qty)
    )
    return snapshot if premise_is_current else None


class AlpacaClient:
    def __init__(
        self,
        cfg: AlpacaOrderConfig,
        *,
        equity_scope_asset_ids: Collection[str] = (),
    ):
        base_url = _canonical_alpaca_paper_base_url(cfg)
        _validated_alpaca_request_timeout_seconds(cfg.timeout_seconds)
        self.cfg = cfg
        self.base_url = base_url
        headers = _alpaca_headers(cfg)
        self._header_items = tuple(headers.items())
        # Keep an immutable copy of the exact values placed in request headers.
        # ``cfg`` remains intentionally mutable for compatibility, so reading it
        # later is insufficient after an in-process credential rotation.
        self._transmitted_sensitive_values = tuple(
            sorted(
                {
                    headers["APCA-API-KEY-ID"],
                    headers["APCA-API-SECRET-KEY"],
                },
                key=lambda value: (-len(value), value),
            )
        )
        boundary_sensitive_values = _ALPACA_PUBLIC_DURABLE_SENSITIVE_VALUES.get()
        if boundary_sensitive_values is not None:
            # Retain every exact header snapshot created inside this public
            # call, even if the mutable cfg rotates again before persistence.
            _ALPACA_PUBLIC_DURABLE_SENSITIVE_VALUES.set(
                tuple(
                    sorted(
                        {*boundary_sensitive_values, *self._transmitted_sensitive_values},
                        key=lambda value: (-len(value), value),
                    )
                )
            )
        sensitive_value_accumulator = _ALPACA_PUBLIC_DURABLE_SENSITIVE_VALUE_ACCUMULATOR.get()
        if sensitive_value_accumulator is not None:
            sensitive_value_accumulator.add(self._transmitted_sensitive_values)
        self.equity_scope_asset_ids = _canonical_alpaca_asset_id_scope(equity_scope_asset_ids)

    @property
    def headers(self) -> dict[str, str]:
        """Return a copy of the immutable credentialed request-header snapshot."""
        return dict(self._header_items)

    def get_order_by_client_order_id(self, client_order_id: str) -> requests.Response:
        return _alpaca_http_request(
            "GET",
            f"{self.base_url}/v2/orders:by_client_order_id",
            cfg=self.cfg,
            headers=self.headers,
            params={"client_order_id": client_order_id},
            timeout=self.cfg.timeout_seconds,
            allow_redirects=False,
        )

    def get_order(self, order_id: str) -> requests.Response:
        order_path = _alpaca_broker_identifier_path(order_id, label="Alpaca order ID")
        return _alpaca_http_request(
            "GET",
            f"{self.base_url}/v2/orders/{order_path}",
            cfg=self.cfg,
            headers=self.headers,
            timeout=self.cfg.timeout_seconds,
            allow_redirects=False,
        )

    def cancel_order(self, order_id: str) -> requests.Response:
        order_path = _alpaca_broker_identifier_path(order_id, label="Alpaca order ID")
        revalidate_active_sqlite_runtime_file()
        return _alpaca_http_request(
            "DELETE",
            f"{self.base_url}/v2/orders/{order_path}",
            cfg=self.cfg,
            headers=self.headers,
            timeout=self.cfg.timeout_seconds,
            allow_redirects=False,
        )

    def market_clock(self) -> dict:
        response = _alpaca_http_request(
            "GET",
            f"{self.base_url}/v2/clock",
            cfg=self.cfg,
            headers=self.headers,
            timeout=self.cfg.timeout_seconds,
            allow_redirects=False,
        )
        _require_2xx_response(response)
        payload = _strict_alpaca_response_json(response)
        if not isinstance(payload, dict):
            raise ValueError("Alpaca clock returned an invalid response")
        _validated_market_clock_is_open(payload)
        _validated_market_clock_times(payload)
        return payload

    def calendar(self, start: date, end: date) -> list[dict]:
        response = _alpaca_http_request(
            "GET",
            f"{self.base_url}/v2/calendar",
            cfg=self.cfg,
            headers=self.headers,
            params={"start": start.isoformat(), "end": end.isoformat()},
            timeout=self.cfg.timeout_seconds,
            allow_redirects=False,
        )
        _require_2xx_response(response)
        payload = _strict_alpaca_response_json(response)
        _validated_alpaca_calendar_session_dates(
            payload,
            start=start,
            end=end,
            required_session=end,
        )
        return payload

    def cash_notional(self, *, eligible_buy_signal_count: int) -> float:
        return _alpaca_cash_notional(
            self.cfg,
            self.headers,
            eligible_buy_signal_count=eligible_buy_signal_count,
        )

    def position_qty(self, symbol: str) -> float:
        return _alpaca_position_qty(symbol, self.cfg, self.headers)

    def positions(self) -> list[dict]:
        response = _alpaca_http_request(
            "GET",
            f"{self.base_url}/v2/positions",
            cfg=self.cfg,
            headers=self.headers,
            timeout=self.cfg.timeout_seconds,
            allow_redirects=False,
        )
        _require_2xx_response(response)
        payload = _strict_alpaca_response_json(response)
        if not isinstance(payload, list) or not all(isinstance(item, dict) for item in payload):
            raise ValueError("Alpaca positions returned an invalid response")
        validated_positions: list[tuple[dict, str | None]] = []
        symbol_by_asset_id: dict[str, str] = {}
        equity_asset_id_by_symbol: dict[str, str] = {}
        for item in payload:
            asset_id = _optional_alpaca_broker_identifier(item.get("asset_id"))
            if asset_id is None:
                raise ValueError("Alpaca positions returned an incomplete stable asset identity")
            asset_class = _alpaca_account_asset_class(item, label="Alpaca positions endpoint")
            if asset_class is None:
                raise ValueError("Alpaca positions returned a missing US-equity asset class")
            if asset_class in _ALPACA_UNRELATED_ASSET_CLASSES:
                symbol = _optional_alpaca_unrelated_symbol(item.get("symbol"))
                if symbol is None:
                    raise ValueError("Alpaca positions returned incomplete non-equity position metadata")
            else:
                raw_symbol = item.get("symbol")
                if not isinstance(raw_symbol, str):
                    raise ValueError("Alpaca positions returned incomplete stable asset identity")
                symbol = _optional_alpaca_equity_symbol(raw_symbol)
                if symbol is None:
                    raise ValueError("Alpaca positions returned a non-canonical equity symbol")

            prior_symbol = symbol_by_asset_id.get(asset_id)
            if prior_symbol is not None:
                if prior_symbol != symbol:
                    raise ValueError("Alpaca positions returned conflicting symbols for the same stable asset identity")
                raise ValueError("Alpaca positions returned a duplicate stable asset identity")
            symbol_by_asset_id[asset_id] = symbol
            if asset_class not in _ALPACA_UNRELATED_ASSET_CLASSES:
                prior_asset_id = equity_asset_id_by_symbol.get(symbol)
                if prior_asset_id is not None:
                    raise ValueError(
                        "Alpaca positions returned conflicting stable asset identities for the same equity symbol"
                    )
                equity_asset_id_by_symbol[symbol] = asset_id
            validated_positions.append((item, asset_class))

        equity_positions: list[dict] = []
        for item, asset_class in validated_positions:
            if asset_class in _ALPACA_UNRELATED_ASSET_CLASSES:
                try:
                    _finite_float(item["qty"])
                except (KeyError, TypeError, ValueError) as exc:
                    raise ValueError("Alpaca positions returned incomplete non-equity position metadata") from exc
                continue
            _validated_alpaca_position_qty(item, label="Alpaca positions endpoint")
            equity_positions.append(item)
        return equity_positions

    def asset(self, symbol: str) -> dict:
        return _alpaca_asset(symbol, self.cfg, self.headers)

    def has_open_order(self, symbol: str, side: str) -> bool:
        return _orders_have_open_order(self.open_orders(), symbol, side)

    def open_orders(self, *, equity_scope_asset_ids: Collection[str] = ()) -> list[dict]:
        return _alpaca_open_orders(
            self.cfg,
            self.headers,
            equity_scope_asset_ids={
                *self.equity_scope_asset_ids,
                *_canonical_alpaca_asset_id_scope(equity_scope_asset_ids),
            },
        )

    def all_orders(self) -> list[dict]:
        """Load one complete account order snapshot for reconciliation."""
        return _alpaca_account_orders(
            self.cfg,
            self.headers,
            status="all",
            equity_scope_asset_ids=self.equity_scope_asset_ids,
        )

    def submit_limit_buy_order(
        self,
        *,
        symbol: str,
        qty: int,
        limit_price: float,
        client_order_id: str,
        authorized_next_open: datetime | None = None,
        dispatch_authorization: _BuySubmissionDispatchAuthorization | None = None,
    ) -> requests.Response:
        try:
            revalidate_active_sqlite_runtime_file()
        except Exception as exc:
            raise _BuySubmissionNotDispatchedError(
                f"Alpaca buy submission was blocked before broker dispatch: {exc}"
            ) from exc
        if dispatch_authorization is None and authorized_next_open is not None:
            host_now = _market_clock_now()
            dispatch_authorization = _buy_submission_dispatch_authorization(
                next_open=authorized_next_open,
                broker_clock_timestamp=host_now,
                request_timeout_seconds=self.cfg.timeout_seconds,
            )
        if dispatch_authorization is not None and (
            authorized_next_open is not None
            and dispatch_authorization.next_open != authorized_next_open.astimezone(UTC)
        ):
            raise ValueError("Alpaca buy dispatch authorization has a conflicting next-open timestamp")
        if dispatch_authorization is not None and _buy_submission_authorization_window_elapsed(dispatch_authorization):
            raise _BuySubmissionWindowElapsedError(
                "market submission window elapsed before the broker POST; "
                "insufficient dispatch time remains before open"
            )
        write_deadline = (
            None if dispatch_authorization is None else dispatch_authorization.request_write_deadline_monotonic
        )
        with _alpaca_request_write_deadline(write_deadline):
            return _alpaca_http_request(
                "POST",
                f"{self.base_url}/v2/orders",
                cfg=self.cfg,
                headers=self.headers,
                json={
                    "symbol": symbol,
                    "side": "buy",
                    "position_intent": _ALPACA_MANAGED_BUY_POSITION_INTENT,
                    "type": "limit",
                    "time_in_force": "day",
                    "extended_hours": False,
                    "client_order_id": client_order_id,
                    "qty": str(qty),
                    "limit_price": _format_alpaca_limit_price(limit_price, rounding=ROUND_FLOOR),
                },
                timeout=self.cfg.timeout_seconds,
                allow_redirects=False,
            )

    def submit_limit_sell_order(
        self,
        *,
        symbol: str,
        qty: float,
        limit_price: float,
        client_order_id: str,
    ) -> requests.Response:
        revalidate_active_sqlite_runtime_file()
        qty = canonical_alpaca_order_quantity(qty)
        if not qty.is_integer():
            raise ValueError("An Alpaca GTC equity limit sell quantity must be a whole-share value.")
        return _alpaca_http_request(
            "POST",
            f"{self.base_url}/v2/orders",
            cfg=self.cfg,
            headers=self.headers,
            json={
                "symbol": symbol,
                "side": "sell",
                "position_intent": _ALPACA_MANAGED_SELL_POSITION_INTENT,
                "type": "limit",
                "time_in_force": "gtc",
                "extended_hours": False,
                "client_order_id": client_order_id,
                "qty": _format_order_number(qty, 9),
                "limit_price": _format_alpaca_limit_price(limit_price, rounding=ROUND_CEILING),
            },
            timeout=self.cfg.timeout_seconds,
            allow_redirects=False,
        )


def _append_result(
    rows: list[dict],
    *,
    symbol: str,
    signal_date: str,
    client_order_id: str,
    amount_key: str,
    amount: float | None,
    status: str,
    alpaca_order_id: str | None,
    message: str,
) -> None:
    rows.append(
        {
            "Asset": symbol,
            "Date": signal_date,
            "Client Order ID": client_order_id,
            amount_key: amount,
            "Status": status,
            "Alpaca Order ID": alpaca_order_id,
            "Message": message,
        }
    )


def _persist_managed_buy_observation(
    *,
    conn: sqlite3.Connection,
    signal: dict,
    symbol: str,
    signal_date: str,
    client_order_id: str,
    buy_order: dict,
    replacement_chain: list[dict],
    order_qty: float,
    limit_price: float,
    notes: str | None,
    expected_alpaca_asset_id: str | None = None,
    expected_buy_submission_attempt_count: int | None = None,
    expected_state_revision: int | None = None,
    require_existing_intent: bool = False,
    cfg: AlpacaOrderConfig | None = None,
    sensitive_values: tuple[str, ...] = (),
    client: AlpacaClient | None = None,
) -> tuple[int, float, float | None]:
    """Persist an authoritative buy leaf and atomically account its lineage fills."""
    notes = _alpaca_durable_diagnostic_note(
        notes,
        cfg=cfg,
        sensitive_values=sensitive_values,
        client=client,
    )
    for order in replacement_chain:
        _validate_alpaca_order_payload_identifiers(order)
    buy_status = _broker_order_status(buy_order, default="existing")
    buy_alpaca_order_id = _optional_alpaca_broker_identifier(buy_order.get("id"))
    alpaca_asset_id = _optional_alpaca_broker_identifier(
        expected_alpaca_asset_id if expected_alpaca_asset_id is not None else buy_order.get("asset_id")
    )
    if buy_alpaca_order_id is None or alpaca_asset_id is None:
        raise ValueError("Authoritative Alpaca buy observation has an invalid order or asset identifier")
    fill_metadata_issue = _buy_replacement_chain_fill_metadata_issue(
        replacement_chain,
        expected_buy_qty=order_qty,
    )
    if fill_metadata_issue is not None:
        raise ValueError(fill_metadata_issue)
    position_id = save_alpaca_managed_buy_order(
        conn,
        workflow=_signal_workflow(signal),
        symbol=symbol,
        alpaca_asset_id=alpaca_asset_id,
        signal_symbol=str(signal["RSI Symbol"]),
        buy_rsi=float(signal["Buy RSI"]),
        profit_target_multiple=float(signal["Sell Return Multiple"]),
        buy_signal_date=signal_date,
        buy_client_order_id=client_order_id,
        buy_alpaca_order_id=buy_alpaca_order_id,
        buy_submitted_at=_optional_alpaca_datetime_str(buy_order.get("submitted_at")),
        buy_status=buy_status,
        notes=notes,
        buy_order_qty=order_qty,
        buy_order_limit_price=limit_price,
        require_applied=True,
        require_existing=require_existing_intent,
        expected_buy_submission_attempt_count=expected_buy_submission_attempt_count,
        expected_state_revision=expected_state_revision,
        buy_broker_updated_at=_optional_alpaca_datetime_str(buy_order.get("updated_at")),
    )
    frozen_economics = conn.execute(
        """
        SELECT profit_target_multiple
        FROM alpaca_managed_positions
        WHERE id = ?
        """,
        (position_id,),
    ).fetchone()
    if frozen_economics is None:
        raise RuntimeError("Managed Alpaca buy intent disappeared before its fill could be accounted.")
    frozen_profit_target_multiple = float(frozen_economics[0])
    filled_qty, filled_avg_price, _ = _replacement_chain_fill_metadata(replacement_chain)
    if filled_qty == 0.0:
        if buy_status in BUY_TERMINAL_STATUSES:
            closed = close_alpaca_managed_buy_if_current_and_unfilled(
                conn,
                position_id,
                expected_buy_status=buy_status,
                expected_buy_alpaca_order_id=buy_alpaca_order_id,
                expected_buy_submission_attempt_count=expected_buy_submission_attempt_count,
                buy_status=buy_status,
                buy_alpaca_order_id=buy_alpaca_order_id,
                buy_submitted_at=_optional_alpaca_datetime_str(buy_order.get("submitted_at")),
                closed_at=_optional_alpaca_datetime_str(buy_order.get("updated_at")),
                buy_broker_updated_at=_optional_alpaca_datetime_str(buy_order.get("updated_at")),
                notes=_alpaca_durable_diagnostic_note(
                    "Alpaca terminated the managed buy without a fill",
                    cfg=cfg,
                    sensitive_values=sensitive_values,
                    client=client,
                ),
            )
            if not closed:
                raise RuntimeError("Terminal managed Alpaca buy observation lost its active-state closure race.")
        return position_id, filled_qty, None

    assert filled_avg_price is not None
    target_price = _target_sell_price(filled_avg_price, frozen_profit_target_multiple)
    filled_at = next(
        (
            observed_filled_at
            for node in reversed(replacement_chain)
            if (observed_filled_at := _optional_alpaca_datetime_str(node.get("filled_at"))) is not None
        ),
        None,
    )
    fill_applied = mark_alpaca_managed_buy_filled(
        conn,
        position_id,
        buy_status=buy_status,
        filled_qty=filled_qty,
        filled_avg_price=filled_avg_price,
        filled_at=filled_at,
        target_sell_price=target_price,
        buy_fill_broker_updated_at=_replacement_chain_latest_broker_updated_at(replacement_chain),
        buy_fill_broker_oldest_updated_at=_replacement_chain_oldest_broker_updated_at(replacement_chain),
        buy_fill_component_revisions=_replacement_chain_broker_component_revisions(replacement_chain),
        buy_alpaca_order_id=buy_alpaca_order_id,
        buy_submitted_at=_optional_alpaca_datetime_str(buy_order.get("submitted_at")),
        notes=notes,
        expected_buy_status=buy_status,
        expected_buy_alpaca_order_id=buy_alpaca_order_id,
        expected_filled_qty=None,
        expected_filled_avg_price=None,
        expected_target_sell_price=None,
        expected_sell_client_order_id=None,
        expected_buy_submission_attempt_count=expected_buy_submission_attempt_count,
    )
    if not fill_applied:
        raise RuntimeError("Managed Alpaca buy fill observation lost its active-state persistence race.")
    return position_id, filled_qty, target_price


def _recover_managed_buy_submission(
    *,
    conn: sqlite3.Connection,
    client: AlpacaClient,
    rows: list[dict],
    signal_index: int,
    signal: dict,
    symbol: str,
    signal_date: str,
    client_order_id: str,
    notional: float,
    qty: int,
    limit_price: float,
    expected_alpaca_asset_id: str | None,
    message: str,
    submission_attempt_count: int,
    managed_position_id: int,
    expected_state_revision: int | None = None,
    observed_payload: dict | None = None,
) -> str | None:
    try:
        if observed_payload is None:
            lookup = client.get_order_by_client_order_id(client_order_id)
            if lookup.status_code != 200:
                return None
            observed_payload = _response_json(lookup)
        recovered, replacement_chain = _fetch_order_replacement_chain(
            client,
            observed_payload,
            client_order_id,
        )
    except Exception:
        return None

    try:
        _validate_buy_order_identity(
            buy_order=recovered,
            expected_client_order_id=client_order_id,
            expected_symbol=symbol,
            expected_alpaca_asset_id=expected_alpaca_asset_id,
            expected_qty=qty,
            expected_limit_price=limit_price,
            replacement_chain=replacement_chain,
        )
    except BuyOrderIdentityError as exc:
        quarantine_status, attributed_order_id, cancellation_lineage, cancellation_message = (
            _attributed_buy_identity_mismatch_quarantine_plan(
                recovered,
                identity_issue=str(exc),
                expected_client_order_id=client_order_id,
                expected_symbol=symbol,
                expected_alpaca_asset_id=expected_alpaca_asset_id,
                replacement_chain=replacement_chain,
            )
        )
        quarantine_notes = (
            f"ambiguous buy recovery found a broker order identity mismatch: {exc}; "
            f"{cancellation_message}; protective-sell automation is quarantined pending review"
        )
        if cancellation_lineage is not None:
            status_updated = _quarantine_managed_buy_side_effect_from_current_snapshot(
                conn=conn,
                position_id=managed_position_id,
                buy_status=quarantine_status,
                observed_buy_alpaca_order_id=attributed_order_id,
                observed_buy_submitted_at=_optional_alpaca_datetime_str(recovered.get("submitted_at")),
                notes=_alpaca_durable_diagnostic_note(
                    quarantine_notes,
                    cfg=client.cfg,
                    client=client,
                ),
                observed_buy_cancellation_alpaca_order_ids=[
                    order_id
                    for node in cancellation_lineage
                    if (order_id := _optional_alpaca_broker_identifier(node.get("id"))) is not None
                ],
            )
        else:
            status_updated = update_alpaca_managed_buy_status_if_current(
                conn,
                managed_position_id,
                expected_buy_status="submission_pending",
                expected_buy_alpaca_order_id=None,
                expected_filled_qty=None,
                expected_sell_client_order_id=None,
                expected_buy_submission_attempt_count=submission_attempt_count,
                expected_state_revision=expected_state_revision,
                buy_status=quarantine_status,
                buy_alpaca_order_id=attributed_order_id,
                buy_submitted_at=_optional_alpaca_datetime_str(recovered.get("submitted_at")),
                notes=_alpaca_durable_diagnostic_note(
                    quarantine_notes,
                    cfg=client.cfg,
                    client=client,
                ),
            )
        if not status_updated:
            _append_accepted_buy_processing_failure(
                conn=conn,
                client=client,
                rows=rows,
                workflow=_signal_workflow(signal),
                signal_index=signal_index,
                symbol=symbol,
                signal_date=signal_date,
                client_order_id=client_order_id,
                notional=notional,
                qty=qty,
                limit_price=limit_price,
                managed_position_id=managed_position_id,
                managed_submission_attempt_count=submission_attempt_count,
                accepted_response_payload=recovered,
                expected_alpaca_asset_id=expected_alpaca_asset_id,
                accepted_replacement_chain=replacement_chain,
                detail=f"recovered buy identity mismatch lost its diagnostic persistence race: {exc}",
            )
            return "identity_mismatch"
        if quarantine_status == "pending_cancel" and cancellation_lineage is not None:
            _pending, cancellation_message = _request_safely_attributed_lineage_cancellations(
                client,
                cancellation_lineage,
            )
        rows.append(
            {
                "Workflow": _signal_workflow(signal),
                "Asset": symbol,
                "Date": signal_date,
                "Client Order ID": client_order_id,
                "Notional": notional,
                "Qty": qty,
                "Limit Price": limit_price,
                "Status": quarantine_status if status_updated else "superseded",
                "Alpaca Order ID": _optional_str(recovered.get("id")),
                "Message": (
                    f"ambiguous submission recovery found a broker order identity mismatch: {exc}; "
                    f"{cancellation_message}; "
                    + (
                        "managed intent was quarantined for review"
                        if status_updated
                        else "managed state changed concurrently, but the visible mismatch still requires review"
                    )
                ),
                "_signal_index": signal_index,
            }
        )
        return "identity_mismatch"
    except Exception:
        return None

    recovered_status = _broker_order_status(recovered, default="existing")
    fill_metadata_issue = _buy_replacement_chain_fill_metadata_issue(
        replacement_chain,
        expected_buy_qty=qty,
    )
    if fill_metadata_issue is not None:
        status_updated = update_alpaca_managed_buy_status_if_current(
            conn,
            managed_position_id,
            expected_buy_status="submission_pending",
            expected_buy_alpaca_order_id=None,
            expected_filled_qty=None,
            expected_sell_client_order_id=None,
            expected_buy_submission_attempt_count=submission_attempt_count,
            expected_state_revision=expected_state_revision,
            buy_status="incomplete_fill_metadata",
            buy_alpaca_order_id=_optional_str(recovered.get("id")),
            buy_submitted_at=_optional_alpaca_datetime_str(recovered.get("submitted_at")),
            notes=_alpaca_durable_diagnostic_note(
                f"{fill_metadata_issue}; protective-sell automation is quarantined pending reconciliation",
                cfg=client.cfg,
                client=client,
            ),
        )
        if not status_updated:
            _append_accepted_buy_processing_failure(
                conn=conn,
                client=client,
                rows=rows,
                workflow=_signal_workflow(signal),
                signal_index=signal_index,
                symbol=symbol,
                signal_date=signal_date,
                client_order_id=client_order_id,
                notional=notional,
                qty=qty,
                limit_price=limit_price,
                managed_position_id=managed_position_id,
                managed_submission_attempt_count=submission_attempt_count,
                accepted_response_payload=recovered,
                expected_alpaca_asset_id=expected_alpaca_asset_id,
                accepted_replacement_chain=replacement_chain,
                detail=(f"recovered incomplete-fill diagnostic lost its persistence race: {fill_metadata_issue}"),
            )
            return "incomplete_fill_metadata"
        rows.append(
            {
                "Workflow": _signal_workflow(signal),
                "Asset": symbol,
                "Date": signal_date,
                "Client Order ID": client_order_id,
                "Notional": notional,
                "Qty": qty,
                "Limit Price": limit_price,
                "Status": "incomplete_fill_metadata" if status_updated else "superseded",
                "Alpaca Order ID": _optional_str(recovered.get("id")),
                "Message": (
                    fill_metadata_issue
                    if status_updated
                    else "incomplete buy-fill recovery was superseded by concurrent managed state"
                ),
                "_signal_index": signal_index,
            }
        )
        return "incomplete_fill_metadata" if status_updated else "superseded"

    try:
        _, recovered_filled_qty, recovered_target_price = _persist_managed_buy_observation(
            conn=conn,
            signal=signal,
            symbol=symbol,
            signal_date=signal_date,
            client_order_id=client_order_id,
            buy_order=recovered,
            replacement_chain=replacement_chain,
            order_qty=qty,
            limit_price=limit_price,
            notes=_alpaca_durable_diagnostic_note(
                "managed buy recovered by client order ID after an ambiguous submission result",
                cfg=client.cfg,
                client=client,
            ),
            expected_alpaca_asset_id=expected_alpaca_asset_id,
            expected_buy_submission_attempt_count=submission_attempt_count,
            expected_state_revision=expected_state_revision,
            cfg=client.cfg,
            client=client,
        )
    except RuntimeError as exc:
        if _managed_buy_lineage_is_durably_adopted(
            conn=conn,
            position_id=managed_position_id,
            client_order_id=client_order_id,
            expected_symbol=symbol,
            expected_alpaca_asset_id=expected_alpaca_asset_id,
            expected_qty=qty,
            expected_limit_price=limit_price,
            replacement_chain=replacement_chain,
        ):
            rows.append(
                {
                    "Workflow": _signal_workflow(signal),
                    "Asset": symbol,
                    "Date": signal_date,
                    "Client Order ID": client_order_id,
                    "Notional": notional,
                    "Qty": qty,
                    "Limit Price": limit_price,
                    "Status": "existing",
                    "Alpaca Order ID": _optional_str(recovered.get("id")),
                    "Message": "concurrent managed state already adopted the exact recovered buy lineage",
                    "_signal_index": signal_index,
                }
            )
            return "recovered"
        _append_accepted_buy_processing_failure(
            conn=conn,
            client=client,
            rows=rows,
            workflow=_signal_workflow(signal),
            signal_index=signal_index,
            symbol=symbol,
            signal_date=signal_date,
            client_order_id=client_order_id,
            notional=notional,
            qty=qty,
            limit_price=limit_price,
            managed_position_id=managed_position_id,
            managed_submission_attempt_count=submission_attempt_count,
            accepted_response_payload=recovered,
            expected_alpaca_asset_id=expected_alpaca_asset_id,
            accepted_replacement_chain=replacement_chain,
            detail=f"recovered managed observation lost its persistence race: {exc}",
        )
        return "submission_unknown"
    rows.append(
        {
            "Workflow": _signal_workflow(signal),
            "Asset": symbol,
            "Date": signal_date,
            "Client Order ID": client_order_id,
            "Notional": notional,
            "Qty": qty,
            "Limit Price": limit_price,
            "Status": (
                "filled"
                if recovered_status == "filled"
                else "partially_filled"
                if recovered_filled_qty > 0.0
                else recovered_status
                if recovered_status
                in {
                    *BUY_TERMINAL_STATUSES,
                    *BUY_NONTERMINAL_PAUSED_STATUSES,
                }
                else "existing"
            ),
            "Alpaca Order ID": _optional_str(recovered.get("id")),
            "Message": (
                f"recovered and accounted {recovered_filled_qty:g} filled shares at target "
                f"{recovered_target_price:g}; post-buy reconciliation will submit protection"
                if recovered_target_price is not None
                else f"recovered after ambiguous submission result: {message}"
            ),
            "_signal_index": signal_index,
        }
    )
    return "recovered"


def _alpaca_config_sensitive_values(cfg: AlpacaOrderConfig | None) -> tuple[str, ...]:
    """Return raw configured credentials for bounded diagnostic redaction."""
    if cfg is None:
        return ()
    raw_configured_values = (cfg.api_key_id, cfg.api_secret_key)
    configured_values = tuple(
        # ``str(value)`` dispatches a subclass's arbitrary ``__str__`` hook.
        # Read the immutable base-string payload directly so even an invalid
        # hostile credential can be captured before public diagnostics cross
        # the boundary. Invalid non-string values are validated elsewhere and
        # must not be rendered merely to build the redaction set.
        str.strip(str.__str__(configured_value), " ")
        for configured_value in raw_configured_values
        if isinstance(configured_value, str)
    )
    return tuple(
        sorted(
            {configured_value for configured_value in configured_values if configured_value},
            key=lambda value: (-len(value), value),
        )
    )


def _merged_alpaca_sensitive_values(*value_groups: Collection[str]) -> tuple[str, ...]:
    """Return one deterministic immutable set of diagnostic secrets."""
    sensitive_values = {
        sensitive_value.strip(" ")
        for value_group in value_groups
        for sensitive_value in value_group
        if type(sensitive_value) is str and sensitive_value.strip(" ")
    }
    return tuple(sorted(sensitive_values, key=lambda value: (-len(value), value)))


def _alpaca_scoped_sensitive_values() -> tuple[str, ...]:
    """Return every credential snapshot accumulated by the active boundary."""
    accumulator = _ALPACA_PUBLIC_DURABLE_SENSITIVE_VALUE_ACCUMULATOR.get()
    return () if accumulator is None else accumulator.snapshot()


def _alpaca_client_sensitive_values(client: AlpacaClient) -> tuple[str, ...]:
    """Combine exact transmitted credentials with the client's current config."""
    try:
        transmitted_values = object.__getattribute__(client, "_transmitted_sensitive_values")
    except (AttributeError, TypeError):
        transmitted_values = ()
    if type(transmitted_values) is not tuple:
        transmitted_values = ()

    try:
        current_cfg = object.__getattribute__(client, "cfg")
    except (AttributeError, TypeError):
        current_cfg = None
    configured_values = (
        _alpaca_config_sensitive_values(current_cfg) if isinstance(current_cfg, AlpacaOrderConfig) else ()
    )
    return _merged_alpaca_sensitive_values(transmitted_values, configured_values)


def _alpaca_diagnostic_redaction_marker(
    sensitive_values: tuple[str, ...],
    *,
    max_chars: int,
) -> str:
    """Choose a bounded marker that cannot itself disclose a credential."""
    for marker in ("[redacted credential]", "[redacted]", "█"):
        if len(marker) <= max_chars and not any(secret in marker for secret in sensitive_values):
            return marker
    # An invalid, post-construction config can theoretically collide with both
    # markers.  Empty output is the only representation safe for every string.
    return ""


def _safe_alpaca_diagnostic_text(
    value: object,
    *,
    max_chars: int,
    sensitive_values: tuple[str, ...] = (),
) -> str:
    """Bound and neutralize broker-controlled diagnostics before logs/state."""
    if (not isinstance(value, (str, BaseException))) or max_chars < 1:
        return ""
    diagnostic = safe_diagnostic_text(
        value,
        max_chars=max_chars,
        sensitive_values=sensitive_values,
    )
    normalized_sensitive_values = _merged_alpaca_sensitive_values(sensitive_values)
    marker = _alpaca_diagnostic_redaction_marker(
        normalized_sensitive_values,
        max_chars=max_chars,
    )
    # Retain the broker diagnostic's established public marker while sharing
    # the canonical bounded matcher (including every valid JSON spelling),
    # unless that marker itself contains a configured credential.
    if marker != "[redacted credential]":
        diagnostic = diagnostic.replace("[redacted credential]", marker)
    diagnostic = diagnostic.replace("[redacted]", marker)
    if len(diagnostic) > max_chars:
        diagnostic = diagnostic[: max_chars - 1].rstrip() + "…"
    # Marker substitution and final truncation happen after the canonical
    # sanitizer's last scan.  Fail closed if either operation reconstructs a
    # configured value at a new boundary.
    if any(secret in diagnostic for secret in normalized_sensitive_values):
        return marker
    return diagnostic


def _malformed_alpaca_error_category(parse_error: Exception) -> str:
    """Describe an invalid error envelope without reflecting its body or keys."""
    if isinstance(parse_error, _DuplicateAlpacaJsonKeyError):
        issue = "duplicate JSON object key"
    elif isinstance(parse_error, _InvalidAlpacaJsonConstantError):
        issue = "invalid JSON numeric value"
    elif isinstance(parse_error, RecursionError):
        issue = "excessive JSON nesting"
    else:
        issue = "invalid JSON envelope"
    return f"malformed Alpaca error response ({issue})"


def _canonical_http_error_detail(exc: HTTPError) -> tuple[str, bool]:
    """Return unsanitized semantic detail from a trustworthy error envelope."""
    response = exc.response
    if response is None:
        return "", False

    try:
        payload = _strict_alpaca_response_json(response)
    except Exception as parse_error:
        return _malformed_alpaca_error_category(parse_error), False

    if isinstance(payload, dict):
        present_fields = [field for field in ("message", "error") if field in payload]
        details: list[str | None] = []
        for field in present_fields:
            raw_detail = payload[field]
            if type(raw_detail) is not str:
                details.append(None)
                continue
            if len(raw_detail) > _ALPACA_ERROR_SEMANTIC_MAX_CHARS:
                if len(present_fields) > 1:
                    # Comparing or normalizing multiple arbitrarily large
                    # fields would make classification provider-amplifiable.
                    return "Alpaca error response exceeded semantic validation limit", False
                return raw_detail, True
            details.append(raw_detail.strip() or None)
        if len(present_fields) > 1 and (any(detail is None for detail in details) or len(set(details)) != 1):
            # Either recognized field can carry the broker's authoritative
            # diagnostic. A malformed or contradictory second field means the
            # envelope cannot prove deterministic rejection or distinguish an
            # asset-scoped denial from account-wide authentication failure.
            return "Alpaca error response contained conflicting diagnostic fields", False
        if details and details[0] is not None:
            detail = details[0]
            if any(character.isprintable() and not character.isspace() for character in detail):
                return detail, True
        return "Alpaca error response did not contain a string message", False
    return "Alpaca error response had an unexpected JSON shape", False


def _http_error_detail(
    exc: HTTPError,
    *,
    sensitive_values: tuple[str, ...] = (),
) -> tuple[str, bool]:
    """Return safe readable detail and whether its JSON envelope is trustworthy."""
    detail, body_is_canonical = _canonical_http_error_detail(exc)
    if not body_is_canonical:
        return detail, False
    safe_detail = _safe_alpaca_diagnostic_text(
        detail,
        max_chars=_ALPACA_ERROR_DETAIL_MAX_CHARS,
        sensitive_values=sensitive_values,
    )
    if safe_detail:
        return safe_detail, True
    return "Alpaca error response did not contain a string message", False


def _http_error_message(
    exc: HTTPError,
    *,
    sensitive_values: tuple[str, ...] = (),
) -> str:
    response = exc.response
    if response is None:
        return _safe_alpaca_diagnostic_text(
            exc,
            max_chars=_ALPACA_HTTP_ERROR_MESSAGE_MAX_CHARS,
            sensitive_values=sensitive_values,
        )

    detail, _body_is_canonical = _http_error_detail(
        exc,
        sensitive_values=sensitive_values,
    )
    summary = _safe_alpaca_diagnostic_text(
        exc,
        max_chars=_ALPACA_ERROR_DETAIL_MAX_CHARS,
        sensitive_values=sensitive_values,
    )
    message = f"{summary}: {detail}" if summary and detail else summary or detail
    # A configured value can straddle the independently safe summary/detail
    # boundary. Re-scan the joined text so formatting cannot reconstruct it.
    # Classification never consumes this display string; it reads the separate
    # canonical response field above.
    return _safe_alpaca_diagnostic_text(
        message,
        max_chars=_ALPACA_HTTP_ERROR_MESSAGE_MAX_CHARS,
        sensitive_values=sensitive_values,
    )


def _alpaca_exception_diagnostic(
    exc: BaseException,
    *,
    cfg: AlpacaOrderConfig | None,
    sensitive_values: tuple[str, ...] = (),
) -> str:
    """Sanitize every failure before it reaches public or durable output."""
    sensitive_values = _merged_alpaca_sensitive_values(
        sensitive_values,
        _alpaca_scoped_sensitive_values(),
        _alpaca_config_sensitive_values(cfg),
    )
    try:
        retained_diagnostic = object.__getattribute__(
            exc,
            _ALPACA_RETAINED_SAFE_DIAGNOSTIC_ATTR,
        )
    except (AttributeError, TypeError):
        retained_diagnostic = None
    if type(retained_diagnostic) is str:
        # Some helpers intentionally preserve an exception's public type for
        # callers while carrying the diagnostic captured by the exact client
        # that performed the request. Re-sanitize it against the caller's
        # current snapshot, but never re-read a stale HTTP response body.
        return _safe_alpaca_diagnostic_text(
            retained_diagnostic,
            max_chars=_ALPACA_HTTP_ERROR_MESSAGE_MAX_CHARS,
            sensitive_values=sensitive_values,
        )
    if isinstance(exc, HTTPError):
        return _http_error_message(exc, sensitive_values=sensitive_values)
    return _safe_alpaca_diagnostic_text(
        exc,
        max_chars=_ALPACA_HTTP_ERROR_MESSAGE_MAX_CHARS,
        sensitive_values=sensitive_values,
    )


def _alpaca_client_exception_diagnostic(
    exc: BaseException,
    *,
    client: AlpacaClient,
) -> str:
    """Sanitize a client failure against sent and currently configured credentials."""
    return _alpaca_exception_diagnostic(
        exc,
        cfg=None,
        sensitive_values=_alpaca_client_sensitive_values(client),
    )


def _alpaca_durable_diagnostic_note(
    value: object,
    *,
    cfg: AlpacaOrderConfig | None,
    sensitive_values: tuple[str, ...] = (),
    client: AlpacaClient | None = None,
) -> str | None:
    """Sanitize a free-form managed-position note immediately before storage."""
    if value is None:
        return None
    request_sensitive_values = _alpaca_client_sensitive_values(client) if client is not None else ()
    current_cfg = cfg if isinstance(cfg, AlpacaOrderConfig) else None
    boundary_sensitive_values = _ALPACA_PUBLIC_DURABLE_SENSITIVE_VALUES.get() or ()
    boundary_cfg = _ALPACA_PUBLIC_DURABLE_DIAGNOSTIC_CFG.get()
    return _safe_alpaca_diagnostic_text(
        value,
        max_chars=_ALPACA_HTTP_ERROR_MESSAGE_MAX_CHARS,
        sensitive_values=_merged_alpaca_sensitive_values(
            sensitive_values,
            request_sensitive_values,
            boundary_sensitive_values,
            _alpaca_scoped_sensitive_values(),
            _alpaca_config_sensitive_values(current_cfg),
            _alpaca_config_sensitive_values(boundary_cfg),
        ),
    )


@contextmanager
def _alpaca_public_durable_diagnostic_scope(
    cfg: AlpacaOrderConfig,
    sensitive_values: tuple[str, ...],
):
    """Retain entry, current, and every exact-client credential snapshot."""
    accumulator = _ALPACA_PUBLIC_DURABLE_SENSITIVE_VALUE_ACCUMULATOR.get()
    if accumulator is None:
        accumulator = _AlpacaSensitiveValueAccumulator()
    accumulator.add(sensitive_values)
    accumulator.add(_alpaca_config_sensitive_values(cfg))
    cfg_token = _ALPACA_PUBLIC_DURABLE_DIAGNOSTIC_CFG.set(cfg)
    values_token = _ALPACA_PUBLIC_DURABLE_SENSITIVE_VALUES.set(sensitive_values)
    accumulator_token = _ALPACA_PUBLIC_DURABLE_SENSITIVE_VALUE_ACCUMULATOR.set(accumulator)
    try:
        yield
    finally:
        accumulator.add(_alpaca_config_sensitive_values(cfg))
        _ALPACA_PUBLIC_DURABLE_SENSITIVE_VALUE_ACCUMULATOR.reset(accumulator_token)
        _ALPACA_PUBLIC_DURABLE_SENSITIVE_VALUES.reset(values_token)
        _ALPACA_PUBLIC_DURABLE_DIAGNOSTIC_CFG.reset(cfg_token)


@contextmanager
def _retain_alpaca_client_exception_diagnostic(client: AlpacaClient):
    """Carry a safe diagnostic with an exception that must retain its type."""
    try:
        yield
    except BaseException as exc:
        try:
            retained_diagnostic = _alpaca_client_exception_diagnostic(exc, client=client)
        except BaseException:
            retained_diagnostic = "Alpaca client operation failed"
        try:
            BaseException.__setattr__(
                exc,
                _ALPACA_RETAINED_SAFE_DIAGNOSTIC_ATTR,
                retained_diagnostic,
            )
            # Direct callers of the migration helper can also render this
            # exception before a workflow boundary sees the retained field.
            # Keep its public type/identity, but replace visible arguments and
            # suppress any older secret-bearing exception chain.
            BaseException.__setattr__(exc, "args", (retained_diagnostic,))
            BaseException.__setattr__(exc, "__cause__", None)
            BaseException.__setattr__(exc, "__context__", None)
            BaseException.__setattr__(exc, "__suppress_context__", True)
        except BaseException:
            # A nonstandard exception that refuses instance attributes cannot
            # safely cross a boundary that has lost the request-header
            # snapshot. Preserve a useful bounded failure without retaining
            # the potentially secret-bearing original as visible context.
            raise RuntimeError(retained_diagnostic) from None
        raise


def _alpaca_public_exception_cause(
    exc: BaseException,
    *,
    cfg: AlpacaOrderConfig | None,
    sensitive_values: tuple[str, ...] = (),
) -> BaseException | None:
    """Suppress raw traceback context whenever configured secrets are in scope."""
    return (
        None
        if _merged_alpaca_sensitive_values(
            sensitive_values,
            _alpaca_scoped_sensitive_values(),
            _alpaca_config_sensitive_values(cfg),
        )
        else exc
    )


_ALPACA_PUBLIC_DIAGNOSTIC_COLUMNS = frozenset({"Message", "message", "Notes", "notes"})


def _alpaca_public_result(
    result: pd.DataFrame,
    *,
    cfg: AlpacaOrderConfig | None,
    sensitive_values: tuple[str, ...] = (),
    diagnostic_columns: Collection[str] = _ALPACA_PUBLIC_DIAGNOSTIC_COLUMNS,
) -> pd.DataFrame:
    """Sanitize only diagnostic columns at a direct public Alpaca boundary."""
    public_columns = [column for column in result.columns if column in diagnostic_columns]
    if not public_columns:
        return result
    merged_sensitive_values = _merged_alpaca_sensitive_values(
        sensitive_values,
        _alpaca_config_sensitive_values(cfg),
    )
    safe_result = result.copy()
    changed = False
    for column in public_columns:
        safe_values: list[object] = []
        for value in safe_result[column].tolist():
            if isinstance(value, (str, BaseException)):
                safe_value: object = _safe_alpaca_diagnostic_text(
                    value,
                    max_chars=_ALPACA_HTTP_ERROR_MESSAGE_MAX_CHARS,
                    sensitive_values=merged_sensitive_values,
                )
                changed = changed or safe_value != value
            else:
                safe_value = value
            safe_values.append(safe_value)
        safe_result[column] = safe_values
    return safe_result if changed else result


def _alpaca_public_exception_notes(
    exc: BaseException,
    *,
    sensitive_values: tuple[str, ...],
) -> list[str]:
    """Return safe notes without iterating an attacker-controlled notes object."""
    try:
        raw_notes = BaseException.__getattribute__(exc, "__notes__")
    except (AttributeError, TypeError):
        return []
    if type(raw_notes) is str:
        note_values = (raw_notes,)
    elif type(raw_notes) in (list, tuple):
        note_values = raw_notes
    else:
        return []
    return [
        _safe_alpaca_diagnostic_text(
            note,
            max_chars=_ALPACA_HTTP_ERROR_MESSAGE_MAX_CHARS,
            sensitive_values=sensitive_values,
        )
        for note in note_values
        if type(note) is str
    ]


def _alpaca_public_rendering_sensitive_values(
    sensitive_values: tuple[str, ...],
    *,
    max_chars: int,
) -> tuple[str, ...]:
    """Bound huge credentials into projections suitable for a render postcondition."""
    # The canonical sanitizer intentionally returns a generic marker for every
    # input when a credential is larger than its bounded scan window. That is
    # correct for arbitrary provider text, but a postcondition must still be
    # able to recognize a freshly built safe exception. Scan bounded leading
    # and trailing projections of such values here; any complete credential is
    # too large to fit in the already bounded rendering, while these projections
    # prevent the useful prefix/suffix fragments from escaping through a slot.
    return _merged_alpaca_sensitive_values(
        tuple(
            projected
            for sensitive_value in sensitive_values
            for projected in (
                sensitive_value if len(sensitive_value) <= max_chars else sensitive_value[:128],
                "" if len(sensitive_value) <= max_chars else sensitive_value[-128:],
            )
            if projected
        )
    )


def _alpaca_public_exception_rendering_is_safe(
    exc: BaseException,
    *,
    sensitive_values: tuple[str, ...],
) -> bool:
    """Verify that a concrete exception's own visible metadata is publishable."""
    max_chars = _ALPACA_HTTP_ERROR_MESSAGE_MAX_CHARS * 4
    rendering_sensitive_values = _alpaca_public_rendering_sensitive_values(
        sensitive_values,
        max_chars=max_chars,
    )
    try:
        if isinstance(exc, BaseExceptionGroup) and type(exc).__repr__ is BaseExceptionGroup.__repr__:
            # The stock group repr recursively renders every child. Each child
            # has already satisfied this postcondition, so validate only the
            # local deterministic pieces and avoid reintroducing recursion.
            rendered_repr = repr(exc.message)
        else:
            rendered_repr = repr(exc)
        exception_type = type(exc)
        type_qualname = type.__getattribute__(exception_type, "__qualname__")
        type_module = type.__getattribute__(exception_type, "__module__")
        if type(type_qualname) is not str or type(type_module) is not str:
            return False
        rendered_type_name = (
            type_qualname if type_module in {"builtins", "__main__"} else f"{type_module}.{type_qualname}"
        )
        rendered_values = (
            str(exc),
            rendered_repr,
            type_qualname,
            rendered_type_name,
        )
    except BaseException:
        return False
    for rendered in rendered_values:
        if type(rendered) is not str or len(rendered) > max_chars:
            return False
        if (
            _safe_alpaca_diagnostic_text(
                rendered,
                max_chars=max_chars,
                sensitive_values=rendering_sensitive_values,
            )
            != rendered
        ):
            return False
    try:
        notes = BaseException.__getattribute__(exc, "__notes__")
    except (AttributeError, TypeError):
        return True
    if type(notes) is not list:
        return False
    return all(
        type(note) is str
        and _safe_alpaca_diagnostic_text(
            note,
            max_chars=_ALPACA_HTTP_ERROR_MESSAGE_MAX_CHARS,
            sensitive_values=rendering_sensitive_values,
        )
        == note
        for note in notes
    )


_ALPACA_STABLE_EXCEPTION_STR_IMPLEMENTATIONS = frozenset(
    {
        BaseException.__str__,
        BaseExceptionGroup.__str__,
        OSError.__str__,
        AttributeError.__str__,
        ImportError.__str__,
        KeyError.__str__,
        NameError.__str__,
        SyntaxError.__str__,
        UnicodeDecodeError.__str__,
        UnicodeEncodeError.__str__,
        UnicodeTranslateError.__str__,
    }
)


def _alpaca_public_exception_render_hooks_are_stable(exc: BaseException) -> bool:
    """Accept only trusted render hooks, never a one-shot custom postcondition."""
    try:
        exception_type = type(exc)
        str_implementation = type.__getattribute__(exception_type, "__str__")
        repr_implementation = type.__getattribute__(exception_type, "__repr__")
    except BaseException:
        return False
    return bool(
        str_implementation in _ALPACA_STABLE_EXCEPTION_STR_IMPLEMENTATIONS
        and repr_implementation is BaseException.__repr__
    )


def _alpaca_public_traceback_is_safe(
    traceback_value: object,
    *,
    sensitive_values: tuple[str, ...],
) -> bool:
    """Retain raw frames only when no credential fence is active."""
    # Traceback formatting can read more than ``co_filename``: function names,
    # mutable linecache source, and future formatter metadata are all outside
    # this sanitizer's control. Dropping the source frames is the only stable
    # postcondition once credentials have been configured.
    return traceback_value is None or not sensitive_values


def _set_alpaca_public_exception_metadata(
    public_exc: BaseException,
    source_exc: BaseException,
    *,
    safe_notes: list[str],
    suppress_chain: bool,
    sensitive_values: tuple[str, ...] = (),
) -> BaseException:
    """Attach safe notes and the permitted traceback/chain to one exception."""
    source_traceback = BaseException.__getattribute__(source_exc, "__traceback__")
    if not _alpaca_public_traceback_is_safe(
        source_traceback,
        sensitive_values=sensitive_values,
    ):
        source_traceback = None
    if (
        public_exc is not source_exc
        or BaseException.__getattribute__(public_exc, "__traceback__") is not source_traceback
    ):
        public_exc = BaseException.with_traceback(public_exc, source_traceback)
    BaseException.__setattr__(public_exc, "__notes__", safe_notes)
    if suppress_chain:
        BaseException.__setattr__(public_exc, "__cause__", None)
        BaseException.__setattr__(public_exc, "__context__", None)
        BaseException.__setattr__(public_exc, "__suppress_context__", True)
    elif public_exc is not source_exc:
        BaseException.__setattr__(public_exc, "__cause__", source_exc.__cause__)
        BaseException.__setattr__(public_exc, "__context__", source_exc.__context__)
        BaseException.__setattr__(public_exc, "__suppress_context__", source_exc.__suppress_context__)
    return public_exc


def _render_alpaca_public_fallback(exc: BaseException) -> str:
    """Render a private fallback from its already sanitized base arguments."""
    return BaseException.__str__(exc)


def _alpaca_public_fallback_type_name(sensitive_values: tuple[str, ...]) -> str:
    """Choose a type name that cannot contain any complete configured value."""
    # A one-character name cannot contain a longer credential. The empty name
    # is accepted by ``type`` and is the final proof-safe choice even if callers
    # supplied every candidate character as a separate short credential.
    for candidate in ("X", "Y", "Z", "Q", "Ω", ""):
        if not any(secret in candidate for secret in sensitive_values):
            return candidate
    return ""


_ALPACA_FALLBACK_CONSTRUCTOR_UNSET = object()


def _new_alpaca_public_fallback(
    safe_message: str,
    *,
    safe_notes: list[str],
    sensitive_values: tuple[str, ...],
    base_type: type[BaseException] = Exception,
    constructor_value: object = _ALPACA_FALLBACK_CONSTRUCTOR_UNSET,
    hide_arguments: bool = False,
) -> BaseException:
    """Build a stable private exception whose dynamic name is credential-safe."""
    fallback_type = type(
        _alpaca_public_fallback_type_name(sensitive_values),
        (base_type,),
        {
            "__module__": "builtins",
            "__repr__": _render_alpaca_public_fallback,
            "__str__": _render_alpaca_public_fallback,
        },
    )
    fallback = fallback_type(
        safe_message if constructor_value is _ALPACA_FALLBACK_CONSTRUCTOR_UNSET else constructor_value
    )
    if hide_arguments:
        BaseException.__setattr__(fallback, "args", ())
    return _set_alpaca_public_exception_metadata(
        fallback,
        fallback,
        safe_notes=safe_notes,
        suppress_chain=True,
        sensitive_values=sensitive_values,
    )


def _new_alpaca_public_structured_fallback(
    source: AlpacaBuyBatchError | AlpacaReconciliationError,
    safe_message: str,
    safe_results: pd.DataFrame,
    *,
    safe_notes: list[str],
    sensitive_values: tuple[str, ...],
) -> AlpacaBuyBatchError | AlpacaReconciliationError:
    """Retain structured result fields under a credential-safe dynamic name."""
    base_type = type(source)
    fallback_type = type(
        _alpaca_public_fallback_type_name(sensitive_values),
        (base_type,),
        {
            "__module__": "builtins",
            "__repr__": _render_alpaca_public_fallback,
            "__str__": _render_alpaca_public_fallback,
        },
    )
    if base_type is AlpacaBuyBatchError:
        fallback = fallback_type(
            safe_message,
            safe_results,
            broker_side_effects_possible=source.broker_side_effects_possible,
        )
    else:
        fallback = fallback_type(safe_message, safe_results)
    return _set_alpaca_public_exception_metadata(
        fallback,
        source,
        safe_notes=safe_notes,
        suppress_chain=bool(sensitive_values),
        sensitive_values=sensitive_values,
    )


def _alpaca_public_exception_fallback(
    safe_message: str,
    *,
    safe_notes: list[str],
    sensitive_values: tuple[str, ...],
) -> Exception:
    """Return a plain exception whose final rendering satisfies the public fence."""
    # RuntimeError is the normal fail-closed type. The alternatives only avoid
    # the degenerate case where a short configured credential equals its class
    # name and would therefore be printed by repr()/traceback formatting.
    for fallback_type in (RuntimeError, Exception, LookupError, ArithmeticError):
        fallback = fallback_type(safe_message)
        try:
            fallback = _set_alpaca_public_exception_metadata(
                fallback,
                fallback,
                safe_notes=safe_notes,
                suppress_chain=True,
                sensitive_values=sensitive_values,
            )
        except BaseException:
            continue
        if _alpaca_public_exception_rendering_is_safe(
            fallback,
            sensitive_values=sensitive_values,
        ):
            return fallback
    # Fixed public class names are a finite namespace and can all collide with
    # short configured values. A private stable type with a selected neutral
    # name closes that last rendering gap without returning the raw exception.
    return _new_alpaca_public_fallback(
        safe_message,
        safe_notes=safe_notes,
        sensitive_values=sensitive_values,
    )


def _alpaca_public_group_metadata_value(
    value: object,
    *,
    sensitive_values: tuple[str, ...],
    depth: int = 0,
) -> tuple[bool, object]:
    """Copy only bounded metadata shapes whose public values can be sanitized."""
    if value is None or type(value) in (bool, int, float):
        return True, value
    if type(value) is str:
        return True, _safe_alpaca_diagnostic_text(
            value,
            max_chars=_ALPACA_HTTP_ERROR_MESSAGE_MAX_CHARS,
            sensitive_values=sensitive_values,
        )
    if depth >= 4 or type(value) not in (tuple, list) or len(value) > 64:
        return False, None
    safe_items: list[object] = []
    for item in value:
        safe, safe_item = _alpaca_public_group_metadata_value(
            item,
            sensitive_values=sensitive_values,
            depth=depth + 1,
        )
        if not safe:
            return False, None
        safe_items.append(safe_item)
    return True, tuple(safe_items) if type(value) is tuple else safe_items


def _copy_alpaca_public_group_subclass_metadata(
    source: BaseExceptionGroup,
    target: BaseExceptionGroup,
    *,
    sensitive_values: tuple[str, ...],
) -> bool:
    """Restore safe constructor metadata needed by a custom group's derive()."""
    for cls in type(source).__mro__:
        if cls in (ExceptionGroup, BaseExceptionGroup, BaseException, object):
            continue
        if cls.__dict__.get("__slots__"):
            # Arbitrary C/Python slot descriptors cannot be enumerated and
            # rewritten generically without invoking subclass code. Collapse
            # such a group to the safe built-in representation instead of
            # returning an exact subtype with missing constructor invariants.
            return False
    try:
        source_metadata = object.__getattribute__(source, "__dict__")
        target_metadata = object.__getattribute__(target, "__dict__")
    except BaseException:
        return False
    if type(source_metadata) is not dict or type(target_metadata) is not dict or len(source_metadata) > 64:
        return False
    safe_metadata: dict[str, object] = {}
    for name, value in source_metadata.items():
        if name == "__notes__":
            continue
        if type(name) is not str or (
            _safe_alpaca_diagnostic_text(
                name,
                max_chars=_ALPACA_HTTP_ERROR_MESSAGE_MAX_CHARS,
                sensitive_values=sensitive_values,
            )
            != name
        ):
            return False
        safe, safe_value = _alpaca_public_group_metadata_value(
            value,
            sensitive_values=sensitive_values,
        )
        if not safe:
            return False
        safe_metadata[name] = safe_value
    target_metadata.update(safe_metadata)
    return True


def _alpaca_public_exception_group(
    exc: BaseExceptionGroup,
    *,
    safe_message: str,
    safe_children: tuple[BaseException, ...],
    safe_notes: list[str],
    sensitive_values: tuple[str, ...],
) -> BaseException:
    """Rebuild one group, retaining a safe exact subtype and its derive metadata."""
    candidates: list[BaseExceptionGroup] = []
    if type(exc) not in (ExceptionGroup, BaseExceptionGroup) and _alpaca_public_exception_render_hooks_are_stable(exc):
        try:
            custom_group = BaseExceptionGroup.__new__(type(exc), safe_message, safe_children)
            if type(custom_group) is type(exc) and _copy_alpaca_public_group_subclass_metadata(
                exc,
                custom_group,
                sensitive_values=sensitive_values,
            ):
                candidates.append(custom_group)
        except BaseException:
            pass
    group_type = ExceptionGroup if isinstance(exc, ExceptionGroup) else BaseExceptionGroup
    candidates.append(group_type(safe_message, safe_children))
    for candidate in candidates:
        try:
            candidate = _set_alpaca_public_exception_metadata(
                candidate,
                exc,
                safe_notes=safe_notes,
                suppress_chain=bool(sensitive_values),
                sensitive_values=sensitive_values,
            )
        except BaseException:
            continue
        if _alpaca_public_exception_rendering_is_safe(
            candidate,
            sensitive_values=sensitive_values,
        ):
            return candidate
    return _alpaca_public_exception_fallback(
        safe_message,
        safe_notes=safe_notes,
        sensitive_values=sensitive_values,
    )


def _alpaca_public_leaf_exception(
    exc: BaseException,
    *,
    cfg: AlpacaOrderConfig | None,
    sensitive_values: tuple[str, ...],
    diagnostic_columns: Collection[str],
    preserve_typed_result_identity: bool,
) -> BaseException:
    """Sanitize one non-group exception, preserving its type when that is safe."""
    try:
        safe_message = _alpaca_exception_diagnostic(
            exc,
            cfg=cfg,
            sensitive_values=sensitive_values,
        )
    except BaseException:
        safe_message = ""
    safe_notes = _alpaca_public_exception_notes(
        exc,
        sensitive_values=sensitive_values,
    )
    suppress_chain = bool(sensitive_values)

    if isinstance(exc, (AlpacaBuyBatchError, AlpacaReconciliationError)) and type(exc) not in (
        AlpacaBuyBatchError,
        AlpacaReconciliationError,
    ):
        # Structured subclasses can add render hooks or public result metadata
        # that the two documented constructors do not control.
        return _alpaca_public_exception_fallback(
            safe_message,
            safe_notes=safe_notes,
            sensitive_values=sensitive_values,
        )

    if type(exc) in (AlpacaBuyBatchError, AlpacaReconciliationError):
        try:
            try:
                raw_notes = BaseException.__getattribute__(exc, "__notes__")
            except (AttributeError, TypeError):
                raw_notes = None
            safe_results = _alpaca_public_result(
                exc.results,
                cfg=cfg,
                sensitive_values=sensitive_values,
                diagnostic_columns=diagnostic_columns,
            )
            notes_are_unchanged = (raw_notes is None and not safe_notes) or (
                type(raw_notes) is list and raw_notes == safe_notes
            )
            retain_original = preserve_typed_result_identity or (
                exc.args == (safe_message,) and safe_results is exc.results and notes_are_unchanged
            )
            if retain_original:
                if safe_results is not exc.results:
                    for column in diagnostic_columns:
                        if column in safe_results:
                            exc.results[column] = safe_results[column]
                public_exc: BaseException = exc
            elif isinstance(exc, AlpacaBuyBatchError):
                public_exc = AlpacaBuyBatchError(
                    safe_message,
                    safe_results,
                    broker_side_effects_possible=exc.broker_side_effects_possible,
                )
            else:
                public_exc = AlpacaReconciliationError(safe_message, safe_results)
            BaseException.__setattr__(public_exc, "args", (safe_message,))
            public_exc = _set_alpaca_public_exception_metadata(
                public_exc,
                exc,
                safe_notes=safe_notes,
                suppress_chain=suppress_chain,
                sensitive_values=sensitive_values,
            )
            if _alpaca_public_exception_rendering_is_safe(
                public_exc,
                sensitive_values=sensitive_values,
            ):
                return public_exc
            public_exc = _new_alpaca_public_structured_fallback(
                exc,
                safe_message,
                safe_results,
                safe_notes=safe_notes,
                sensitive_values=sensitive_values,
            )
            if _alpaca_public_exception_rendering_is_safe(
                public_exc,
                sensitive_values=sensitive_values,
            ):
                return public_exc
        except BaseException:
            pass
        return _alpaca_public_exception_fallback(
            safe_message,
            safe_notes=safe_notes,
            sensitive_values=sensitive_values,
        )

    if isinstance(exc, SystemExit):
        try:
            code = SystemExit.__dict__["code"].__get__(exc, SystemExit)
            preserve_code = code is None or type(code) in (bool, int)
            public_code = code if preserve_code else safe_message
            public_exc = SystemExit() if code is None else SystemExit(public_code)
            public_exc = _set_alpaca_public_exception_metadata(
                public_exc,
                exc,
                safe_notes=safe_notes,
                suppress_chain=suppress_chain,
                sensitive_values=sensitive_values,
            )
            if _alpaca_public_exception_rendering_is_safe(
                public_exc,
                sensitive_values=sensitive_values,
            ):
                return public_exc
            return _new_alpaca_public_fallback(
                safe_message,
                safe_notes=safe_notes,
                sensitive_values=sensitive_values,
                base_type=SystemExit,
                constructor_value=public_code,
                hide_arguments=preserve_code,
            )
        except BaseException:
            return _alpaca_public_exception_fallback(
                safe_message,
                safe_notes=safe_notes,
                sensitive_values=sensitive_values,
            )

    stable_render_hooks = _alpaca_public_exception_render_hooks_are_stable(exc)

    # Most built-in and library exceptions render only ``args``. Mutating the
    # original keeps cancellation/interrupt identity and useful public fields
    # such as HTTPError.response when those fields do not affect rendering.
    # Exceptions with arbitrary custom hooks are never certified by calling a
    # potentially stateful renderer once.
    if stable_render_hooks:
        try:
            BaseException.__setattr__(exc, "args", (safe_message,))
            public_exc = _set_alpaca_public_exception_metadata(
                exc,
                exc,
                safe_notes=safe_notes,
                suppress_chain=suppress_chain,
                sensitive_values=sensitive_values,
            )
            if _alpaca_public_exception_rendering_is_safe(
                public_exc,
                sensitive_values=sensitive_values,
            ):
                return public_exc
        except BaseException:
            pass

    # OSError/SyntaxError and custom exceptions can retain slot-backed fields
    # that their __str__ ignores ``args`` in favour of. A fresh one-argument
    # instance clears those fields while retaining the exact type when its
    # constructor and rendering permit that safely.
    if stable_render_hooks:
        try:
            reconstructed = type(exc)(safe_message)
            if type(reconstructed) is type(exc):
                reconstructed = _set_alpaca_public_exception_metadata(
                    reconstructed,
                    exc,
                    safe_notes=safe_notes,
                    suppress_chain=suppress_chain,
                    sensitive_values=sensitive_values,
                )
                if _alpaca_public_exception_rendering_is_safe(
                    reconstructed,
                    sensitive_values=sensitive_values,
                ):
                    return reconstructed
        except BaseException:
            pass
    return _alpaca_public_exception_fallback(
        safe_message,
        safe_notes=safe_notes,
        sensitive_values=sensitive_values,
    )


def _alpaca_public_exception(
    exc: BaseException,
    *,
    cfg: AlpacaOrderConfig | None,
    sensitive_values: tuple[str, ...] = (),
    diagnostic_columns: Collection[str] = _ALPACA_PUBLIC_DIAGNOSTIC_COLUMNS,
    preserve_typed_result_identity: bool = False,
) -> BaseException:
    """Publish a depth-safe exception tree while retaining safe public types."""
    merged_sensitive_values = _merged_alpaca_sensitive_values(
        sensitive_values,
        _alpaca_scoped_sensitive_values(),
        _alpaca_config_sensitive_values(cfg),
    )
    sanitized: dict[int, BaseException] = {}
    pending: list[tuple[BaseException, bool]] = [(exc, False)]
    try:
        while pending:
            current, expanded = pending.pop()
            current_id = id(current)
            if current_id in sanitized:
                continue
            if isinstance(current, BaseExceptionGroup) and not expanded:
                pending.append((current, True))
                pending.extend((child, False) for child in reversed(current.exceptions))
                continue
            if not isinstance(current, BaseExceptionGroup):
                sanitized[current_id] = _alpaca_public_leaf_exception(
                    current,
                    cfg=cfg,
                    sensitive_values=merged_sensitive_values,
                    diagnostic_columns=diagnostic_columns,
                    preserve_typed_result_identity=preserve_typed_result_identity,
                )
                continue

            safe_message = _safe_alpaca_diagnostic_text(
                current.message,
                max_chars=_ALPACA_HTTP_ERROR_MESSAGE_MAX_CHARS,
                sensitive_values=merged_sensitive_values,
            )
            safe_notes = _alpaca_public_exception_notes(
                current,
                sensitive_values=merged_sensitive_values,
            )
            safe_children = tuple(sanitized[id(child)] for child in current.exceptions)
            sanitized[current_id] = _alpaca_public_exception_group(
                current,
                safe_message=safe_message,
                safe_children=safe_children,
                safe_notes=safe_notes,
                sensitive_values=merged_sensitive_values,
            )
        return sanitized[id(exc)]
    except BaseException:
        # Sanitization is itself a public boundary. Never let a hostile custom
        # exception or malformed tree replace the operation failure while the
        # raw credential-bearing exception is the active implicit context.
        return _alpaca_public_exception_fallback(
            "",
            safe_notes=[],
            sensitive_values=merged_sensitive_values,
        )


def _ambiguous_submission_http_error(
    exc: HTTPError,
    *,
    sensitive_values: tuple[str, ...] = (),
) -> bool:
    """Whether an HTTP error could still mean Alpaca accepted the order."""
    # Keep this keyword for private-call compatibility, but never allow
    # configured credential redaction to change broker-response semantics.
    del sensitive_values
    response = exc.response
    if response is None:
        return True
    if 200 <= response.status_code < 300:
        # The exact endpoint-status guard rejects an unexpected success code so
        # callers do not parse it under the wrong response contract.  It still
        # cannot prove that a mutating request was rejected: 201/202/204, for
        # example, all indicate that the server accepted or fulfilled work.
        # Retain the deterministic intent until a client-order-ID lookup
        # establishes the broker outcome.
        return True
    if response.status_code >= 500 or response.status_code in {408, 409, 425, 429}:
        return True
    if 300 <= response.status_code < 400:
        # A POST can be processed before the broker returns a redirect (303 is
        # commonly used to identify the resulting resource). Reject the
        # response as non-2xx, but retain/recover the deterministic intent
        # because the status does not prove that no order was accepted.
        return True
    detail, body_is_canonical = _canonical_http_error_detail(exc)
    if not body_is_canonical:
        # A malformed response cannot prove that a deterministic submission was
        # rejected. Keep its durable intent active until an exact-ID lookup does.
        return True
    if len(detail) > _ALPACA_ERROR_SEMANTIC_MAX_CHARS:
        # Do not allocate or scan an unbounded case-normalized broker string.
        # An oversized rejection cannot safely prove that the POST was refused.
        return True
    detail = detail.casefold()
    mentions_client_order_id = any(
        marker in detail for marker in {"client_order_id", "client order id", "client order"}
    )
    return mentions_client_order_id and any(marker in detail for marker in {"exist", "duplicate", "already", "unique"})


def _authentication_http_error(
    exc: HTTPError,
    *,
    sensitive_values: tuple[str, ...] = (),
) -> bool:
    # Classification must use the canonical field, never its redacted display
    # form. Retain the keyword only so existing private callers remain valid.
    del sensitive_values
    response = exc.response
    if response is None:
        return False
    if response.status_code == 401:
        return True
    if response.status_code != 403:
        return False
    detail, body_is_canonical = _canonical_http_error_detail(exc)
    if not body_is_canonical:
        # A malformed authorization response cannot safely distinguish a
        # per-asset denial from account-wide credential failure.
        return True
    if len(detail) > _ALPACA_ERROR_SEMANTIC_MAX_CHARS:
        # Unknown oversized 403 details cannot safely narrow a denial to one
        # order, so stop the batch without allocating another unbounded copy.
        return True
    detail = detail.casefold()
    if any(
        marker in detail
        for marker in {
            "api key",
            "api-key",
            "api_key",
            "authenticate",
            "authentication",
            "authorization",
            "credential",
            "unauthorized",
            "not authorized",
            "access denied",
        }
    ):
        return True
    # Alpaca can return only {"message":"forbidden."} for stale or
    # endpoint-mismatched paper credentials. Unknown 403s must therefore stop
    # a batch unless their text positively scopes the rejection to this order.
    order_scoped_markers = {
        "asset",
        "symbol",
        "buying power",
        "insufficient qty",
        "insufficient quantity",
        "insufficient shares",
        "not enough shares",
        "pattern day",
        "wash trade",
    }
    return not any(marker in detail for marker in order_scoped_markers)


def _transient_broker_http_error(exc: HTTPError) -> bool:
    response = exc.response
    return response is None or response.status_code >= 500 or response.status_code in {408, 425, 429}


def _credential_configuration_error(exc: Exception) -> bool:
    detail = safe_diagnostic_text(exc, max_chars=_ALPACA_HTTP_ERROR_MESSAGE_MAX_CHARS).lower()
    return "alpaca" in detail and any(marker in detail for marker in {"credential", "api_key", "placeholder"})


def _resolve_order_replacement_successors(
    client: AlpacaClient,
    chain: list[dict],
    *,
    validate_order_timestamps: bool = True,
) -> tuple[dict, list[dict]]:
    """Resolve successors without re-fetching an already validated ancestor prefix."""
    seen_ids = {
        order_id
        for order in chain[:-1]
        if (order_id := _optional_alpaca_broker_identifier(order.get("id"))) is not None
    }

    for _ in range(_ALPACA_REPLACEMENT_CHAIN_LIMIT):
        current = chain[-1]
        current_id = _optional_alpaca_broker_identifier(current.get("id"))
        if current_id is not None:
            if current_id in seen_ids:
                raise ValueError("Alpaca order replacement chain contains a cycle")
            seen_ids.add(current_id)
        raw_successor_id = current.get("replaced_by")
        successor_id = _optional_alpaca_broker_identifier(raw_successor_id)
        if raw_successor_id is not None and successor_id is None:
            raise ValueError("Alpaca replaced order returned an invalid successor order ID")
        if _broker_order_status(current) != "replaced" and successor_id is None:
            if len(chain) > 1 and not _replacement_chain_is_consistent(chain):
                raise ValueError("Alpaca order replacement chain is inconsistent")
            return current, chain

        if current_id is None or successor_id is None:
            raise ValueError("Alpaca replaced order did not identify its successor")
        successor_response = client.get_order(successor_id)
        _require_2xx_response(successor_response)
        successor = _response_json(
            successor_response,
            validate_order_timestamps=validate_order_timestamps,
        )
        if _optional_alpaca_broker_identifier(successor.get("id")) != successor_id:
            raise ValueError("Alpaca replacement lookup returned a different order ID")
        if _optional_alpaca_broker_identifier(successor.get("replaces")) != current_id:
            raise ValueError("Alpaca replacement successor does not link to the prior order")
        chain.append(successor)

    raise RuntimeError(f"Alpaca order replacement chain exceeded {_ALPACA_REPLACEMENT_CHAIN_LIMIT} generations")


def _resolve_order_replacement_chain(
    client: AlpacaClient,
    payload: dict,
    *,
    validate_order_timestamps: bool = True,
) -> tuple[dict, list[dict]]:
    """Resolve any broker observation to its complete replacement lineage."""
    chain = [payload]
    raw_prior_id = payload.get("replaces")
    if raw_prior_id is not None and _optional_alpaca_broker_identifier(raw_prior_id) is None:
        raise ValueError("Alpaca order returned an invalid predecessor order ID")
    if _optional_alpaca_broker_identifier(raw_prior_id) is not None:
        backward_chain = [payload]
        for _ in range(_ALPACA_REPLACEMENT_CHAIN_LIMIT):
            current = backward_chain[-1]
            raw_prior_id = current.get("replaces")
            prior_id = _optional_alpaca_broker_identifier(raw_prior_id)
            if raw_prior_id is not None and prior_id is None:
                raise ValueError("Alpaca order returned an invalid predecessor order ID")
            if prior_id is None:
                chain = list(reversed(backward_chain))
                break
            prior_response = client.get_order(prior_id)
            _require_2xx_response(prior_response)
            prior = _response_json(
                prior_response,
                validate_order_timestamps=validate_order_timestamps,
            )
            if _optional_alpaca_broker_identifier(prior.get("id")) != prior_id:
                raise ValueError("Alpaca replacement ancestor lookup returned a different order ID")
            if _optional_alpaca_broker_identifier(prior.get("replaced_by")) != (
                _optional_alpaca_broker_identifier(current.get("id"))
            ):
                raise ValueError("Alpaca replacement ancestor does not link to its successor")
            backward_chain.append(prior)
        else:
            raise RuntimeError(
                f"Alpaca order replacement lineage exceeded {_ALPACA_REPLACEMENT_CHAIN_LIMIT} generations"
            )

    return _resolve_order_replacement_successors(
        client,
        chain,
        validate_order_timestamps=validate_order_timestamps,
    )


def _fetch_order_replacement_chain(
    client: AlpacaClient,
    payload: dict,
    client_order_id: str,
    *,
    validate_order_timestamps: bool = True,
) -> tuple[dict, list[dict]]:
    """Resolve a direct broker observation to its authoritative managed leaf."""
    leaf, chain = _resolve_order_replacement_chain(
        client,
        payload,
        validate_order_timestamps=validate_order_timestamps,
    )
    if len(chain) > 1 and _optional_str(chain[0].get("client_order_id")) != client_order_id:
        raise ValueError("Alpaca replacement root does not match the managed client order ID")
    return leaf, chain


def _cached_reconciliation_order_payload(
    client: AlpacaClient,
    order_id: str | None,
) -> dict | None:
    if order_id is None:
        return None
    cache = vars(client).get("_reconciliation_order_payloads")
    if not isinstance(cache, Mapping):
        return None
    payload = cache.get(order_id)
    return payload if isinstance(payload, dict) else None


def _fetch_order_payload(
    client: AlpacaClient,
    order_id: str | None,
    client_order_id: str,
    *,
    validate_order_timestamps: bool = True,
) -> tuple[dict, list[dict]]:
    used_direct_id_lookup = order_id is not None
    payload = _cached_reconciliation_order_payload(client, order_id)
    if payload is None:
        response = client.get_order(order_id) if order_id else client.get_order_by_client_order_id(client_order_id)
        if response.status_code == 404 and order_id:
            response = client.get_order_by_client_order_id(client_order_id)
            used_direct_id_lookup = False
        _require_2xx_response(response)
        payload = _response_json(
            response,
            validate_order_timestamps=validate_order_timestamps,
        )
    if used_direct_id_lookup and _optional_alpaca_broker_identifier(payload.get("id")) != order_id:
        raise _OrderLookupIdentityError(payload)
    return _fetch_order_replacement_chain(
        client,
        payload,
        client_order_id,
        validate_order_timestamps=validate_order_timestamps,
    )


def _fetch_durable_buy_cancellation_lineages(
    client: AlpacaClient,
    order_ids: list[str],
    *,
    expected_client_order_id: str,
    expected_symbol: str,
    expected_alpaca_asset_id: str | None,
    accepted_alpaca_asset_ids: Collection[str] | None = None,
) -> tuple[list[list[dict]], list[dict], list[str]]:
    """Best-effort refresh every independently accepted buy retained for follow-up."""
    lineages: list[list[dict]] = []
    unique_orders: list[dict] = []
    resolution_issues_by_order_id: dict[str, str] = {}
    seen_order_ids: set[str] = set()
    for persisted_order_id in order_ids:
        try:
            direct_order = _cached_reconciliation_order_payload(client, persisted_order_id)
            if direct_order is None:
                response = client.get_order(persisted_order_id)
                _require_2xx_response(response)
                direct_order = _response_json(response)
            if _optional_str(direct_order.get("id")) != persisted_order_id:
                raise BuyOrderIdentityError("lookup returned a different broker order ID")
            leaf, lineage = _fetch_order_replacement_chain(
                client,
                direct_order,
                expected_client_order_id,
            )
            observed_asset_id = _replacement_chain_stable_asset_id(lineage)
            lineage_expected_asset_id = expected_alpaca_asset_id
            if observed_asset_id in frozenset(accepted_alpaca_asset_ids or ()):
                lineage_expected_asset_id = observed_asset_id
            attributed_lineage = _safely_attributed_buy_order_lineage(
                leaf,
                expected_client_order_id=expected_client_order_id,
                expected_symbol=expected_symbol,
                expected_alpaca_asset_id=lineage_expected_asset_id,
                expected_alpaca_order_id=persisted_order_id,
                replacement_chain=lineage,
            )
            if attributed_lineage is None:
                raise BuyOrderIdentityError("lineage could not be strictly attributed")
        except (requests.RequestException, RuntimeError, ValueError) as exc:
            detail = _alpaca_client_exception_diagnostic(exc, client=client)
            resolution_issues_by_order_id[persisted_order_id] = f"broker order {persisted_order_id}: {detail}"
            continue
        lineages.append(attributed_lineage)
        for order in attributed_lineage:
            order_id = _optional_str(order.get("id"))
            if order_id is None or order_id in seen_order_ids:
                continue
            seen_order_ids.add(order_id)
            unique_orders.append(order)
    resolution_issues = [
        issue for order_id, issue in resolution_issues_by_order_id.items() if order_id not in seen_order_ids
    ]
    return lineages, unique_orders, resolution_issues


def _tracked_buy_lineages_intent_issue(
    lineages: list[list[dict]],
    *,
    expected_client_order_id: str,
    expected_symbol: str,
    expected_alpaca_asset_id: str | None,
    accepted_alpaca_asset_ids: Collection[str] | None = None,
    expected_qty: float | None,
    expected_limit_price: float | None,
) -> str | None:
    """Validate frozen economics on every independently tracked buy lineage."""
    issues: list[str] = []
    seen_lineages: set[tuple[str, ...]] = set()
    for lineage in lineages:
        lineage_ids = tuple(order_id for node in lineage if (order_id := _optional_str(node.get("id"))) is not None)
        if lineage_ids in seen_lineages:
            continue
        seen_lineages.add(lineage_ids)
        observed_asset_id = _replacement_chain_stable_asset_id(lineage)
        lineage_expected_asset_id = expected_alpaca_asset_id
        if observed_asset_id in frozenset(accepted_alpaca_asset_ids or ()):
            lineage_expected_asset_id = observed_asset_id
        issue = _buy_order_identity_issue(
            lineage[-1],
            expected_client_order_id=expected_client_order_id,
            expected_symbol=expected_symbol,
            expected_alpaca_asset_id=lineage_expected_asset_id,
            expected_alpaca_order_id=None,
            expected_qty=expected_qty,
            expected_limit_price=expected_limit_price,
            replacement_chain=lineage,
            require_expected_intent=True,
        )
        if issue is not None:
            label = lineage_ids[-1] if lineage_ids else "unknown"
            issues.append(f"tracked buy lineage {label}: {issue}")
    return "; ".join(issues) if issues else None


def _historical_managed_sell_lineages(
    *,
    conn: sqlite3.Connection,
    client: AlpacaClient,
    position: dict,
    current_orders: dict[str, dict],
    expected_alpaca_asset_id: str | None,
) -> tuple[dict[str, dict], dict[str, dict], list[str]]:
    """Resolve and safely attribute every persisted historical sell lineage.

    The fill ledger stores exact broker order IDs, including zero-fill
    generations. A persisted ID can be any node in an Alpaca-created
    replacement chain, so each previously unseen ID is expanded in both
    directions before accounting or cancellation. Broker IDs are deduplicated
    across overlapping ledger entries.
    """
    position_id = int(position["id"])
    symbol = str(position["symbol"])
    sell_order_namespace = _optional_str(position.get("sell_order_namespace"))
    observed_orders = dict(current_orders)
    historical_leaves: dict[str, dict] = {}
    intent_issues: list[str] = []
    persisted_generation_intents = alpaca_managed_sell_generation_intents(conn, position_id)
    accepted_asset_ids = frozenset(alpaca_managed_position_asset_ids(position))

    for persisted_order_id in alpaca_managed_sell_fill_order_ids(conn, position_id):
        if persisted_order_id in observed_orders:
            continue
        direct_order = _cached_reconciliation_order_payload(client, persisted_order_id)
        if direct_order is None:
            response = client.get_order(persisted_order_id)
            _require_2xx_response(response)
            direct_order = _response_json(response)
        if _optional_str(direct_order.get("id")) != persisted_order_id:
            raise SellOrderIdentityError("historical sell-fill audit returned a different broker order ID")
        leaf, lineage = _resolve_order_replacement_chain(client, direct_order)
        lineage_ids = {_optional_str(order.get("id")) for order in lineage}
        if persisted_order_id not in lineage_ids:
            raise SellOrderIdentityError(
                "historical sell-fill audit lost the persisted broker order in its replacement lineage"
            )
        root_client_order_id = _optional_str(lineage[0].get("client_order_id"))
        if (
            root_client_order_id is None
            or _alpaca_exit_client_order_generation(
                symbol,
                position_id,
                root_client_order_id,
                order_namespace=sell_order_namespace,
                allow_legacy_position_id=True,
            )
            is None
        ):
            raise SellOrderIdentityError(
                "historical sell replacement root is not attributable to this managed position"
            )
        lineage_asset_id = _replacement_chain_stable_asset_id(lineage)
        if accepted_asset_ids and lineage_asset_id not in accepted_asset_ids:
            raise SellOrderIdentityError(
                "historical sell replacement lineage conflicts with every managed asset-ID generation"
            )
        lineage_expected_asset_id = lineage_asset_id if accepted_asset_ids else expected_alpaca_asset_id
        if not all(
            _order_matches_core_intent(
                order,
                expected_symbol=symbol,
                expected_alpaca_asset_id=lineage_expected_asset_id,
                expected_side="sell",
                expected_order_type="limit",
                expected_time_in_force="gtc",
                require_complete=True,
            )
            for order in lineage
        ):
            raise SellOrderIdentityError(
                "historical sell replacement lineage conflicts with the managed asset or order type"
            )

        submitted_qty, submitted_limit_price = persisted_generation_intents.get(
            persisted_order_id,
            (None, None),
        )
        if submitted_qty is None or submitted_limit_price is None:
            intent_issues.append(
                f"{persisted_order_id}: historical managed sell generation is missing its "
                "immutable submitted quantity or limit price"
            )
        else:
            lineage_issue = _sell_replacement_chain_intent_issue(
                lineage,
                requested_qty=submitted_qty,
                target_sell_price=submitted_limit_price,
            )
            if lineage_issue is not None:
                intent_issues.append(f"{persisted_order_id}: {lineage_issue}")

        for order in lineage:
            order_id = _optional_str(order.get("id"))
            assert order_id is not None
            observed_orders.setdefault(order_id, order)
        leaf_id = _optional_str(leaf.get("id"))
        assert leaf_id is not None
        historical_leaves.setdefault(leaf_id, leaf)

    return observed_orders, historical_leaves, intent_issues


def _observed_sell_generation_intents(
    *,
    observed_orders: dict[str, dict],
    persisted_intents: dict[str, tuple[float | None, float | None]],
    current_order_ids: set[str] | None = None,
    current_intent: tuple[float, float] | None = None,
) -> dict[str, tuple[float, float]]:
    """Propagate frozen economics across newly discovered replacement links."""
    intents: dict[str, tuple[float, float]] = {
        order_id: (submitted_qty, submitted_limit_price)
        for order_id, (submitted_qty, submitted_limit_price) in persisted_intents.items()
        if submitted_qty is not None and submitted_limit_price is not None
    }
    if current_intent is not None:
        for order_id in current_order_ids or set():
            intents.setdefault(order_id, current_intent)

    intent_was_propagated = True
    while intent_was_propagated:
        intent_was_propagated = False
        for order_id, order in observed_orders.items():
            if order_id in intents:
                continue
            for linked_order_id in (
                _optional_str(order.get("replaces")),
                _optional_str(order.get("replaced_by")),
            ):
                linked_intent = intents.get(linked_order_id or "")
                if linked_intent is not None:
                    intents[order_id] = linked_intent
                    intent_was_propagated = True
                    break
    return intents


def _missing_sell_retry_historical_exposure_audit(
    *,
    conn: sqlite3.Connection,
    client: AlpacaClient,
    position: dict,
    allow_fenced_inactive_intent_mismatch: bool = False,
) -> tuple[list[dict], str | None]:
    """Verify prior sell lineages without changing the quantity claimed for a retry."""
    observed_orders, _historical_leaves, intent_issues = _historical_managed_sell_lineages(
        conn=conn,
        client=client,
        position=position,
        current_orders={},
        expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
    )
    persisted_fills = alpaca_managed_sell_fill_observations(conn, int(position["id"]))
    accounting_issues: list[str] = []
    for order_id, order in observed_orders.items():
        if _sell_replacement_chain_position_intent_issue([order]) is not None:
            # A non-closing sell may be owned strongly enough to cancel, but
            # its fills can never revise the managed long's realized ledger.
            continue
        raw_filled_qty = _replacement_chain_nonnegative_filled_qty([order])
        filled_qty, filled_avg_price, metadata_is_valid = _sell_fill_metadata(order)
        order_status = _broker_order_status(order)
        if (
            raw_filled_qty is None
            or not metadata_is_valid
            or (order_status in {"filled", "partially_filled"} and (filled_qty == 0.0 or filled_avg_price is None))
        ):
            accounting_issues.append(f"sell order {order_id} has incomplete authoritative fill metadata")
            continue

        filled_value = 0.0 if filled_avg_price is None else filled_qty * filled_avg_price
        persisted_fill = persisted_fills.get(order_id)
        if persisted_fill is None:
            if filled_qty > 0.0:
                accounting_issues.append(f"sell order {order_id} has an unaccounted historical fill")
            continue
        persisted_qty, persisted_value = persisted_fill
        if abs(filled_qty - persisted_qty) > _managed_qty_tolerance(filled_qty, persisted_qty) or abs(
            filled_value - persisted_value
        ) > _managed_value_tolerance(filled_value, persisted_value):
            accounting_issues.append(f"authoritative historical sell fill for {order_id} changed")

    active_historical_orders = [
        order for order in observed_orders.values() if _broker_order_status(order) in _ORDER_MAY_BE_ACTIVE_STATUSES
    ]
    # A replacement reached this point only after the prior generation's
    # cancellation ownership was persisted and the broker re-read proved all
    # attributed orders inactive. Its immutable-economics mismatch remains in
    # the ledger for closed audits, but cannot strand currently uncovered
    # shares by blocking fresh protection. Accounting conflicts always block.
    blocking_intent_issues = (
        [] if allow_fenced_inactive_intent_mismatch and not active_historical_orders else intent_issues
    )
    issues = [*blocking_intent_issues, *accounting_issues]
    return active_historical_orders, "; ".join(issues) if issues else None


def _deduplicated_managed_sell_leaves(
    current_replacement_chain: list[dict],
    historical_leaves: dict[str, dict],
) -> dict[str, dict]:
    """Return every attributed executable leaf once, preferring the current observation."""
    leaves = dict(historical_leaves)
    if current_replacement_chain:
        current_leaf = current_replacement_chain[-1]
        current_leaf_id = _optional_str(current_leaf.get("id"))
        if current_leaf_id is not None:
            leaves[current_leaf_id] = current_leaf
    return leaves


def _active_managed_sell_leaves(leaves: dict[str, dict]) -> list[dict]:
    return [order for order in leaves.values() if _broker_order_status(order) in _ORDER_MAY_BE_ACTIVE_STATUSES]


def _request_managed_sell_leaf_cancellations(
    client: AlpacaClient,
    leaves: list[dict],
) -> tuple[bool, list[str]]:
    """Request cancellation of every already-attributed active leaf."""
    cancellation_pending = False
    messages: list[str] = []
    for leaf in leaves:
        pending, message = _request_safely_attributed_order_cancellation(client, leaf)
        cancellation_pending = cancellation_pending or pending
        messages.append(f"{_optional_str(leaf.get('id'))}: {message}")
    return cancellation_pending, messages


def _record_active_historical_sell_fills(
    *,
    conn: sqlite3.Connection,
    client: AlpacaClient,
    position: dict,
    current_replacement_chain: list[dict],
    initial_remaining_qty: float,
) -> tuple[
    float,
    list[dict],
    str | None,
    tuple[dict[str, dict], dict[str, dict], list[str]],
    float,
]:
    """Account corrections from every prior sell generation before trusting coverage."""
    current_orders = {
        order_id: order
        for order in current_replacement_chain
        if (order_id := _optional_str(order.get("id"))) is not None
    }
    observed_orders, historical_leaves, historical_intent_issues = _historical_managed_sell_lineages(
        conn=conn,
        client=client,
        position=position,
        current_orders=current_orders,
        expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
    )
    persisted_fills = alpaca_managed_sell_fill_observations(conn, int(position["id"]))
    current_order_ids = set(current_orders)
    current_submitted_qty = _optional_positive_float(position.get("sell_order_qty"))
    current_submitted_limit_price = _optional_positive_float(position.get("sell_order_limit_price"))
    generation_intents = _observed_sell_generation_intents(
        observed_orders=observed_orders,
        persisted_intents=alpaca_managed_sell_generation_intents(
            conn,
            int(position["id"]),
        ),
        current_order_ids=current_order_ids,
        current_intent=(
            (current_submitted_qty, current_submitted_limit_price)
            if current_submitted_qty is not None and current_submitted_limit_price is not None
            else None
        ),
    )
    remaining_qty = initial_remaining_qty

    historical_observations: list[tuple[str, str, float, float | None, str | None]] = []
    for order_id, order in observed_orders.items():
        if order_id in current_orders:
            continue
        if _sell_replacement_chain_position_intent_issue([order]) is not None:
            # Retain and cancel the attributed generation, but do not treat a
            # non-closing execution as a sale of the managed long.
            continue
        raw_filled_qty = _replacement_chain_nonnegative_filled_qty([order])
        filled_qty, filled_avg_price, metadata_is_valid = _sell_fill_metadata(order)
        order_status = _broker_order_status(order)
        if (
            raw_filled_qty is None
            or not metadata_is_valid
            or (order_status in {"filled", "partially_filled"} and (filled_qty == 0.0 or filled_avg_price is None))
        ):
            raise SellFillMetadataError(filled_qty)

        prior_qty, prior_value = persisted_fills.get(order_id, (0.0, 0.0))
        regression_mark_price = _managed_sell_residual_mark_price(
            filled_avg_price,
            prior_value / prior_qty if prior_qty > 0.0 else None,
            order.get("limit_price"),
        )
        if filled_qty < prior_qty and not _managed_sell_quantities_match(
            filled_qty,
            prior_qty,
            mark_price=regression_mark_price,
        ):
            raise SellFillQuantityRegressionError(
                "Alpaca historical sell filled quantity moved backwards for a managed order."
            )
        if filled_qty == 0.0 and abs(prior_value) > _managed_value_tolerance(prior_value):
            raise SellFillQuantityRegressionError(
                "Alpaca historical sell value conflicts with its zero filled quantity."
            )
        historical_observations.append(
            (
                order_id,
                order_status,
                filled_qty,
                filled_avg_price,
                _optional_alpaca_datetime_str(order.get("updated_at")),
            )
        )

    for order_id, order_status, filled_qty, filled_avg_price, broker_updated_at in historical_observations:
        generation_intent = generation_intents.get(order_id)
        record_alpaca_managed_sell_generation(
            conn,
            int(position["id"]),
            order_id,
            broker_updated_at=(broker_updated_at if filled_qty == 0.0 else _STORAGE_UNSET),
            submitted_qty=None if generation_intent is None else generation_intent[0],
            submitted_limit_price=None if generation_intent is None else generation_intent[1],
        )
        if filled_qty == 0.0:
            continue
        assert filled_avg_price is not None
        remaining_qty, _ = mark_alpaca_managed_sell_filled_if_current(
            conn,
            int(position["id"]),
            expected_sell_client_order_id=f"__historical-fill-only__:{order_id}",
            sell_status=order_status,
            sell_filled_qty=filled_qty,
            sell_filled_avg_price=filled_avg_price,
            sell_filled_at=None,
            sell_broker_updated_at=broker_updated_at,
            sell_alpaca_order_id=order_id,
        )

    active_historical_orders = [
        order
        for order_id, order in observed_orders.items()
        if order_id not in current_orders and _broker_order_status(order) in _ORDER_MAY_BE_ACTIVE_STATUSES
    ]
    intent_issue = "; ".join(historical_intent_issues) if historical_intent_issues else None
    compatible_historical_orders = [
        order for order in observed_orders.values() if _sell_replacement_chain_position_intent_issue([order]) is None
    ]
    historical_sell_mark_price = _managed_sell_residual_mark_price(
        *(order.get("limit_price") for order in compatible_historical_orders),
        *(_sell_fill_metadata(order)[1] for order in compatible_historical_orders),
    )
    return (
        remaining_qty,
        active_historical_orders,
        intent_issue,
        (observed_orders, historical_leaves, historical_intent_issues),
        historical_sell_mark_price,
    )


def _managed_sell_exposure_close_audit(
    *,
    conn: sqlite3.Connection,
    client: AlpacaClient,
    position: dict,
    current_replacement_chain: list[dict],
    current_intent_issue: str | None,
    resolved_historical_audit: tuple[dict[str, dict], dict[str, dict], list[str]] | None = None,
) -> tuple[list[dict], str | None]:
    """Confirm that persisted accounting covers every attributed sell lineage."""
    current_orders = {
        order_id: order
        for order in current_replacement_chain
        if (order_id := _optional_str(order.get("id"))) is not None
    }
    if resolved_historical_audit is None:
        try:
            observed_orders, historical_leaves, historical_intent_issues = _historical_managed_sell_lineages(
                conn=conn,
                client=client,
                position=position,
                current_orders=current_orders,
                expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
            )
        except (requests.RequestException, SellOrderIdentityError, RuntimeError, ValueError) as exc:
            return [], _alpaca_client_exception_diagnostic(exc, client=client)
    else:
        observed_orders, historical_leaves, historical_intent_issues = resolved_historical_audit

    current_leaf_id = _optional_str(current_replacement_chain[-1].get("id"))
    if current_leaf_id is None:
        return [], "current managed sell replacement leaf has no broker order ID"
    # A contradictory broker snapshot can report a replacement ancestor as
    # active even while it links to a successor.  Closure is safe only when
    # every attributed node, not merely each semantic leaf, is inactive.
    active_orders = [
        order for order in observed_orders.values() if _broker_order_status(order) in _ORDER_MAY_BE_ACTIVE_STATUSES
    ]

    intent_issues = [issue for issue in [current_intent_issue, *historical_intent_issues] if issue]
    if intent_issues:
        return active_orders, "; ".join(intent_issues)

    authoritative_fills: dict[str, tuple[float, float]] = {}
    for order_id, order in observed_orders.items():
        raw_filled_qty = _replacement_chain_nonnegative_filled_qty([order])
        filled_qty, filled_avg_price, metadata_is_valid = _sell_fill_metadata(order)
        if raw_filled_qty is None or not metadata_is_valid:
            return active_orders, f"sell order {order_id} has incomplete authoritative fill metadata"
        filled_value = 0.0
        if filled_qty > 0.0:
            if filled_avg_price is None:
                return active_orders, f"sell order {order_id} has no positive authoritative fill price"
            filled_value = filled_qty * filled_avg_price
        authoritative_fills[order_id] = (filled_qty, filled_value)

    persisted_fills = alpaca_managed_sell_fill_observations(conn, int(position["id"]))
    if authoritative_fills.keys() != persisted_fills.keys():
        return active_orders, "authoritative sell lineages do not match the persisted per-order fill ledger"
    for order_id, (filled_qty, filled_value) in authoritative_fills.items():
        persisted_qty, persisted_value = persisted_fills[order_id]
        if abs(filled_qty - persisted_qty) > _managed_qty_tolerance(filled_qty, persisted_qty) or abs(
            filled_value - persisted_value
        ) > _managed_value_tolerance(filled_value, persisted_value):
            return active_orders, f"authoritative sell fill for {order_id} changed after closed-position correction"

    return active_orders, None


def _replacement_lineage_to_client_order_id(
    client: AlpacaClient,
    order: dict,
    expected_client_order_id: str,
) -> list[dict]:
    """Walk a persisted replacement successor backward to its managed ancestor."""
    lineage = [order]
    seen_ids: set[str] = set()
    for _ in range(_ALPACA_REPLACEMENT_CHAIN_LIMIT):
        current = lineage[-1]
        current_id = _optional_str(current.get("id"))
        if current_id is None or current_id in seen_ids:
            raise ValueError("Alpaca order replacement lineage has a missing or repeated order ID")
        seen_ids.add(current_id)
        if _optional_str(current.get("client_order_id")) == expected_client_order_id:
            return lineage

        prior_id = _optional_str(current.get("replaces"))
        if prior_id is None:
            raise ValueError("Alpaca replacement successor is not linked to the persisted client order ID")
        prior_response = client.get_order(prior_id)
        _require_2xx_response(prior_response)
        prior = _response_json(prior_response)
        if _optional_str(prior.get("id")) != prior_id:
            raise ValueError("Alpaca replacement ancestor lookup returned a different order ID")
        if _optional_str(prior.get("replaced_by")) != current_id:
            raise ValueError("Alpaca replacement ancestor does not link to its successor")
        lineage.append(prior)

    raise RuntimeError(f"Alpaca order replacement lineage exceeded {_ALPACA_REPLACEMENT_CHAIN_LIMIT} generations")


def _append_reconciliation_result(
    rows: list[dict],
    *,
    position_id: int,
    symbol: str,
    action: str,
    status: str,
    buy_client_order_id: str,
    sell_client_order_id: str | None,
    qty: float | None,
    limit_price: float | None,
    alpaca_order_id: str | None,
    message: str,
    systemic_failure: bool = False,
    required_failure: bool = False,
) -> None:
    rows.append(
        {
            "Position ID": position_id,
            "Asset": symbol,
            "Action": action,
            "Status": status,
            "Buy Client Order ID": buy_client_order_id,
            "Sell Client Order ID": sell_client_order_id,
            "Qty": qty,
            "Limit Price": limit_price,
            "Alpaca Order ID": alpaca_order_id,
            "Message": message,
            "_Systemic Failure": systemic_failure,
            "_Required Failure": required_failure,
        }
    )


def _append_live_position_quantity_mismatch_result(
    *,
    rows: list[dict],
    position_id: int,
    symbol: str,
    buy_client_order_id: str,
    sell_client_order_id: str | None,
    requested_qty: float,
    live_qty: float,
    target_sell_price: float,
    sell_alpaca_order_id: str | None,
    existing_order_preserved: bool,
) -> None:
    message = (
        "live stable-asset quantity no longer matches managed replacement coverage; "
        "the existing protective order was left untouched for manual review"
        if existing_order_preserved
        else "requested managed sell quantity does not match the live stable-asset holding; no sell was submitted"
    )
    _append_reconciliation_result(
        rows,
        position_id=position_id,
        symbol=symbol,
        action="sell",
        status="position_quantity_mismatch",
        buy_client_order_id=buy_client_order_id,
        sell_client_order_id=sell_client_order_id,
        qty=requested_qty,
        limit_price=target_sell_price,
        alpaca_order_id=sell_alpaca_order_id,
        message=f"{message} (managed={requested_qty}, live={live_qty})",
        required_failure=True,
    )


def _record_filled_managed_sell(
    *,
    conn: sqlite3.Connection,
    position_id: int,
    sell_order: dict,
    sell_alpaca_order_id: str | None,
    sell_client_order_id: str,
    sell_status: str = "filled",
    close_on_complete: bool = True,
) -> tuple[float, float, bool]:
    sell_filled_qty, sell_filled_avg_price, fill_metadata_is_valid = _sell_fill_metadata(sell_order)
    if not fill_metadata_is_valid or sell_filled_qty <= 0.0:
        raise SellFillMetadataError(sell_filled_qty)
    if not sell_alpaca_order_id:
        raise SellOrderIdentityError("filled Alpaca sell order is missing its broker order ID")
    sell_fill_mark_price = _managed_sell_residual_mark_price(
        sell_filled_avg_price,
        sell_order.get("limit_price"),
    )

    remaining_qty, generation_is_current = mark_alpaca_managed_sell_filled_if_current(
        conn,
        position_id,
        expected_sell_client_order_id=sell_client_order_id,
        sell_status=sell_status,
        sell_filled_qty=sell_filled_qty,
        sell_filled_avg_price=sell_filled_avg_price,
        sell_filled_at=_optional_alpaca_datetime_str(sell_order.get("filled_at")),
        sell_broker_updated_at=_optional_alpaca_datetime_str(sell_order.get("updated_at")),
        sell_alpaca_order_id=sell_alpaca_order_id,
        sell_submitted_at=_optional_alpaca_datetime_str(sell_order.get("submitted_at")),
        sell_expires_at=_optional_alpaca_datetime_str(sell_order.get("expires_at")),
    )
    if not generation_is_current:
        return sell_filled_qty, remaining_qty, False
    if (
        sell_status == "filled"
        and _managed_sell_is_complete(
            remaining_qty,
            sell_filled_qty,
            mark_price=sell_fill_mark_price,
        )
        and close_on_complete
    ):
        closed = close_alpaca_managed_position_if_current_and_complete(
            conn,
            position_id,
            expected_sell_client_order_id=sell_client_order_id,
            expected_sell_alpaca_order_id=sell_alpaca_order_id,
            closed_at=_optional_alpaca_datetime_str(sell_order.get("filled_at")),
            notes="managed target sell filled",
        )
        if not closed:
            return sell_filled_qty, remaining_qty, False
    elif sell_status == "filled" and not _managed_sell_is_complete(
        remaining_qty,
        sell_filled_qty,
        mark_price=sell_fill_mark_price,
    ):
        mismatch_generation_is_current = update_alpaca_managed_sell_status_if_current(
            conn,
            position_id,
            expected_sell_client_order_id=sell_client_order_id,
            sell_status="quantity_mismatch",
            notes="filled sell quantity did not close the managed buy quantity; manual review required",
        )
        if not mismatch_generation_is_current:
            return sell_filled_qty, remaining_qty, False
    return sell_filled_qty, remaining_qty, True


def _record_replacement_chain_sell_fills(
    *,
    conn: sqlite3.Connection,
    position_id: int,
    sell_client_order_id: str,
    replacement_chain: list[dict],
    initial_remaining_qty: float,
    expected_renewal_snapshot: AlpacaManagedSellRenewalSnapshot | None = None,
    preserve_pending_cancel: bool = False,
) -> tuple[float, bool]:
    """Persist each replacement generation's cumulative fill under its own order ID."""
    position_intent_issue = _sell_replacement_chain_position_intent_issue(replacement_chain)
    if position_intent_issue is not None:
        raise SellOrderIdentityError(position_intent_issue)
    remaining_qty = initial_remaining_qty
    generation_is_current = True
    submitted_generation_qty = _optional_positive_float(replacement_chain[0].get("qty"))
    submitted_generation_limit_price = _optional_positive_float(replacement_chain[0].get("limit_price"))
    observations: list[tuple[dict, str, float, float | None]] = []
    for order in replacement_chain:
        order_id = _optional_str(order.get("id"))
        order_qty, order_avg_price, metadata_is_valid = _sell_fill_metadata(order)
        if not metadata_is_valid:
            raise SellFillMetadataError(order_qty)
        if order_id is None:
            raise SellOrderIdentityError("Alpaca sell replacement generation has no broker order ID")
        observations.append((order, order_id, order_qty, order_avg_price))

    persisted_intents = alpaca_managed_sell_generation_intents(conn, position_id)
    persisted_chain_intent = next(
        (
            intent
            for _order, order_id, _order_qty, _order_avg_price in observations
            if (intent := persisted_intents.get(order_id)) is not None
            and intent[0] is not None
            and intent[1] is not None
        ),
        None,
    )
    parent_intent = conn.execute(
        """
        SELECT sell_order_qty, sell_order_limit_price
        FROM alpaca_managed_positions
        WHERE id = ? AND sell_client_order_id = ?
        """,
        (position_id, sell_client_order_id),
    ).fetchone()
    if persisted_chain_intent is not None:
        submitted_generation_qty = persisted_chain_intent[0]
        submitted_generation_limit_price = persisted_chain_intent[1]
    elif parent_intent is not None:
        parent_qty = _optional_positive_float(parent_intent[0])
        parent_limit_price = _optional_positive_float(parent_intent[1])
        if parent_qty is not None and parent_limit_price is not None:
            submitted_generation_qty = parent_qty
            submitted_generation_limit_price = parent_limit_price

    # Reject a malformed correction anywhere in the lineage before persisting
    # any generation or fill.  In particular, do not update the active leaf
    # and invalidate the caller's diagnostic snapshot before discovering that
    # an ancestor's cumulative fill moved backwards.
    persisted_fills = alpaca_managed_sell_fill_observations(conn, position_id)
    for _order, order_id, order_qty, order_avg_price in observations:
        prior_qty, prior_value = persisted_fills.get(order_id, (0.0, 0.0))
        regression_mark_price = _managed_sell_residual_mark_price(
            order_avg_price,
            prior_value / prior_qty if prior_qty > 0.0 else None,
            submitted_generation_limit_price,
        )
        if order_qty < prior_qty and not _managed_sell_quantities_match(
            order_qty,
            prior_qty,
            mark_price=regression_mark_price,
        ):
            raise SellFillQuantityRegressionError("Alpaca sell filled quantity moved backwards for a managed order.")
        if order_qty == 0.0 and abs(prior_value) > _managed_value_tolerance(prior_value):
            raise SellFillQuantityRegressionError("Alpaca sell value conflicts with its zero filled quantity.")

    # The identity ledger is deliberately seeded even for zero-filled orders.
    # A later broker correction can then be discovered after the managed state
    # has advanced to a different renewal generation.
    for order, order_id, order_qty, _order_avg_price in observations:
        record_alpaca_managed_sell_generation(
            conn,
            position_id,
            order_id,
            broker_updated_at=(
                _optional_alpaca_datetime_str(order.get("updated_at")) if order_qty == 0.0 else _STORAGE_UNSET
            ),
            submitted_qty=submitted_generation_qty,
            submitted_limit_price=submitted_generation_limit_price,
        )

    terminal_order, terminal_id, terminal_qty, terminal_avg_price = observations[-1]
    current_renewal_snapshot = (
        None
        if expected_renewal_snapshot is None
        else alpaca_managed_sell_renewal_snapshot_if_current(
            conn,
            position_id,
            expected_sell_client_order_id=sell_client_order_id,
            expected_sell_alpaca_order_id=terminal_id,
            expected_sell_renewal_requested_at=expected_renewal_snapshot.requested_at,
        )
    )
    if expected_renewal_snapshot is not None:
        generation_is_current = bool(
            current_renewal_snapshot is not None
            and _managed_sell_snapshots_have_same_premise(
                current_renewal_snapshot,
                expected_renewal_snapshot,
            )
        )
    fill_renewal_snapshot = (
        current_renewal_snapshot
        if expected_renewal_snapshot is None or generation_is_current
        else expected_renewal_snapshot
    )
    if terminal_qty > 0.0:
        assert terminal_avg_price is not None
        remaining_qty, terminal_generation_is_current = mark_alpaca_managed_sell_filled_if_current(
            conn,
            position_id,
            expected_sell_client_order_id=sell_client_order_id,
            **_renewal_fill_snapshot_cas_kwargs(fill_renewal_snapshot),
            sell_status=(
                "pending_cancel"
                if preserve_pending_cancel
                else _broker_order_status(terminal_order, default="submitted")
            ),
            sell_filled_qty=terminal_qty,
            sell_filled_avg_price=terminal_avg_price,
            sell_filled_at=_optional_alpaca_datetime_str(terminal_order.get("filled_at")),
            sell_broker_updated_at=_optional_alpaca_datetime_str(terminal_order.get("updated_at")),
            sell_alpaca_order_id=terminal_id,
            sell_submitted_at=_optional_alpaca_datetime_str(terminal_order.get("submitted_at")),
            sell_expires_at=_optional_alpaca_datetime_str(terminal_order.get("expires_at")),
            preserve_pending_cancel=preserve_pending_cancel,
        )
        generation_is_current = generation_is_current and terminal_generation_is_current
        if not generation_is_current and expected_renewal_snapshot is None:
            return remaining_qty, False

    for ancestor, ancestor_id, ancestor_qty, ancestor_avg_price in observations[:-1]:
        if ancestor_qty == 0.0:
            continue
        assert ancestor_avg_price is not None
        # The storage primitive records broker-order fills even when its
        # generation guard does not match, while preserving the current sell
        # identity.  Ancestors are accounting-only observations here.
        remaining_qty, _ = mark_alpaca_managed_sell_filled_if_current(
            conn,
            position_id,
            expected_sell_client_order_id=f"__lineage-fill-only__:{ancestor_id}",
            sell_status=(
                "pending_cancel" if preserve_pending_cancel else _broker_order_status(ancestor, default="replaced")
            ),
            sell_filled_qty=ancestor_qty,
            sell_filled_avg_price=ancestor_avg_price,
            sell_filled_at=None,
            sell_broker_updated_at=_optional_alpaca_datetime_str(ancestor.get("updated_at")),
            sell_alpaca_order_id=ancestor_id,
            preserve_pending_cancel=preserve_pending_cancel,
        )
    if expected_renewal_snapshot is not None:
        generation_is_current = bool(
            generation_is_current
            and alpaca_managed_sell_renewal_snapshot_if_current(
                conn,
                position_id,
                expected_sell_client_order_id=sell_client_order_id,
                expected_sell_alpaca_order_id=terminal_id,
                expected_sell_renewal_requested_at=expected_renewal_snapshot.requested_at,
            )
            is not None
        )
    return remaining_qty, generation_is_current


def _record_observed_managed_sell_order(
    *,
    conn: sqlite3.Connection,
    position_id: int,
    sell_client_order_id: str,
    sell_order: dict,
    submitted_qty: float | None = None,
    submitted_limit_price: float | None = None,
    expected_sell_submission_retry_claimed_at: str | None | object = _STORAGE_UNSET,
    expected_sell_state_revision: int | object = _STORAGE_UNSET,
) -> tuple[str, str | None, bool]:
    _validate_alpaca_order_payload_identifiers(sell_order)
    sell_status = _broker_order_status(sell_order, default="submitted")
    sell_alpaca_order_id = _optional_alpaca_broker_identifier(sell_order.get("id"))
    observed_filled_qty, _observed_fill_price, fill_metadata_is_valid = _sell_fill_metadata(sell_order)
    generation_is_current = update_alpaca_managed_sell_status_if_current(
        conn,
        position_id,
        expected_sell_client_order_id=sell_client_order_id,
        sell_alpaca_order_id=sell_alpaca_order_id,
        sell_submitted_at=_optional_alpaca_datetime_str(sell_order.get("submitted_at")),
        sell_status=sell_status,
        sell_expires_at=_optional_alpaca_datetime_str(sell_order.get("expires_at")),
        sell_order_qty=submitted_qty,
        sell_order_limit_price=submitted_limit_price,
        observed_sell_filled_qty=observed_filled_qty if fill_metadata_is_valid else _STORAGE_UNSET,
        sell_broker_updated_at=_optional_alpaca_datetime_str(sell_order.get("updated_at")),
        clear_sell_submission_retry_claim=True,
        expected_sell_submission_retry_claimed_at=expected_sell_submission_retry_claimed_at,
        expected_state_revision=expected_sell_state_revision,
    )
    return sell_status, sell_alpaca_order_id, generation_is_current


def _managed_sell_adoption_premise_snapshot(
    *,
    current_snapshot: dict | None,
    symbol: str,
    sell_client_order_id: str,
    submitted_qty: float,
    target_sell_price: float,
    replacement_chain: list[dict],
) -> dict | None:
    """Return current state only when identity and immutable intent match."""
    if not replacement_chain:
        return None
    leaf = replacement_chain[-1]
    leaf_order_id = _optional_str(leaf.get("id"))
    observed_asset_id = _replacement_chain_stable_asset_id(replacement_chain)
    if leaf_order_id is None or observed_asset_id is None:
        return None
    if not _sell_order_identity_is_consistent(
        leaf,
        expected_sell_client_order_id=sell_client_order_id,
        expected_sell_alpaca_order_id=leaf_order_id,
        expected_symbol=symbol,
        expected_alpaca_asset_id=observed_asset_id,
        replacement_chain=replacement_chain,
    ):
        return None
    if (
        _sell_replacement_chain_intent_issue(
            replacement_chain,
            requested_qty=submitted_qty,
            target_sell_price=target_sell_price,
        )
        is not None
    ):
        return None

    if current_snapshot is None:
        return None
    current = current_snapshot
    persisted_status = str(current.get("sell_status") or "").lower()
    if persisted_status == "pending_cancel" or persisted_status not in _ALPACA_ORDER_STATUSES:
        return None
    if (
        _optional_str(current.get("sell_client_order_id")) != sell_client_order_id
        or _optional_str(current.get("sell_alpaca_order_id")) != leaf_order_id
        or str(current.get("symbol") or "").upper() != symbol.upper()
        or _optional_str(current.get("alpaca_asset_id")) != observed_asset_id
    ):
        return None

    persisted_order_qty = _optional_positive_decimal(current.get("sell_order_qty"))
    submitted_order_qty = _optional_positive_decimal(submitted_qty)
    if (
        persisted_order_qty is None
        or submitted_order_qty is None
        or persisted_order_qty != submitted_order_qty
        or not _limit_price_matches_frozen_intent(current.get("sell_order_limit_price"), target_sell_price)
        or not _limit_price_matches_frozen_intent(current.get("target_sell_price"), target_sell_price)
    ):
        return None

    return current


def _durably_adopted_managed_sell_snapshot(
    *,
    conn: sqlite3.Connection,
    current_snapshot: dict | None,
    position_id: int,
    symbol: str,
    sell_client_order_id: str,
    submitted_qty: float,
    target_sell_price: float,
    replacement_chain: list[dict],
) -> dict | None:
    """Return current state only when it retained this exact sell exposure."""
    current = _managed_sell_adoption_premise_snapshot(
        current_snapshot=current_snapshot,
        symbol=symbol,
        sell_client_order_id=sell_client_order_id,
        submitted_qty=submitted_qty,
        target_sell_price=target_sell_price,
        replacement_chain=replacement_chain,
    )
    if current is None:
        return None
    try:
        buy_filled_qty = _optional_float(current.get("filled_qty"))
        sold_qty = _optional_float(current.get("sold_qty")) or 0.0
        persisted_remaining_qty = _optional_float(current.get("remaining_qty"))
    except (TypeError, ValueError):
        return None
    if persisted_remaining_qty is None:
        if buy_filled_qty is None:
            return None
        persisted_remaining_qty = buy_filled_qty - sold_qty
    # Prove the accounting premise from the durable per-order ledger instead
    # of only from boundaries implied by this broker response.  This response
    # may be stale: a concurrent reconciler can already have persisted a
    # larger cumulative fill for one of these exact order IDs.  Conversely, a
    # fill under any unrelated order ID changes ``remaining_qty`` without
    # appearing in this lineage total, so the final equality still rejects it.
    persisted_fill_rows = conn.execute(
        """
        SELECT alpaca_order_id, filled_qty, filled_value, broker_updated_at
        FROM alpaca_managed_sell_fills
        WHERE managed_position_id = ?
        """,
        (position_id,),
    ).fetchall()
    persisted_fills = {
        str(order_id): (float(filled_qty), float(filled_value), broker_updated_at)
        for order_id, filled_qty, filled_value, broker_updated_at in persisted_fill_rows
    }
    persisted_lineage_filled_qty = 0.0
    for order in replacement_chain:
        order_id = _optional_str(order.get("id"))
        order_qty = _optional_positive_float(order.get("qty"))
        observed_filled_qty, observed_filled_avg_price, fill_metadata_is_valid = _sell_fill_metadata(order)
        if order_id is None or order_qty is None or not fill_metadata_is_valid:
            return None
        observed_filled_value = (
            0.0 if observed_filled_qty == 0.0 else observed_filled_qty * float(observed_filled_avg_price)
        )
        persisted_qty, persisted_value, persisted_broker_updated_at = persisted_fills.get(
            order_id,
            (0.0, 0.0, None),
        )
        accounting_mark_price = _managed_sell_residual_mark_price(
            target_sell_price,
            current.get("filled_avg_price"),
            current.get("sell_order_limit_price"),
            order.get("limit_price"),
            observed_filled_avg_price,
            persisted_value / persisted_qty if persisted_qty > 0.0 else None,
        )
        if (
            not isfinite(persisted_qty)
            or not isfinite(persisted_value)
            or (
                persisted_qty < 0.0
                and not _managed_sell_quantities_match(
                    persisted_qty,
                    0.0,
                    order_qty,
                    mark_price=accounting_mark_price,
                )
            )
            or (
                persisted_qty > order_qty
                and not _managed_sell_quantities_match(
                    persisted_qty,
                    order_qty,
                    mark_price=accounting_mark_price,
                )
            )
            or persisted_value < -_managed_value_tolerance(persisted_value)
            or (persisted_qty == 0.0 and abs(persisted_value) > _managed_value_tolerance(persisted_value))
        ):
            return None
        accounting_matches_response = bool(
            _managed_sell_quantities_match(
                persisted_qty,
                observed_filled_qty,
                order_qty,
                mark_price=accounting_mark_price,
            )
            and abs(persisted_value - observed_filled_value)
            <= _managed_value_tolerance(persisted_value, observed_filled_value)
        )
        if not accounting_matches_response:
            persisted_revision = _parse_alpaca_datetime(persisted_broker_updated_at)
            response_revision = _parse_alpaca_broker_datetime(order.get("updated_at"))
            if persisted_revision is None or response_revision is None or persisted_revision <= response_revision:
                return None
        persisted_lineage_filled_qty += persisted_qty
    expected_remaining_qty = submitted_qty - persisted_lineage_filled_qty
    residual_mark_price = _managed_sell_residual_mark_price(
        target_sell_price,
        current.get("filled_avg_price"),
        current.get("sell_order_limit_price"),
        sold_qty and (_optional_float(current.get("sold_value")) or 0.0) / sold_qty,
    )
    if not _managed_sell_quantities_match(
        persisted_remaining_qty,
        expected_remaining_qty,
        submitted_qty,
        mark_price=residual_mark_price,
    ):
        return None
    return current


def _durable_sell_fill_revision_blocks_merge(
    *,
    conn: sqlite3.Connection,
    position_id: int,
    order_id: str,
    observed_filled_qty: float,
    observed_filled_value: float,
    observed_broker_updated_at: object,
    accounting_mark_price: float,
) -> bool:
    """Keep an equal/newer versioned ledger value over conflicting input."""
    persisted = conn.execute(
        """
        SELECT filled_qty, filled_value, broker_updated_at
        FROM alpaca_managed_sell_fills
        WHERE managed_position_id = ? AND alpaca_order_id = ?
        """,
        (position_id, order_id),
    ).fetchone()
    if persisted is None:
        return False
    persisted_qty = float(persisted[0])
    persisted_value = float(persisted[1])
    residual_mark_price = _managed_sell_residual_mark_price(
        accounting_mark_price,
        persisted_value / persisted_qty if persisted_qty > 0.0 else None,
        observed_filled_value / observed_filled_qty if observed_filled_qty > 0.0 else None,
    )
    accounting_differs = bool(
        not _managed_sell_quantities_match(
            persisted_qty,
            observed_filled_qty,
            mark_price=residual_mark_price,
        )
        or abs(persisted_value - observed_filled_value)
        > _managed_value_tolerance(persisted_value, observed_filled_value)
    )
    if not accounting_differs:
        return False
    persisted_revision = _parse_alpaca_datetime(persisted[2])
    observed_revision = _parse_alpaca_broker_datetime(observed_broker_updated_at)
    return bool(
        persisted_revision is not None and (observed_revision is None or persisted_revision >= observed_revision)
    )


def _managed_position_snapshot(
    conn: sqlite3.Connection,
    position_id: int,
) -> dict | None:
    positions = load_alpaca_managed_positions(conn)
    current_match = positions.loc[positions["id"].eq(position_id)]
    return None if current_match.empty else current_match.iloc[0].to_dict()


def _append_adopted_fenced_sell_result(
    *,
    conn: sqlite3.Connection,
    rows: list[dict],
    adopted_snapshot: dict,
    position_id: int,
    symbol: str,
    buy_client_order_id: str,
    sell_client_order_id: str,
    submitted_qty: float,
    target_sell_price: float,
    leaf_order_id: str,
    source: str,
    sell_submission_retry_claimed_at: str,
) -> None:
    retry_token_released = False
    if _optional_str(adopted_snapshot.get("sell_submission_retry_claimed_at")) == sell_submission_retry_claimed_at:
        retry_token_released = release_alpaca_managed_sell_submission_claim_if_adopted(
            conn,
            position_id,
            sell_alpaca_order_id=leaf_order_id,
            sell_client_order_id=sell_client_order_id,
            claimed_at=sell_submission_retry_claimed_at,
            expected_state_revision=int(adopted_snapshot["state_revision"]),
        )
    retained_token = _optional_str(adopted_snapshot.get("sell_submission_retry_claimed_at"))
    token_message = (
        "the stale submission token was released"
        if retry_token_released or retained_token is None
        else "a concurrently changing submission token was left untouched"
    )
    _append_reconciliation_result(
        rows,
        position_id=position_id,
        symbol=symbol,
        action="sell",
        status=str(adopted_snapshot.get("sell_status") or "existing").lower(),
        buy_client_order_id=buy_client_order_id,
        sell_client_order_id=sell_client_order_id,
        qty=submitted_qty,
        limit_price=target_sell_price,
        alpaca_order_id=leaf_order_id,
        message=(
            f"managed state changed during {source}, but concurrent state already adopted the exact "
            f"broker sell lineage; no authoritative order was canceled or quarantined and {token_message}"
        ),
    )


def _append_fenced_stale_sell_submission_result(
    *,
    conn: sqlite3.Connection,
    client: AlpacaClient,
    rows: list[dict],
    position_id: int,
    symbol: str,
    buy_client_order_id: str,
    sell_client_order_id: str,
    submitted_qty: float,
    target_sell_price: float,
    replacement_chain: list[dict],
    source: str,
    sell_submission_retry_claimed_at: str,
    allow_terminal_resolution: bool = True,
) -> None:
    """Quarantine an attributed order observed after a fence lost.

    The broker call cannot participate in the SQLite transaction.  If managed
    state changes while that call is in flight, retain every exact broker ID
    and compatible closing fill without allowing the stale response to replace
    the corrected sell identity. Explicit non-closing fills are evidence only:
    they are never booked against the managed long. An exact lineage that
    concurrent state already adopted is preserved; otherwise every executable
    node is canceled and the local position is quarantined for follow-up.
    """
    leaf = replacement_chain[-1]
    leaf_order_id = _optional_str(leaf.get("id"))
    observed_asset_id = _replacement_chain_stable_asset_id(replacement_chain)
    position_intent_issue = _sell_replacement_chain_position_intent_issue(replacement_chain)
    pre_adoption_accounting_issues: list[str] = (
        []
        if position_intent_issue is None
        else [f"{position_intent_issue}; non-closing fills were not added to managed accounting"]
    )
    adoption_accounting_failed = False
    current_snapshot = _managed_position_snapshot(conn, position_id)
    potential_adoption = _managed_sell_adoption_premise_snapshot(
        current_snapshot=current_snapshot,
        symbol=symbol,
        sell_client_order_id=sell_client_order_id,
        submitted_qty=submitted_qty,
        target_sell_price=target_sell_price,
        replacement_chain=replacement_chain,
    )
    if potential_adoption is not None and position_intent_issue is None:
        for order in replacement_chain:
            order_id = _optional_str(order.get("id"))
            filled_qty, filled_avg_price, metadata_is_valid = _sell_fill_metadata(order)
            if not metadata_is_valid or order_id is None:
                adoption_accounting_failed = True
                pre_adoption_accounting_issues.append(
                    f"sell order {order_id or '<missing>'} could not be durably merged before adoption"
                )
                continue
            if filled_qty == 0.0:
                continue
            assert filled_avg_price is not None
            observed_filled_value = filled_qty * filled_avg_price
            if _durable_sell_fill_revision_blocks_merge(
                conn=conn,
                position_id=position_id,
                order_id=order_id,
                observed_filled_qty=filled_qty,
                observed_filled_value=observed_filled_value,
                observed_broker_updated_at=order.get("updated_at"),
                accounting_mark_price=_managed_sell_residual_mark_price(
                    target_sell_price,
                    potential_adoption.get("filled_avg_price"),
                    potential_adoption.get("sell_order_limit_price"),
                    order.get("limit_price"),
                    filled_avg_price,
                ),
            ):
                # Do not let the monotonic live-fill primitive overwrite a
                # later broker bust/correction with this stale response. The
                # durable proof below retains a strictly newer observation and
                # rejects an equal or unversioned conflict.
                continue
            try:
                # The deliberately impossible client ID records authoritative
                # broker accounting while preserving current sell identity and
                # status.  This closes the leaf-first/ancestor window before
                # deciding whether the exact exposure was adopted.
                mark_alpaca_managed_sell_filled_if_current(
                    conn,
                    position_id,
                    expected_sell_client_order_id=f"__adoption-fill-only__:{order_id}",
                    sell_status=_broker_order_status(order, default="unknown"),
                    sell_filled_qty=filled_qty,
                    sell_filled_avg_price=filled_avg_price,
                    sell_filled_at=_optional_alpaca_datetime_str(order.get("filled_at")),
                    sell_broker_updated_at=_optional_alpaca_datetime_str(order.get("updated_at")),
                    sell_alpaca_order_id=order_id,
                    sell_submitted_at=_optional_alpaca_datetime_str(order.get("submitted_at")),
                    sell_expires_at=_optional_alpaca_datetime_str(order.get("expires_at")),
                    observed_alpaca_asset_id=observed_asset_id,
                )
            except SellFillQuantityRegressionError:
                # A stale response is expected to lose to a larger durable
                # fill. The timestamp-aware proof below decides whether that
                # difference is truly a newer local broker revision.
                continue
            except (sqlite3.Error, TypeError, ValueError) as exc:
                adoption_accounting_failed = True
                pre_adoption_accounting_issues.append(f"sell order {order_id} pre-adoption fill merge failed: {exc}")

    # Every positive response fill has now either been committed, lost to a
    # monotonic local observation, or marked as a failed merge.  Evaluate a
    # fresh parent snapshot against that durable ledger.
    current_snapshot = _managed_position_snapshot(conn, position_id)
    adopted_snapshot = (
        None
        if adoption_accounting_failed or position_intent_issue is not None
        else _durably_adopted_managed_sell_snapshot(
            conn=conn,
            current_snapshot=current_snapshot,
            position_id=position_id,
            symbol=symbol,
            sell_client_order_id=sell_client_order_id,
            submitted_qty=submitted_qty,
            target_sell_price=target_sell_price,
            replacement_chain=replacement_chain,
        )
    )
    if adopted_snapshot is not None:
        assert leaf_order_id is not None
        _append_adopted_fenced_sell_result(
            conn=conn,
            rows=rows,
            adopted_snapshot=adopted_snapshot,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            submitted_qty=submitted_qty,
            target_sell_price=target_sell_price,
            leaf_order_id=leaf_order_id,
            source=source,
            sell_submission_retry_claimed_at=sell_submission_retry_claimed_at,
        )
        return
    unique_orders: list[dict] = []
    seen_order_ids: set[str] = set()
    for order in replacement_chain:
        order_id = _optional_str(order.get("id"))
        if order_id is None or order_id in seen_order_ids:
            continue
        seen_order_ids.add(order_id)
        unique_orders.append(order)
    order_ids = [str(order["id"]) for order in unique_orders]
    quarantine_notes = (
        "an attributed managed sell was accepted after its submission fence became stale; "
        "local cancellation ownership was claimed before broker cancellation; current sell identity "
        "was preserved and automatic reconciliation is quarantined"
    )
    cancellation_claimed = False
    cancellation_claim_issue: str | None = None
    if current_snapshot is None:
        cancellation_claim_issue = "the managed position no longer exists"
    else:
        try:
            cancellation_claimed = quarantine_alpaca_managed_sell_stale_submission(
                conn,
                position_id,
                sell_client_order_id=sell_client_order_id,
                expected_sell_submission_retry_claimed_at=sell_submission_retry_claimed_at,
                stale_alpaca_order_ids=order_ids,
                notes=_alpaca_durable_diagnostic_note(
                    quarantine_notes,
                    cfg=client.cfg,
                    client=client,
                ),
                observed_alpaca_asset_id=observed_asset_id,
                expected_state_revision=int(current_snapshot["state_revision"]),
            )
        except sqlite3.Error as exc:
            cancellation_claim_issue = f"local cancellation ownership failed: {exc}"

    if not cancellation_claimed:
        # The compare-and-swap may have lost specifically because another
        # worker adopted this exact lineage.  Re-read once and preserve that
        # authoritative protection.  For every other outcome, fail closed:
        # without a durable local quarantine claim, no broker DELETE is safe.
        refreshed_snapshot = _managed_position_snapshot(conn, position_id)
        adopted_snapshot = (
            None
            if adoption_accounting_failed or position_intent_issue is not None
            else _durably_adopted_managed_sell_snapshot(
                conn=conn,
                current_snapshot=refreshed_snapshot,
                position_id=position_id,
                symbol=symbol,
                sell_client_order_id=sell_client_order_id,
                submitted_qty=submitted_qty,
                target_sell_price=target_sell_price,
                replacement_chain=replacement_chain,
            )
        )
        if adopted_snapshot is not None:
            assert leaf_order_id is not None
            _append_adopted_fenced_sell_result(
                conn=conn,
                rows=rows,
                adopted_snapshot=adopted_snapshot,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                submitted_qty=submitted_qty,
                target_sell_price=target_sell_price,
                leaf_order_id=leaf_order_id,
                source=source,
                sell_submission_retry_claimed_at=sell_submission_retry_claimed_at,
            )
            return
        cancellation_claim_issue = cancellation_claim_issue or "the local cancellation ownership fence changed"

    if cancellation_claimed:
        # The sticky local quarantine now owns cancellation.  Any later
        # attempt to adopt the exposure must lose its state fence before
        # broker DELETE begins.
        cancellation_results = [
            (
                _optional_str(order.get("id")),
                *_request_safely_attributed_order_cancellation(client, order),
            )
            for order in unique_orders
        ]
    else:
        # Exact broker identities and fills remain authoritative accounting
        # even when cancellation ownership is lost.  Retain them below, but
        # make every unresolved executable node pending and issue no DELETE.
        cancellation_results = [
            (
                _optional_str(order.get("id")),
                True,
                (
                    f"not canceled because {cancellation_claim_issue}; durable local cancellation "
                    "ownership could not be proven"
                ),
            )
            for order in unique_orders
        ]
    cancellation_pending = any(pending for _order_id, pending, _message in cancellation_results)
    cancellation_message = "; ".join(
        f"sell order {order_id}: {message}" for order_id, _pending, message in cancellation_results
    )
    accounting_issues = list(pre_adoption_accounting_issues)
    if observed_asset_id is None:
        accounting_issues.append(
            "attributed lineage has no single complete stable asset ID; a closed legacy row cannot be reopened"
        )
    retained_generation_count = 0
    for order in unique_orders:
        order_id = str(order["id"])
        try:
            filled_qty, _filled_avg_price, metadata_is_valid = _sell_fill_metadata(order)
            record_alpaca_managed_sell_generation(
                conn,
                position_id,
                order_id,
                broker_updated_at=(
                    _optional_alpaca_datetime_str(order.get("updated_at"))
                    if metadata_is_valid and filled_qty == 0.0
                    else _STORAGE_UNSET
                ),
                submitted_qty=submitted_qty,
                submitted_limit_price=target_sell_price,
            )
            retained_generation_count += 1
        except (sqlite3.Error, TypeError, ValueError) as exc:
            accounting_issues.append(f"sell order {order_id} generation retention failed: {exc}")

    observed_filled_qty = 0.0
    accounted_filled_qty = 0.0
    remaining_qty: float | None = None
    for order in replacement_chain:
        order_id = _optional_str(order.get("id"))
        filled_qty, filled_avg_price, metadata_is_valid = _sell_fill_metadata(order)
        order_status = _broker_order_status(order, default="unknown")
        if order_status in {"filled", "partially_filled"} and (filled_qty == 0.0 or filled_avg_price is None):
            metadata_is_valid = False
        if not metadata_is_valid:
            accounting_issues.append(f"sell order {order_id or '<missing>'} has incomplete fill metadata")
            continue
        observed_filled_qty += filled_qty
        if filled_qty == 0.0:
            continue
        assert order_id is not None and filled_avg_price is not None
        if not _optional_alpaca_position_intent_matches(
            order.get("position_intent"),
            expected=_ALPACA_MANAGED_SELL_POSITION_INTENT,
        ):
            continue
        if _durable_sell_fill_revision_blocks_merge(
            conn=conn,
            position_id=position_id,
            order_id=order_id,
            observed_filled_qty=filled_qty,
            observed_filled_value=filled_qty * filled_avg_price,
            observed_broker_updated_at=order.get("updated_at"),
            accounting_mark_price=_managed_sell_residual_mark_price(
                target_sell_price,
                current_snapshot.get("filled_avg_price") if current_snapshot is not None else None,
                current_snapshot.get("sell_order_limit_price") if current_snapshot is not None else None,
                order.get("limit_price"),
                filled_avg_price,
            ),
        ):
            accounting_issues.append(
                f"sell order {order_id} response accounting did not supersede its durable broker revision"
            )
            continue
        try:
            remaining_qty, _ = mark_alpaca_managed_sell_filled_if_current(
                conn,
                position_id,
                expected_sell_client_order_id=f"__stale-submission-fill-only__:{order_id}",
                sell_status=order_status,
                sell_filled_qty=filled_qty,
                sell_filled_avg_price=filled_avg_price,
                sell_filled_at=_optional_alpaca_datetime_str(order.get("filled_at")),
                sell_broker_updated_at=_optional_alpaca_datetime_str(order.get("updated_at")),
                sell_alpaca_order_id=order_id,
                sell_submitted_at=_optional_alpaca_datetime_str(order.get("submitted_at")),
                sell_expires_at=_optional_alpaca_datetime_str(order.get("expires_at")),
                observed_alpaca_asset_id=observed_asset_id,
            )
            accounted_filled_qty += filled_qty
        except SellFillQuantityRegressionError as exc:
            accounting_issues.append(str(exc))
        except (sqlite3.Error, TypeError, ValueError) as exc:
            accounting_issues.append(f"sell order {order_id} fill accounting failed: {exc}")

    quarantine_message = (
        "corrected managed state was quarantined for authoritative follow-up"
        if cancellation_claimed
        else "authoritative reconciliation is required before any broker cancellation can be retried"
    )

    accounting_message = (
        "exact broker generations were retained"
        if retained_generation_count == len(order_ids)
        else f"only {retained_generation_count} of {len(order_ids)} exact broker generations were retained"
    )
    if observed_filled_qty > 0.0:
        if abs(accounted_filled_qty - observed_filled_qty) <= _managed_qty_tolerance(
            accounted_filled_qty, observed_filled_qty
        ):
            accounting_message += f" and {accounted_filled_qty:g} filled shares were accounted"
        else:
            accounting_message += (
                f"; {observed_filled_qty:g} filled shares were observed but only "
                f"{accounted_filled_qty:g} were persisted"
            )
    if remaining_qty is not None:
        accounting_message += f" (managed remaining quantity {remaining_qty:g})"
    if accounting_issues:
        accounting_message += "; " + "; ".join(accounting_issues)
    terminal_resolution_message = ""
    if (
        cancellation_claimed
        and allow_terminal_resolution
        and all(
            _broker_order_status(order, default="unknown") not in _ORDER_MAY_BE_ACTIVE_STATUSES
            for order in unique_orders
        )
        and not cancellation_pending
        and not accounting_issues
    ):
        resolved = resolve_alpaca_managed_sell_stale_submission(
            conn,
            position_id,
            sell_client_order_id=sell_client_order_id,
            expected_sell_submission_retry_claimed_at=sell_submission_retry_claimed_at,
            stale_alpaca_order_ids=order_ids,
            notes=_alpaca_durable_diagnostic_note(
                "attributed stale managed sell is terminal; retained retry quarantine was released without "
                "replacing the concurrently corrected broker identity",
                cfg=client.cfg,
                client=client,
            ),
        )
        terminal_resolution_message = (
            "; retained retry quarantine was released for the next managed reconciliation"
            if resolved
            else "; terminal stale lineage could not release its retained retry quarantine"
        )
    _append_reconciliation_result(
        rows,
        position_id=position_id,
        symbol=symbol,
        action="sell",
        status=("pending_cancel" if cancellation_claimed and cancellation_pending else "superseded"),
        buy_client_order_id=buy_client_order_id,
        sell_client_order_id=sell_client_order_id,
        qty=(observed_filled_qty if observed_filled_qty > 0.0 else submitted_qty),
        limit_price=target_sell_price,
        alpaca_order_id=leaf_order_id,
        message=(
            f"managed state changed during {source}; the stale broker response did not replace corrected "
            f"sell identity; {accounting_message}; {cancellation_message}; {quarantine_message}"
            f"{terminal_resolution_message}"
        ),
        required_failure=True,
    )


def _append_fenced_unresolved_sell_submission_result(
    *,
    conn: sqlite3.Connection,
    rows: list[dict],
    position_id: int,
    symbol: str,
    buy_client_order_id: str,
    sell_client_order_id: str,
    submitted_qty: float,
    target_sell_price: float,
    sell_submission_retry_claimed_at: str,
) -> None:
    quarantine_persisted = quarantine_alpaca_managed_sell_stale_submission(
        conn,
        position_id,
        sell_client_order_id=sell_client_order_id,
        expected_sell_submission_retry_claimed_at=sell_submission_retry_claimed_at,
        stale_alpaca_order_ids=[],
        notes=_alpaca_durable_diagnostic_note(
            "a managed sell submission became ambiguous after its state fence changed; "
            "the corrected identity was preserved and broker exposure requires review",
            cfg=None,
        ),
    )
    quarantine_message = (
        "possible stale broker exposure is quarantined"
        if quarantine_persisted
        else (
            "the retained quarantine was persisted on the closed row, but it could not reopen because another "
            "active managed position owns the symbol/asset; automation remains blocked pending reconciliation"
        )
    )
    _append_reconciliation_result(
        rows,
        position_id=position_id,
        symbol=symbol,
        action="sell",
        status="superseded",
        buy_client_order_id=buy_client_order_id,
        sell_client_order_id=sell_client_order_id,
        qty=submitted_qty,
        limit_price=target_sell_price,
        alpaca_order_id=None,
        message=(
            "managed state changed during an ambiguous broker submission and exact client-order recovery "
            "did not confirm the outcome; corrected sell identity was preserved and possible stale broker "
            f"exposure remains unresolved; {quarantine_message}"
        ),
        required_failure=True,
    )


def _reconcile_retained_sell_submission_quarantine(
    *,
    conn: sqlite3.Connection,
    client: AlpacaClient,
    rows: list[dict],
    position: dict,
) -> bool:
    """Probe and neutralize a retry whose broker outcome remained ambiguous."""
    retry_token = _optional_str(position.get("sell_submission_retry_claimed_at"))
    sell_client_order_id = _optional_str(position.get("sell_client_order_id"))
    if (
        retry_token is None
        or sell_client_order_id is None
        or (_optional_str(position.get("sell_status")) or "").lower() != "quantity_mismatch"
    ):
        return False

    position_id = int(position["id"])
    symbol = str(position["symbol"])
    buy_client_order_id = str(position["buy_client_order_id"])
    expected_asset_id = _optional_str(position.get("alpaca_asset_id"))
    target_sell_price = _optional_positive_float(position.get("target_sell_price"))
    if target_sell_price is None:
        target_sell_price = _optional_positive_float(position.get("sell_order_limit_price"))
    submitted_qty = _optional_positive_float(position.get("sell_order_qty"))
    if submitted_qty is None:
        filled_qty = _optional_positive_float(position.get("filled_qty")) or 0.0
        submitted_qty = max(_managed_remaining_qty(position, filled_qty), 0.0)
    response = client.get_order_by_client_order_id(sell_client_order_id)
    candidate_payloads: list[dict] = []
    if response.status_code == 200:
        candidate_payloads = [_response_json(response)]
    elif response.status_code == 404:
        candidate_payloads = [
            order
            for order in client.open_orders(
                equity_scope_asset_ids=((expected_asset_id,) if expected_asset_id is not None else ())
            )
            if _optional_str(order.get("client_order_id")) == sell_client_order_id
        ]
        if not candidate_payloads:
            quarantine_persisted = quarantine_alpaca_managed_sell_stale_submission(
                conn,
                position_id,
                sell_client_order_id=sell_client_order_id,
                expected_sell_submission_retry_claimed_at=retry_token,
                stale_alpaca_order_ids=[],
                notes=_alpaca_durable_diagnostic_note(
                    "retained ambiguous managed sell is still not broker-visible; automatic reconciliation "
                    "remains quarantined",
                    cfg=client.cfg,
                    client=client,
                ),
            )
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="quantity_mismatch",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=submitted_qty,
                limit_price=target_sell_price,
                alpaca_order_id=None,
                message=(
                    "retained ambiguous sell retry is not yet visible by exact client ID or in complete open "
                    "orders; possible broker exposure remains quarantined"
                    if quarantine_persisted
                    else (
                        "retained ambiguous sell retry is not yet visible and its closed row could not reopen "
                        "because another active managed position owns the symbol/asset"
                    )
                ),
                required_failure=True,
            )
            return True
    else:
        _require_2xx_response(response)
        raise ValueError(f"retained sell lookup returned unexpected successful HTTP status {response.status_code}")

    attributed_chains: list[list[dict]] = []
    for candidate in candidate_payloads:
        try:
            recovered, replacement_chain = _fetch_order_replacement_chain(
                client,
                candidate,
                sell_client_order_id,
            )
        except (HTTPError, RuntimeError, ValueError) as exc:
            detail = _alpaca_client_exception_diagnostic(exc, client=client)
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="incomplete_order_metadata",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=submitted_qty,
                limit_price=target_sell_price,
                alpaca_order_id=_optional_str(candidate.get("id")),
                message=f"retained ambiguous sell retry lineage could not be validated: {detail}",
                required_failure=True,
            )
            continue
        if not _sell_order_identity_is_consistent(
            recovered,
            expected_sell_client_order_id=sell_client_order_id,
            expected_symbol=symbol,
            expected_alpaca_asset_id=expected_asset_id,
            replacement_chain=replacement_chain,
        ) or not _sell_order_matches_intent_chronology(
            replacement_chain[0],
            _optional_str(position.get("created_at")),
        ):
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="incomplete_order_metadata",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=submitted_qty,
                limit_price=target_sell_price,
                alpaca_order_id=_optional_str(recovered.get("id")),
                message=(
                    "retained ambiguous sell retry lookup did not match its exact managed identity and chronology"
                ),
                required_failure=True,
            )
            continue
        attributed_chains.append(replacement_chain)

    for replacement_chain in attributed_chains:
        observed_limit_price = _optional_positive_float(replacement_chain[0].get("limit_price"))
        effective_target_sell_price = target_sell_price or observed_limit_price
        if effective_target_sell_price is None:
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="incomplete_order_metadata",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=submitted_qty,
                limit_price=None,
                alpaca_order_id=_optional_str(replacement_chain[-1].get("id")),
                message="attributed retained sell has no valid limit price; cancellation requires review",
                required_failure=True,
            )
            continue
        _append_fenced_stale_sell_submission_result(
            conn=conn,
            client=client,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            submitted_qty=submitted_qty,
            target_sell_price=effective_target_sell_price,
            replacement_chain=replacement_chain,
            source="retained ambiguous submission recovery",
            sell_submission_retry_claimed_at=retry_token,
        )
    return True


def _retry_exact_pending_sell_cancellation_before_buy_audit(
    *,
    conn: sqlite3.Connection,
    client: AlpacaClient,
    rows: list[dict],
    position: dict,
) -> bool:
    """Consume an exact active-sell cancellation fence before parent audits can exit."""
    sell_status = (_optional_str(position.get("sell_status")) or "").lower()
    sell_client_order_id = _optional_str(position.get("sell_client_order_id"))
    sell_alpaca_order_id = _optional_alpaca_broker_identifier(position.get("sell_alpaca_order_id"))
    requested_at = _optional_str(position.get("sell_renewal_requested_at"))
    if (
        sell_status != "pending_cancel"
        or sell_client_order_id is None
        or sell_alpaca_order_id is None
        or requested_at is None
    ):
        return False
    filled_qty = _optional_float(position.get("filled_qty"))
    filled_avg_price = _optional_float(position.get("filled_avg_price"))
    target_sell_price = _optional_float(position.get("target_sell_price"))
    buy_status = (_optional_str(position.get("buy_status")) or "submission_pending").lower()
    buy_audit_will_run = bool(
        filled_qty is None
        or filled_avg_price is None
        or target_sell_price is None
        or buy_status not in {"filled", *BUY_TERMINAL_STATUSES}
        or _active_filled_buy_correction_audit_due(position)
    )
    if not buy_audit_will_run:
        return False

    position_id = int(position["id"])
    symbol = str(position["symbol"])
    buy_client_order_id = str(position["buy_client_order_id"])
    sell_order, replacement_chain = _fetch_order_payload(
        client,
        sell_alpaca_order_id,
        sell_client_order_id,
        validate_order_timestamps=False,
    )
    submitted_limit_price = _optional_positive_float(position.get("sell_order_limit_price"))
    if submitted_limit_price is None:
        submitted_limit_price = _optional_positive_float(position.get("target_sell_price"))
    submitted_qty = _optional_positive_float(position.get("sell_order_qty"))
    if submitted_qty is None:
        submitted_qty = _optional_positive_float(position.get("remaining_qty"))

    # A broker-side pending cancellation or fully inactive lineage belongs to
    # the ordinary renewal/terminal-state path. Only executable exposure needs
    # to preempt a parent-buy correction audit.
    if not _attributed_lineage_has_cancellable_order(replacement_chain):
        return False

    if not _sell_order_identity_is_consistent(
        sell_order,
        expected_sell_client_order_id=sell_client_order_id,
        expected_sell_alpaca_order_id=sell_alpaca_order_id,
        expected_symbol=symbol,
        expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
        replacement_chain=replacement_chain,
    ):
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="pending_cancel",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=submitted_qty,
            limit_price=submitted_limit_price,
            alpaca_order_id=_optional_str(sell_order.get("id")),
            message=(
                "durably fenced sell cancellation could not be retried because the authoritative "
                "replacement lineage did not match its managed identity"
            ),
            required_failure=True,
        )
        return True

    snapshot = alpaca_managed_sell_renewal_snapshot_if_current(
        conn,
        position_id,
        expected_sell_client_order_id=sell_client_order_id,
        expected_sell_alpaca_order_id=sell_alpaca_order_id,
        expected_sell_renewal_requested_at=requested_at,
    )
    cancellation_requested_at = _utc_now().isoformat().replace("+00:00", "Z")
    cancellation_owned = bool(
        snapshot is not None
        and (_optional_str(snapshot.sell_status) or "").lower() == "pending_cancel"
        and update_alpaca_managed_sell_status_if_current(
            conn,
            position_id,
            expected_sell_client_order_id=sell_client_order_id,
            **_renewal_snapshot_cas_kwargs(snapshot),
            sell_status="pending_cancel",
            sell_renewal_requested_at=cancellation_requested_at,
            notes=_alpaca_durable_diagnostic_note(
                "an exact pending sell cancellation was retried before the parent-buy correction audit",
                cfg=client.cfg,
                client=client,
            ),
        )
    )
    cancellation_message = "broker cancellation was not requested because the exact managed fence changed"
    if cancellation_owned:
        _pending, cancellation_message = _request_safely_attributed_lineage_cancellations(
            client,
            replacement_chain,
        )
    _append_reconciliation_result(
        rows,
        position_id=position_id,
        symbol=symbol,
        action="sell",
        status="pending_cancel" if cancellation_owned else "superseded",
        buy_client_order_id=buy_client_order_id,
        sell_client_order_id=sell_client_order_id,
        qty=submitted_qty,
        limit_price=submitted_limit_price,
        alpaca_order_id=_optional_str(sell_order.get("id")),
        message=(
            f"durably fenced active sell cancellation was prioritized before parent-buy auditing; "
            f"{cancellation_message}"
            if cancellation_owned
            else cancellation_message
        ),
        required_failure=cancellation_owned,
    )
    return True


def _recover_managed_sell_submission(
    *,
    conn: sqlite3.Connection,
    client: AlpacaClient,
    rows: list[dict],
    position_id: int,
    symbol: str,
    buy_client_order_id: str,
    sell_client_order_id: str,
    filled_qty: float,
    target_sell_price: float,
    message: str,
    close_on_complete: bool,
    expected_alpaca_asset_id: str | None = None,
    intent_not_before: str | None = None,
    expected_sell_submission_retry_claimed_at: str | None | object = _STORAGE_UNSET,
    expected_sell_state_revision: int | object = _STORAGE_UNSET,
    observed_payload: dict | None = None,
) -> bool:
    def durable_note(value: str) -> str:
        safe_note = _alpaca_durable_diagnostic_note(
            value,
            cfg=client.cfg,
            client=client,
        )
        assert safe_note is not None
        return safe_note

    try:
        if observed_payload is None:
            lookup = client.get_order_by_client_order_id(sell_client_order_id)
            if lookup.status_code != 200:
                return False
            observed_payload = _response_json(lookup)
        recovered, replacement_chain = _fetch_order_replacement_chain(
            client,
            observed_payload,
            sell_client_order_id,
        )
    except Exception:
        return False

    if _optional_str(recovered.get("id")) is None or not _sell_order_identity_is_consistent(
        recovered,
        expected_sell_client_order_id=sell_client_order_id,
        expected_symbol=symbol,
        expected_alpaca_asset_id=expected_alpaca_asset_id,
        replacement_chain=replacement_chain,
    ):
        _append_incomplete_sell_order_identity_result(
            conn=conn,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            observed_sell_qty=_sell_fill_metadata(recovered)[0],
            target_sell_price=target_sell_price,
            sell_alpaca_order_id=_optional_str(recovered.get("id")),
            identity_issue="broker response does not match the managed sell client-order generation",
            required_failure=True,
            expected_sell_submission_retry_claimed_at=expected_sell_submission_retry_claimed_at,
            expected_sell_state_revision=expected_sell_state_revision,
            clear_sell_submission_claim=(expected_sell_submission_retry_claimed_at is not _STORAGE_UNSET),
        )
        return True
    replacement_root = replacement_chain[0]
    if not _sell_order_matches_intent_chronology(replacement_root, intent_not_before):
        _append_incomplete_sell_order_identity_result(
            conn=conn,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            observed_sell_qty=_sell_fill_metadata(recovered)[0],
            target_sell_price=target_sell_price,
            sell_alpaca_order_id=_optional_str(recovered.get("id")),
            identity_issue=(
                "broker response predates the persisted managed sell intent or has no valid submission time"
            ),
            required_failure=True,
            expected_sell_submission_retry_claimed_at=expected_sell_submission_retry_claimed_at,
            expected_sell_state_revision=expected_sell_state_revision,
            clear_sell_submission_claim=(expected_sell_submission_retry_claimed_at is not _STORAGE_UNSET),
        )
        return True
    submission_intent_issue = _sell_replacement_chain_intent_issue(
        replacement_chain,
        requested_qty=filled_qty,
        target_sell_price=target_sell_price,
    )
    position_intent_issue = _sell_replacement_chain_position_intent_issue(replacement_chain)

    sell_status, sell_alpaca_order_id, generation_is_current = _record_observed_managed_sell_order(
        conn=conn,
        position_id=position_id,
        sell_client_order_id=sell_client_order_id,
        sell_order=recovered,
        submitted_qty=filled_qty,
        submitted_limit_price=target_sell_price,
        expected_sell_submission_retry_claimed_at=expected_sell_submission_retry_claimed_at,
        expected_sell_state_revision=expected_sell_state_revision,
    )
    if not generation_is_current:
        if expected_sell_state_revision is not _STORAGE_UNSET and isinstance(
            expected_sell_submission_retry_claimed_at, str
        ):
            _append_fenced_stale_sell_submission_result(
                conn=conn,
                client=client,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                submitted_qty=filled_qty,
                target_sell_price=target_sell_price,
                replacement_chain=replacement_chain,
                source="ambiguous submission recovery",
                sell_submission_retry_claimed_at=expected_sell_submission_retry_claimed_at,
            )
            return True
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="superseded",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=filled_qty,
            limit_price=target_sell_price,
            alpaca_order_id=sell_alpaca_order_id,
            message="submission recovery belongs to a superseded managed GTC sell generation",
        )
        return True
    recovery_snapshot = alpaca_managed_sell_renewal_snapshot_if_current(
        conn,
        position_id,
        expected_sell_client_order_id=sell_client_order_id,
        expected_sell_alpaca_order_id=sell_alpaca_order_id,
    )
    if recovery_snapshot is None or recovery_snapshot.remaining_qty is None:
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="superseded",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=filled_qty,
            limit_price=target_sell_price,
            alpaca_order_id=sell_alpaca_order_id,
            message="submission recovery lost its exact managed-state snapshot",
        )
        return True
    if position_intent_issue is not None:
        _append_sell_submission_intent_mismatch_result(
            conn=conn,
            client=client,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            requested_qty=filled_qty,
            target_sell_price=target_sell_price,
            sell_order=recovered,
            replacement_chain=replacement_chain,
            intent_issue=position_intent_issue,
            expected_renewal_snapshot=recovery_snapshot,
        )
        return True
    remaining_qty: float | None = recovery_snapshot.remaining_qty
    recovered_sell_qty, recovered_sell_avg_price, fill_metadata_is_valid = _replacement_chain_fill_metadata(
        replacement_chain
    )
    sell_residual_mark_price = _managed_sell_residual_mark_price(
        target_sell_price,
        recovered_sell_avg_price,
        *(order.get("limit_price") for order in replacement_chain),
    )
    if not fill_metadata_is_valid or (sell_status == "filled" and recovered_sell_qty == 0.0):
        _append_incomplete_sell_fill_result(
            conn=conn,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            observed_sell_qty=recovered_sell_qty,
            target_sell_price=target_sell_price,
            sell_alpaca_order_id=sell_alpaca_order_id,
            expected_renewal_snapshot=recovery_snapshot,
        )
        return True
    if recovered_sell_qty > 0.0:
        try:
            remaining_qty, generation_is_current = _record_replacement_chain_sell_fills(
                conn=conn,
                position_id=position_id,
                sell_client_order_id=sell_client_order_id,
                replacement_chain=replacement_chain,
                initial_remaining_qty=filled_qty,
                expected_renewal_snapshot=recovery_snapshot,
            )
        except SellFillMetadataError:
            _append_incomplete_sell_fill_result(
                conn=conn,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                observed_sell_qty=recovered_sell_qty,
                target_sell_price=target_sell_price,
                sell_alpaca_order_id=sell_alpaca_order_id,
                expected_renewal_snapshot=recovery_snapshot,
            )
            return True
        except SellOrderIdentityError:
            _append_incomplete_sell_order_identity_result(
                conn=conn,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                observed_sell_qty=recovered_sell_qty,
                target_sell_price=target_sell_price,
                expected_renewal_snapshot=recovery_snapshot,
            )
            return True
        except SellFillQuantityRegressionError:
            _append_sell_fill_quantity_regression_result(
                conn=conn,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                observed_sell_qty=recovered_sell_qty,
                target_sell_price=target_sell_price,
                sell_alpaca_order_id=sell_alpaca_order_id,
                expected_renewal_snapshot=recovery_snapshot,
            )
            return True
        if not generation_is_current:
            return True
        recovery_snapshot = alpaca_managed_sell_renewal_snapshot_if_current(
            conn,
            position_id,
            expected_sell_client_order_id=sell_client_order_id,
            expected_sell_alpaca_order_id=sell_alpaca_order_id,
        )
        if recovery_snapshot is None or recovery_snapshot.remaining_qty is None:
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="superseded",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=recovered_sell_qty,
                limit_price=target_sell_price,
                alpaca_order_id=sell_alpaca_order_id,
                message="sell-fill recovery lost its exact managed-state snapshot",
            )
            return True
        remaining_qty = recovery_snapshot.remaining_qty
        if submission_intent_issue is not None:
            _append_sell_submission_intent_mismatch_result(
                conn=conn,
                client=client,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                requested_qty=filled_qty,
                target_sell_price=target_sell_price,
                sell_order=recovered,
                replacement_chain=replacement_chain,
                intent_issue=submission_intent_issue,
                expected_renewal_snapshot=recovery_snapshot,
            )
            return True
        if _managed_sell_is_overfilled(
            remaining_qty,
            filled_qty,
            recovered_sell_qty,
            mark_price=sell_residual_mark_price,
        ):
            _append_overfilled_sell_result(
                conn=conn,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                observed_sell_qty=recovered_sell_qty,
                target_sell_price=target_sell_price,
                sell_alpaca_order_id=sell_alpaca_order_id,
                expected_renewal_snapshot=recovery_snapshot,
            )
            return True
        if sell_status in _ORDER_MAY_BE_ACTIVE_STATUSES and _managed_sell_is_complete(
            remaining_qty,
            filled_qty,
            recovered_sell_qty,
            mark_price=sell_residual_mark_price,
        ):
            _append_active_sell_completion_mismatch_result(
                conn=conn,
                client=client,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                observed_sell_qty=recovered_sell_qty,
                target_sell_price=target_sell_price,
                sell_order=recovered,
                replacement_chain=replacement_chain,
                expected_renewal_snapshot=recovery_snapshot,
            )
            return True
    if submission_intent_issue is not None:
        _append_sell_submission_intent_mismatch_result(
            conn=conn,
            client=client,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            requested_qty=filled_qty,
            target_sell_price=target_sell_price,
            sell_order=recovered,
            replacement_chain=replacement_chain,
            intent_issue=submission_intent_issue,
            expected_renewal_snapshot=recovery_snapshot,
        )
        return True
    effective_close_on_complete = close_on_complete and str(recovery_snapshot.buy_status or "").lower() in {
        "filled",
        *BUY_TERMINAL_STATUSES,
    }
    if sell_status == "filled" and _managed_sell_is_complete(
        remaining_qty,
        filled_qty,
        recovered_sell_qty,
        mark_price=sell_residual_mark_price,
    ):
        current_parent_is_closed = str(recovery_snapshot.buy_status or "").lower() in {
            "filled",
            *BUY_TERMINAL_STATUSES,
        }
        if effective_close_on_complete and current_parent_is_closed:
            assert sell_alpaca_order_id is not None
            closed = close_alpaca_managed_position_if_current_and_complete(
                conn,
                position_id,
                expected_sell_client_order_id=sell_client_order_id,
                expected_sell_alpaca_order_id=sell_alpaca_order_id,
                closed_at=_optional_alpaca_datetime_str(recovered.get("filled_at")),
                expected_sell_status=recovery_snapshot.sell_status or sell_status,
                expected_sell_filled_qty=recovery_snapshot.sell_filled_qty,
                expected_sell_renewal_count=recovery_snapshot.sell_renewal_count,
                expected_sell_renewal_requested_at=recovery_snapshot.requested_at,
                expected_state_revision=recovery_snapshot.state_revision,
                notes=durable_note("managed target sell filled"),
            )
            if not closed:
                _append_reconciliation_result(
                    rows,
                    position_id=position_id,
                    symbol=symbol,
                    action="sell",
                    status="superseded",
                    buy_client_order_id=buy_client_order_id,
                    sell_client_order_id=sell_client_order_id,
                    qty=recovered_sell_qty,
                    limit_price=target_sell_price,
                    alpaca_order_id=sell_alpaca_order_id,
                    message="completed sell recovery belongs to a superseded managed GTC sell generation",
                )
                return True
    elif sell_status == "filled":
        mismatch_generation_is_current = update_alpaca_managed_sell_status_if_current(
            conn,
            position_id,
            expected_sell_client_order_id=sell_client_order_id,
            **_renewal_snapshot_cas_kwargs(recovery_snapshot),
            sell_status="quantity_mismatch",
            notes=durable_note("filled sell quantity did not close the managed buy quantity; manual review required"),
        )
        if not mismatch_generation_is_current:
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="superseded",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=recovered_sell_qty,
                limit_price=target_sell_price,
                alpaca_order_id=sell_alpaca_order_id,
                message="fill mismatch belongs to a superseded managed GTC sell generation",
            )
            return True
    if sell_status in SELL_RENEWABLE_STATUSES and _gtc_sell_renewal_due(recovered, client.cfg):
        _append_incomplete_sell_expiration_metadata_result(
            conn=conn,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            target_sell_price=target_sell_price,
            sell_alpaca_order_id=sell_alpaca_order_id or "",
            expiration_issue="recovered managed GTC sell expiration remains inside the renewal window",
            expected_renewal_snapshot=recovery_snapshot,
        )
        return True
    result_message = f"recovered managed sell after ambiguous submission result: {message}"
    if sell_status == "filled":
        if remaining_qty is not None and _managed_sell_is_complete(
            remaining_qty,
            filled_qty,
            recovered_sell_qty,
            mark_price=sell_residual_mark_price,
        ):
            result_message = (
                "managed target sell filled; position closed"
                if effective_close_on_complete
                else "managed sell filled; awaiting final status of the still-open parent buy"
            )
        else:
            result_message = (
                "managed sell fill quantity does not match the managed buy; position remains active for review"
            )
    elif sell_status not in SELL_RENEWABLE_STATUSES:
        result_message = (
            f"recovered managed sell returned {sell_status}; no active protective sell was confirmed and "
            "manual review is required"
        )
    _append_reconciliation_result(
        rows,
        position_id=position_id,
        symbol=symbol,
        action="sell",
        status=sell_status,
        buy_client_order_id=buy_client_order_id,
        sell_client_order_id=sell_client_order_id,
        qty=(recovered_sell_qty if recovered_sell_qty > 0.0 else filled_qty),
        limit_price=target_sell_price,
        alpaca_order_id=sell_alpaca_order_id,
        message=result_message,
        required_failure=(
            sell_status not in {*SELL_RENEWABLE_STATUSES, "filled"}
            or (
                sell_status == "filled"
                and (
                    remaining_qty is None
                    or not _managed_sell_is_complete(
                        remaining_qty,
                        filled_qty,
                        recovered_sell_qty,
                        mark_price=sell_residual_mark_price,
                    )
                )
            )
        ),
    )
    return True


def _final_managed_sell_submission_exposure_fence(
    *,
    conn: sqlite3.Connection,
    client: AlpacaClient,
    rows: list[dict],
    position_id: int,
    symbol: str,
    buy_client_order_id: str,
    sell_client_order_id: str,
    filled_qty: float,
    target_sell_price: float,
    quantity_mark_price: float | None,
    close_on_complete: bool,
    intent_not_before: str | None,
    sell_submission_claimed_at: str,
    expected_sell_state_revision: int,
    expected_sell_status: str,
    expected_alpaca_asset_id: str | None,
    allow_fenced_inactive_historical_intent_mismatch: bool = False,
) -> tuple[int, str] | None:
    """Recheck all broker exposure and renew the local fence just before POST."""
    effective_quantity_mark_price = _managed_sell_residual_mark_price(
        target_sell_price,
        quantity_mark_price,
    )

    def release_no_post(*, sell_status: str, notes: str) -> bool:
        # This worker still owns the exact client-ID/status/claim-token tuple,
        # and every caller reaches this helper before sending a broker POST.
        # A parent-fill or close update may legitimately advance the broader
        # row revision while leaving that submission lease ours to release.
        # Rebase from the current row under the exact token instead of
        # stranding the known-unsubmitted generation on such a revision bump.
        return release_alpaca_managed_sell_submission_fence(
            conn,
            position_id,
            sell_client_order_id=sell_client_order_id,
            claimed_at=sell_submission_claimed_at,
            expected_sell_status=expected_sell_status,
            expected_state_revision=expected_sell_state_revision,
            allow_current_intent_rebase=True,
            sell_status=sell_status,
            notes=_alpaca_durable_diagnostic_note(
                notes,
                cfg=client.cfg,
                client=client,
            ),
        )

    exact_payload: dict | None = None
    visible_exposure_payload: dict | None = None
    deterministic_exposure_was_visible = False
    visible_deterministic_order_ids: list[str] = []

    def retain_visible_deterministic_exposure(payloads: list[dict]) -> None:
        """Latch broker evidence before any later validation can fail.

        A deterministic client ID is affirmative exposure evidence even when
        Alpaca violates its uniqueness contract or returns an otherwise
        incomplete account page. Keep every canonical broker ID in the
        diagnostic while deliberately avoiding cancellation until one order
        lineage can be safely attributed.
        """
        nonlocal deterministic_exposure_was_visible, visible_exposure_payload
        if not payloads:
            return
        deterministic_exposure_was_visible = True
        if visible_exposure_payload is None:
            visible_exposure_payload = payloads[0]
        for payload in payloads:
            order_id = _optional_alpaca_broker_identifier(payload.get("id"))
            if order_id is not None and order_id not in visible_deterministic_order_ids:
                visible_deterministic_order_ids.append(order_id)

    def quarantine_visible_deterministic_exposures(
        payloads: list[dict],
        *,
        invalid_account_snapshot: bool = False,
    ) -> None:
        """Retain and neutralize every independently attributable exposure.

        Multiple orders sharing a supposedly unique client ID cannot be
        treated as one replacement lineage. Resolve and validate each row on
        its own. Only lineages that prove the stable asset, frozen economics,
        and submission chronology are eligible for cancellation. Position
        intent is excluded here so an otherwise exact, dangerously non-closing
        sell is neutralized; every other mismatch remains diagnostic evidence
        under the retained retry fence.
        """
        attributed_chains: list[list[dict]] = []
        seen_lineages: set[tuple[str, ...]] = set()
        attribution_issues: list[str] = []
        for payload in payloads:
            observed_order_id = _optional_alpaca_broker_identifier(payload.get("id"))
            observed_label = observed_order_id or "<missing-or-invalid-order-id>"
            try:
                recovered, replacement_chain = _fetch_order_replacement_chain(
                    client,
                    payload,
                    sell_client_order_id,
                )
                if not _sell_order_identity_is_consistent(
                    recovered,
                    expected_sell_client_order_id=sell_client_order_id,
                    expected_symbol=symbol,
                    expected_alpaca_asset_id=expected_alpaca_asset_id,
                    replacement_chain=replacement_chain,
                ):
                    raise SellOrderIdentityError(
                        "core sell identity does not match the managed stable asset and order role"
                    )
                if not _sell_order_matches_intent_chronology(
                    replacement_chain[0],
                    intent_not_before,
                ):
                    raise SellOrderIdentityError(
                        "sell order predates the managed intent or has no valid submission time"
                    )
                intent_issue = _sell_replacement_chain_intent_issue(
                    replacement_chain,
                    requested_qty=filled_qty,
                    target_sell_price=target_sell_price,
                    validate_position_intent=False,
                )
                if intent_issue is not None:
                    raise SellOrderIdentityError(intent_issue)
                lineage_key = tuple(
                    order_id
                    for order in replacement_chain
                    if (order_id := _optional_alpaca_broker_identifier(order.get("id"))) is not None
                )
                if not lineage_key or len(lineage_key) != len(replacement_chain):
                    raise SellOrderIdentityError("sell replacement lineage has an invalid broker order ID")
            except (requests.RequestException, RuntimeError, ValueError) as exc:
                detail = _alpaca_client_exception_diagnostic(exc, client=client)
                attribution_issues.append(f"{observed_label}: {detail}")
                continue
            if lineage_key in seen_lineages:
                continue
            seen_lineages.add(lineage_key)
            attributed_chains.append(replacement_chain)

        for replacement_chain in attributed_chains:
            _append_fenced_stale_sell_submission_result(
                conn=conn,
                client=client,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                submitted_qty=filled_qty,
                target_sell_price=target_sell_price,
                replacement_chain=replacement_chain,
                source="final validation with duplicate deterministic-client-ID exposure",
                sell_submission_retry_claimed_at=sell_submission_claimed_at,
                allow_terminal_resolution=False,
            )

        safe_order_ids = sorted(
            {
                order_id
                for replacement_chain in attributed_chains
                for order in replacement_chain
                if (order_id := _optional_alpaca_broker_identifier(order.get("id"))) is not None
            }
        )
        evidence_summary = (
            (
                "the incomplete account snapshot or contradictory snapshot contained deterministic managed-sell "
                "exposure; "
                if invalid_account_snapshot
                else "multiple broker orders shared the deterministic managed-sell client ID; "
            )
            + (
                "safely attributed broker lineages were retained for cancellation: " + ", ".join(safe_order_ids)
                if safe_order_ids
                else "no broker row was safe enough for cancellation"
            )
            + (
                "; diagnostic-only broker rows were not canceled: " + "; ".join(attribution_issues)
                if attribution_issues
                else ""
            )
        )
        current_snapshot = _managed_position_snapshot(conn, position_id)
        quarantine_persisted = bool(
            current_snapshot is not None
            and quarantine_alpaca_managed_sell_stale_submission(
                conn,
                position_id,
                sell_client_order_id=sell_client_order_id,
                expected_sell_submission_retry_claimed_at=sell_submission_claimed_at,
                stale_alpaca_order_ids=visible_deterministic_order_ids,
                notes=_alpaca_durable_diagnostic_note(
                    evidence_summary,
                    cfg=client.cfg,
                    client=client,
                ),
                observed_alpaca_asset_id=expected_alpaca_asset_id,
                expected_state_revision=int(current_snapshot["state_revision"]),
            )
        )
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="quantity_mismatch" if quarantine_persisted else "superseded",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=filled_qty,
            limit_price=target_sell_price,
            alpaca_order_id=(visible_deterministic_order_ids[0] if visible_deterministic_order_ids else None),
            message=(
                f"{evidence_summary}; the in-flight retry claim remains quarantined"
                if quarantine_persisted
                else f"{evidence_summary}; concurrent managed state prevented refreshing the quarantine"
            ),
            required_failure=True,
        )

    try:
        exact_lookup = client.get_order_by_client_order_id(sell_client_order_id)
        if exact_lookup.status_code == 200:
            # A successful exact-client-ID lookup is affirmative exposure
            # evidence even when strict JSON decoding subsequently rejects an
            # ambiguous body. Latch that fact before touching the payload.
            deterministic_exposure_was_visible = True
            exact_payload = _response_json(exact_lookup)
            retain_visible_deterministic_exposure([exact_payload])
        elif exact_lookup.status_code != 404:
            _require_2xx_response(exact_lookup)
            raise ValueError(
                f"Alpaca final managed-sell lookup returned unexpected HTTP status {exact_lookup.status_code}"
            )

        active_positions = load_alpaca_managed_positions(conn, active_only=True)
        current_match = active_positions.loc[active_positions["id"].eq(position_id)]
        if current_match.empty:
            if exact_payload is not None:
                try:
                    exact_leaf, exact_replacement_chain = _fetch_order_replacement_chain(
                        client,
                        exact_payload,
                        sell_client_order_id,
                    )
                    exact_identity_is_proven = _sell_order_identity_is_consistent(
                        exact_leaf,
                        expected_sell_client_order_id=sell_client_order_id,
                        expected_symbol=symbol,
                        expected_alpaca_asset_id=expected_alpaca_asset_id,
                        replacement_chain=exact_replacement_chain,
                    ) and _sell_order_matches_intent_chronology(
                        exact_replacement_chain[0],
                        intent_not_before,
                    )
                except (requests.RequestException, RuntimeError, ValueError) as exc:
                    exact_identity_is_proven = False
                    exact_replacement_chain = []
                    exact_resolution_issue = _alpaca_client_exception_diagnostic(exc, client=client)
                else:
                    exact_resolution_issue = "the exact broker order could not be safely attributed"
                if exact_identity_is_proven:
                    _append_fenced_stale_sell_submission_result(
                        conn=conn,
                        client=client,
                        rows=rows,
                        position_id=position_id,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        submitted_qty=filled_qty,
                        target_sell_price=target_sell_price,
                        replacement_chain=exact_replacement_chain,
                        source="final validation after the managed position closed",
                        sell_submission_retry_claimed_at=sell_submission_claimed_at,
                    )
                    return None
                _append_incomplete_sell_order_identity_result(
                    conn=conn,
                    rows=rows,
                    position_id=position_id,
                    symbol=symbol,
                    buy_client_order_id=buy_client_order_id,
                    sell_client_order_id=sell_client_order_id,
                    observed_sell_qty=_sell_fill_metadata(exact_payload)[0],
                    target_sell_price=target_sell_price,
                    sell_alpaca_order_id=_optional_str(exact_payload.get("id")),
                    identity_issue=(
                        "managed sell position closed after an exact broker order became visible, but its "
                        f"lineage could not be safely neutralized: {exact_resolution_issue}"
                    ),
                    expected_sell_submission_retry_claimed_at=sell_submission_claimed_at,
                    expected_sell_state_revision=expected_sell_state_revision,
                    clear_sell_submission_claim=False,
                )
                return None
            released = release_no_post(
                sell_status="submission_not_found",
                notes="managed sell position closed before final broker exposure validation; no broker request sent",
            )
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="superseded",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=filled_qty,
                limit_price=target_sell_price,
                alpaca_order_id=None,
                message=(
                    "managed sell position closed before final broker exposure validation"
                    + ("; the in-flight token was released" if released else "")
                ),
            )
            return None
        current_position = current_match.iloc[0].to_dict()

        try:
            active_historical_leaves, historical_audit_issue = _missing_sell_retry_historical_exposure_audit(
                conn=conn,
                client=client,
                position=current_position,
                allow_fenced_inactive_intent_mismatch=(allow_fenced_inactive_historical_intent_mismatch),
            )
        except (requests.RequestException, SellOrderIdentityError, RuntimeError, ValueError) as exc:
            active_historical_leaves = []
            detail = _alpaca_client_exception_diagnostic(exc, client=client)
            historical_audit_issue = f"historical managed sell audit failed: {detail}"
        if active_historical_leaves or historical_audit_issue is not None:
            issue = historical_audit_issue or "historical managed sell exposure is still executable"
            historical_cancellation_message = ""
            if active_historical_leaves:
                cancellation_fence_revision = confirm_alpaca_managed_sell_submission(
                    conn,
                    position_id,
                    sell_client_order_id=sell_client_order_id,
                    claimed_at=sell_submission_claimed_at,
                    expected_sell_status=expected_sell_status,
                    expected_state_revision=expected_sell_state_revision,
                    expected_remaining_qty=filled_qty,
                    expected_target_sell_price=target_sell_price,
                )
                if cancellation_fence_revision is None:
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="sell",
                        status="superseded",
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=filled_qty,
                        limit_price=target_sell_price,
                        alpaca_order_id=None,
                        message=(
                            "historical managed sell exposure changed with the local submission "
                            "premise; no broker cancellation was requested"
                        ),
                    )
                    return None
                expected_sell_state_revision = cancellation_fence_revision
                _pending, historical_cancellation_messages = _request_managed_sell_leaf_cancellations(
                    client,
                    active_historical_leaves,
                )
                historical_cancellation_message = (
                    "; historical exposure cancellation requires confirmation: "
                    + "; ".join(historical_cancellation_messages)
                )

            if exact_payload is not None:
                try:
                    exact_leaf, exact_replacement_chain = _fetch_order_replacement_chain(
                        client,
                        exact_payload,
                        sell_client_order_id,
                    )
                    exact_identity_is_proven = _sell_order_identity_is_consistent(
                        exact_leaf,
                        expected_sell_client_order_id=sell_client_order_id,
                        expected_symbol=symbol,
                        expected_alpaca_asset_id=expected_alpaca_asset_id,
                        replacement_chain=exact_replacement_chain,
                    ) and _sell_order_matches_intent_chronology(
                        exact_replacement_chain[0],
                        intent_not_before,
                    )
                except (requests.RequestException, RuntimeError, ValueError):
                    exact_identity_is_proven = False
                    exact_replacement_chain = []
                if exact_identity_is_proven:
                    _append_fenced_stale_sell_submission_result(
                        conn=conn,
                        client=client,
                        rows=rows,
                        position_id=position_id,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        submitted_qty=filled_qty,
                        target_sell_price=target_sell_price,
                        replacement_chain=exact_replacement_chain,
                        source="final validation with conflicting historical sell exposure",
                        sell_submission_retry_claimed_at=sell_submission_claimed_at,
                    )
                    rows[-1]["Message"] += f"; historical exposure audit blocked adoption: {issue}"
                    rows[-1]["Message"] += historical_cancellation_message
                    return None

            _append_incomplete_sell_order_identity_result(
                conn=conn,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                observed_sell_qty=0.0,
                target_sell_price=target_sell_price,
                identity_issue=(f"final managed-sell submission blocked: {issue}{historical_cancellation_message}"),
                expected_sell_submission_retry_claimed_at=sell_submission_claimed_at,
                expected_sell_state_revision=expected_sell_state_revision,
                clear_sell_submission_claim=exact_payload is None,
            )
            return None

        try:
            open_orders = client.open_orders(
                equity_scope_asset_ids=((expected_alpaca_asset_id,) if expected_alpaca_asset_id is not None else ())
            )
        except _OpenOrderSnapshotError as exc:
            # An incomplete or contradictory account snapshot cannot authorize a POST, but an
            # exact deterministic client ID is still affirmative evidence that
            # this sell may already exist. Retain that evidence so the outer
            # failure path quarantines the in-flight generation instead of
            # releasing it as an ordinary pre-submission failure.
            deterministic_orders = [
                order
                for order in exc.observed_orders
                if _optional_str(order.get("client_order_id")) == sell_client_order_id
            ]
            retain_visible_deterministic_exposure(deterministic_orders)
            if deterministic_orders:
                quarantine_visible_deterministic_exposures(
                    deterministic_orders,
                    invalid_account_snapshot=True,
                )
                return None
            raise
        position_aliases = alpaca_managed_position_aliases(conn, position_id)
        deterministic_orders = [
            order for order in open_orders if _optional_str(order.get("client_order_id")) == sell_client_order_id
        ]
        retain_visible_deterministic_exposure(deterministic_orders)
        deterministic_payloads = [
            *([exact_payload] if exact_payload is not None else []),
            *deterministic_orders,
        ]
        distinct_deterministic_ids = {
            order_id
            for payload in deterministic_payloads
            if (order_id := _optional_alpaca_broker_identifier(payload.get("id"))) is not None
        }
        missing_deterministic_id_count = sum(
            _optional_alpaca_broker_identifier(payload.get("id")) is None for payload in deterministic_payloads
        )
        if len(distinct_deterministic_ids) + missing_deterministic_id_count > 1:
            quarantine_visible_deterministic_exposures(deterministic_payloads)
            return None
        if exact_payload is None and deterministic_orders:
            exact_payload = deterministic_orders[0]

        if exact_payload is not None:
            try:
                exact_leaf, exact_replacement_chain = _fetch_order_replacement_chain(
                    client,
                    exact_payload,
                    sell_client_order_id,
                )
                exact_identity_is_proven = _sell_order_identity_is_consistent(
                    exact_leaf,
                    expected_sell_client_order_id=sell_client_order_id,
                    expected_symbol=symbol,
                    expected_alpaca_asset_id=expected_alpaca_asset_id,
                    replacement_chain=exact_replacement_chain,
                ) and _sell_order_matches_intent_chronology(
                    exact_replacement_chain[0],
                    intent_not_before,
                )
            except (requests.RequestException, RuntimeError, ValueError):
                exact_identity_is_proven = False
                exact_replacement_chain = []
            if exact_identity_is_proven:
                exact_order_ids = {
                    order_id
                    for order in exact_replacement_chain
                    if (order_id := _optional_str(order.get("id"))) is not None
                }
                other_open_orders = [
                    order for order in open_orders if _optional_str(order.get("id")) not in exact_order_ids
                ]
                if _orders_have_open_order(
                    other_open_orders,
                    symbol,
                    "sell",
                    expected_alpaca_asset_id=expected_alpaca_asset_id,
                    symbol_aliases=position_aliases,
                ):
                    _append_fenced_stale_sell_submission_result(
                        conn=conn,
                        client=client,
                        rows=rows,
                        position_id=position_id,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        submitted_qty=filled_qty,
                        target_sell_price=target_sell_price,
                        replacement_chain=exact_replacement_chain,
                        source="final validation with conflicting same-asset sell exposure",
                        sell_submission_retry_claimed_at=sell_submission_claimed_at,
                        allow_terminal_resolution=False,
                    )
                    rows[-1]["Message"] += (
                        "; another same-asset sell remained open, so the exact submission quarantine was retained"
                    )
                    return None

            recovered = _recover_managed_sell_submission(
                conn=conn,
                client=client,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                filled_qty=filled_qty,
                target_sell_price=target_sell_price,
                message="final pre-submit deterministic-ID and open-order check",
                close_on_complete=close_on_complete,
                expected_alpaca_asset_id=expected_alpaca_asset_id,
                intent_not_before=intent_not_before,
                expected_sell_submission_retry_claimed_at=sell_submission_claimed_at,
                expected_sell_state_revision=expected_sell_state_revision,
                observed_payload=exact_payload,
            )
            if not recovered:
                _append_incomplete_sell_order_identity_result(
                    conn=conn,
                    rows=rows,
                    position_id=position_id,
                    symbol=symbol,
                    buy_client_order_id=buy_client_order_id,
                    sell_client_order_id=sell_client_order_id,
                    observed_sell_qty=0.0,
                    target_sell_price=target_sell_price,
                    identity_issue=(
                        "deterministic managed sell became visible during final validation but its lineage "
                        "could not be resolved"
                    ),
                    expected_sell_submission_retry_claimed_at=sell_submission_claimed_at,
                    expected_sell_state_revision=expected_sell_state_revision,
                    clear_sell_submission_claim=False,
                )
            return None

        matching_managed_orders = _matching_managed_open_sell_orders(
            open_orders,
            symbol,
            position_id,
            sell_order_namespace=_optional_str(current_position.get("sell_order_namespace")),
            legacy_sell_client_order_id=sell_client_order_id,
            expected_alpaca_asset_id=expected_alpaca_asset_id,
        )
        if len(matching_managed_orders) > 1:
            released = release_no_post(
                sell_status="submission_not_found",
                notes=("managed sell submission skipped because multiple managed generations were open before POST"),
            )
            _append_multiple_managed_open_sells_result(
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                filled_qty=filled_qty,
                target_sell_price=target_sell_price,
            )
            if not released:
                rows[-1]["Status"] = "superseded"
                rows[-1]["Message"] += "; the managed submission generation changed concurrently"
            return None
        if _orders_have_open_order(
            open_orders,
            symbol,
            "sell",
            expected_alpaca_asset_id=expected_alpaca_asset_id,
            symbol_aliases=position_aliases,
        ):
            released = release_no_post(
                sell_status="submission_not_found",
                notes="managed sell submission skipped because a same-asset open sell appeared before POST",
            )
            _append_open_sell_result(
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                filled_qty=filled_qty,
                target_sell_price=target_sell_price,
            )
            if not released:
                rows[-1]["Status"] = "superseded"
                rows[-1]["Message"] += "; the managed submission generation changed concurrently"
            return None

        live_position_asset_id, live_position_qty = _managed_live_position_identity_and_qty(
            client.positions(),
            symbol=symbol,
            expected_alpaca_asset_id=expected_alpaca_asset_id,
            symbol_aliases=position_aliases,
        )
        if not _managed_sell_quantities_match(
            filled_qty,
            live_position_qty,
            mark_price=effective_quantity_mark_price,
        ):
            released = release_no_post(
                sell_status="submission_not_found",
                notes="managed sell submission skipped because live stable-asset quantity changed before POST",
            )
            _append_live_position_quantity_mismatch_result(
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                requested_qty=filled_qty,
                live_qty=live_position_qty,
                target_sell_price=target_sell_price,
                sell_alpaca_order_id=None,
                existing_order_preserved=False,
            )
            if not released:
                rows[-1]["Status"] = "superseded"
                rows[-1]["Message"] += "; the managed submission generation changed concurrently"
            return None
        if live_position_asset_id is None:
            released = release_no_post(
                sell_status="submission_not_found",
                notes="managed sell submission skipped because its live stable asset identity was missing",
            )
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="error" if released else "superseded",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=filled_qty,
                limit_price=target_sell_price,
                alpaca_order_id=None,
                message=(
                    "managed sell submission requires a validated live stable asset identity; "
                    "no broker order was submitted"
                    if released
                    else "live stable-asset identity belonged to a superseded managed sell generation"
                ),
                required_failure=released,
            )
            return None

        confirmed_state_revision = confirm_alpaca_managed_sell_submission(
            conn,
            position_id,
            sell_client_order_id=sell_client_order_id,
            claimed_at=sell_submission_claimed_at,
            expected_sell_status=expected_sell_status,
            expected_state_revision=expected_sell_state_revision,
            expected_remaining_qty=filled_qty,
            expected_target_sell_price=target_sell_price,
        )
        if confirmed_state_revision is None:
            released = release_no_post(
                sell_status="submission_not_found",
                notes="managed sell submission generation changed before its final local fence",
            )
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="superseded",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=filled_qty,
                limit_price=target_sell_price,
                alpaca_order_id=None,
                message=(
                    "managed sell submission generation changed before the final local fence; no broker order "
                    "was submitted" + ("; the in-flight token was released" if released else "")
                ),
            )
            return None
        return confirmed_state_revision, live_position_asset_id
    except Exception as exc:
        detail = _alpaca_client_exception_diagnostic(exc, client=client)
        if deterministic_exposure_was_visible:
            observed_ids_detail = (
                "; observed canonical broker order IDs: " + ", ".join(visible_deterministic_order_ids)
                if visible_deterministic_order_ids
                else ""
            )
            _append_incomplete_sell_order_identity_result(
                conn=conn,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                observed_sell_qty=(
                    _sell_fill_metadata(visible_exposure_payload)[0] if visible_exposure_payload is not None else 0.0
                ),
                target_sell_price=target_sell_price,
                sell_alpaca_order_id=(
                    _optional_str(visible_exposure_payload.get("id")) if visible_exposure_payload is not None else None
                ),
                identity_issue=(
                    "final managed-sell validation failed after deterministic broker exposure became visible; "
                    f"the in-flight token was retained: {detail}{observed_ids_detail}"
                ),
                expected_sell_submission_retry_claimed_at=sell_submission_claimed_at,
                expected_sell_state_revision=expected_sell_state_revision,
                clear_sell_submission_claim=False,
            )
            return None
        released = release_no_post(
            sell_status="submission_not_found",
            notes=f"managed sell final broker exposure validation failed before POST: {detail}",
        )
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="error" if released else "superseded",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=filled_qty,
            limit_price=target_sell_price,
            alpaca_order_id=None,
            message=(
                f"final broker exposure validation failed before managed sell submission: {detail}"
                if released
                else (
                    f"final broker exposure validation failed after the managed submission generation changed: {detail}"
                )
            ),
            systemic_failure=isinstance(exc, requests.RequestException),
            required_failure=True,
        )
        return None


def _submit_managed_gtc_sell(
    *,
    conn: sqlite3.Connection,
    client: AlpacaClient,
    rows: list[dict],
    position_id: int,
    symbol: str,
    buy_client_order_id: str,
    sell_client_order_id: str,
    filled_qty: float,
    target_sell_price: float,
    quantity_mark_price: float | None = None,
    increment_renewal_count: bool,
    replacement_message: str,
    live_position_qty: float,
    close_on_complete: bool = True,
    intent_already_persisted: bool = False,
    sell_order_namespace: str | None = None,
    intent_not_before: str | None = None,
    sell_submission_retry_claimed_at: str | None = None,
    expected_sell_state_revision: int | object = _STORAGE_UNSET,
    expected_sell_submission_status: str = "submission_pending",
    expected_alpaca_asset_id: str | None = None,
    allow_fenced_inactive_historical_intent_mismatch: bool = False,
) -> None:
    sensitive_values = _alpaca_client_sensitive_values(client)

    def durable_note(value: str) -> str:
        safe_note = _alpaca_durable_diagnostic_note(
            value,
            cfg=client.cfg,
            sensitive_values=sensitive_values,
            client=client,
        )
        assert safe_note is not None
        return safe_note

    effective_quantity_mark_price = _managed_sell_residual_mark_price(
        target_sell_price,
        quantity_mark_price,
    )
    if not _managed_sell_quantities_match(
        filled_qty,
        live_position_qty,
        mark_price=effective_quantity_mark_price,
    ):
        retry_claim_release_attempted = bool(
            sell_submission_retry_claimed_at is not None and expected_sell_submission_status == "submission_retrying"
        )
        retry_claim_released = bool(
            retry_claim_release_attempted
            and release_alpaca_managed_sell_submission_fence(
                conn,
                position_id,
                sell_client_order_id=sell_client_order_id,
                claimed_at=sell_submission_retry_claimed_at,
                expected_sell_status=expected_sell_submission_status,
                expected_state_revision=(
                    expected_sell_state_revision if isinstance(expected_sell_state_revision, int) else None
                ),
                allow_current_intent_rebase=True,
                sell_status="submission_not_found",
                notes=durable_note(
                    "managed sell retry quantity no longer matched the live stable-asset holding; "
                    "no broker request was sent"
                ),
            )
        )
        _append_live_position_quantity_mismatch_result(
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            requested_qty=filled_qty,
            live_qty=live_position_qty,
            target_sell_price=target_sell_price,
            sell_alpaca_order_id=None,
            existing_order_preserved=False,
        )
        if retry_claim_release_attempted and not retry_claim_released:
            rows[-1]["Status"] = "superseded"
            rows[-1]["Message"] += "; the managed sell retry generation changed concurrently"
        return
    if not _is_whole_share_qty(float(filled_qty)):
        status_updated: bool | None = None
        if sell_submission_retry_claimed_at is not None:
            status_updated = release_alpaca_managed_sell_submission_fence(
                conn,
                position_id,
                sell_client_order_id=sell_client_order_id,
                claimed_at=sell_submission_retry_claimed_at,
                expected_sell_status=expected_sell_submission_status,
                expected_state_revision=(
                    expected_sell_state_revision if isinstance(expected_sell_state_revision, int) else None
                ),
                sell_status="fractional_qty",
                notes=durable_note("filled quantity is fractional; no GTC limit sell submitted"),
            )
        _append_fractional_sell_result(
            conn=conn,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=(sell_client_order_id if intent_already_persisted else None),
            filled_qty=filled_qty,
            target_sell_price=target_sell_price,
            status_updated=status_updated,
        )
        return
    if not intent_already_persisted:
        initial_snapshot = alpaca_managed_sell_renewal_snapshot_if_current(
            conn,
            position_id,
            expected_sell_client_order_id=None,
            expected_sell_alpaca_order_id=None,
            expected_sell_renewal_requested_at=None,
        )
        initial_snapshot_matches_intent = bool(
            initial_snapshot is not None
            and initial_snapshot.remaining_qty is not None
            and _managed_sell_quantities_match(
                initial_snapshot.remaining_qty,
                filled_qty,
                mark_price=effective_quantity_mark_price,
            )
            and initial_snapshot.target_sell_price is not None
            and abs(initial_snapshot.target_sell_price - target_sell_price)
            <= _alpaca_limit_price_tolerance(target_sell_price)
        )
        if not initial_snapshot_matches_intent:
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="superseded",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=filled_qty,
                limit_price=target_sell_price,
                alpaca_order_id=None,
                message="initial managed sell submission was superseded by concurrent managed state",
            )
            return
        assert initial_snapshot is not None
        sell_submission_retry_claimed_at = _utc_now().isoformat().replace("+00:00", "Z")
        initial_claim = claim_alpaca_managed_initial_sell_submission(
            conn,
            position_id,
            sell_order_namespace=sell_order_namespace,
            sell_client_order_id=sell_client_order_id,
            notes=durable_note("managed GTC sell submission intent persisted before broker request"),
            expected_remaining_qty=filled_qty,
            expected_target_sell_price=target_sell_price,
            claimed_at=sell_submission_retry_claimed_at,
            expected_state_snapshot=initial_snapshot,
        )
        if initial_claim is None:
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="superseded",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=filled_qty,
                limit_price=target_sell_price,
                alpaca_order_id=None,
                message="initial managed sell submission was superseded by concurrent managed state",
            )
            return
        filled_qty = initial_claim.remaining_qty
        target_sell_price = initial_claim.target_sell_price
        expected_sell_state_revision = initial_claim.state_revision
        close_on_complete = str(initial_claim.buy_status or "").lower() in {
            "filled",
            *BUY_TERMINAL_STATUSES,
        }

    if sell_submission_retry_claimed_at is None:
        sell_submission_retry_claimed_at = _utc_now().isoformat().replace("+00:00", "Z")
        claimed_state_revision = claim_alpaca_managed_sell_submission_fence(
            conn,
            position_id,
            sell_client_order_id=sell_client_order_id,
            claimed_at=sell_submission_retry_claimed_at,
            expected_remaining_qty=filled_qty,
            expected_target_sell_price=target_sell_price,
            notes=durable_note("managed sell submission leased before final broker exposure validation"),
        )
        if claimed_state_revision is None:
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="superseded",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=filled_qty,
                limit_price=target_sell_price,
                alpaca_order_id=None,
                message="managed sell submission could not acquire its final in-flight generation fence",
            )
            return
        expected_sell_state_revision = claimed_state_revision
    elif expected_sell_state_revision is _STORAGE_UNSET:
        released = release_alpaca_managed_sell_submission_fence(
            conn,
            position_id,
            sell_client_order_id=sell_client_order_id,
            claimed_at=sell_submission_retry_claimed_at,
            expected_sell_status=expected_sell_submission_status,
            expected_state_revision=None,
            allow_current_intent_rebase=True,
            sell_status="submission_not_found",
            notes=durable_note(
                "managed sell submission token had no matching state revision; no broker request was sent"
            ),
        )
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="superseded",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=filled_qty,
            limit_price=target_sell_price,
            alpaca_order_id=None,
            message=(
                "managed sell submission token had no matching state revision; no broker order was submitted"
                + ("; the in-flight token was released" if released else "")
            ),
        )
        return

    assert isinstance(expected_sell_state_revision, int)
    submission_asset_id = _optional_alpaca_broker_identifier(expected_alpaca_asset_id)
    final_fence = _final_managed_sell_submission_exposure_fence(
        conn=conn,
        client=client,
        rows=rows,
        position_id=position_id,
        symbol=symbol,
        buy_client_order_id=buy_client_order_id,
        sell_client_order_id=sell_client_order_id,
        filled_qty=filled_qty,
        target_sell_price=target_sell_price,
        quantity_mark_price=effective_quantity_mark_price,
        close_on_complete=close_on_complete,
        intent_not_before=intent_not_before,
        sell_submission_claimed_at=sell_submission_retry_claimed_at,
        expected_sell_state_revision=expected_sell_state_revision,
        expected_sell_status=expected_sell_submission_status,
        expected_alpaca_asset_id=expected_alpaca_asset_id,
        allow_fenced_inactive_historical_intent_mismatch=(allow_fenced_inactive_historical_intent_mismatch),
    )
    if final_fence is None:
        return
    expected_sell_state_revision, validated_live_position_asset_id = final_fence
    validated_live_asset_id = _optional_alpaca_broker_identifier(validated_live_position_asset_id)
    if submission_asset_id is None:
        submission_asset_id = validated_live_asset_id
    if submission_asset_id is None:
        released = release_alpaca_managed_sell_submission_fence(
            conn,
            position_id,
            sell_client_order_id=sell_client_order_id,
            claimed_at=sell_submission_retry_claimed_at,
            expected_sell_status=expected_sell_submission_status,
            expected_state_revision=expected_sell_state_revision,
            allow_current_intent_rebase=True,
            sell_status="submission_not_found",
            notes=durable_note(
                "managed sell submission was blocked because its stable Alpaca asset identity is missing"
            ),
        )
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="error" if released else "superseded",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=filled_qty,
            limit_price=target_sell_price,
            alpaca_order_id=None,
            message=(
                "managed sell submission requires a validated stable Alpaca asset identity; "
                "no broker order was submitted"
                if released
                else "missing stable-asset identity belonged to a superseded managed sell generation"
            ),
            required_failure=released,
        )
        return

    if expected_alpaca_asset_id is None:
        adopted_revision = adopt_alpaca_managed_position_asset_if_current(
            conn,
            position_id,
            expected_state_revision=expected_sell_state_revision,
            alpaca_asset_id=submission_asset_id,
        )
        if adopted_revision is None:
            released = release_alpaca_managed_sell_submission_fence(
                conn,
                position_id,
                sell_client_order_id=sell_client_order_id,
                claimed_at=sell_submission_retry_claimed_at,
                expected_sell_status=expected_sell_submission_status,
                expected_state_revision=expected_sell_state_revision,
                allow_current_intent_rebase=True,
                sell_status="submission_not_found",
                notes=durable_note(
                    "managed sell submission was blocked because its stable Alpaca asset identity "
                    "could not be durably adopted"
                ),
            )
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="error" if released else "superseded",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=filled_qty,
                limit_price=target_sell_price,
                alpaca_order_id=None,
                message=(
                    "managed sell submission could not durably adopt its validated stable Alpaca asset identity; "
                    "no broker order was submitted"
                    if released
                    else "stable-asset adoption belonged to a superseded managed sell generation"
                ),
                required_failure=released,
            )
            return
        expected_sell_state_revision = adopted_revision
    expected_alpaca_asset_id = submission_asset_id

    try:
        sell_resp = client.submit_limit_sell_order(
            symbol=submission_asset_id,
            qty=float(filled_qty),
            limit_price=float(target_sell_price),
            client_order_id=sell_client_order_id,
        )
        _require_2xx_response(sell_resp)
    except HTTPError as exc:
        error_message = _http_error_message(exc, sensitive_values=sensitive_values)
        if _ambiguous_submission_http_error(exc, sensitive_values=sensitive_values):
            if _recover_managed_sell_submission(
                conn=conn,
                client=client,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                filled_qty=filled_qty,
                target_sell_price=target_sell_price,
                message=error_message,
                close_on_complete=close_on_complete,
                expected_alpaca_asset_id=expected_alpaca_asset_id,
                intent_not_before=intent_not_before,
                expected_sell_submission_retry_claimed_at=(
                    sell_submission_retry_claimed_at if sell_submission_retry_claimed_at is not None else _STORAGE_UNSET
                ),
                expected_sell_state_revision=expected_sell_state_revision,
            ):
                return
            state_updated = update_alpaca_managed_sell_status_if_current(
                conn,
                position_id,
                expected_sell_client_order_id=sell_client_order_id,
                sell_status="submission_unknown",
                expected_sell_submission_retry_claimed_at=(
                    sell_submission_retry_claimed_at if sell_submission_retry_claimed_at is not None else _STORAGE_UNSET
                ),
                expected_state_revision=expected_sell_state_revision,
                notes=durable_note(
                    "broker returned an ambiguous error after managed sell submission; recovery is pending"
                ),
            )
            if not state_updated:
                if expected_sell_state_revision is not _STORAGE_UNSET and sell_submission_retry_claimed_at:
                    _append_fenced_unresolved_sell_submission_result(
                        conn=conn,
                        rows=rows,
                        position_id=position_id,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        submitted_qty=filled_qty,
                        target_sell_price=target_sell_price,
                        sell_submission_retry_claimed_at=sell_submission_retry_claimed_at,
                    )
                    return
                _append_reconciliation_result(
                    rows,
                    position_id=position_id,
                    symbol=symbol,
                    action="sell",
                    status="superseded",
                    buy_client_order_id=buy_client_order_id,
                    sell_client_order_id=sell_client_order_id,
                    qty=filled_qty,
                    limit_price=target_sell_price,
                    alpaca_order_id=None,
                    message="submission result belongs to a superseded managed GTC sell generation",
                )
                return
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="submission_unknown",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=filled_qty,
                limit_price=target_sell_price,
                alpaca_order_id=None,
                message="broker response is ambiguous; managed sell recovery will retry by client order ID",
                systemic_failure=_transient_broker_http_error(exc),
                required_failure=True,
            )
            return
        state_updated = update_alpaca_managed_sell_status_if_current(
            conn,
            position_id,
            expected_sell_client_order_id=sell_client_order_id,
            sell_status="submission_failed",
            expected_sell_submission_retry_claimed_at=(
                sell_submission_retry_claimed_at if sell_submission_retry_claimed_at is not None else _STORAGE_UNSET
            ),
            expected_state_revision=expected_sell_state_revision,
            clear_sell_submission_retry_claim=True,
            notes=durable_note("managed sell submission failed before an Alpaca order was accepted"),
        )
        if not state_updated:
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="superseded",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=filled_qty,
                limit_price=target_sell_price,
                alpaca_order_id=None,
                message="submission result belongs to a superseded managed GTC sell generation",
            )
            return
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="error",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=filled_qty,
            limit_price=target_sell_price,
            alpaca_order_id=None,
            message=error_message,
            systemic_failure=(
                _authentication_http_error(exc, sensitive_values=sensitive_values) or _transient_broker_http_error(exc)
            ),
            required_failure=True,
        )
        return
    except requests.RequestException as exc:
        error_message = _alpaca_client_exception_diagnostic(exc, client=client)
        if _recover_managed_sell_submission(
            conn=conn,
            client=client,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            filled_qty=filled_qty,
            target_sell_price=target_sell_price,
            message=error_message,
            close_on_complete=close_on_complete,
            expected_alpaca_asset_id=expected_alpaca_asset_id,
            intent_not_before=intent_not_before,
            expected_sell_submission_retry_claimed_at=(
                sell_submission_retry_claimed_at if sell_submission_retry_claimed_at is not None else _STORAGE_UNSET
            ),
            expected_sell_state_revision=expected_sell_state_revision,
        ):
            return
        state_updated = update_alpaca_managed_sell_status_if_current(
            conn,
            position_id,
            expected_sell_client_order_id=sell_client_order_id,
            sell_status="submission_unknown",
            expected_sell_submission_retry_claimed_at=(
                sell_submission_retry_claimed_at if sell_submission_retry_claimed_at is not None else _STORAGE_UNSET
            ),
            expected_state_revision=expected_sell_state_revision,
            notes=durable_note("managed sell submission transport failed; recovery is pending"),
        )
        if not state_updated:
            if expected_sell_state_revision is not _STORAGE_UNSET and sell_submission_retry_claimed_at:
                _append_fenced_unresolved_sell_submission_result(
                    conn=conn,
                    rows=rows,
                    position_id=position_id,
                    symbol=symbol,
                    buy_client_order_id=buy_client_order_id,
                    sell_client_order_id=sell_client_order_id,
                    submitted_qty=filled_qty,
                    target_sell_price=target_sell_price,
                    sell_submission_retry_claimed_at=sell_submission_retry_claimed_at,
                )
                return
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="superseded",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=filled_qty,
                limit_price=target_sell_price,
                alpaca_order_id=None,
                message="submission result belongs to a superseded managed GTC sell generation",
            )
            return
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="submission_unknown",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=filled_qty,
            limit_price=target_sell_price,
            alpaca_order_id=None,
            message="managed sell submission is ambiguous; recovery will retry by client order ID",
            systemic_failure=True,
            required_failure=True,
        )
        return
    except Exception as exc:
        error_message = _alpaca_client_exception_diagnostic(exc, client=client)
        if _recover_managed_sell_submission(
            conn=conn,
            client=client,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            filled_qty=filled_qty,
            target_sell_price=target_sell_price,
            message=error_message,
            close_on_complete=close_on_complete,
            expected_alpaca_asset_id=expected_alpaca_asset_id,
            intent_not_before=intent_not_before,
            expected_sell_submission_retry_claimed_at=(
                sell_submission_retry_claimed_at if sell_submission_retry_claimed_at is not None else _STORAGE_UNSET
            ),
            expected_sell_state_revision=expected_sell_state_revision,
        ):
            return
        state_updated = update_alpaca_managed_sell_status_if_current(
            conn,
            position_id,
            expected_sell_client_order_id=sell_client_order_id,
            sell_status="submission_unknown",
            expected_sell_submission_retry_claimed_at=(
                sell_submission_retry_claimed_at if sell_submission_retry_claimed_at is not None else _STORAGE_UNSET
            ),
            expected_state_revision=expected_sell_state_revision,
            notes=durable_note("managed sell submission ended unexpectedly; recovery is pending"),
        )
        if not state_updated:
            if expected_sell_state_revision is not _STORAGE_UNSET and sell_submission_retry_claimed_at:
                _append_fenced_unresolved_sell_submission_result(
                    conn=conn,
                    rows=rows,
                    position_id=position_id,
                    symbol=symbol,
                    buy_client_order_id=buy_client_order_id,
                    sell_client_order_id=sell_client_order_id,
                    submitted_qty=filled_qty,
                    target_sell_price=target_sell_price,
                    sell_submission_retry_claimed_at=sell_submission_retry_claimed_at,
                )
                return
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="superseded",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=filled_qty,
                limit_price=target_sell_price,
                alpaca_order_id=None,
                message="submission result belongs to a superseded managed GTC sell generation",
            )
            return
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="submission_unknown",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=filled_qty,
            limit_price=target_sell_price,
            alpaca_order_id=None,
            message="managed sell submission is ambiguous; recovery will retry by client order ID",
            required_failure=True,
        )
        return
    try:
        submitted_payload = _response_json(sell_resp)
    except Exception as exc:
        _append_fenced_unresolved_sell_submission_result(
            conn=conn,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            submitted_qty=filled_qty,
            target_sell_price=target_sell_price,
            sell_submission_retry_claimed_at=sell_submission_retry_claimed_at,
        )
        detail = _alpaca_client_exception_diagnostic(exc, client=client)
        rows[-1]["Message"] += (
            f"; Alpaca returned a successful sell submission response that could not be parsed: {detail}"
        )
        return
    try:
        sell_order, submitted_replacement_chain = _fetch_order_replacement_chain(
            client,
            submitted_payload,
            sell_client_order_id,
        )
    except (requests.RequestException, RuntimeError, ValueError) as exc:
        detail = _alpaca_client_exception_diagnostic(exc, client=client)
        _append_incomplete_sell_order_identity_result(
            conn=conn,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            observed_sell_qty=_sell_fill_metadata(submitted_payload)[0],
            target_sell_price=target_sell_price,
            sell_alpaca_order_id=_optional_str(submitted_payload.get("id")),
            identity_issue=f"submitted sell replacement lineage could not be resolved: {detail}",
            required_failure=True,
            expected_sell_submission_retry_claimed_at=sell_submission_retry_claimed_at,
            expected_sell_state_revision=expected_sell_state_revision,
        )
        return
    if _optional_str(sell_order.get("id")) is None or not _sell_order_identity_is_consistent(
        sell_order,
        expected_sell_client_order_id=sell_client_order_id,
        expected_symbol=symbol,
        expected_alpaca_asset_id=expected_alpaca_asset_id,
        replacement_chain=submitted_replacement_chain,
    ):
        _append_incomplete_sell_order_identity_result(
            conn=conn,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            observed_sell_qty=_sell_fill_metadata(sell_order)[0],
            target_sell_price=target_sell_price,
            sell_alpaca_order_id=_optional_str(sell_order.get("id")),
            identity_issue="broker response does not match the submitted sell client-order generation",
            required_failure=True,
            expected_sell_submission_retry_claimed_at=(
                sell_submission_retry_claimed_at if sell_submission_retry_claimed_at is not None else _STORAGE_UNSET
            ),
            expected_sell_state_revision=expected_sell_state_revision,
        )
        return
    submission_intent_issue = _sell_replacement_chain_intent_issue(
        submitted_replacement_chain,
        requested_qty=filled_qty,
        target_sell_price=target_sell_price,
    )
    position_intent_issue = _sell_replacement_chain_position_intent_issue(submitted_replacement_chain)
    submission_intent_matches = submission_intent_issue is None
    sell_status, sell_alpaca_order_id, generation_is_current = _record_observed_managed_sell_order(
        conn=conn,
        position_id=position_id,
        sell_client_order_id=sell_client_order_id,
        sell_order=sell_order,
        submitted_qty=filled_qty,
        submitted_limit_price=target_sell_price,
        expected_sell_submission_retry_claimed_at=(
            sell_submission_retry_claimed_at if sell_submission_retry_claimed_at is not None else _STORAGE_UNSET
        ),
        expected_sell_state_revision=expected_sell_state_revision,
    )
    if not generation_is_current:
        if expected_sell_state_revision is not _STORAGE_UNSET and sell_submission_retry_claimed_at is not None:
            _append_fenced_stale_sell_submission_result(
                conn=conn,
                client=client,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                submitted_qty=filled_qty,
                target_sell_price=target_sell_price,
                replacement_chain=submitted_replacement_chain,
                source="broker submission",
                sell_submission_retry_claimed_at=sell_submission_retry_claimed_at,
            )
            return
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="superseded",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=filled_qty,
            limit_price=target_sell_price,
            alpaca_order_id=sell_alpaca_order_id,
            message="submission response belongs to a superseded managed GTC sell generation",
        )
        return
    submission_snapshot = alpaca_managed_sell_renewal_snapshot_if_current(
        conn,
        position_id,
        expected_sell_client_order_id=sell_client_order_id,
        expected_sell_alpaca_order_id=sell_alpaca_order_id,
    )
    if submission_snapshot is None or submission_snapshot.remaining_qty is None:
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="superseded",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=filled_qty,
            limit_price=target_sell_price,
            alpaca_order_id=sell_alpaca_order_id,
            message="submission response lost its exact managed-state snapshot",
        )
        return
    if position_intent_issue is not None:
        _append_sell_submission_intent_mismatch_result(
            conn=conn,
            client=client,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            requested_qty=filled_qty,
            target_sell_price=target_sell_price,
            sell_order=sell_order,
            replacement_chain=submitted_replacement_chain,
            intent_issue=position_intent_issue,
            expected_renewal_snapshot=submission_snapshot,
        )
        return
    remaining_qty: float | None = submission_snapshot.remaining_qty
    submitted_sell_qty, submitted_sell_avg_price, fill_metadata_is_valid = _replacement_chain_fill_metadata(
        submitted_replacement_chain
    )
    sell_residual_mark_price = _managed_sell_residual_mark_price(
        target_sell_price,
        submitted_sell_avg_price,
        *(order.get("limit_price") for order in submitted_replacement_chain),
    )
    if not fill_metadata_is_valid or (sell_status == "filled" and submitted_sell_qty == 0.0):
        _append_incomplete_sell_fill_result(
            conn=conn,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            observed_sell_qty=submitted_sell_qty,
            target_sell_price=target_sell_price,
            sell_alpaca_order_id=sell_alpaca_order_id,
            expected_renewal_snapshot=submission_snapshot,
        )
        return
    if sell_status == "filled" or submitted_sell_qty > 0.0:
        try:
            remaining_qty, generation_is_current = _record_replacement_chain_sell_fills(
                conn=conn,
                position_id=position_id,
                sell_client_order_id=sell_client_order_id,
                replacement_chain=submitted_replacement_chain,
                initial_remaining_qty=filled_qty,
                expected_renewal_snapshot=submission_snapshot,
            )
        except SellFillMetadataError:
            _append_incomplete_sell_fill_result(
                conn=conn,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                observed_sell_qty=submitted_sell_qty,
                target_sell_price=target_sell_price,
                sell_alpaca_order_id=sell_alpaca_order_id,
                expected_renewal_snapshot=submission_snapshot,
            )
            return
        except SellOrderIdentityError:
            _append_incomplete_sell_order_identity_result(
                conn=conn,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                observed_sell_qty=_sell_fill_metadata(sell_order)[0],
                target_sell_price=target_sell_price,
                expected_renewal_snapshot=submission_snapshot,
            )
            return
        except SellFillQuantityRegressionError:
            _append_sell_fill_quantity_regression_result(
                conn=conn,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                observed_sell_qty=_sell_fill_metadata(sell_order)[0],
                target_sell_price=target_sell_price,
                sell_alpaca_order_id=sell_alpaca_order_id,
                expected_renewal_snapshot=submission_snapshot,
            )
            return
        if not generation_is_current:
            return
        submission_snapshot = alpaca_managed_sell_renewal_snapshot_if_current(
            conn,
            position_id,
            expected_sell_client_order_id=sell_client_order_id,
            expected_sell_alpaca_order_id=sell_alpaca_order_id,
        )
        if submission_snapshot is None or submission_snapshot.remaining_qty is None:
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="superseded",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=submitted_sell_qty,
                limit_price=target_sell_price,
                alpaca_order_id=sell_alpaca_order_id,
                message="submitted sell-fill response lost its exact managed-state snapshot",
            )
            return
        remaining_qty = submission_snapshot.remaining_qty
        if _managed_sell_is_overfilled(
            remaining_qty,
            filled_qty,
            submitted_sell_qty,
            mark_price=sell_residual_mark_price,
        ):
            _append_overfilled_sell_result(
                conn=conn,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                observed_sell_qty=submitted_sell_qty,
                target_sell_price=target_sell_price,
                sell_alpaca_order_id=sell_alpaca_order_id,
                expected_renewal_snapshot=submission_snapshot,
            )
            return
        if sell_status in _ORDER_MAY_BE_ACTIVE_STATUSES and _managed_sell_is_complete(
            remaining_qty,
            filled_qty,
            submitted_sell_qty,
            mark_price=sell_residual_mark_price,
        ):
            _append_active_sell_completion_mismatch_result(
                conn=conn,
                client=client,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                observed_sell_qty=submitted_sell_qty,
                target_sell_price=target_sell_price,
                sell_order=sell_order,
                replacement_chain=submitted_replacement_chain,
                expected_renewal_snapshot=submission_snapshot,
            )
            return
        if (
            sell_status == "filled"
            and _managed_sell_is_complete(
                remaining_qty,
                filled_qty,
                submitted_sell_qty,
                mark_price=sell_residual_mark_price,
            )
            and close_on_complete
            and str(submission_snapshot.buy_status or "").lower() in {"filled", *BUY_TERMINAL_STATUSES}
            and submission_intent_matches
        ):
            assert sell_alpaca_order_id is not None
            closed = close_alpaca_managed_position_if_current_and_complete(
                conn,
                position_id,
                expected_sell_client_order_id=sell_client_order_id,
                expected_sell_alpaca_order_id=sell_alpaca_order_id,
                closed_at=_optional_alpaca_datetime_str(sell_order.get("filled_at")),
                expected_sell_status=submission_snapshot.sell_status or sell_status,
                expected_sell_filled_qty=submission_snapshot.sell_filled_qty,
                expected_sell_renewal_count=submission_snapshot.sell_renewal_count,
                expected_sell_renewal_requested_at=submission_snapshot.requested_at,
                expected_state_revision=submission_snapshot.state_revision,
                notes=durable_note("managed target sell filled"),
            )
            if not closed:
                _append_reconciliation_result(
                    rows,
                    position_id=position_id,
                    symbol=symbol,
                    action="sell",
                    status="superseded",
                    buy_client_order_id=buy_client_order_id,
                    sell_client_order_id=sell_client_order_id,
                    qty=submitted_sell_qty,
                    limit_price=target_sell_price,
                    alpaca_order_id=sell_alpaca_order_id,
                    message="completed sell response was superseded by concurrent managed state",
                )
                return
    if not submission_intent_matches:
        _append_sell_submission_intent_mismatch_result(
            conn=conn,
            client=client,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            requested_qty=filled_qty,
            target_sell_price=target_sell_price,
            sell_order=sell_order,
            replacement_chain=submitted_replacement_chain,
            intent_issue=submission_intent_issue,
            expected_renewal_snapshot=submission_snapshot,
        )
        return
    if sell_status == "filled" and (
        remaining_qty is None
        or not _managed_sell_is_complete(
            remaining_qty,
            filled_qty,
            submitted_sell_qty,
            mark_price=sell_residual_mark_price,
        )
    ):
        mismatch_generation_is_current = update_alpaca_managed_sell_status_if_current(
            conn,
            position_id,
            expected_sell_client_order_id=sell_client_order_id,
            **_renewal_snapshot_cas_kwargs(submission_snapshot),
            sell_status="quantity_mismatch",
            notes=durable_note("filled sell quantity did not close the managed buy quantity; manual review required"),
        )
        if not mismatch_generation_is_current:
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="superseded",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=submitted_sell_qty,
                limit_price=target_sell_price,
                alpaca_order_id=sell_alpaca_order_id,
                message="fill mismatch belongs to a superseded managed GTC sell generation",
            )
            return
    effective_close_on_complete = close_on_complete and str(submission_snapshot.buy_status or "").lower() in {
        "filled",
        *BUY_TERMINAL_STATUSES,
    }
    message = replacement_message
    if sell_status == "filled":
        if remaining_qty is not None and _managed_sell_is_complete(
            remaining_qty,
            filled_qty,
            submitted_sell_qty,
            mark_price=sell_residual_mark_price,
        ):
            message = (
                "managed target sell filled; position closed"
                if effective_close_on_complete
                else "managed sell filled; awaiting final status of the still-open parent buy"
            )
        else:
            message = "managed sell fill quantity does not match the managed buy; position remains active for review"
    renewal_submission = increment_renewal_count or intent_already_persisted
    renewal_is_active = sell_status in SELL_RENEWABLE_STATUSES
    if renewal_submission and renewal_is_active and _gtc_sell_renewal_due(sell_order, client.cfg):
        _append_incomplete_sell_expiration_metadata_result(
            conn=conn,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            target_sell_price=target_sell_price,
            sell_alpaca_order_id=sell_alpaca_order_id or "",
            expiration_issue="replacement managed GTC sell expiration remains inside the renewal window",
            expected_renewal_snapshot=submission_snapshot,
        )
        return
    if renewal_submission and sell_status != "filled" and not renewal_is_active:
        message = (
            f"managed GTC sell replacement returned {sell_status}; "
            "no active replacement was confirmed and manual review is required"
        )
    _append_reconciliation_result(
        rows,
        position_id=position_id,
        symbol=symbol,
        action="sell",
        status=("renewed" if renewal_submission and renewal_is_active else sell_status),
        buy_client_order_id=buy_client_order_id,
        sell_client_order_id=sell_client_order_id,
        qty=filled_qty,
        limit_price=target_sell_price,
        alpaca_order_id=sell_alpaca_order_id,
        message=message,
        required_failure=(
            sell_status not in {*SELL_RENEWABLE_STATUSES, "filled"}
            or (
                sell_status == "filled"
                and (
                    remaining_qty is None
                    or not _managed_sell_is_complete(
                        remaining_qty,
                        filled_qty,
                        submitted_sell_qty,
                        mark_price=sell_residual_mark_price,
                    )
                )
            )
        ),
    )


def _append_fractional_sell_result(
    *,
    conn: sqlite3.Connection,
    rows: list[dict],
    position_id: int,
    symbol: str,
    buy_client_order_id: str,
    sell_client_order_id: str | None,
    filled_qty: float,
    target_sell_price: float,
    status_updated: bool | None = None,
    expected_state_snapshot: AlpacaManagedSellRenewalSnapshot | None = None,
) -> None:
    if status_updated is None:
        status_updated = bool(
            expected_state_snapshot is not None
            and update_alpaca_managed_sell_status_if_current(
                conn,
                position_id,
                expected_sell_client_order_id=sell_client_order_id,
                sell_status="fractional_qty",
                notes=_alpaca_durable_diagnostic_note(
                    "filled quantity is fractional; no GTC limit sell submitted",
                    cfg=None,
                ),
                **_renewal_snapshot_cas_kwargs(expected_state_snapshot),
            )
        )
    _append_reconciliation_result(
        rows,
        position_id=position_id,
        symbol=symbol,
        action="sell",
        status="fractional_qty" if status_updated else "superseded",
        buy_client_order_id=buy_client_order_id,
        sell_client_order_id=sell_client_order_id,
        qty=filled_qty,
        limit_price=target_sell_price,
        alpaca_order_id=None,
        message=(
            "filled quantity is fractional; no GTC limit sell submitted"
            if status_updated
            else "fractional quantity result belongs to a superseded managed GTC sell generation"
        ),
        required_failure=status_updated,
    )


def _append_open_sell_result(
    *,
    rows: list[dict],
    position_id: int,
    symbol: str,
    buy_client_order_id: str,
    sell_client_order_id: str | None,
    filled_qty: float,
    target_sell_price: float,
) -> None:
    _append_reconciliation_result(
        rows,
        position_id=position_id,
        symbol=symbol,
        action="sell",
        status="open_order",
        buy_client_order_id=buy_client_order_id,
        sell_client_order_id=sell_client_order_id,
        qty=filled_qty,
        limit_price=target_sell_price,
        alpaca_order_id=None,
        message="open sell order already exists for symbol in Alpaca account",
        required_failure=True,
    )


def _append_multiple_managed_open_sells_result(
    *,
    rows: list[dict],
    position_id: int,
    symbol: str,
    buy_client_order_id: str,
    sell_client_order_id: str | None,
    filled_qty: float,
    target_sell_price: float,
) -> None:
    _append_reconciliation_result(
        rows,
        position_id=position_id,
        symbol=symbol,
        action="sell",
        status="managed_order_conflict",
        buy_client_order_id=buy_client_order_id,
        sell_client_order_id=sell_client_order_id,
        qty=filled_qty,
        limit_price=target_sell_price,
        alpaca_order_id=None,
        message="multiple managed GTC sell generations are open; no order was attached or submitted",
        required_failure=True,
    )


def _append_recovered_open_sell_result(
    *,
    conn: sqlite3.Connection,
    client: AlpacaClient,
    rows: list[dict],
    position_id: int,
    symbol: str,
    buy_client_order_id: str,
    sell_order: dict,
    filled_qty: float,
    target_sell_price: float,
    expected_sell_client_order_id: str | None,
    expected_sell_alpaca_order_id: str | None,
    expected_renewal_count: int,
    cfg: AlpacaOrderConfig,
    sell_order_namespace: str | None = None,
    expected_alpaca_asset_id: str | None = None,
    close_on_complete: bool = True,
    expected_state_snapshot: AlpacaManagedSellRenewalSnapshot | None = None,
) -> None:
    observed_client_order_id = _optional_str(sell_order.get("client_order_id"))
    if observed_client_order_id is None:
        observed_client_order_id = _alpaca_exit_client_order_id(
            symbol,
            position_id,
            order_namespace=sell_order_namespace,
        )
    try:
        sell_order, replacement_chain = _resolve_order_replacement_chain(
            client,
            sell_order,
        )
    except (HTTPError, RuntimeError, ValueError) as exc:
        detail = _alpaca_client_exception_diagnostic(exc, client=client)
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="identity_mismatch",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=observed_client_order_id,
            qty=filled_qty,
            limit_price=target_sell_price,
            alpaca_order_id=_optional_str(sell_order.get("id")),
            message=f"open managed-sell replacement lineage could not be resolved: {detail}",
            required_failure=True,
        )
        return
    sell_client_order_id = _optional_str(replacement_chain[0].get("client_order_id")) or _alpaca_exit_client_order_id(
        symbol,
        position_id,
        order_namespace=sell_order_namespace,
    )
    sell_status = _broker_order_status(sell_order, default="submitted")
    sell_alpaca_order_id = _optional_str(sell_order.get("id"))
    legacy_generation_is_expected = bool(
        expected_sell_client_order_id
        and _alpaca_exit_client_order_generation(
            symbol,
            position_id,
            expected_sell_client_order_id,
        )
        is not None
    )
    sell_renewal_count = _alpaca_exit_client_order_generation(
        symbol,
        position_id,
        sell_client_order_id,
        order_namespace=sell_order_namespace,
        allow_legacy_position_id=legacy_generation_is_expected,
    )
    if not _sell_order_identity_is_consistent(
        sell_order,
        expected_sell_client_order_id=sell_client_order_id,
        expected_symbol=symbol,
        expected_alpaca_asset_id=expected_alpaca_asset_id,
        replacement_chain=replacement_chain,
    ):
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="identity_mismatch",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=filled_qty,
            limit_price=target_sell_price,
            alpaca_order_id=sell_alpaca_order_id,
            message=(
                "open managed-sell candidate conflicts with the required asset, symbol, side, "
                "limit/GTC intent, or regular-hours setting; order was not attached"
            ),
            required_failure=True,
        )
        return
    if sell_alpaca_order_id is None:
        _append_incomplete_sell_order_identity_result(
            conn=conn,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            observed_sell_qty=_sell_fill_metadata(sell_order)[0],
            target_sell_price=target_sell_price,
            identity_issue="recovered open managed sell has no broker order ID",
            expected_sell_client_order_id=expected_sell_client_order_id,
            match_missing_sell_client_order_id=expected_sell_client_order_id is None,
        )
        return
    if (
        expected_state_snapshot is None
        or expected_state_snapshot.remaining_qty is None
        or expected_state_snapshot.target_sell_price is None
    ):
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="superseded",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=filled_qty,
            limit_price=target_sell_price,
            alpaca_order_id=sell_alpaca_order_id,
            message="open-order recovery had no exact parent and sell-state snapshot",
        )
        return
    authoritative_requested_qty = expected_state_snapshot.remaining_qty
    authoritative_target_sell_price = expected_state_snapshot.target_sell_price
    intent_issue = _sell_replacement_chain_intent_issue(
        replacement_chain,
        requested_qty=authoritative_requested_qty,
        target_sell_price=authoritative_target_sell_price,
    )
    position_intent_issue = _sell_replacement_chain_position_intent_issue(replacement_chain)
    non_fill_intent_issue = _sell_replacement_chain_non_fill_intent_issue(
        replacement_chain,
        requested_qty=authoritative_requested_qty,
        target_sell_price=authoritative_target_sell_price,
    )
    intent_matches = intent_issue is None
    cancellation_pending = bool(not intent_matches and _attributed_lineage_requires_cancellation(replacement_chain))
    attachment_status = (
        sell_status if intent_matches else "pending_cancel" if cancellation_pending else "quantity_mismatch"
    )
    attachment_cancellation_requested_at = (
        _utc_now().isoformat().replace("+00:00", "Z") if cancellation_pending else None
    )
    root_order = replacement_chain[0]
    attached = sell_renewal_count is not None and attach_alpaca_managed_sell_order_if_current(
        conn,
        position_id,
        expected_sell_client_order_id=expected_sell_client_order_id,
        expected_sell_alpaca_order_id=expected_sell_alpaca_order_id,
        expected_renewal_count=expected_renewal_count,
        sell_renewal_count=sell_renewal_count,
        sell_client_order_id=sell_client_order_id,
        sell_alpaca_order_id=sell_alpaca_order_id,
        sell_submitted_at=_optional_alpaca_datetime_str(sell_order.get("submitted_at")),
        sell_status=attachment_status,
        sell_expires_at=_optional_alpaca_datetime_str(sell_order.get("expires_at")),
        sell_order_qty=_optional_float(root_order.get("qty")),
        sell_order_limit_price=_optional_float(root_order.get("limit_price")),
        sell_renewal_requested_at=attachment_cancellation_requested_at,
        notes=_alpaca_durable_diagnostic_note(
            None
            if intent_matches
            else f"{intent_issue}; recovered broker lineage was attached only under diagnostic quarantine",
            cfg=client.cfg,
            client=client,
        ),
        expected_state_snapshot=expected_state_snapshot,
        allow_diagnostic_sell_intent_mismatch=not intent_matches,
    )
    if not attached:
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="superseded",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=filled_qty,
            limit_price=target_sell_price,
            alpaca_order_id=sell_alpaca_order_id,
            message="open-order recovery belongs to a superseded managed GTC sell generation",
        )
        return

    recovery_snapshot = alpaca_managed_sell_renewal_snapshot_if_current(
        conn,
        position_id,
        expected_sell_client_order_id=sell_client_order_id,
        expected_sell_alpaca_order_id=sell_alpaca_order_id,
    )
    if recovery_snapshot is None or recovery_snapshot.remaining_qty is None:
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="superseded",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=filled_qty,
            limit_price=target_sell_price,
            alpaca_order_id=sell_alpaca_order_id,
            message="open-order attachment lost its exact managed-state snapshot",
        )
        return

    if position_intent_issue is not None:
        _append_sell_submission_intent_mismatch_result(
            conn=conn,
            client=client,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            requested_qty=filled_qty,
            target_sell_price=target_sell_price,
            sell_order=sell_order,
            replacement_chain=replacement_chain,
            intent_issue=position_intent_issue,
            expected_renewal_snapshot=recovery_snapshot,
        )
        return

    observed_sell_qty, observed_sell_avg_price, fill_metadata_is_valid = _replacement_chain_fill_metadata(
        replacement_chain
    )
    sell_residual_mark_price = _managed_sell_residual_mark_price(
        target_sell_price,
        observed_sell_avg_price,
        *(order.get("limit_price") for order in replacement_chain),
    )
    if not fill_metadata_is_valid or (sell_status == "filled" and observed_sell_qty == 0.0):
        if cancellation_pending and non_fill_intent_issue is not None:
            _append_sell_submission_intent_mismatch_result(
                conn=conn,
                client=client,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                requested_qty=filled_qty,
                target_sell_price=target_sell_price,
                sell_order=sell_order,
                replacement_chain=replacement_chain,
                intent_issue=non_fill_intent_issue,
                expected_renewal_snapshot=recovery_snapshot,
            )
            return
        _append_incomplete_sell_fill_result(
            conn=conn,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            observed_sell_qty=observed_sell_qty,
            target_sell_price=target_sell_price,
            sell_alpaca_order_id=sell_alpaca_order_id,
            expected_renewal_snapshot=recovery_snapshot,
        )
        return
    remaining_qty = recovery_snapshot.remaining_qty
    if observed_sell_qty > 0.0:
        try:
            remaining_qty, generation_is_current = _record_replacement_chain_sell_fills(
                conn=conn,
                position_id=position_id,
                sell_client_order_id=sell_client_order_id,
                replacement_chain=replacement_chain,
                initial_remaining_qty=filled_qty,
                expected_renewal_snapshot=recovery_snapshot,
                preserve_pending_cancel=cancellation_pending,
            )
        except SellFillMetadataError:
            if cancellation_pending:
                _append_sell_submission_intent_mismatch_result(
                    conn=conn,
                    client=client,
                    rows=rows,
                    position_id=position_id,
                    symbol=symbol,
                    buy_client_order_id=buy_client_order_id,
                    sell_client_order_id=sell_client_order_id,
                    requested_qty=filled_qty,
                    target_sell_price=target_sell_price,
                    sell_order=sell_order,
                    replacement_chain=replacement_chain,
                    intent_issue=intent_issue,
                    expected_renewal_snapshot=recovery_snapshot,
                )
                return
            _append_incomplete_sell_fill_result(
                conn=conn,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                observed_sell_qty=observed_sell_qty,
                target_sell_price=target_sell_price,
                sell_alpaca_order_id=sell_alpaca_order_id,
                expected_renewal_snapshot=recovery_snapshot,
            )
            return
        except SellOrderIdentityError:
            if cancellation_pending:
                _append_sell_submission_intent_mismatch_result(
                    conn=conn,
                    client=client,
                    rows=rows,
                    position_id=position_id,
                    symbol=symbol,
                    buy_client_order_id=buy_client_order_id,
                    sell_client_order_id=sell_client_order_id,
                    requested_qty=filled_qty,
                    target_sell_price=target_sell_price,
                    sell_order=sell_order,
                    replacement_chain=replacement_chain,
                    intent_issue=intent_issue,
                    expected_renewal_snapshot=recovery_snapshot,
                )
                return
            _append_incomplete_sell_order_identity_result(
                conn=conn,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                observed_sell_qty=observed_sell_qty,
                target_sell_price=target_sell_price,
                sell_alpaca_order_id=sell_alpaca_order_id,
                expected_renewal_snapshot=recovery_snapshot,
            )
            return
        except SellFillQuantityRegressionError:
            if cancellation_pending:
                _append_sell_submission_intent_mismatch_result(
                    conn=conn,
                    client=client,
                    rows=rows,
                    position_id=position_id,
                    symbol=symbol,
                    buy_client_order_id=buy_client_order_id,
                    sell_client_order_id=sell_client_order_id,
                    requested_qty=filled_qty,
                    target_sell_price=target_sell_price,
                    sell_order=sell_order,
                    replacement_chain=replacement_chain,
                    intent_issue=(f"{intent_issue}; Alpaca sell filled quantity moved backwards for a managed order"),
                    expected_renewal_snapshot=recovery_snapshot,
                )
                return
            _append_sell_fill_quantity_regression_result(
                conn=conn,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                observed_sell_qty=observed_sell_qty,
                target_sell_price=target_sell_price,
                sell_alpaca_order_id=sell_alpaca_order_id,
                expected_renewal_snapshot=recovery_snapshot,
            )
            return
        if not generation_is_current:
            if cancellation_pending:
                post_accounting_snapshot = alpaca_managed_sell_renewal_snapshot_if_current(
                    conn,
                    position_id,
                    expected_sell_client_order_id=sell_client_order_id,
                    expected_sell_alpaca_order_id=sell_alpaca_order_id,
                    expected_sell_renewal_requested_at=recovery_snapshot.requested_at,
                )
                cancellation_snapshot = (
                    post_accounting_snapshot
                    if post_accounting_snapshot is not None
                    and _managed_sell_snapshots_have_same_premise(
                        post_accounting_snapshot,
                        recovery_snapshot,
                    )
                    else None
                )
                _append_sell_submission_intent_mismatch_result(
                    conn=conn,
                    client=client,
                    rows=rows,
                    position_id=position_id,
                    symbol=symbol,
                    buy_client_order_id=buy_client_order_id,
                    sell_client_order_id=sell_client_order_id,
                    requested_qty=filled_qty,
                    target_sell_price=target_sell_price,
                    sell_order=sell_order,
                    replacement_chain=replacement_chain,
                    intent_issue=(f"{intent_issue}; broker fill revision was not newer than persisted accounting"),
                    expected_renewal_snapshot=cancellation_snapshot,
                )
            return
        recovery_snapshot = alpaca_managed_sell_renewal_snapshot_if_current(
            conn,
            position_id,
            expected_sell_client_order_id=sell_client_order_id,
            expected_sell_alpaca_order_id=sell_alpaca_order_id,
        )
        if recovery_snapshot is None or recovery_snapshot.remaining_qty is None:
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="superseded",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=observed_sell_qty,
                limit_price=target_sell_price,
                alpaca_order_id=sell_alpaca_order_id,
                message="recovered open-order fill lost its exact managed-state snapshot",
            )
            return
        remaining_qty = recovery_snapshot.remaining_qty
        if cancellation_pending:
            _append_sell_submission_intent_mismatch_result(
                conn=conn,
                client=client,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                requested_qty=filled_qty,
                target_sell_price=target_sell_price,
                sell_order=sell_order,
                replacement_chain=replacement_chain,
                intent_issue=intent_issue,
                expected_renewal_snapshot=recovery_snapshot,
            )
            return
        if _managed_sell_is_overfilled(
            remaining_qty,
            filled_qty,
            observed_sell_qty,
            mark_price=sell_residual_mark_price,
        ):
            _append_overfilled_sell_result(
                conn=conn,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                observed_sell_qty=observed_sell_qty,
                target_sell_price=target_sell_price,
                sell_alpaca_order_id=sell_alpaca_order_id,
                expected_renewal_snapshot=recovery_snapshot,
            )
            return
        if sell_status in _ORDER_MAY_BE_ACTIVE_STATUSES and _managed_sell_is_complete(
            remaining_qty,
            filled_qty,
            observed_sell_qty,
            mark_price=sell_residual_mark_price,
        ):
            _append_active_sell_completion_mismatch_result(
                conn=conn,
                client=client,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                observed_sell_qty=observed_sell_qty,
                target_sell_price=target_sell_price,
                sell_order=sell_order,
                replacement_chain=replacement_chain,
                expected_renewal_snapshot=recovery_snapshot,
            )
            return
    if not intent_matches:
        _append_sell_submission_intent_mismatch_result(
            conn=conn,
            client=client,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            requested_qty=filled_qty,
            target_sell_price=target_sell_price,
            sell_order=sell_order,
            replacement_chain=replacement_chain,
            intent_issue=intent_issue,
            expected_renewal_snapshot=recovery_snapshot,
        )
        return
    if (
        sell_status == "filled"
        and _managed_sell_is_complete(
            remaining_qty,
            filled_qty,
            observed_sell_qty,
            mark_price=sell_residual_mark_price,
        )
        and close_on_complete
        and str(recovery_snapshot.buy_status or "").lower() in {"filled", *BUY_TERMINAL_STATUSES}
    ):
        assert sell_alpaca_order_id is not None
        closed = close_alpaca_managed_position_if_current_and_complete(
            conn,
            position_id,
            expected_sell_client_order_id=sell_client_order_id,
            expected_sell_alpaca_order_id=sell_alpaca_order_id,
            closed_at=_optional_alpaca_datetime_str(sell_order.get("filled_at")),
            expected_sell_status=recovery_snapshot.sell_status or sell_status,
            expected_sell_filled_qty=recovery_snapshot.sell_filled_qty,
            expected_sell_renewal_count=recovery_snapshot.sell_renewal_count,
            expected_sell_renewal_requested_at=recovery_snapshot.requested_at,
            expected_state_revision=recovery_snapshot.state_revision,
            notes=_alpaca_durable_diagnostic_note(
                "managed target sell filled",
                cfg=client.cfg,
                client=client,
            ),
        )
        if not closed:
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="superseded",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=observed_sell_qty,
                limit_price=target_sell_price,
                alpaca_order_id=sell_alpaca_order_id,
                message="completed open-order recovery was superseded by concurrent managed state",
            )
            return
    if sell_status in SELL_RENEWABLE_STATUSES and _gtc_sell_renewal_due(sell_order, cfg):
        _append_incomplete_sell_expiration_metadata_result(
            conn=conn,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            target_sell_price=target_sell_price,
            sell_alpaca_order_id=sell_alpaca_order_id,
            expiration_issue="recovered open managed GTC sell expiration remains inside the renewal window",
            expected_renewal_snapshot=recovery_snapshot,
        )
        return
    _append_reconciliation_result(
        rows,
        position_id=position_id,
        symbol=symbol,
        action="sell",
        status=sell_status,
        buy_client_order_id=buy_client_order_id,
        sell_client_order_id=sell_client_order_id,
        qty=filled_qty,
        limit_price=target_sell_price,
        alpaca_order_id=sell_alpaca_order_id,
        message="recovered existing managed GTC sell order from Alpaca open orders",
        required_failure=(
            sell_status not in {*SELL_RENEWABLE_STATUSES, "filled"}
            or (
                sell_status == "filled"
                and (
                    remaining_qty is None
                    or not _managed_sell_is_complete(
                        remaining_qty,
                        filled_qty,
                        observed_sell_qty,
                        mark_price=sell_residual_mark_price,
                    )
                )
            )
        ),
    )


def _submit_replacement_gtc_sell(
    *,
    conn: sqlite3.Connection,
    client: AlpacaClient,
    rows: list[dict],
    position: dict,
    symbol: str,
    buy_client_order_id: str,
    filled_qty: float,
    target_sell_price: float,
    quantity_mark_price: float | None = None,
    replacement_message: str,
    check_open_order: bool,
    live_position_qty: float,
    close_on_complete: bool = True,
    expected_renewal_snapshot: AlpacaManagedSellRenewalSnapshot | None = None,
) -> None:
    position_id = int(position["id"])
    effective_quantity_mark_price = _managed_sell_residual_mark_price(
        target_sell_price,
        quantity_mark_price,
    )
    if not _managed_sell_quantities_match(
        filled_qty,
        live_position_qty,
        mark_price=effective_quantity_mark_price,
    ):
        _append_live_position_quantity_mismatch_result(
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=_optional_str(position.get("sell_client_order_id")),
            requested_qty=filled_qty,
            live_qty=live_position_qty,
            target_sell_price=target_sell_price,
            sell_alpaca_order_id=_optional_str(position.get("sell_alpaca_order_id")),
            existing_order_preserved=False,
        )
        return
    if not _is_whole_share_qty(float(filled_qty)):
        fractional_snapshot = expected_renewal_snapshot
        if fractional_snapshot is None:
            persisted_buy_qty = _optional_float(position.get("filled_qty"))
            persisted_buy_avg = _optional_float(position.get("filled_avg_price"))
            if persisted_buy_qty is not None and persisted_buy_avg is not None:
                fractional_snapshot = _managed_sell_replacement_snapshot_if_current(
                    conn,
                    position_id=position_id,
                    sell_client_order_id=_optional_str(position.get("sell_client_order_id")),
                    sell_alpaca_order_id=_optional_str(position.get("sell_alpaca_order_id")),
                    sell_renewal_requested_at=_optional_str(position.get("sell_renewal_requested_at")),
                    expected_buy_status=_optional_str(position.get("buy_status")),
                    expected_buy_filled_qty=persisted_buy_qty,
                    expected_buy_filled_avg_price=persisted_buy_avg,
                    expected_target_sell_price=target_sell_price,
                    expected_remaining_qty=filled_qty,
                    expected_sell_status=_optional_str(position.get("sell_status")),
                    expected_sell_renewal_count=_optional_int(position.get("sell_renewal_count")),
                )
        _append_fractional_sell_result(
            conn=conn,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=_optional_str(position.get("sell_client_order_id")),
            filled_qty=filled_qty,
            target_sell_price=target_sell_price,
            expected_state_snapshot=fractional_snapshot,
        )
        return

    # An owned renewal is claimed below together with the final-submission
    # token. Its final exposure fence performs deterministic/open-order
    # recovery under that token, so a preliminary weak attachment here would
    # create an unfenced path around the renewal continuation.
    if check_open_order and expected_renewal_snapshot is None:
        expected_asset_id = _optional_str(position.get("alpaca_asset_id"))
        open_orders = client.open_orders(
            equity_scope_asset_ids=((expected_asset_id,) if expected_asset_id is not None else ())
        )
        matching_orders = _matching_managed_open_sell_orders(
            open_orders,
            symbol,
            position_id,
            sell_order_namespace=_optional_str(position.get("sell_order_namespace")),
            legacy_sell_client_order_id=_optional_str(position.get("sell_client_order_id")),
            expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
            excluded_client_order_id=_optional_str(position.get("sell_client_order_id")),
            excluded_alpaca_order_id=_optional_str(position.get("sell_alpaca_order_id")),
        )
        if len(matching_orders) > 1:
            _append_multiple_managed_open_sells_result(
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=_optional_str(position.get("sell_client_order_id")),
                filled_qty=filled_qty,
                target_sell_price=target_sell_price,
            )
            return
        if len(matching_orders) == 1:
            persisted_buy_qty = _optional_float(position.get("filled_qty"))
            persisted_buy_avg = _optional_float(position.get("filled_avg_price"))
            open_recovery_snapshot = (
                None
                if persisted_buy_qty is None or persisted_buy_avg is None
                else _managed_sell_replacement_snapshot_if_current(
                    conn,
                    position_id=position_id,
                    sell_client_order_id=_optional_str(position.get("sell_client_order_id")),
                    sell_alpaca_order_id=_optional_str(position.get("sell_alpaca_order_id")),
                    sell_renewal_requested_at=_optional_str(position.get("sell_renewal_requested_at")),
                    expected_buy_status=_optional_str(position.get("buy_status")),
                    expected_buy_filled_qty=persisted_buy_qty,
                    expected_buy_filled_avg_price=persisted_buy_avg,
                    expected_target_sell_price=target_sell_price,
                    expected_remaining_qty=filled_qty,
                    expected_sell_status=_optional_str(position.get("sell_status")),
                    expected_sell_renewal_count=_optional_int(position.get("sell_renewal_count")),
                )
            )
            _append_recovered_open_sell_result(
                conn=conn,
                client=client,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_order=matching_orders[0],
                filled_qty=filled_qty,
                target_sell_price=target_sell_price,
                expected_sell_client_order_id=_optional_str(position.get("sell_client_order_id")),
                expected_sell_alpaca_order_id=_optional_str(position.get("sell_alpaca_order_id")),
                expected_renewal_count=_optional_int(position.get("sell_renewal_count")),
                cfg=client.cfg,
                sell_order_namespace=_optional_str(position.get("sell_order_namespace")),
                expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
                close_on_complete=close_on_complete,
                expected_state_snapshot=open_recovery_snapshot,
            )
            return
        if _orders_have_open_order(
            open_orders,
            symbol,
            "sell",
            expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
            symbol_aliases=alpaca_managed_position_aliases(conn, position_id),
        ):
            _append_open_sell_result(
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=_optional_str(position.get("sell_client_order_id")),
                filled_qty=filled_qty,
                target_sell_price=target_sell_price,
            )
            return

    next_renewal_count = _optional_int(position.get("sell_renewal_count")) + 1
    sell_order_namespace = _optional_str(position.get("sell_order_namespace"))
    sell_client_order_id = _alpaca_exit_client_order_id(
        symbol,
        position_id,
        next_renewal_count,
        order_namespace=sell_order_namespace,
    )
    prior_sell_client_order_id = _optional_str(position.get("sell_client_order_id"))
    prior_sell_alpaca_order_id = _optional_str(position.get("sell_alpaca_order_id"))
    authoritative_remaining_qty = None
    sell_submission_claimed_at: str | None = None
    expected_sell_state_revision: int | object = _STORAGE_UNSET
    if prior_sell_client_order_id and prior_sell_alpaca_order_id:
        claim_kwargs = {
            "prior_sell_client_order_id": prior_sell_client_order_id,
            "prior_sell_alpaca_order_id": prior_sell_alpaca_order_id,
            "prior_renewal_count": next_renewal_count - 1,
            "replacement_sell_client_order_id": sell_client_order_id,
            "requested_remaining_qty": filled_qty,
            "expected_target_sell_price": target_sell_price,
            "notes": "managed GTC sell replacement submission claimed before broker request",
        }
        if expected_renewal_snapshot is None:
            authoritative_remaining_qty = claim_alpaca_managed_sell_replacement(
                conn,
                position_id,
                **claim_kwargs,
            )
        else:
            sell_submission_claimed_at = _utc_now().isoformat().replace("+00:00", "Z")
            replacement_claim = claim_alpaca_managed_sell_replacement_submission(
                conn,
                position_id,
                **claim_kwargs,
                expected_renewal_snapshot=expected_renewal_snapshot,
                claimed_at=sell_submission_claimed_at,
            )
            if replacement_claim is not None:
                authoritative_remaining_qty = replacement_claim.remaining_qty
                expected_sell_state_revision = replacement_claim.state_revision
    if authoritative_remaining_qty is None:
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="submission_pending",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=filled_qty,
            limit_price=target_sell_price,
            alpaca_order_id=None,
            message="managed GTC sell replacement is already claimed by another workflow",
            required_failure=True,
        )
        return
    _submit_managed_gtc_sell(
        conn=conn,
        client=client,
        rows=rows,
        position_id=position_id,
        symbol=symbol,
        buy_client_order_id=buy_client_order_id,
        sell_client_order_id=sell_client_order_id,
        filled_qty=authoritative_remaining_qty,
        target_sell_price=target_sell_price,
        quantity_mark_price=effective_quantity_mark_price,
        increment_renewal_count=False,
        replacement_message=replacement_message,
        live_position_qty=live_position_qty,
        close_on_complete=close_on_complete,
        intent_already_persisted=True,
        sell_order_namespace=sell_order_namespace,
        intent_not_before=_optional_str(position.get("created_at")),
        expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
        sell_submission_retry_claimed_at=sell_submission_claimed_at,
        expected_sell_state_revision=expected_sell_state_revision,
        allow_fenced_inactive_historical_intent_mismatch=bool(
            expected_renewal_snapshot is not None and expected_renewal_snapshot.requested_at is not None
        ),
    )


def _request_gtc_sell_renewal(
    *,
    conn: sqlite3.Connection,
    client: AlpacaClient,
    rows: list[dict],
    position: dict,
    symbol: str,
    buy_client_order_id: str,
    filled_qty: float,
    target_sell_price: float,
    sell_alpaca_order_id: str,
    live_position_qty: float,
    replacement_chain: list[dict] | None = None,
    replacement_message: str = "renewed managed GTC limit sell before Alpaca aged-order expiration",
    renewal_note: str = "managed GTC sell renewal requested before expiration",
    pending_message: str = (
        "managed GTC sell expires soon; cancellation requested and replacement "
        "will be submitted after Alpaca confirms cancellation"
    ),
    close_on_complete: bool = True,
) -> None:
    def durable_note(value: str | None) -> str | None:
        return _alpaca_durable_diagnostic_note(
            value,
            cfg=client.cfg,
            client=client,
        )

    position_id = int(position["id"])
    sell_client_order_id = _optional_str(position.get("sell_client_order_id"))
    managed_remaining_qty = _managed_remaining_qty(position, filled_qty)
    if not _managed_sell_quantities_match(
        managed_remaining_qty,
        live_position_qty,
        filled_qty,
        mark_price=target_sell_price,
    ):
        _append_live_position_quantity_mismatch_result(
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            requested_qty=managed_remaining_qty,
            live_qty=live_position_qty,
            target_sell_price=target_sell_price,
            sell_alpaca_order_id=sell_alpaca_order_id,
            existing_order_preserved=True,
        )
        return
    now = _utc_now()
    requested_at = now.isoformat().replace("+00:00", "Z")
    reclaim_before = (now - _SELL_RENEWAL_CLAIM_LEASE).isoformat().replace("+00:00", "Z")
    broker_sell_status = (
        _broker_order_status((replacement_chain or [{}])[-1]) or str(position.get("sell_status") or "unknown").lower()
    )
    observed_sell_status = _sell_status_after_pending_cancel(
        persisted_status=position.get("sell_status"),
        observed_status=broker_sell_status,
    )
    filled_avg_price = _optional_float(position.get("filled_avg_price"))
    renewal_premise = (
        None
        if not sell_client_order_id or filled_avg_price is None
        else _managed_sell_replacement_snapshot_if_current(
            conn,
            position_id=position_id,
            sell_client_order_id=sell_client_order_id,
            sell_alpaca_order_id=sell_alpaca_order_id,
            sell_renewal_requested_at=_optional_str(position.get("sell_renewal_requested_at")),
            expected_buy_status=_optional_str(position.get("buy_status")),
            expected_buy_filled_qty=float(filled_qty),
            expected_buy_filled_avg_price=filled_avg_price,
            expected_target_sell_price=target_sell_price,
            expected_remaining_qty=managed_remaining_qty,
            expected_sell_status=observed_sell_status,
            expected_sell_renewal_count=_optional_int(position.get("sell_renewal_count")),
        )
    )
    renewal_claim = (
        None
        if renewal_premise is None
        else claim_alpaca_managed_sell_renewal_with_revision(
            conn,
            position_id,
            sell_client_order_id=sell_client_order_id,
            sell_alpaca_order_id=sell_alpaca_order_id,
            expected_target_sell_price=target_sell_price,
            expected_remaining_qty=managed_remaining_qty,
            requested_at=requested_at,
            reclaim_before=reclaim_before,
            notes=durable_note(renewal_note),
            expected_renewal_snapshot=renewal_premise,
        )
    )
    if renewal_claim is None:
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="superseded",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=_optional_str(position.get("sell_client_order_id")),
            qty=filled_qty,
            limit_price=target_sell_price,
            alpaca_order_id=sell_alpaca_order_id,
            message=(
                "managed GTC sell renewal claim was superseded because its order, quantity, target, or lease changed"
            ),
        )
        return
    cancel_error: requests.RequestException | None = None
    try:
        cancel_resp = client.cancel_order(sell_alpaca_order_id)
        _require_2xx_response(cancel_resp, expected_status=204)
    except (requests.exceptions.Timeout, requests.exceptions.ConnectionError) as exc:
        cancel_error = exc
    except HTTPError as exc:
        status_code = exc.response.status_code if exc.response is not None else None
        if status_code not in {404, 422}:
            raise
        cancel_error = exc

    try:
        refreshed_resp = client.get_order(sell_alpaca_order_id)
        _require_2xx_response(refreshed_resp)
    except requests.RequestException as exc:
        if cancel_error is not None:
            raise cancel_error from exc
        raise
    refreshed_payload = _response_json(refreshed_resp)
    refreshed_order, refreshed_suffix = _resolve_order_replacement_successors(
        client,
        [refreshed_payload],
    )
    prior_sell_client_order_id = _optional_str(position.get("sell_client_order_id"))
    refreshed_replacement_chain = (
        [*replacement_chain[:-1], *refreshed_suffix] if replacement_chain else refreshed_suffix
    )
    if not _replacement_chain_is_consistent(refreshed_replacement_chain):
        raise ValueError("Alpaca cancellation refresh returned an inconsistent replacement lineage")
    if prior_sell_client_order_id and not _sell_order_identity_is_consistent(
        refreshed_order,
        expected_sell_client_order_id=prior_sell_client_order_id,
        expected_sell_alpaca_order_id=sell_alpaca_order_id,
        expected_symbol=symbol,
        expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
        replacement_chain=refreshed_replacement_chain,
    ):
        _append_incomplete_sell_order_identity_result(
            conn=conn,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=prior_sell_client_order_id,
            observed_sell_qty=_sell_fill_metadata(refreshed_order)[0],
            target_sell_price=target_sell_price,
            sell_alpaca_order_id=_optional_str(refreshed_order.get("id")),
            identity_issue="cancellation refresh does not match the managed sell order",
            expected_sell_status="pending_cancel",
            expected_sell_alpaca_order_id=sell_alpaca_order_id,
            expected_sell_filled_qty=renewal_claim.sell_filled_qty,
            expected_sell_renewal_count=renewal_claim.sell_renewal_count,
            expected_sell_renewal_requested_at=renewal_claim.requested_at,
            expected_sell_state_revision=renewal_claim.state_revision,
        )
        return
    refreshed_chain = refreshed_replacement_chain or [refreshed_order]
    _, refreshed_sell_avg_price, _ = _replacement_chain_fill_metadata(refreshed_chain)
    sell_residual_mark_price = _managed_sell_residual_mark_price(
        target_sell_price,
        refreshed_sell_avg_price,
        *(order.get("limit_price") for order in refreshed_chain),
    )
    refreshed_sell_alpaca_order_id = _optional_str(refreshed_order.get("id")) or sell_alpaca_order_id
    refreshed_is_verified_successor = bool(
        refreshed_sell_alpaca_order_id != sell_alpaca_order_id
        and sell_alpaca_order_id
        in {order_id for node in refreshed_chain if (order_id := _optional_str(node.get("id"))) is not None}
    )
    refreshed_status = _sell_status_after_pending_cancel(
        persisted_status="pending_cancel",
        observed_status=_broker_order_status(refreshed_order, default="pending_cancel"),
        observed_is_verified_replacement_successor=refreshed_is_verified_successor,
    )
    submitted_sell_qty = _optional_positive_float(position.get("sell_order_qty"))
    if submitted_sell_qty is None:
        submitted_sell_qty = _optional_positive_float(refreshed_chain[0].get("qty"))
    if submitted_sell_qty is None:
        submitted_sell_qty = managed_remaining_qty
    submitted_sell_limit_price = _optional_positive_float(position.get("sell_order_limit_price"))
    if submitted_sell_limit_price is None:
        submitted_sell_limit_price = _optional_positive_float(refreshed_chain[0].get("limit_price"))
    if submitted_sell_limit_price is None:
        submitted_sell_limit_price = target_sell_price
    sell_intent_issue = _sell_replacement_chain_intent_issue(
        refreshed_chain,
        requested_qty=submitted_sell_qty,
        target_sell_price=submitted_sell_limit_price,
    )
    sell_position_intent_issue = _sell_replacement_chain_position_intent_issue(refreshed_chain)
    if not prior_sell_client_order_id or not update_alpaca_managed_sell_status_if_current(
        conn,
        position_id,
        expected_sell_client_order_id=prior_sell_client_order_id,
        expected_sell_status="pending_cancel",
        expected_sell_alpaca_order_id=sell_alpaca_order_id,
        expected_sell_filled_qty=renewal_claim.sell_filled_qty,
        expected_sell_renewal_count=renewal_claim.sell_renewal_count,
        expected_sell_renewal_requested_at=renewal_claim.requested_at,
        expected_state_revision=renewal_claim.state_revision,
        sell_status=refreshed_status,
        sell_alpaca_order_id=refreshed_sell_alpaca_order_id,
        sell_submitted_at=_optional_alpaca_datetime_str(refreshed_order.get("submitted_at")),
        sell_expires_at=_optional_alpaca_datetime_str(refreshed_order.get("expires_at")),
        sell_order_qty=submitted_sell_qty,
        sell_order_limit_price=submitted_sell_limit_price,
        sell_renewal_requested_at=requested_at,
        notes=durable_note(renewal_note),
        allow_verified_replaced_successor=refreshed_is_verified_successor,
    ):
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="superseded",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=prior_sell_client_order_id,
            qty=filled_qty,
            limit_price=target_sell_price,
            alpaca_order_id=sell_alpaca_order_id,
            message="broker observation belongs to a superseded managed GTC sell generation",
        )
        return
    assert prior_sell_client_order_id is not None

    def load_current_renewal_snapshot() -> AlpacaManagedSellRenewalSnapshot | None:
        return alpaca_managed_sell_renewal_snapshot_if_current(
            conn,
            position_id,
            expected_sell_client_order_id=prior_sell_client_order_id,
            expected_sell_alpaca_order_id=refreshed_sell_alpaca_order_id,
            expected_sell_renewal_requested_at=renewal_claim.requested_at,
        )

    def renewal_snapshot_matches_premise(
        snapshot: AlpacaManagedSellRenewalSnapshot,
        expected_remaining_qty: float,
        *,
        expected_sell_status: str = refreshed_status,
    ) -> bool:
        expected_parent_filled_qty = float(filled_qty)
        expected_parent_avg_price = _optional_float(position.get("filled_avg_price"))
        expected_sell_filled_qty = max(expected_parent_filled_qty - expected_remaining_qty, 0.0)
        observed_sell_filled_qty = snapshot.sell_filled_qty or 0.0
        return bool(
            snapshot.buy_status == _optional_str(position.get("buy_status"))
            and snapshot.filled_qty is not None
            and _managed_sell_quantities_match(
                snapshot.filled_qty,
                expected_parent_filled_qty,
                mark_price=sell_residual_mark_price,
            )
            and (
                snapshot.filled_avg_price is None
                and expected_parent_avg_price is None
                or snapshot.filled_avg_price is not None
                and expected_parent_avg_price is not None
                and abs(snapshot.filled_avg_price - expected_parent_avg_price) <= _MANAGED_PRICE_TOLERANCE
            )
            and snapshot.sell_status == expected_sell_status
            and snapshot.sell_alpaca_order_id == refreshed_sell_alpaca_order_id
            and snapshot.sell_renewal_count == renewal_claim.sell_renewal_count
            and abs(observed_sell_filled_qty - expected_sell_filled_qty)
            <= _managed_qty_tolerance(observed_sell_filled_qty, expected_sell_filled_qty)
            and snapshot.remaining_qty is not None
            and _managed_sell_quantities_match(
                snapshot.remaining_qty,
                expected_remaining_qty,
                mark_price=sell_residual_mark_price,
            )
            and snapshot.target_sell_price is not None
            and abs(snapshot.target_sell_price - target_sell_price) <= _alpaca_limit_price_tolerance(target_sell_price)
        )

    renewal_snapshot = load_current_renewal_snapshot()
    if renewal_snapshot is None or not renewal_snapshot_matches_premise(
        renewal_snapshot,
        managed_remaining_qty,
    ):
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="superseded",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=prior_sell_client_order_id,
            qty=filled_qty,
            limit_price=target_sell_price,
            alpaca_order_id=refreshed_sell_alpaca_order_id,
            message=(
                "renewal continuation or its parent quantity/target premise was superseded "
                "after cancellation refresh persistence"
            ),
        )
        return
    if sell_position_intent_issue is not None:
        _append_sell_submission_intent_mismatch_result(
            conn=conn,
            client=client,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=prior_sell_client_order_id,
            requested_qty=submitted_sell_qty,
            target_sell_price=submitted_sell_limit_price,
            sell_order=refreshed_order,
            replacement_chain=refreshed_chain,
            intent_issue=sell_position_intent_issue,
            expected_renewal_snapshot=renewal_snapshot,
        )
        return
    # The cancellation refresh can advance to a broker-created successor. Keep
    # the in-memory CAS snapshot aligned with the state just persisted so a
    # terminal successor can be replaced in this same reconciliation pass.
    position["sell_status"] = refreshed_status
    position["sell_alpaca_order_id"] = refreshed_sell_alpaca_order_id
    position["sell_order_qty"] = submitted_sell_qty
    position["sell_order_limit_price"] = submitted_sell_limit_price
    position["sell_renewal_requested_at"] = requested_at
    if refreshed_submitted_at := _optional_alpaca_datetime_str(refreshed_order.get("submitted_at")):
        position["sell_submitted_at"] = refreshed_submitted_at
    if refreshed_expires_at := _optional_alpaca_datetime_str(refreshed_order.get("expires_at")):
        position["sell_expires_at"] = refreshed_expires_at
    remaining_qty = _managed_remaining_qty(position, filled_qty)
    observed_sell_qty, _, fill_metadata_is_valid = _sell_fill_metadata(refreshed_order)
    if not fill_metadata_is_valid or (refreshed_status == "filled" and observed_sell_qty == 0.0):
        _append_incomplete_sell_fill_result(
            conn=conn,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=_optional_str(position.get("sell_client_order_id")),
            observed_sell_qty=observed_sell_qty,
            target_sell_price=target_sell_price,
            sell_alpaca_order_id=refreshed_sell_alpaca_order_id,
            expected_renewal_snapshot=renewal_snapshot,
        )
        return
    try:
        remaining_qty, fill_generation_is_current = _record_replacement_chain_sell_fills(
            conn=conn,
            position_id=position_id,
            sell_client_order_id=prior_sell_client_order_id,
            replacement_chain=refreshed_chain,
            initial_remaining_qty=remaining_qty,
            expected_renewal_snapshot=renewal_snapshot,
        )
    except SellFillQuantityRegressionError:
        regression_snapshot = load_current_renewal_snapshot()
        if regression_snapshot is None or not renewal_snapshot_matches_premise(
            regression_snapshot,
            remaining_qty,
        ):
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="superseded",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=prior_sell_client_order_id,
                qty=observed_sell_qty,
                limit_price=target_sell_price,
                alpaca_order_id=refreshed_sell_alpaca_order_id,
                message="fill regression diagnostic lost its renewal or parent-state premise",
            )
            return
        _append_sell_fill_quantity_regression_result(
            conn=conn,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=prior_sell_client_order_id,
            observed_sell_qty=observed_sell_qty,
            target_sell_price=target_sell_price,
            sell_alpaca_order_id=refreshed_sell_alpaca_order_id,
            expected_renewal_snapshot=regression_snapshot,
        )
        return
    if not fill_generation_is_current:
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="superseded",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=prior_sell_client_order_id,
            qty=observed_sell_qty,
            limit_price=target_sell_price,
            alpaca_order_id=sell_alpaca_order_id,
            message="fill observation belongs to a superseded managed GTC sell generation",
        )
        return
    renewal_snapshot = load_current_renewal_snapshot()
    if renewal_snapshot is None or not renewal_snapshot_matches_premise(
        renewal_snapshot,
        remaining_qty,
        expected_sell_status=(
            "quantity_mismatch"
            if _managed_sell_is_overfilled(
                remaining_qty,
                filled_qty,
                observed_sell_qty,
                mark_price=sell_residual_mark_price,
            )
            else refreshed_status
        ),
    ):
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="superseded",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=prior_sell_client_order_id,
            qty=observed_sell_qty,
            limit_price=target_sell_price,
            alpaca_order_id=refreshed_sell_alpaca_order_id,
            message=(
                "renewal continuation or its parent quantity/target premise was superseded "
                "after authoritative fill accounting"
            ),
        )
        return
    if sell_intent_issue is not None and refreshed_status not in SELL_REPLACEMENT_SAFE_STATUSES:
        assert prior_sell_client_order_id is not None
        _append_sell_submission_intent_mismatch_result(
            conn=conn,
            client=client,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=prior_sell_client_order_id,
            requested_qty=submitted_sell_qty,
            target_sell_price=submitted_sell_limit_price,
            sell_order=refreshed_order,
            replacement_chain=refreshed_replacement_chain,
            intent_issue=sell_intent_issue,
            expected_renewal_snapshot=renewal_snapshot,
        )
        return
    if _managed_sell_is_overfilled(
        remaining_qty,
        filled_qty,
        observed_sell_qty,
        mark_price=sell_residual_mark_price,
    ):
        _append_overfilled_sell_result(
            conn=conn,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=_optional_str(position.get("sell_client_order_id")),
            observed_sell_qty=observed_sell_qty,
            target_sell_price=target_sell_price,
            sell_alpaca_order_id=refreshed_sell_alpaca_order_id,
            expected_renewal_snapshot=renewal_snapshot,
        )
        return
    if refreshed_status in _ORDER_MAY_BE_ACTIVE_STATUSES and _managed_sell_is_complete(
        remaining_qty,
        filled_qty,
        observed_sell_qty,
        mark_price=sell_residual_mark_price,
    ):
        _append_active_sell_completion_mismatch_result(
            conn=conn,
            client=client,
            rows=rows,
            position_id=position_id,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=prior_sell_client_order_id,
            observed_sell_qty=observed_sell_qty,
            target_sell_price=target_sell_price,
            sell_order=refreshed_order,
            replacement_chain=refreshed_replacement_chain,
            expected_renewal_snapshot=renewal_snapshot,
        )
        return
    if _managed_sell_is_complete(
        remaining_qty,
        filled_qty,
        observed_sell_qty,
        mark_price=sell_residual_mark_price,
    ):
        if close_on_complete:
            closing_sell_alpaca_order_id = _optional_str(refreshed_order.get("id")) or sell_alpaca_order_id
            assert closing_sell_alpaca_order_id is not None
            closed = close_alpaca_managed_position_if_current_and_complete(
                conn,
                position_id,
                expected_sell_client_order_id=prior_sell_client_order_id,
                expected_sell_alpaca_order_id=closing_sell_alpaca_order_id,
                closed_at=_optional_alpaca_datetime_str(refreshed_order.get("filled_at")),
                expected_sell_status=refreshed_status,
                expected_sell_filled_qty=renewal_snapshot.sell_filled_qty,
                expected_sell_renewal_count=renewal_snapshot.sell_renewal_count,
                expected_sell_renewal_requested_at=renewal_snapshot.requested_at,
                expected_state_revision=renewal_snapshot.state_revision,
                notes=durable_note("managed target sell filled"),
            )
            if not closed:
                _append_reconciliation_result(
                    rows,
                    position_id=position_id,
                    symbol=symbol,
                    action="sell",
                    status="superseded",
                    buy_client_order_id=buy_client_order_id,
                    sell_client_order_id=prior_sell_client_order_id,
                    qty=observed_sell_qty,
                    limit_price=target_sell_price,
                    alpaca_order_id=sell_alpaca_order_id,
                    message="position closure belongs to a superseded managed GTC sell generation",
                )
                return
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status="filled",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=_optional_str(position.get("sell_client_order_id")),
            qty=observed_sell_qty,
            limit_price=target_sell_price,
            alpaca_order_id=sell_alpaca_order_id,
            message=(
                "managed target sell filled; position closed"
                if close_on_complete
                else "managed sell filled; awaiting final status of the still-open parent buy"
            ),
        )
        return
    if refreshed_status == "filled":
        mismatch_generation_is_current = update_alpaca_managed_sell_status_if_current(
            conn,
            position_id,
            expected_sell_client_order_id=prior_sell_client_order_id,
            **_renewal_snapshot_cas_kwargs(renewal_snapshot),
            sell_status="quantity_mismatch",
            notes=durable_note("filled sell quantity did not close the managed buy quantity; manual review required"),
        )
        if not mismatch_generation_is_current:
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="superseded",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=prior_sell_client_order_id,
                qty=observed_sell_qty,
                limit_price=target_sell_price,
                alpaca_order_id=sell_alpaca_order_id,
                message="quantity mismatch belongs to a superseded managed GTC sell generation",
            )
            return
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="sell",
            status=refreshed_status,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=_optional_str(position.get("sell_client_order_id")),
            qty=observed_sell_qty,
            limit_price=target_sell_price,
            alpaca_order_id=sell_alpaca_order_id,
            message="managed sell fill quantity does not match the managed buy; position remains active for review",
            required_failure=True,
        )
        return
    if refreshed_status in SELL_RENEWABLE_STATUSES:
        refreshed_order_qty = _optional_positive_float(refreshed_order.get("qty"))
        refreshed_limit_price = _optional_positive_float(refreshed_order.get("limit_price"))
        refreshed_open_qty = None if refreshed_order_qty is None else max(refreshed_order_qty - observed_sell_qty, 0.0)
        refreshed_successor_covers_current_intent = bool(
            refreshed_open_qty is not None
            and _managed_sell_quantities_match(
                refreshed_open_qty,
                remaining_qty,
                mark_price=sell_residual_mark_price,
            )
            and refreshed_limit_price is not None
            and abs(refreshed_limit_price - target_sell_price) <= _alpaca_limit_price_tolerance(target_sell_price)
        )
        if not refreshed_successor_covers_current_intent:
            current_renewal_snapshot = load_current_renewal_snapshot()
            current_is_exact_successor = bool(
                current_renewal_snapshot is not None
                and renewal_snapshot_matches_premise(
                    current_renewal_snapshot,
                    remaining_qty,
                )
            )
            cancellation_requested_at = _utc_now().isoformat().replace("+00:00", "Z")
            cancellation_claimed = bool(
                current_is_exact_successor
                and update_alpaca_managed_sell_status_if_current(
                    conn,
                    position_id,
                    expected_sell_client_order_id=prior_sell_client_order_id,
                    **_renewal_snapshot_cas_kwargs(current_renewal_snapshot),
                    sell_status="pending_cancel",
                    sell_alpaca_order_id=refreshed_sell_alpaca_order_id,
                    sell_renewal_requested_at=cancellation_requested_at,
                    notes=durable_note(
                        "broker-created renewal successor does not cover the current managed quantity "
                        "and frozen target; cancellation requested"
                    ),
                )
            )
            if not cancellation_claimed:
                _append_reconciliation_result(
                    rows,
                    position_id=position_id,
                    symbol=symbol,
                    action="sell",
                    status="superseded",
                    buy_client_order_id=buy_client_order_id,
                    sell_client_order_id=prior_sell_client_order_id,
                    qty=remaining_qty,
                    limit_price=target_sell_price,
                    alpaca_order_id=refreshed_sell_alpaca_order_id,
                    message=("inadequate broker-created renewal successor changed concurrently before cancellation"),
                )
                return
            _cancellation_pending, cancellation_message = _request_safely_attributed_order_cancellation(
                client, refreshed_order
            )
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="sell",
                status="pending_cancel",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=prior_sell_client_order_id,
                qty=remaining_qty,
                limit_price=target_sell_price,
                alpaca_order_id=refreshed_sell_alpaca_order_id,
                message=(
                    "broker-created renewal successor does not cover the current managed quantity "
                    f"and frozen target; {cancellation_message}"
                ),
                required_failure=True,
            )
            return
    if refreshed_status in SELL_REPLACEMENT_SAFE_STATUSES:
        refreshed_live_position_qty = live_position_qty
        if not _managed_sell_quantities_match(
            remaining_qty,
            managed_remaining_qty,
            filled_qty,
            mark_price=sell_residual_mark_price,
        ):
            refreshed_live_position_qty = _managed_live_position_qty(
                client.positions(),
                symbol=symbol,
                expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
                symbol_aliases=alpaca_managed_position_aliases(conn, position_id),
            )
        _submit_replacement_gtc_sell(
            conn=conn,
            client=client,
            rows=rows,
            position=position,
            symbol=symbol,
            buy_client_order_id=buy_client_order_id,
            filled_qty=remaining_qty,
            target_sell_price=target_sell_price,
            quantity_mark_price=sell_residual_mark_price,
            replacement_message=replacement_message,
            check_open_order=True,
            live_position_qty=refreshed_live_position_qty,
            close_on_complete=close_on_complete,
            expected_renewal_snapshot=renewal_snapshot,
        )
        return

    if refreshed_status in SELL_INACTIVE_STATUSES:
        pending_message = (
            f"managed GTC sell entered {refreshed_status}; replacement was not submitted because "
            "Alpaca has not confirmed cancellation or expiration"
        )

    _append_reconciliation_result(
        rows,
        position_id=position_id,
        symbol=symbol,
        action="sell",
        status="pending_cancel" if refreshed_status in SELL_CANCEL_PENDING_STATUSES else refreshed_status,
        buy_client_order_id=buy_client_order_id,
        sell_client_order_id=_optional_str(position.get("sell_client_order_id")),
        qty=filled_qty,
        limit_price=target_sell_price,
        alpaca_order_id=sell_alpaca_order_id,
        message=pending_message,
        required_failure=refreshed_status not in SELL_RENEWABLE_STATUSES,
    )


def _quarantine_buy_fill_quantity_regression(
    *,
    conn: sqlite3.Connection,
    client: AlpacaClient,
    rows: list[dict],
    position: dict,
    observed_buy_order: dict,
    observed_buy_lineage: list[dict],
    observed_filled_qty: float,
    retained_buy_status: str = "fill_quantity_regression",
) -> bool:
    """Fail closed when Alpaca lowers a previously persisted cumulative buy fill."""
    position_id = int(position["id"])
    symbol = str(position["symbol"])
    buy_client_order_id = str(position["buy_client_order_id"])
    sell_client_order_id = _optional_str(position.get("sell_client_order_id"))
    persisted_filled_qty = _optional_float(position.get("filled_qty")) or 0.0
    if not alpaca_managed_buy_fill_observation_authorizes_mutation(
        persisted_broker_updated_at=_optional_str(position.get("buy_fill_broker_updated_at")),
        persisted_component_revisions=_optional_str(position.get("buy_fill_component_revisions")),
        observed_broker_updated_at=_replacement_chain_latest_broker_updated_at(observed_buy_lineage),
        observed_oldest_broker_updated_at=_replacement_chain_oldest_broker_updated_at(observed_buy_lineage),
        observed_component_revisions=_replacement_chain_broker_component_revisions(observed_buy_lineage),
    ):
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="buy",
            status="superseded",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=observed_filled_qty,
            limit_price=None,
            alpaca_order_id=_optional_str(observed_buy_order.get("id")),
            message="stale buy-fill quantity regression was superseded by a newer lineage observation",
        )
        return False
    diagnostic = (
        f"Alpaca corrected cumulative buy fill quantity downward from {persisted_filled_qty:g} "
        f"to {observed_filled_qty:g}; managed accounting and protective sell require review"
    )
    status_updated = update_alpaca_managed_buy_status_if_current(
        conn,
        position_id,
        expected_buy_status=str(position.get("buy_status", "submission_pending")).lower(),
        expected_buy_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
        expected_filled_qty=_optional_float(position.get("filled_qty")),
        expected_sell_client_order_id=sell_client_order_id,
        expected_buy_submission_attempt_count=_optional_int(position.get("buy_submission_attempt_count")),
        expected_state_revision=int(position["state_revision"]),
        buy_status=retained_buy_status,
        buy_alpaca_order_id=_optional_str(observed_buy_order.get("id")),
        buy_submitted_at=_optional_alpaca_datetime_str(observed_buy_order.get("submitted_at")),
        notes=_alpaca_durable_diagnostic_note(
            diagnostic,
            cfg=client.cfg,
            client=client,
        ),
    )

    cancellation_message = "no active protective sell was recorded"
    if sell_client_order_id is not None and status_updated:
        try:
            sell_order, replacement_chain = _fetch_order_payload(
                client,
                _optional_str(position.get("sell_alpaca_order_id")),
                sell_client_order_id,
            )
            if not _sell_order_identity_is_consistent(
                sell_order,
                expected_sell_client_order_id=sell_client_order_id,
                expected_sell_alpaca_order_id=_optional_str(position.get("sell_alpaca_order_id")),
                expected_symbol=symbol,
                expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
                replacement_chain=replacement_chain,
            ):
                cancellation_message = "protective sell identity could not be verified for cancellation"
            else:
                current_orders = {
                    order_id: order
                    for order in replacement_chain
                    if (order_id := _optional_str(order.get("id"))) is not None
                }
                observed_orders = dict(current_orders)
                historical_issue: str | None = None
                try:
                    observed_orders, _historical_leaves, historical_intent_issues = _historical_managed_sell_lineages(
                        conn=conn,
                        client=client,
                        position=position,
                        current_orders=current_orders,
                        expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
                    )
                    if historical_intent_issues:
                        historical_issue = "; ".join(historical_intent_issues)
                except (HTTPError, SellOrderIdentityError, RuntimeError, ValueError) as exc:
                    historical_issue = _alpaca_client_exception_diagnostic(exc, client=client)

                corrected_sold_qty = 0.0
                fill_metadata_is_complete = historical_issue is None
                for observed_order in observed_orders.values():
                    if _sell_replacement_chain_position_intent_issue([observed_order]) is not None:
                        continue
                    raw_filled_qty = _replacement_chain_nonnegative_filled_qty([observed_order])
                    filled_qty, _, metadata_is_valid = _sell_fill_metadata(observed_order)
                    if raw_filled_qty is None or not metadata_is_valid:
                        fill_metadata_is_complete = False
                        continue
                    corrected_sold_qty += filled_qty
                if not fill_metadata_is_complete:
                    corrected_sold_qty = _optional_float(position.get("sold_qty")) or 0.0
                corrected_remaining_qty = max(observed_filled_qty - corrected_sold_qty, 0.0)

                active_orders = [
                    order
                    for order in observed_orders.values()
                    if _broker_order_status(order) in _ORDER_MAY_BE_ACTIVE_STATUSES
                ]
                active_wrong_position_intent_orders = [
                    order
                    for order in active_orders
                    if _sell_replacement_chain_position_intent_issue([order]) is not None
                ]
                open_sell_qty = 0.0
                open_sell_qty_is_complete = fill_metadata_is_complete
                for active_order in active_orders:
                    order_qty = _optional_positive_float(active_order.get("qty"))
                    order_filled_qty, _, order_fill_is_valid = _sell_fill_metadata(active_order)
                    if order_qty is None or not order_fill_is_valid:
                        open_sell_qty_is_complete = False
                        continue
                    open_sell_qty += max(order_qty - order_filled_qty, 0.0)
                residual_mark_price = max(
                    _optional_positive_float(position.get("filled_avg_price")) or 0.0,
                    _optional_positive_float(position.get("target_sell_price")) or 0.0,
                    _optional_positive_float(position.get("sell_order_limit_price")) or 0.0,
                    *(_optional_positive_float(order.get("limit_price")) or 0.0 for order in observed_orders.values()),
                    *(_sell_fill_metadata(order)[1] or 0.0 for order in observed_orders.values()),
                )
                oversized = bool(
                    active_orders
                    and (
                        active_wrong_position_intent_orders
                        or not open_sell_qty_is_complete
                        or (
                            open_sell_qty > corrected_remaining_qty
                            and not _managed_sell_quantities_match(
                                open_sell_qty,
                                corrected_remaining_qty,
                                mark_price=residual_mark_price,
                            )
                        )
                    )
                )
                if oversized:
                    persisted_avg_price = _optional_float(position.get("filled_avg_price"))
                    persisted_target = _optional_float(position.get("target_sell_price"))
                    persisted_remaining = _optional_float(position.get("remaining_qty"))
                    cancellation_snapshot = (
                        None
                        if (
                            persisted_avg_price is None
                            or persisted_target is None
                            or persisted_remaining is None
                            or _optional_str(position.get("sell_alpaca_order_id")) is None
                        )
                        else _managed_sell_replacement_snapshot_if_current(
                            conn,
                            position_id=position_id,
                            sell_client_order_id=sell_client_order_id,
                            sell_alpaca_order_id=str(position["sell_alpaca_order_id"]),
                            sell_renewal_requested_at=_optional_str(position.get("sell_renewal_requested_at")),
                            expected_buy_status=retained_buy_status,
                            expected_buy_filled_qty=persisted_filled_qty,
                            expected_buy_filled_avg_price=persisted_avg_price,
                            expected_target_sell_price=persisted_target,
                            expected_remaining_qty=persisted_remaining,
                            expected_sell_status=str(position.get("sell_status") or ""),
                            expected_sell_renewal_count=_optional_int(position.get("sell_renewal_count")),
                        )
                    )
                    cancellation_requested_at = _utc_now().isoformat().replace("+00:00", "Z")
                    cancellation_owned = bool(cancellation_snapshot) and (
                        update_alpaca_managed_sell_status_if_current(
                            conn,
                            position_id,
                            expected_sell_client_order_id=sell_client_order_id,
                            **_renewal_snapshot_cas_kwargs(cancellation_snapshot),
                            sell_status="pending_cancel",
                            sell_renewal_requested_at=cancellation_requested_at,
                            notes=_alpaca_durable_diagnostic_note(
                                "protective sell cancellation ownership fenced after Alpaca lowered "
                                "the parent buy fill",
                                cfg=client.cfg,
                                client=client,
                            ),
                        )
                    )
                    if cancellation_owned:
                        _pending, cancellation_messages = _request_managed_sell_leaf_cancellations(
                            client,
                            active_orders,
                        )
                        cancellation_message = (
                            "unsafe attributed protective sell cancellations require confirmation; "
                            + "; ".join(cancellation_messages)
                        )
                    else:
                        cancellation_message = (
                            "protective sell cancellation was not requested because its exact managed premise changed"
                        )
                elif active_orders:
                    cancellation_message = "attributed protective sell exposure has no cancellable excess"
                else:
                    cancellation_message = "all attributed protective sell leaves are inactive"
                if historical_issue is not None:
                    cancellation_message += f"; historical sell audit requires review: {historical_issue}"
        except Exception as exc:
            detail = _alpaca_client_exception_diagnostic(exc, client=client)
            cancellation_message = f"protective sell cancellation could not be confirmed: {detail}"
    elif sell_client_order_id is not None:
        cancellation_message = (
            "protective sell cancellation was not requested because the parent regression claim "
            "lost its managed-state fence"
        )

    _append_reconciliation_result(
        rows,
        position_id=position_id,
        symbol=symbol,
        action="buy",
        status="fill_quantity_regression",
        buy_client_order_id=buy_client_order_id,
        sell_client_order_id=sell_client_order_id,
        qty=observed_filled_qty,
        limit_price=_optional_float(position.get("target_sell_price")),
        alpaca_order_id=_optional_str(observed_buy_order.get("id")),
        message=(
            f"{diagnostic}; {cancellation_message}"
            if status_updated
            else (
                f"{diagnostic}; local state changed concurrently, but the broker regression remains fatal; "
                f"{cancellation_message}"
            )
        ),
        required_failure=True,
    )
    return status_updated


def _fence_attached_sell_after_unproven_buy(
    *,
    conn: sqlite3.Connection,
    client: AlpacaClient,
    position: dict,
    expected_buy_status: str,
    expected_state_revision: int,
) -> str:
    """Cancel attributed sell exposure only after an exact local quarantine fence."""
    position_id = int(position["id"])
    symbol = str(position["symbol"])
    sell_client_order_id = _optional_str(position.get("sell_client_order_id"))
    if sell_client_order_id is None:
        return "no attached managed sell was recorded"

    persisted_sell_order_id = _optional_str(position.get("sell_alpaca_order_id"))
    try:
        sell_order, replacement_chain = _fetch_order_payload(
            client,
            persisted_sell_order_id,
            sell_client_order_id,
        )
    except (requests.RequestException, RuntimeError, ValueError) as exc:
        detail = _alpaca_client_exception_diagnostic(exc, client=client)
        return f"attached managed sell could not be verified for cancellation: {detail}"
    if not _sell_order_identity_is_consistent(
        sell_order,
        expected_sell_client_order_id=sell_client_order_id,
        expected_sell_alpaca_order_id=persisted_sell_order_id,
        expected_symbol=symbol,
        expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
        replacement_chain=replacement_chain,
    ):
        return "attached managed sell identity could not be verified for cancellation"

    current_orders = {
        order_id: order for order in replacement_chain if (order_id := _optional_str(order.get("id"))) is not None
    }
    historical_leaves: dict[str, dict] = {}
    historical_issue: str | None = None
    try:
        _, historical_leaves, historical_intent_issues = _historical_managed_sell_lineages(
            conn=conn,
            client=client,
            position=position,
            current_orders=current_orders,
            expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
        )
        if historical_intent_issues:
            historical_issue = "; ".join(historical_intent_issues)
    except (requests.RequestException, SellOrderIdentityError, RuntimeError, ValueError) as exc:
        historical_issue = _alpaca_client_exception_diagnostic(exc, client=client)

    active_leaves = _active_managed_sell_leaves(_deduplicated_managed_sell_leaves(replacement_chain, historical_leaves))
    if not active_leaves:
        message = "all strictly attributed managed sell leaves are inactive"
        if historical_issue is not None:
            message += f"; historical sell audit requires review: {historical_issue}"
        return message

    current = _managed_position_snapshot(conn, position_id)
    if (
        current is None
        or _optional_str(current.get("closed_at")) is not None
        or int(current.get("state_revision", -1)) != expected_state_revision
        or (_optional_str(current.get("buy_status")) or "").lower() != expected_buy_status.lower()
        or _optional_str(current.get("sell_client_order_id")) != sell_client_order_id
        or _optional_str(current.get("sell_alpaca_order_id")) != persisted_sell_order_id
    ):
        return "attached managed sell cancellation was not requested because the quarantined premise changed"

    filled_qty = _optional_float(current.get("filled_qty"))
    filled_avg_price = _optional_float(current.get("filled_avg_price"))
    target_sell_price = _optional_float(current.get("target_sell_price"))
    sell_renewal_count = _optional_int(current.get("sell_renewal_count"))
    if filled_qty is None or filled_avg_price is None or target_sell_price is None or sell_renewal_count is None:
        return "attached managed sell cancellation requires complete persisted parent accounting"
    remaining_qty = _managed_remaining_qty(current, filled_qty)
    cancellation_snapshot = _managed_sell_replacement_snapshot_if_current(
        conn,
        position_id=position_id,
        sell_client_order_id=sell_client_order_id,
        sell_alpaca_order_id=persisted_sell_order_id,
        sell_renewal_requested_at=_optional_str(current.get("sell_renewal_requested_at")),
        expected_buy_status=expected_buy_status,
        expected_buy_filled_qty=filled_qty,
        expected_buy_filled_avg_price=filled_avg_price,
        expected_target_sell_price=target_sell_price,
        expected_remaining_qty=remaining_qty,
        expected_sell_status=_optional_str(current.get("sell_status")),
        expected_sell_renewal_count=sell_renewal_count,
    )
    if cancellation_snapshot is None:
        return "attached managed sell cancellation was not requested because its exact state could not be fenced"
    if cancellation_snapshot.state_revision != expected_state_revision:
        return "attached managed sell cancellation was not requested because its exact state changed"

    cancellation_requested_at = _utc_now().isoformat().replace("+00:00", "Z")
    cancellation_owned = update_alpaca_managed_sell_status_if_current(
        conn,
        position_id,
        expected_sell_client_order_id=sell_client_order_id,
        **_renewal_snapshot_cas_kwargs(cancellation_snapshot),
        sell_status="pending_cancel",
        sell_alpaca_order_id=_optional_str(replacement_chain[-1].get("id")),
        sell_renewal_requested_at=cancellation_requested_at,
        notes=_alpaca_durable_diagnostic_note(
            "managed buy has no authoritative opening fill; attached sell cancellation ownership "
            "was fenced before broker requests",
            cfg=client.cfg,
            client=client,
        ),
    )
    if not cancellation_owned:
        return "attached managed sell cancellation was not requested because its exact state changed"

    _pending, cancellation_messages = _request_managed_sell_leaf_cancellations(
        client,
        active_leaves,
    )
    message = "unsafe attributed managed sell cancellations require confirmation; " + "; ".join(cancellation_messages)
    if historical_issue is not None:
        message += f"; historical sell audit requires review: {historical_issue}"
    return message


def _active_filled_buy_correction_audit_due(position: dict) -> bool:
    """Keep authoritative rechecks bounded to Alpaca's practical correction window."""
    persisted_filled_qty = _optional_float(position.get("filled_qty"))
    if persisted_filled_qty is None or persisted_filled_qty <= 0.0:
        return False
    audit_anchor = (
        _parse_alpaca_datetime(position.get("filled_at"))
        or _parse_alpaca_datetime(position.get("buy_submitted_at"))
        or _parse_alpaca_datetime(position.get("created_at"))
    )
    # Missing broker fill time must not silently disable correction auditing.
    # An entirely timestamp-less legacy row is audited conservatively.
    return audit_anchor is None or audit_anchor >= _utc_now() - timedelta(days=_CLOSED_POSITION_CORRECTION_AUDIT_DAYS)


def _audit_recently_closed_managed_position(
    *,
    conn: sqlite3.Connection,
    client: AlpacaClient,
    rows: list[dict],
    position: dict,
) -> None:
    """Re-read authoritative fills while Alpaca can still correct a closed trade."""
    position_id = int(position["id"])
    symbol = str(position["symbol"])
    buy_client_order_id = str(position["buy_client_order_id"])
    sell_client_order_id = _optional_str(position.get("sell_client_order_id"))
    persisted_asset_id = _optional_str(position.get("alpaca_asset_id"))
    accepted_asset_ids = frozenset(alpaca_managed_position_asset_ids(position))
    tracked_buy_cancellation_ids = _managed_buy_followup_order_ids(position)
    tracked_buy_resolution_issues: list[str] = []
    tracked_buy_lineages: list[list[dict]] = []
    if tracked_buy_cancellation_ids:
        tracked_buy_lineages, buy_accounting_orders, tracked_buy_resolution_issues = (
            _fetch_durable_buy_cancellation_lineages(
                client,
                tracked_buy_cancellation_ids,
                expected_client_order_id=buy_client_order_id,
                expected_symbol=symbol,
                expected_alpaca_asset_id=persisted_asset_id,
                accepted_alpaca_asset_ids=accepted_asset_ids,
            )
        )
        if not tracked_buy_lineages:
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="closed_audit",
                status=str(position.get("buy_status") or "submission_unknown").lower(),
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=None,
                limit_price=None,
                alpaca_order_id=None,
                message=(
                    "no durably tracked accepted buy could be refreshed and strictly attributed; "
                    + "; ".join(tracked_buy_resolution_issues)
                ),
                required_failure=True,
            )
            return
        persisted_buy_order_id = _optional_str(position.get("buy_alpaca_order_id"))
        buy_replacement_chain = next(
            (
                lineage
                for lineage in tracked_buy_lineages
                if persisted_buy_order_id in {_optional_str(order.get("id")) for order in lineage}
            ),
            tracked_buy_lineages[0],
        )
        buy_order = buy_replacement_chain[-1]
    else:
        buy_order, buy_replacement_chain = _fetch_order_payload(
            client,
            _optional_str(position.get("buy_alpaca_order_id")),
            buy_client_order_id,
        )
        buy_accounting_orders = buy_replacement_chain
    chain_asset_ids = [_optional_str(node.get("asset_id")) for node in buy_accounting_orders]
    observed_asset_ids = {asset_id for asset_id in chain_asset_ids if asset_id is not None}
    if any(asset_id is None for asset_id in chain_asset_ids) or len(observed_asset_ids) != 1:
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="closed_audit",
            status="identity_mismatch",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=None,
            limit_price=None,
            alpaca_order_id=_optional_str(buy_order.get("id")),
            message="recently closed buy replacement chain has a missing or inconsistent stable asset ID",
            required_failure=True,
        )
        return
    observed_asset_id = next(iter(observed_asset_ids))
    if persisted_asset_id is not None and observed_asset_id not in accepted_asset_ids:
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="closed_audit",
            status="identity_mismatch",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=None,
            limit_price=None,
            alpaca_order_id=_optional_str(buy_order.get("id")),
            message="recently closed buy stable asset ID conflicts with immutable managed state",
            required_failure=True,
        )
        return
    if (
        persisted_asset_id is None
        and _safely_attributed_buy_order_lineage(
            buy_order,
            expected_client_order_id=buy_client_order_id,
            expected_symbol=symbol,
            expected_alpaca_asset_id=None,
            expected_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
            replacement_chain=buy_replacement_chain,
        )
        is None
    ):
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="closed_audit",
            status="identity_mismatch",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=None,
            limit_price=None,
            alpaca_order_id=_optional_str(buy_order.get("id")),
            message=(
                "recently closed legacy buy stable asset was not adopted because immutable "
                "core order identity could not be proven"
            ),
            required_failure=True,
        )
        return
    expected_asset_id = observed_asset_id
    buy_root = buy_replacement_chain[0]
    persisted_buy_order_qty = _optional_positive_float(position.get("buy_order_qty"))
    persisted_buy_order_limit_price = _optional_positive_float(position.get("buy_order_limit_price"))
    expected_buy_qty = persisted_buy_order_qty or _optional_positive_float(buy_root.get("qty"))
    expected_buy_limit_price = persisted_buy_order_limit_price or _optional_positive_float(buy_root.get("limit_price"))
    persisted_buy_status = str(position.get("buy_status") or "").lower()
    persisted_buy_intent_quarantined = persisted_buy_status in {
        "pending_cancel",
        "identity_mismatch",
    }
    representative_buy_identity_issue = _buy_order_identity_issue(
        buy_order,
        expected_client_order_id=buy_client_order_id,
        expected_symbol=symbol,
        expected_alpaca_asset_id=expected_asset_id,
        expected_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
        expected_qty=expected_buy_qty,
        expected_limit_price=expected_buy_limit_price,
        replacement_chain=buy_replacement_chain,
        require_expected_intent=True,
    )
    tracked_buy_economics_issue = (
        _tracked_buy_lineages_intent_issue(
            tracked_buy_lineages,
            expected_client_order_id=buy_client_order_id,
            expected_symbol=symbol,
            expected_alpaca_asset_id=expected_asset_id,
            accepted_alpaca_asset_ids=accepted_asset_ids,
            expected_qty=expected_buy_qty,
            expected_limit_price=expected_buy_limit_price,
        )
        if tracked_buy_cancellation_ids
        else None
    )
    tracked_buy_economics_mismatch = tracked_buy_economics_issue is not None
    buy_identity_issues = list(
        dict.fromkeys(
            issue
            for issue in (
                representative_buy_identity_issue,
                tracked_buy_economics_issue,
            )
            if issue is not None
        )
    )
    buy_identity_issue = "; ".join(buy_identity_issues) if buy_identity_issues else None
    attributed_intent_mismatch = bool(
        buy_identity_issue is not None
        and _buy_identity_issue_is_attributable_cancellation_issue(buy_identity_issue)
        and _safely_attributed_buy_order_lineage(
            buy_order,
            expected_client_order_id=buy_client_order_id,
            expected_symbol=symbol,
            expected_alpaca_asset_id=expected_asset_id,
            expected_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
            replacement_chain=buy_replacement_chain,
        )
        is not None
    )
    if buy_identity_issue is not None and not attributed_intent_mismatch:
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="closed_audit",
            status="identity_mismatch",
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=None,
            limit_price=None,
            alpaca_order_id=_optional_str(buy_order.get("id")),
            message=f"recently closed buy could not be audited: {buy_identity_issue}",
            required_failure=True,
        )
        return

    pending_buy_intent_issue = buy_identity_issue if attributed_intent_mismatch else None
    tracked_buy_fill_exceeds_intent = False
    retain_pending_buy_cancellation = False
    pending_buy_cancellation_message: str | None = None
    buy_has_unproven_opening_fill = False
    observed_buy_has_active_generation = any(
        _broker_order_status(node, default="unknown") in _ORDER_MAY_BE_ACTIVE_STATUSES for node in buy_accounting_orders
    )
    if (
        persisted_buy_intent_quarantined
        or attributed_intent_mismatch
        or observed_buy_has_active_generation
        or tracked_buy_resolution_issues
    ):
        attributed_buy_lineage = (
            buy_accounting_orders
            if tracked_buy_cancellation_ids
            else _safely_attributed_buy_order_lineage(
                buy_order,
                expected_client_order_id=buy_client_order_id,
                expected_symbol=symbol,
                expected_alpaca_asset_id=expected_asset_id,
                expected_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                replacement_chain=buy_replacement_chain,
            )
        )
        if attributed_buy_lineage is None:
            raise BuyOrderIdentityError("pending-cancel buy replacement lineage could not be strictly attributed")
        retain_pending_buy_cancellation = bool(
            tracked_buy_resolution_issues or _attributed_lineage_requires_cancellation(attributed_buy_lineage)
        )
        pending_buy_cancellation_message = (
            "buy cancellation ownership will be fenced by durable local quarantine before broker requests"
            if _attributed_lineage_requires_cancellation(attributed_buy_lineage)
            else "all attributed buy replacement generations are terminal"
        )
        if tracked_buy_resolution_issues:
            pending_buy_cancellation_message += "; some durably tracked accepted buys remain unresolved: " + "; ".join(
                tracked_buy_resolution_issues
            )
        if pending_buy_intent_issue is not None:
            pending_buy_cancellation_message = f"{pending_buy_intent_issue}; {pending_buy_cancellation_message}"

    buy_position_intent_issue = _buy_replacement_chain_position_intent_issue(buy_accounting_orders)
    if buy_position_intent_issue is not None:
        attributed_buy_orders = buy_accounting_orders
        compatible_buy_fill_orders = [
            node
            for node in attributed_buy_orders
            if _optional_alpaca_position_intent_matches(
                node.get("position_intent"),
                expected=_ALPACA_MANAGED_BUY_POSITION_INTENT,
            )
        ]
        cancellation_order_ids = [
            order_id
            for node in attributed_buy_orders
            if (order_id := _optional_alpaca_broker_identifier(node.get("id"))) is not None
        ]
        diagnostic_status = "pending_cancel" if retain_pending_buy_cancellation else "identity_mismatch"
        diagnostic_notes = (
            f"{buy_position_intent_issue}; broker fills with an explicit non-opening intent "
            "were excluded from managed-long accounting"
        )
        quarantine_premise_revision = int(position["state_revision"])
        exact_quarantine_owned = _quarantine_managed_buy_side_effect_from_current_snapshot(
            conn=conn,
            position_id=position_id,
            buy_status=diagnostic_status,
            observed_buy_alpaca_order_id=_optional_str(buy_order.get("id")),
            observed_buy_submitted_at=_optional_alpaca_datetime_str(buy_order.get("submitted_at")),
            notes=_alpaca_durable_diagnostic_note(
                diagnostic_notes,
                cfg=client.cfg,
                client=client,
            ),
            observed_buy_cancellation_alpaca_order_ids=cancellation_order_ids,
            required_state_revision=quarantine_premise_revision,
        )
        quarantine_persisted = exact_quarantine_owned or (
            _quarantine_managed_buy_side_effect_from_current_snapshot(
                conn=conn,
                position_id=position_id,
                buy_status=diagnostic_status,
                observed_buy_alpaca_order_id=_optional_str(buy_order.get("id")),
                observed_buy_submitted_at=_optional_alpaca_datetime_str(buy_order.get("submitted_at")),
                notes=_alpaca_durable_diagnostic_note(
                    diagnostic_notes,
                    cfg=client.cfg,
                    client=client,
                ),
                observed_buy_cancellation_alpaca_order_ids=cancellation_order_ids,
            )
        )
        cancellation_message = pending_buy_cancellation_message
        if quarantine_persisted and retain_pending_buy_cancellation:
            _, cancellation_message = _request_safely_attributed_lineage_cancellations(
                client,
                attributed_buy_orders,
            )
        elif retain_pending_buy_cancellation:
            cancellation_message = (
                "buy cancellation was not requested because durable local quarantine persistence failed"
            )
        pending_buy_cancellation_message = cancellation_message
        compatible_filled_qty = _replacement_chain_nonnegative_filled_qty(compatible_buy_fill_orders)
        compatible_opening_fill = bool(
            compatible_buy_fill_orders and compatible_filled_qty is not None and compatible_filled_qty > 0.0
        )
        if not exact_quarantine_owned:
            if quarantine_persisted:
                quarantine_message = (
                    f"{diagnostic_notes}; {cancellation_message}; "
                    "attached sell cancellation was not requested because the exact "
                    "no-opening-fill quarantine premise changed"
                )
            else:
                quarantine_message = (
                    f"{diagnostic_notes}; durable local buy quarantine persistence failed and requires retry"
                )
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="closed_audit",
                status="superseded",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=None,
                limit_price=None,
                alpaca_order_id=_optional_str(buy_order.get("id")),
                message=quarantine_message,
                required_failure=True,
            )
            return
        expected_quarantine_revision = quarantine_premise_revision + 1
        quarantined_position = _managed_position_snapshot(conn, position_id)
        if (
            quarantined_position is None
            or int(quarantined_position.get("state_revision", -1)) != expected_quarantine_revision
            or (_optional_str(quarantined_position.get("buy_status")) or "").lower() != diagnostic_status
            or _optional_str(quarantined_position.get("sell_client_order_id")) != sell_client_order_id
            or _optional_str(quarantined_position.get("closed_at")) != _optional_str(position.get("closed_at"))
        ):
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="closed_audit",
                status="superseded",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=None,
                limit_price=None,
                alpaca_order_id=_optional_str(buy_order.get("id")),
                message=(
                    f"{diagnostic_notes}; exact closed-position quarantine changed before "
                    "attached sell exposure could be audited"
                ),
                required_failure=True,
            )
            return
        position = quarantined_position
        if compatible_opening_fill:
            buy_accounting_orders = compatible_buy_fill_orders
        else:
            # The broker cannot authoritatively revise historical long
            # accounting through a non-opening order. Keep the last durable
            # economics while auditing and fencing any attached sell exposure.
            buy_has_unproven_opening_fill = True

    assert expected_buy_qty is not None
    assert expected_buy_limit_price is not None
    persisted_buy_qty = _optional_float(position.get("filled_qty")) or 0.0
    raw_observed_buy_qty = (
        persisted_buy_qty
        if buy_has_unproven_opening_fill
        else _replacement_chain_nonnegative_filled_qty(buy_accounting_orders)
    )
    exact_observed_buy_qty = (
        _optional_nonnegative_decimal(persisted_buy_qty)
        if buy_has_unproven_opening_fill
        else _replacement_chain_nonnegative_filled_qty_decimal(buy_accounting_orders)
    )
    exact_expected_buy_qty = _optional_positive_decimal(expected_buy_qty)
    tracked_buy_fill_exceeds_intent = bool(
        tracked_buy_cancellation_ids
        and exact_observed_buy_qty is not None
        and exact_expected_buy_qty is not None
        and exact_observed_buy_qty > exact_expected_buy_qty
    )
    if tracked_buy_fill_exceeds_intent:
        assert exact_observed_buy_qty is not None
        aggregate_fill_issue = (
            f"aggregate fills across independently accepted buys ({exact_observed_buy_qty}) "
            f"exceed the immutable managed buy quantity ({expected_buy_qty:g})"
        )
        pending_buy_intent_issue = "; ".join(
            dict.fromkeys(
                issue
                for issue in (
                    pending_buy_intent_issue,
                    aggregate_fill_issue,
                )
                if issue is not None
            )
        )
        if retain_pending_buy_cancellation:
            pending_buy_cancellation_message = f"{pending_buy_intent_issue}; {pending_buy_cancellation_message}"
    tracked_buy_diagnostic_mismatch = bool(tracked_buy_economics_mismatch or tracked_buy_fill_exceeds_intent)
    confirmed_zero_quantity_bust = bool(
        not buy_has_unproven_opening_fill
        and raw_observed_buy_qty is not None
        and raw_observed_buy_qty == 0.0
        and raw_observed_buy_qty < persisted_buy_qty - _managed_qty_tolerance(raw_observed_buy_qty, persisted_buy_qty)
    )
    buy_fill_issue = (
        None
        if buy_has_unproven_opening_fill
        else _buy_replacement_chain_fill_metadata_issue(
            buy_accounting_orders,
            expected_buy_qty=(
                None if pending_buy_intent_issue is not None or tracked_buy_cancellation_ids else expected_buy_qty
            ),
        )
    )
    if buy_fill_issue is not None and not confirmed_zero_quantity_bust:
        diagnostic_status = "pending_cancel" if retain_pending_buy_cancellation else "incomplete_fill_metadata"
        diagnostic_notes = buy_fill_issue
        if pending_buy_cancellation_message is not None:
            diagnostic_notes += f"; {pending_buy_cancellation_message}"
        quarantine_persisted = _quarantine_managed_buy_side_effect_from_current_snapshot(
            conn=conn,
            position_id=position_id,
            buy_status=diagnostic_status,
            observed_buy_alpaca_order_id=_optional_str(buy_order.get("id")),
            observed_buy_submitted_at=_optional_alpaca_datetime_str(buy_order.get("submitted_at")),
            notes=_alpaca_durable_diagnostic_note(
                diagnostic_notes,
                cfg=client.cfg,
                client=client,
            ),
        )
        if retain_pending_buy_cancellation:
            if quarantine_persisted:
                if tracked_buy_cancellation_ids:
                    _, cancellation_result = _request_safely_attributed_lineage_cancellations(
                        client,
                        buy_accounting_orders,
                    )
                else:
                    _, cancellation_result = _retry_pending_buy_lineage_cancellation(
                        client,
                        buy_order,
                        expected_client_order_id=buy_client_order_id,
                        expected_symbol=symbol,
                        expected_alpaca_asset_id=expected_asset_id,
                        expected_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                        replacement_chain=buy_replacement_chain,
                    )
                pending_buy_cancellation_message = cancellation_result
            else:
                pending_buy_cancellation_message = (
                    "buy cancellation was not requested because durable local quarantine persistence failed"
                )
            diagnostic_notes = f"{buy_fill_issue}; {pending_buy_cancellation_message}"
        _append_reconciliation_result(
            rows,
            position_id=position_id,
            symbol=symbol,
            action="closed_audit",
            status=diagnostic_status,
            buy_client_order_id=buy_client_order_id,
            sell_client_order_id=sell_client_order_id,
            qty=None,
            limit_price=None,
            alpaca_order_id=_optional_str(buy_order.get("id")),
            message=(
                diagnostic_notes
                if quarantine_persisted
                else (f"{diagnostic_notes}; durable local buy quarantine persistence failed and requires retry")
            ),
            required_failure=True,
        )
        return
    if buy_has_unproven_opening_fill:
        observed_buy_qty = persisted_buy_qty
        observed_buy_avg_price = _optional_float(position.get("filled_avg_price"))
    elif confirmed_zero_quantity_bust:
        assert raw_observed_buy_qty is not None
        observed_buy_qty, observed_buy_avg_price = raw_observed_buy_qty, None
    else:
        observed_buy_qty, observed_buy_avg_price, _ = _replacement_chain_fill_metadata(buy_accounting_orders)
    observed_buy_status = (
        "pending_cancel"
        if buy_has_unproven_opening_fill and retain_pending_buy_cancellation
        else "identity_mismatch"
        if buy_has_unproven_opening_fill
        else _broker_order_status(buy_order, default="unknown")
    )
    observed_buy_filled_at = (
        _optional_str(position.get("filled_at"))
        if buy_has_unproven_opening_fill
        else next(
            (
                filled_at
                for node in reversed(buy_accounting_orders)
                if (filled_at := _optional_alpaca_datetime_str(node.get("filled_at"))) is not None
            ),
            None,
        )
        if observed_buy_qty > 0.0
        else None
    )
    observed_target_price = (
        _optional_float(position.get("target_sell_price"))
        if buy_has_unproven_opening_fill
        else _target_sell_price(observed_buy_avg_price, float(position["profit_target_multiple"]))
        if observed_buy_avg_price is not None and observed_buy_qty > 0.0
        else None
    )

    observed_sell_orders: dict[str, dict] = {}
    persisted_sell_status = _optional_str(position.get("sell_status"))
    observed_sell_status = persisted_sell_status.lower() if persisted_sell_status is not None else None
    observed_sell_filled_at = _optional_str(position.get("sell_filled_at"))
    current_sell_order_id = _optional_str(position.get("sell_alpaca_order_id"))
    current_sell_order: dict | None = None
    current_sell_order_ids: set[str] = set()
    current_sell_intent_issue: str | None = None
    current_sell_expected_intent: tuple[float, float] | None = None
    if sell_client_order_id is not None:
        sell_order, sell_replacement_chain = _fetch_order_payload(
            client,
            current_sell_order_id,
            sell_client_order_id,
        )
        sell_lineage_asset_id = _replacement_chain_stable_asset_id(sell_replacement_chain)
        expected_current_sell_asset_id = persisted_asset_id or observed_asset_id
        if sell_lineage_asset_id in accepted_asset_ids:
            expected_current_sell_asset_id = sell_lineage_asset_id
        if not _sell_order_identity_is_consistent(
            sell_order,
            expected_sell_client_order_id=sell_client_order_id,
            expected_sell_alpaca_order_id=current_sell_order_id,
            expected_symbol=symbol,
            expected_alpaca_asset_id=expected_current_sell_asset_id,
            replacement_chain=sell_replacement_chain,
        ):
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="closed_audit",
                status="identity_mismatch",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=None,
                limit_price=None,
                alpaca_order_id=_optional_str(sell_order.get("id")),
                message="recently closed sell response does not match the managed asset or order generation",
                required_failure=True,
            )
            return
        current_sell_order = sell_order
        observed_sell_status = _broker_order_status(sell_order, default="unknown")
        sell_root = sell_replacement_chain[0]
        expected_sell_qty = _optional_positive_float(position.get("sell_order_qty")) or _optional_positive_float(
            sell_root.get("qty")
        )
        expected_sell_limit_price = _optional_positive_float(
            position.get("sell_order_limit_price")
        ) or _optional_positive_float(sell_root.get("limit_price"))
        if expected_sell_qty is None or expected_sell_limit_price is None:
            current_sell_intent_issue = "closed managed sell is missing its frozen submitted quantity or limit price"
        else:
            current_sell_expected_intent = (expected_sell_qty, expected_sell_limit_price)
            current_sell_intent_issue = _sell_replacement_chain_intent_issue(
                sell_replacement_chain,
                requested_qty=expected_sell_qty,
                target_sell_price=expected_sell_limit_price,
            )
        for node in sell_replacement_chain:
            order_id = _optional_str(node.get("id"))
            if order_id is not None:
                observed_sell_orders[order_id] = node
                current_sell_order_ids.add(order_id)

    historical_sell_audit_issue: str | None = None
    try:
        observed_sell_orders, _historical_sell_leaves, historical_sell_intent_issues = (
            _historical_managed_sell_lineages(
                conn=conn,
                client=client,
                position=position,
                current_orders=observed_sell_orders,
                expected_alpaca_asset_id=expected_asset_id,
            )
        )
    except SellOrderIdentityError as exc:
        if not buy_has_unproven_opening_fill:
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="closed_audit",
                status="identity_mismatch",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=None,
                limit_price=None,
                alpaca_order_id=None,
                message=str(exc),
                required_failure=True,
            )
            return
        # A failed historical identity proof must never make that payload
        # cancellable, but it also must not strand an independently verified
        # current sell after the managed buy lost opening attribution.
        historical_sell_intent_issues = []
        historical_sell_audit_issue = _alpaca_client_exception_diagnostic(exc, client=client)
    except (requests.RequestException, RuntimeError, ValueError) as exc:
        if not buy_has_unproven_opening_fill:
            raise
        historical_sell_intent_issues = []
        historical_sell_audit_issue = _alpaca_client_exception_diagnostic(exc, client=client)

    persisted_sell_order_intents = alpaca_managed_sell_generation_intents(conn, position_id)
    # Alpaca-created replacement successors are first discovered during this
    # audit.  Carry forward the immutable economics from any connected root;
    # never derive them from the successor's mutable current payload.
    observed_sell_order_intents = _observed_sell_generation_intents(
        observed_orders=observed_sell_orders,
        persisted_intents=persisted_sell_order_intents,
        current_order_ids=current_sell_order_ids,
        current_intent=current_sell_expected_intent,
    )

    authoritative_sell_fills: list[tuple[str, float, float]] = []
    authoritative_sell_fill_updated_at: dict[str, str | None] = {}
    current_sell_fill_times: list[tuple[datetime, str]] = []
    observed_sold_qty = 0.0
    observed_sold_value = 0.0
    persisted_sell_fills = alpaca_managed_sell_fill_observations(conn, position_id)
    for order_id, order in observed_sell_orders.items():
        if buy_has_unproven_opening_fill or _sell_replacement_chain_position_intent_issue([order]) is not None:
            # Neither an explicitly non-closing sell nor a sell whose parent
            # has lost managed-long attribution can authoritatively revise the
            # realized ledger. Preserve durable accounting while the strictly
            # attributed active lineage is fenced and canceled.
            persisted_sell_qty, persisted_sell_value = persisted_sell_fills.get(
                order_id,
                (0.0, 0.0),
            )
            authoritative_sell_fills.append((order_id, persisted_sell_qty, persisted_sell_value))
            authoritative_sell_fill_updated_at[order_id] = _optional_alpaca_datetime_str(order.get("updated_at"))
            observed_sold_qty += persisted_sell_qty
            observed_sold_value += persisted_sell_value
            continue
        raw_sell_qty = _replacement_chain_nonnegative_filled_qty([order])
        sell_qty, sell_avg_price, metadata_is_valid = _sell_fill_metadata(order)
        if raw_sell_qty is None or not metadata_is_valid:
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="closed_audit",
                status="incomplete_fill_metadata",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=sell_qty,
                limit_price=_optional_float(position.get("target_sell_price")),
                alpaca_order_id=order_id,
                message="recently closed sell has incomplete corrected fill metadata",
                required_failure=True,
            )
            return
        authoritative_sell_fill_updated_at[order_id] = _optional_alpaca_datetime_str(order.get("updated_at"))
        if sell_qty > 0.0:
            assert sell_avg_price is not None
            sell_value = sell_qty * sell_avg_price
            next_sold_qty = observed_sold_qty + sell_qty
            next_sold_value = observed_sold_value + sell_value
            if not all(isfinite(value) for value in (sell_value, next_sold_qty, next_sold_value)):
                _append_reconciliation_result(
                    rows,
                    position_id=position_id,
                    symbol=symbol,
                    action="closed_audit",
                    status="incomplete_fill_metadata",
                    buy_client_order_id=buy_client_order_id,
                    sell_client_order_id=sell_client_order_id,
                    qty=sell_qty,
                    limit_price=_optional_float(position.get("target_sell_price")),
                    alpaca_order_id=order_id,
                    message="recently closed sell has non-finite aggregate fill accounting",
                    required_failure=True,
                )
                return
            authoritative_sell_fills.append((order_id, sell_qty, sell_value))
            observed_sold_qty = next_sold_qty
            observed_sold_value = next_sold_value
            filled_at = _optional_alpaca_datetime_str(order.get("filled_at"))
            parsed_filled_at = _parse_alpaca_broker_datetime(filled_at)
            if order_id in current_sell_order_ids and filled_at is not None and parsed_filled_at is not None:
                current_sell_fill_times.append((parsed_filled_at, filled_at))
        else:
            # Keep zeroed historical generations discoverable if Alpaca later
            # reinstates or otherwise corrects their fill.
            authoritative_sell_fills.append((order_id, 0.0, 0.0))

    if current_sell_fill_times:
        observed_sell_filled_at = max(current_sell_fill_times, key=lambda item: item[0])[1]
    elif observed_sold_qty == 0.0:
        observed_sell_filled_at = None
    remaining_qty = observed_buy_qty - observed_sold_qty
    current_sell_open_qty: float | None = None
    current_sell_may_be_active = bool(
        current_sell_order is not None and observed_sell_status in _ORDER_MAY_BE_ACTIVE_STATUSES
    )
    current_sell_leaf_id = _optional_str(current_sell_order.get("id")) if current_sell_order is not None else None
    unexpected_active_current_orders = [
        order
        for order_id, order in observed_sell_orders.items()
        if order_id in current_sell_order_ids
        and order_id != current_sell_leaf_id
        and _broker_order_status(order) in _ORDER_MAY_BE_ACTIVE_STATUSES
    ]
    if current_sell_may_be_active:
        current_order_qty = _optional_positive_float(current_sell_order.get("qty"))
        current_order_filled_qty = _sell_fill_metadata(current_sell_order)[0]
        if current_order_qty is not None:
            current_sell_open_qty = max(current_order_qty - current_order_filled_qty, 0.0)
    residual_mark_price = max(
        observed_buy_avg_price or 0.0,
        _optional_positive_float(position.get("buy_order_limit_price")) or 0.0,
        _optional_positive_float(position.get("target_sell_price")) or 0.0,
        _optional_positive_float(position.get("sell_order_limit_price")) or 0.0,
        observed_sold_value / observed_sold_qty if observed_sold_qty > 0.0 else 0.0,
    )
    active_sell_residual = bool(
        current_sell_may_be_active
        and (
            current_sell_open_qty is None
            or (
                current_sell_open_qty > max(remaining_qty, 0.0)
                and not _managed_sell_quantities_match(
                    current_sell_open_qty,
                    max(remaining_qty, 0.0),
                    mark_price=residual_mark_price,
                )
            )
        )
    )
    active_historical_sell_orders = [
        order
        for order_id, order in observed_sell_orders.items()
        if order_id not in current_sell_order_ids and _broker_order_status(order) in _ORDER_MAY_BE_ACTIVE_STATUSES
    ]
    historical_sell_intent_issue = "; ".join(historical_sell_intent_issues) if historical_sell_intent_issues else None
    sell_intent_issue = current_sell_intent_issue or historical_sell_intent_issue
    dangerous_closed_sell = bool(
        (
            current_sell_may_be_active
            and (buy_has_unproven_opening_fill or active_sell_residual or current_sell_intent_issue is not None)
        )
        or unexpected_active_current_orders
        or active_historical_sell_orders
    )
    persisted_buy_avg = _optional_float(position.get("filled_avg_price"))
    persisted_sold_qty = _optional_float(position.get("sold_qty")) or 0.0
    persisted_sold_value = _optional_float(position.get("sold_value")) or 0.0
    buy_price_changed = (persisted_buy_avg is None) != (observed_buy_avg_price is None) or (
        persisted_buy_avg is not None
        and observed_buy_avg_price is not None
        and abs(persisted_buy_avg - observed_buy_avg_price) > _MANAGED_PRICE_TOLERANCE
    )
    buy_quantity_changed = not _managed_sell_quantities_match(
        persisted_buy_qty,
        observed_buy_qty,
        mark_price=residual_mark_price,
    )
    sold_quantity_changed = not _managed_sell_quantities_match(
        persisted_sold_qty,
        observed_sold_qty,
        mark_price=residual_mark_price,
    )
    correction_detected = bool(
        buy_quantity_changed
        or buy_price_changed
        or sold_quantity_changed
        or abs(persisted_sold_value - observed_sold_value)
        > _managed_value_tolerance(persisted_sold_value, observed_sold_value)
        or persisted_asset_id is None
        or persisted_buy_order_qty is None
        or persisted_buy_order_limit_price is None
        or not _managed_sell_is_complete(
            remaining_qty,
            observed_buy_qty,
            observed_sold_qty,
            mark_price=residual_mark_price,
        )
        or sell_intent_issue is not None
        or active_sell_residual
        or unexpected_active_current_orders
        or active_historical_sell_orders
        or persisted_buy_intent_quarantined
        or retain_pending_buy_cancellation
        or tracked_buy_diagnostic_mismatch
        or buy_has_unproven_opening_fill
        or (
            pending_buy_intent_issue is not None
            and persisted_buy_status in {"submission_unknown", "incomplete_fill_metadata"}
        )
    )
    if not correction_detected:
        return

    positive_shortfall = _managed_sell_has_shortfall(
        remaining_qty,
        observed_buy_qty,
        observed_sold_qty,
        mark_price=residual_mark_price,
    )
    negative_quantity_mismatch = _managed_sell_is_overfilled(
        remaining_qty,
        observed_buy_qty,
        observed_sold_qty,
        mark_price=residual_mark_price,
    )
    closed_sell_shortfall = sell_client_order_id is not None and positive_shortfall
    dangerous_closed_buy = retain_pending_buy_cancellation
    corrected_buy_status = (
        "pending_cancel"
        if dangerous_closed_buy
        else "identity_mismatch"
        if buy_has_unproven_opening_fill
        or (pending_buy_intent_issue is not None and (positive_shortfall or tracked_buy_diagnostic_mismatch))
        else "fill_quantity_regression"
        if observed_buy_qty < persisted_buy_qty and buy_quantity_changed
        else observed_buy_status
    )
    cancellation_orders: list[dict] = []
    if current_sell_may_be_active and (
        buy_has_unproven_opening_fill or active_sell_residual or current_sell_intent_issue is not None
    ):
        assert current_sell_order is not None
        cancellation_orders.append(current_sell_order)
    cancellation_orders.extend(unexpected_active_current_orders)
    cancellation_orders.extend(active_historical_sell_orders)
    cancellation_pending = bool(cancellation_orders)
    cancellation_has_executable_order = any(
        (order_qty := _optional_positive_float(order.get("qty"))) is None
        or max(order_qty - _sell_fill_metadata(order)[0], 0.0) > 0.0
        for order in cancellation_orders
    )
    cancellation_requested_at = _utc_now().isoformat().replace("+00:00", "Z") if cancellation_orders else None
    cancellation_message = (
        "sell cancellation ownership will be fenced by the closed-position correction" if cancellation_orders else None
    )
    corrected_sell_status = (
        "position_quantity_mismatch"
        if negative_quantity_mismatch
        else "pending_cancel"
        if dangerous_closed_sell and cancellation_pending
        else "quantity_mismatch"
        if (
            sell_intent_issue is not None
            or active_sell_residual
            or unexpected_active_current_orders
            or active_historical_sell_orders
        )
        else observed_sell_status
    )
    correction_notes = (
        (
            "authoritative closed-position audit invalidated the managed-long attribution; "
            "historical buy accounting was preserved and active attributed sells were fenced "
            "before broker requests"
        )
        if buy_has_unproven_opening_fill
        else (
            "authoritative closed-position audit found a still-active pending-cancel buy; "
            f"{pending_buy_cancellation_message or 'cancellation could not be requested'}"
        )
        if dangerous_closed_buy
        else (
            "authoritative closed-position audit found independently accepted buy lineages "
            "conflicting with immutable economics or aggregate exposure; accounting remains "
            "quarantined for review"
        )
        if tracked_buy_diagnostic_mismatch
        else (
            "authoritative closed-position audit found a live managed sell with unsafe residual exposure; "
            "cancellation ownership was fenced before broker requests"
        )
        if dangerous_closed_sell
        else _CLOSED_SELL_SHORTFALL_REOPEN_NOTE
        if closed_sell_shortfall
        else (
            "authoritative Alpaca re-audit changed a recently closed position's buy or sell fills; "
            "the position was reopened for protective reconciliation"
            if positive_shortfall or negative_quantity_mismatch
            else "authoritative Alpaca re-audit corrected realized fill prices for a closed position"
        )
    )
    if historical_sell_audit_issue is not None:
        correction_notes += f"; historical sell audit requires review: {historical_sell_audit_issue}"
    durable_correction_notes = _alpaca_durable_diagnostic_note(
        correction_notes,
        cfg=client.cfg,
        client=client,
    )
    assert durable_correction_notes is not None
    applied, reopened, active_conflict, corrected_remaining_qty = apply_alpaca_closed_position_broker_correction(
        conn,
        position_id,
        expected_closed_at=str(position["closed_at"]),
        expected_state_revision=int(position["state_revision"]),
        alpaca_asset_id=observed_asset_id,
        buy_order_qty=expected_buy_qty,
        buy_order_limit_price=expected_buy_limit_price,
        buy_status=corrected_buy_status,
        filled_qty=observed_buy_qty,
        filled_avg_price=observed_buy_avg_price,
        filled_at=observed_buy_filled_at,
        target_sell_price=observed_target_price,
        sell_status=corrected_sell_status,
        sell_fills=authoritative_sell_fills,
        sell_order_intents=observed_sell_order_intents,
        sell_renewal_requested_at=cancellation_requested_at,
        sell_filled_at=observed_sell_filled_at,
        notes=durable_correction_notes,
        buy_fill_broker_updated_at=(
            _STORAGE_UNSET
            if buy_has_unproven_opening_fill
            else _replacement_chain_latest_broker_updated_at(buy_accounting_orders)
        ),
        buy_fill_broker_oldest_updated_at=(
            _STORAGE_UNSET
            if buy_has_unproven_opening_fill
            else _replacement_chain_oldest_broker_updated_at(buy_accounting_orders)
        ),
        buy_fill_component_revisions=(
            _STORAGE_UNSET
            if buy_has_unproven_opening_fill
            else _replacement_chain_broker_component_revisions(buy_accounting_orders)
        ),
        sell_fill_broker_updated_at=authoritative_sell_fill_updated_at,
        current_sell_leaf_alpaca_order_id=current_sell_leaf_id,
        current_sell_leaf_status=observed_sell_status,
        current_sell_lineage_alpaca_order_ids=sorted(current_sell_order_ids),
        sell_cancellation_alpaca_order_ids=[
            order_id for order in cancellation_orders if (order_id := _optional_str(order.get("id"))) is not None
        ],
        closed_sell_shortfall_reopen_pending=closed_sell_shortfall,
        force_reopen_buy=dangerous_closed_buy,
        force_reopen_sell=dangerous_closed_sell,
    )
    if dangerous_closed_buy:
        if applied:
            if tracked_buy_cancellation_ids:
                _, pending_buy_cancellation_message = _request_safely_attributed_lineage_cancellations(
                    client,
                    buy_accounting_orders,
                )
            else:
                cancellation_ids = [
                    order_id
                    for node in buy_replacement_chain
                    if (order_id := _optional_alpaca_broker_identifier(node.get("id"))) is not None
                ]
                quarantine_owned = _quarantine_managed_buy_side_effect_from_current_snapshot(
                    conn=conn,
                    position_id=position_id,
                    buy_status="pending_cancel",
                    observed_buy_alpaca_order_id=_optional_alpaca_broker_identifier(buy_order.get("id")),
                    observed_buy_submitted_at=_optional_alpaca_datetime_str(buy_order.get("submitted_at")),
                    notes=durable_correction_notes,
                    observed_buy_cancellation_alpaca_order_ids=cancellation_ids,
                )
                if quarantine_owned:
                    _, pending_buy_cancellation_message = _retry_pending_buy_lineage_cancellation(
                        client,
                        buy_order,
                        expected_client_order_id=buy_client_order_id,
                        expected_symbol=symbol,
                        expected_alpaca_asset_id=expected_asset_id,
                        expected_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                        replacement_chain=buy_replacement_chain,
                    )
                else:
                    pending_buy_cancellation_message = (
                        "buy cancellation was not requested because every canonical lineage ID could not be "
                        "durably retained"
                    )
        else:
            pending_buy_cancellation_message = (
                "buy cancellation was not requested because the closed-position correction was superseded"
            )
    if applied and cancellation_orders:
        cancellation_pending, cancellation_messages = _request_managed_sell_leaf_cancellations(
            client,
            cancellation_orders,
        )
        cancellation_message = "; ".join(cancellation_messages)
    elif not applied and cancellation_orders:
        cancellation_message = (
            "sell cancellation was not requested because the closed-position correction was superseded"
        )
    if historical_sell_audit_issue is not None:
        historical_message = f"historical sell audit requires review: {historical_sell_audit_issue}"
        cancellation_message = (
            f"{cancellation_message}; {historical_message}" if cancellation_message else historical_message
        )
    status = (
        "position_quantity_mismatch"
        if negative_quantity_mismatch or active_conflict
        else "identity_mismatch"
        if buy_has_unproven_opening_fill or tracked_buy_diagnostic_mismatch
        else "pending_cancel"
        if dangerous_closed_buy or (dangerous_closed_sell and cancellation_pending)
        else "quantity_mismatch"
        if (
            sell_intent_issue is not None
            or active_sell_residual
            or unexpected_active_current_orders
            or active_historical_sell_orders
        )
        else "reopened"
        if positive_shortfall and reopened
        else "corrected"
    )
    _append_reconciliation_result(
        rows,
        position_id=position_id,
        symbol=symbol,
        action="closed_audit",
        status=status if applied else "superseded",
        buy_client_order_id=buy_client_order_id,
        sell_client_order_id=sell_client_order_id,
        qty=observed_buy_qty,
        limit_price=observed_target_price,
        alpaca_order_id=_optional_str(buy_order.get("id")),
        message=(
            "broker correction conflicts with a newer active managed position; corrected accounting remains closed"
            if applied and active_conflict
            else (
                (
                    "broker audit reopened the position after managed-long attribution was invalidated; "
                    "historical buy accounting was preserved and attributed sell exposure was fenced; "
                    f"{cancellation_message or 'cancellation requires review'}"
                    if buy_has_unproven_opening_fill
                    else "broker audit reopened the position to quarantine an active pending-cancel buy; "
                    f"{pending_buy_cancellation_message or 'cancellation requires review'}"
                    if dangerous_closed_buy
                    else (
                        "broker audit reopened the position to quarantine a live residual sell; "
                        f"{cancellation_message or 'cancellation requires review'}"
                    )
                    if dangerous_closed_sell
                    else f"broker correction reopened the position with {corrected_remaining_qty:g} shares remaining"
                )
                if applied and reopened
                else (
                    "broker correction retained a duplicate-buy economics or aggregate-exposure "
                    "mismatch for manual review"
                )
                if applied and tracked_buy_diagnostic_mismatch
                else "broker correction updated closed-position realized P/L"
                if applied
                else "closed-position correction was superseded by concurrent managed state"
            )
        ),
        # A successfully reopened position is reconciled again in the active
        # pass below.  Let that pass decide whether protection succeeded;
        # retaining a required failure here would report a failure even after
        # the uncovered shares were protected in this same invocation.
        required_failure=bool(
            (
                not applied
                and (
                    buy_has_unproven_opening_fill
                    or cancellation_has_executable_order
                    or dangerous_closed_buy
                    or positive_shortfall
                    or negative_quantity_mismatch
                    or tracked_buy_diagnostic_mismatch
                )
            )
            or (
                applied
                and (
                    active_conflict
                    or negative_quantity_mismatch
                    or (positive_shortfall and not reopened)
                    or dangerous_closed_buy
                    or (sell_intent_issue is not None and not (dangerous_closed_sell and reopened))
                    or tracked_buy_diagnostic_mismatch
                    or buy_has_unproven_opening_fill
                )
            )
        ),
    )


def _reconcile_alpaca_managed_positions_pass(
    conn: sqlite3.Connection,
    cfg: AlpacaOrderConfig,
    *,
    audit_closed: bool,
    skip_active_position_ids: frozenset[int] = frozenset(),
    order_snapshot: _ReconciliationOrderSnapshot | None = None,
) -> pd.DataFrame:
    columns = [
        "Position ID",
        "Workflow",
        "Asset",
        "Action",
        "Status",
        "Buy Client Order ID",
        "Sell Client Order ID",
        "Qty",
        "Limit Price",
        "Alpaca Order ID",
        "Message",
    ]
    if not (cfg.enabled or cfg.sell_enabled):
        return pd.DataFrame(columns=columns)
    sensitive_values = _alpaca_config_sensitive_values(cfg)

    positions = load_alpaca_managed_positions(conn, active_only=True)
    if skip_active_position_ids:
        positions = positions.loc[~positions["id"].isin(skip_active_position_ids)].reset_index(drop=True)
    recently_closed_positions = (
        load_recently_closed_alpaca_managed_positions(
            conn,
            audit_days=_CLOSED_POSITION_CORRECTION_AUDIT_DAYS,
            audit_limit=_CLOSED_POSITION_CORRECTION_AUDIT_LIMIT,
        )
        if audit_closed
        else pd.DataFrame()
    )
    if skip_active_position_ids and not recently_closed_positions.empty:
        recently_closed_positions = recently_closed_positions.loc[
            ~recently_closed_positions["id"].isin(skip_active_position_ids)
        ].reset_index(drop=True)
    if positions.empty and recently_closed_positions.empty:
        return pd.DataFrame(columns=columns)
    reconciliation_candidates = pd.concat(
        [positions, recently_closed_positions],
        ignore_index=True,
    )
    workflow_by_position_id = {
        int(position["id"]): _optional_str(position.get("workflow"))
        for position in reconciliation_candidates.to_dict("records")
    }
    managed_equity_scope_asset_ids = frozenset(
        asset_id
        for position in reconciliation_candidates.to_dict("records")
        if (asset_id := _optional_alpaca_broker_identifier(position.get("alpaca_asset_id"))) is not None
    )

    client = AlpacaClient(
        cfg,
        equity_scope_asset_ids=managed_equity_scope_asset_ids,
    )
    sensitive_values = _merged_alpaca_sensitive_values(
        sensitive_values,
        _alpaca_client_sensitive_values(client),
    )
    order_snapshot = order_snapshot or _ReconciliationOrderSnapshot()
    tracked_order_ids = {
        order_id
        for position in reconciliation_candidates.to_dict("records")
        for value in (
            position.get("buy_alpaca_order_id"),
            position.get("sell_alpaca_order_id"),
        )
        if (order_id := _optional_alpaca_broker_identifier(value)) is not None
    }
    snapshot_candidate_count = (
        len(recently_closed_positions)
        if audit_closed
        else sum(
            _optional_alpaca_broker_identifier(position.get("sell_alpaca_order_id")) is not None
            for position in positions.to_dict("records")
        )
    )
    if (
        snapshot_candidate_count >= _ALPACA_RECONCILIATION_ORDER_SNAPSHOT_THRESHOLD
        and len(tracked_order_ids) >= _ALPACA_RECONCILIATION_ORDER_SNAPSHOT_THRESHOLD
        and not order_snapshot.attempted
    ):
        order_snapshot.attempted = True
        try:
            account_orders = client.all_orders()
            if not isinstance(account_orders, list):
                raise TypeError("Alpaca all-orders snapshot must be a list.")
        except Exception:
            # An old closed order can make the all-orders validation fail even
            # when current open orders are usable. Preserve the active-sell
            # fast path before falling back to exact lookups.
            try:
                account_orders = client.open_orders()
                if not isinstance(account_orders, list):
                    raise TypeError("Alpaca open-orders snapshot must be a list.")
            except Exception:
                account_orders = []
        order_snapshot.orders_by_id = {
            order_id: order
            for order in account_orders
            if (order_id := _optional_alpaca_broker_identifier(order.get("id"))) is not None
        }
    if order_snapshot.orders_by_id is not None:
        client._reconciliation_order_payloads = order_snapshot.orders_by_id

    def durable_note(value: str | None) -> str | None:
        return _alpaca_durable_diagnostic_note(
            value,
            cfg=cfg,
            sensitive_values=sensitive_values,
            client=client,
        )

    rows = []
    retained_retry_handled_ids: set[int] = set()
    for closed_position in recently_closed_positions.to_dict("records"):
        position_id = int(closed_position["id"])
        symbol = str(closed_position["symbol"])
        buy_client_order_id = str(closed_position["buy_client_order_id"])
        sell_client_order_id = _optional_str(closed_position.get("sell_client_order_id"))
        audit_row_start = len(rows)
        audit_completed = False
        try:
            if _reconcile_retained_sell_submission_quarantine(
                conn=conn,
                client=client,
                rows=rows,
                position=closed_position,
            ):
                retained_retry_handled_ids.add(position_id)
                audit_completed = not any(bool(row.get("_Required Failure")) for row in rows[audit_row_start:])
                continue
            _audit_recently_closed_managed_position(
                conn=conn,
                client=client,
                rows=rows,
                position=closed_position,
            )
            audit_completed = not any(bool(row.get("_Required Failure")) for row in rows[audit_row_start:])
            # A zero-fill closed buy can be reopened solely to retain ownership
            # while cancellation is unresolved.  Its full lineage was already
            # refreshed and canceled above; avoid issuing the same DELETEs a
            # second time in this invocation.  The next scheduled active pass
            # will retry if Alpaca still reports executable exposure.
            reopened_zero_fill_quarantine = conn.execute(
                """
                SELECT 1
                FROM alpaca_managed_positions
                WHERE id = ?
                  AND closed_at IS NULL
                  AND LOWER(buy_status) = 'pending_cancel'
                  AND filled_qty IS NULL
                """,
                (position_id,),
            ).fetchone()
            if reopened_zero_fill_quarantine is not None:
                retained_retry_handled_ids.add(position_id)
        except HTTPError as exc:
            error_message = _http_error_message(exc, sensitive_values=sensitive_values)
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="closed_audit",
                status="error",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=None,
                limit_price=None,
                alpaca_order_id=None,
                message=error_message,
                systemic_failure=(
                    _authentication_http_error(exc, sensitive_values=sensitive_values)
                    or _transient_broker_http_error(exc)
                ),
                required_failure=True,
            )
        except Exception as exc:
            error_message = _alpaca_exception_diagnostic(
                exc,
                cfg=cfg,
                sensitive_values=sensitive_values,
            )
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="closed_audit",
                status="error",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=None,
                limit_price=None,
                alpaca_order_id=None,
                message=error_message,
                systemic_failure=isinstance(exc, requests.RequestException),
                required_failure=True,
            )
        finally:
            # A required failure means the broker re-audit did not complete.
            # Leave its marker untouched so the bounded rotating loader keeps
            # the position ahead of successfully audited rows on the next run.
            if audit_completed:
                mark_alpaca_closed_correction_audited(
                    conn,
                    position_id,
                    expected_state_revision=int(closed_position["state_revision"]),
                )
    # A closed-position correction can reopen shares that need protection.
    # Refresh the active snapshot so those shares enter this invocation's
    # ordinary reconciliation pass instead of waiting for the next schedule.
    if not recently_closed_positions.empty:
        positions = load_alpaca_managed_positions(conn, active_only=True)
        if skip_active_position_ids:
            positions = positions.loc[~positions["id"].isin(skip_active_position_ids)].reset_index(drop=True)
    for position in positions.to_dict("records"):
        position_id = int(position["id"])
        if position_id in retained_retry_handled_ids:
            continue
        buy_submission_attempt_count = _optional_int(position.get("buy_submission_attempt_count"))
        symbol = str(position["symbol"])
        buy_client_order_id = str(position["buy_client_order_id"])
        sell_client_order_id = _optional_str(position.get("sell_client_order_id"))
        current_sell_status = str(position.get("sell_status") or "").lower()
        accepted_asset_ids = frozenset(alpaca_managed_position_asset_ids(position))
        try:
            if _reconcile_retained_sell_submission_quarantine(
                conn=conn,
                client=client,
                rows=rows,
                position=position,
            ):
                continue
            if _retry_exact_pending_sell_cancellation_before_buy_audit(
                conn=conn,
                client=client,
                rows=rows,
                position=position,
            ):
                continue
            filled_qty = _optional_float(position.get("filled_qty"))
            filled_avg_price = _optional_float(position.get("filled_avg_price"))
            target_sell_price = _optional_float(position.get("target_sell_price"))
            prior_filled_qty = filled_qty
            prior_filled_avg_price = filled_avg_price
            prior_target_sell_price = target_sell_price
            parent_buy_fill_increased = False

            persisted_buy_status = str(position.get("buy_status", "submission_pending")).lower()
            persisted_buy_intent_quarantined = persisted_buy_status in {
                "pending_cancel",
                "identity_mismatch",
            }
            buy_status = persisted_buy_status
            retain_pending_buy_cancellation = False
            pending_buy_cancellation_message: str | None = None
            pending_buy_intent_issue: str | None = None
            tracked_buy_cancellation_ids = _managed_buy_followup_order_ids(position)
            tracked_buy_cancellation_pending = False
            tracked_buy_cancellation_message: str | None = None
            tracked_buy_resolution_issues: list[str] = []
            tracked_buy_lineages: list[list[dict]] = []
            attributed_cancellation_pending = False
            buy_accounting_orders: list[dict]
            buy_is_open = buy_status not in {"filled", *BUY_TERMINAL_STATUSES}
            if (
                filled_qty is None
                or filled_avg_price is None
                or target_sell_price is None
                or buy_is_open
                or _active_filled_buy_correction_audit_due(position)
            ):
                try:
                    if tracked_buy_cancellation_ids:
                        tracked_buy_lineages, buy_accounting_orders, tracked_buy_resolution_issues = (
                            _fetch_durable_buy_cancellation_lineages(
                                client,
                                tracked_buy_cancellation_ids,
                                expected_client_order_id=buy_client_order_id,
                                expected_symbol=symbol,
                                expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
                                accepted_alpaca_asset_ids=accepted_asset_ids,
                            )
                        )
                        if not tracked_buy_lineages:
                            _append_reconciliation_result(
                                rows,
                                position_id=position_id,
                                symbol=symbol,
                                action="buy",
                                status=persisted_buy_status,
                                buy_client_order_id=buy_client_order_id,
                                sell_client_order_id=sell_client_order_id,
                                qty=None,
                                limit_price=None,
                                alpaca_order_id=None,
                                message=(
                                    "no durably tracked accepted buy could be refreshed and strictly attributed; "
                                    + "; ".join(tracked_buy_resolution_issues)
                                ),
                                required_failure=True,
                            )
                            continue
                        persisted_buy_order_id = _optional_str(position.get("buy_alpaca_order_id"))
                        buy_replacement_chain = next(
                            (
                                lineage
                                for lineage in tracked_buy_lineages
                                if persisted_buy_order_id in {_optional_str(order.get("id")) for order in lineage}
                            ),
                            tracked_buy_lineages[0],
                        )
                        buy_order = buy_replacement_chain[-1]
                        attributed_cancellation_pending = _attributed_lineage_requires_cancellation(
                            buy_accounting_orders
                        )
                        tracked_buy_cancellation_pending = bool(
                            attributed_cancellation_pending or tracked_buy_resolution_issues
                        )
                    else:
                        buy_order, buy_replacement_chain = _fetch_order_payload(
                            client,
                            _optional_str(position.get("buy_alpaca_order_id")),
                            buy_client_order_id,
                        )
                        buy_accounting_orders = buy_replacement_chain
                except _OrderLookupIdentityError as exc:
                    diagnostic_status = (
                        "pending_cancel" if persisted_buy_status == "pending_cancel" else "identity_mismatch"
                    )
                    status_updated = update_alpaca_managed_buy_status_if_current(
                        conn,
                        position_id,
                        expected_buy_status=persisted_buy_status,
                        expected_buy_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                        expected_filled_qty=prior_filled_qty,
                        expected_sell_client_order_id=sell_client_order_id,
                        expected_buy_submission_attempt_count=buy_submission_attempt_count,
                        expected_state_revision=int(position["state_revision"]),
                        buy_status=diagnostic_status,
                        notes=durable_note(
                            f"{exc}; fill accounting and broker cancellation are blocked because "
                            "the observed order cannot be attributed to the managed buy"
                        ),
                    )
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="buy",
                        status=diagnostic_status if status_updated else "superseded",
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=None,
                        limit_price=None,
                        alpaca_order_id=_optional_str(exc.payload.get("id")),
                        message=(
                            f"{exc}; no fills were accounted and no broker cancellation was requested"
                            if status_updated
                            else "buy order-ID lookup conflict was superseded by concurrent managed state"
                        ),
                        required_failure=status_updated,
                    )
                    continue
                except HTTPError as exc:
                    if (
                        buy_status in {"submission_pending", "submission_unknown"}
                        and exc.response is not None
                        and exc.response.status_code == 404
                    ):
                        if _buy_submission_visibility_lease_active(position, cfg):
                            _append_reconciliation_result(
                                rows,
                                position_id=position_id,
                                symbol=symbol,
                                action="buy",
                                status=buy_status,
                                buy_client_order_id=buy_client_order_id,
                                sell_client_order_id=sell_client_order_id,
                                qty=None,
                                limit_price=None,
                                alpaca_order_id=None,
                                message=(
                                    "managed buy submission is not visible yet; "
                                    "the owner visibility lease is still active"
                                ),
                            )
                            continue
                        closed = close_alpaca_managed_buy_if_current_and_unfilled(
                            conn,
                            position_id,
                            expected_buy_status=buy_status,
                            expected_buy_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                            expected_buy_submission_attempt_count=buy_submission_attempt_count,
                            expected_state_revision=int(position["state_revision"]),
                            buy_status="submission_not_found",
                            closed_at=None,
                            notes=durable_note(
                                "managed buy submission was not found by client order ID after recovery"
                            ),
                        )
                        _append_reconciliation_result(
                            rows,
                            position_id=position_id,
                            symbol=symbol,
                            action="buy",
                            status="submission_not_found" if closed else "superseded",
                            buy_client_order_id=buy_client_order_id,
                            sell_client_order_id=sell_client_order_id,
                            qty=None,
                            limit_price=None,
                            alpaca_order_id=None,
                            message=(
                                "managed buy submission was not found; intent closed without an Alpaca order"
                                if closed
                                else "missing-buy observation was superseded by concurrent managed state"
                            ),
                        )
                        continue
                    raise
                observed_buy_asset_id = _replacement_chain_stable_asset_id(buy_accounting_orders)
                if observed_buy_asset_id is None:
                    diagnostic_status = (
                        "pending_cancel" if persisted_buy_status == "pending_cancel" else "identity_mismatch"
                    )
                    status_updated = update_alpaca_managed_buy_status_if_current(
                        conn,
                        position_id,
                        expected_buy_status=persisted_buy_status,
                        expected_buy_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                        expected_filled_qty=prior_filled_qty,
                        expected_sell_client_order_id=sell_client_order_id,
                        expected_buy_submission_attempt_count=(buy_submission_attempt_count),
                        expected_state_revision=int(position["state_revision"]),
                        buy_status=diagnostic_status,
                        notes=durable_note(
                            "buy replacement observations have missing or inconsistent stable "
                            "asset IDs; fill aggregation and cancellation are blocked"
                        ),
                    )
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="buy",
                        status=(diagnostic_status if status_updated else "superseded"),
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=None,
                        limit_price=None,
                        alpaca_order_id=None,
                        message=(
                            "buy replacement observations have missing or inconsistent stable "
                            "asset IDs; no fills were aggregated or orders canceled"
                        ),
                        required_failure=status_updated,
                    )
                    continue
                persisted_buy_asset_id = _optional_str(position.get("alpaca_asset_id"))
                attributed_observed_buy_lineage = (
                    _safely_attributed_buy_order_lineage(
                        buy_order,
                        expected_client_order_id=buy_client_order_id,
                        expected_symbol=symbol,
                        expected_alpaca_asset_id=None,
                        expected_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                        replacement_chain=buy_replacement_chain,
                    )
                    if persisted_buy_asset_id is None
                    else buy_replacement_chain
                )
                if persisted_buy_asset_id is None and attributed_observed_buy_lineage is None:
                    diagnostic_status = (
                        "pending_cancel" if persisted_buy_status == "pending_cancel" else "identity_mismatch"
                    )
                    status_updated = update_alpaca_managed_buy_status_if_current(
                        conn,
                        position_id,
                        expected_buy_status=persisted_buy_status,
                        expected_buy_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                        expected_filled_qty=prior_filled_qty,
                        expected_sell_client_order_id=sell_client_order_id,
                        expected_buy_submission_attempt_count=(buy_submission_attempt_count),
                        expected_state_revision=int(position["state_revision"]),
                        buy_status=diagnostic_status,
                        notes=durable_note(
                            "buy stable-asset observation was not adopted because immutable "
                            "core order identity could not be proven"
                        ),
                    )
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="buy",
                        status=(diagnostic_status if status_updated else "superseded"),
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=None,
                        limit_price=None,
                        alpaca_order_id=_optional_str(buy_order.get("id")),
                        message=(
                            "buy stable-asset observation failed immutable core attribution; "
                            "no asset was adopted, fills aggregated, or orders canceled"
                        ),
                        required_failure=status_updated,
                    )
                    continue
                if persisted_buy_asset_id is None:
                    adopted_revision = adopt_alpaca_managed_position_asset_if_current(
                        conn,
                        position_id,
                        expected_state_revision=int(position["state_revision"]),
                        alpaca_asset_id=observed_buy_asset_id,
                    )
                    if adopted_revision is None:
                        current_positions = load_alpaca_managed_positions(
                            conn,
                            active_only=True,
                        )
                        current_match = current_positions.loc[current_positions["id"].eq(position_id)]
                        adoption_was_superseded = bool(
                            current_match.empty
                            or int(current_match.iloc[0]["state_revision"]) != int(position["state_revision"])
                        )
                        _append_reconciliation_result(
                            rows,
                            position_id=position_id,
                            symbol=symbol,
                            action="buy",
                            status="superseded",
                            buy_client_order_id=buy_client_order_id,
                            sell_client_order_id=sell_client_order_id,
                            qty=None,
                            limit_price=None,
                            alpaca_order_id=_optional_str(buy_order.get("id")),
                            message=(
                                (
                                    "stable buy asset adoption was superseded by newer managed state"
                                    if adoption_was_superseded
                                    else "stable buy asset adoption conflicts with another active asset owner"
                                )
                                + "; no fills were accounted or orders canceled"
                            ),
                            required_failure=not adoption_was_superseded,
                        )
                        continue
                    position["alpaca_asset_id"] = observed_buy_asset_id
                    position["state_revision"] = adopted_revision
                    accepted_asset_ids = frozenset({observed_buy_asset_id})
                elif observed_buy_asset_id not in accepted_asset_ids:
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="buy",
                        status="identity_mismatch",
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=None,
                        limit_price=None,
                        alpaca_order_id=_optional_str(buy_order.get("id")),
                        message=(
                            "buy replacement observations conflict with the persisted stable asset ID; "
                            "no fills were accounted or orders canceled"
                        ),
                        required_failure=True,
                    )
                    continue
                expected_buy_identity_asset_id = observed_buy_asset_id
                if tracked_buy_cancellation_ids:
                    if attributed_cancellation_pending:
                        if persisted_buy_status != "pending_cancel":
                            quarantine_owned = bool(
                                buy_submission_attempt_count is not None
                                and quarantine_alpaca_managed_buy_side_effect_if_current(
                                    conn,
                                    position_id,
                                    expected_state_revision=int(position["state_revision"]),
                                    expected_buy_submission_attempt_count=(buy_submission_attempt_count),
                                    expected_buy_status=persisted_buy_status,
                                    expected_buy_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                                    expected_filled_qty=prior_filled_qty,
                                    expected_filled_avg_price=prior_filled_avg_price,
                                    expected_target_sell_price=prior_target_sell_price,
                                    expected_sell_client_order_id=sell_client_order_id,
                                    expected_closed_at=None,
                                    buy_status="pending_cancel",
                                    observed_buy_alpaca_order_id=None,
                                    observed_buy_submitted_at=None,
                                    notes=durable_note(
                                        "durably tracked accepted buy is active; cancellation "
                                        "ownership was fenced before broker requests"
                                    ),
                                    expected_buy_cancellation_alpaca_order_ids=(
                                        _optional_str(position.get("buy_cancellation_alpaca_order_ids"))
                                    ),
                                    buy_cancellation_alpaca_order_ids=(tracked_buy_cancellation_ids),
                                )
                            )
                            if not quarantine_owned:
                                _append_reconciliation_result(
                                    rows,
                                    position_id=position_id,
                                    symbol=symbol,
                                    action="buy",
                                    status="superseded",
                                    buy_client_order_id=buy_client_order_id,
                                    sell_client_order_id=sell_client_order_id,
                                    qty=None,
                                    limit_price=None,
                                    alpaca_order_id=_optional_str(buy_order.get("id")),
                                    message=(
                                        "tracked-buy cancellation ownership changed before "
                                        "durable pending-cancel quarantine"
                                    ),
                                    required_failure=True,
                                )
                                continue
                            persisted_buy_status = "pending_cancel"
                            persisted_buy_intent_quarantined = True
                            position["buy_status"] = "pending_cancel"
                            position["state_revision"] = int(position["state_revision"]) + 1
                        _, tracked_buy_cancellation_message = _request_safely_attributed_lineage_cancellations(
                            client,
                            buy_accounting_orders,
                        )
                    else:
                        tracked_buy_cancellation_message = "all durably tracked buy cancellation lineages are terminal"
                    if tracked_buy_resolution_issues:
                        tracked_buy_cancellation_message += (
                            "; some durably tracked accepted buys remain unresolved: "
                            + "; ".join(tracked_buy_resolution_issues)
                        )
                expected_buy_order_qty = _optional_positive_float(position.get("buy_order_qty"))
                expected_buy_order_limit_price = _optional_positive_float(position.get("buy_order_limit_price"))
                representative_buy_identity_issue = _buy_order_identity_issue(
                    buy_order,
                    expected_client_order_id=buy_client_order_id,
                    expected_symbol=symbol,
                    expected_alpaca_asset_id=expected_buy_identity_asset_id,
                    expected_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                    expected_qty=expected_buy_order_qty,
                    expected_limit_price=expected_buy_order_limit_price,
                    replacement_chain=buy_replacement_chain,
                    require_expected_intent=True,
                )
                tracked_buy_economics_issue = (
                    _tracked_buy_lineages_intent_issue(
                        tracked_buy_lineages,
                        expected_client_order_id=buy_client_order_id,
                        expected_symbol=symbol,
                        expected_alpaca_asset_id=expected_buy_identity_asset_id,
                        accepted_alpaca_asset_ids=accepted_asset_ids,
                        expected_qty=expected_buy_order_qty,
                        expected_limit_price=expected_buy_order_limit_price,
                    )
                    if tracked_buy_lineages
                    else None
                )
                buy_identity_issues = list(
                    dict.fromkeys(
                        issue
                        for issue in (
                            representative_buy_identity_issue,
                            tracked_buy_economics_issue,
                        )
                        if issue is not None
                    )
                )
                buy_identity_issue = "; ".join(buy_identity_issues) if buy_identity_issues else None
                attributed_intent_mismatch = bool(
                    buy_identity_issue is not None
                    and _buy_identity_issue_is_attributable_cancellation_issue(buy_identity_issue)
                    and _safely_attributed_buy_order_lineage(
                        buy_order,
                        expected_client_order_id=buy_client_order_id,
                        expected_symbol=symbol,
                        expected_alpaca_asset_id=expected_buy_identity_asset_id,
                        expected_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                        replacement_chain=buy_replacement_chain,
                    )
                    is not None
                )
                lifecycle_issue = _replacement_chain_lifecycle_issue(buy_replacement_chain)
                if lifecycle_issue is not None and attributed_intent_mismatch:
                    lineage_order_ids = [
                        order_id
                        for node in buy_replacement_chain
                        if (order_id := _optional_alpaca_broker_identifier(node.get("id"))) is not None
                    ]
                    quarantine_owned = _quarantine_managed_buy_side_effect_from_current_snapshot(
                        conn=conn,
                        position_id=position_id,
                        buy_status="pending_cancel",
                        observed_buy_alpaca_order_id=_optional_alpaca_broker_identifier(buy_order.get("id")),
                        observed_buy_submitted_at=_optional_alpaca_datetime_str(buy_order.get("submitted_at")),
                        notes=durable_note(
                            f"{lifecycle_issue}; every core-attributed replacement generation was durably "
                            "retained before cancellation"
                        ),
                        observed_buy_cancellation_alpaca_order_ids=lineage_order_ids,
                    )
                    if not quarantine_owned:
                        _append_reconciliation_result(
                            rows,
                            position_id=position_id,
                            symbol=symbol,
                            action="buy",
                            status="superseded",
                            buy_client_order_id=buy_client_order_id,
                            sell_client_order_id=sell_client_order_id,
                            qty=None,
                            limit_price=None,
                            alpaca_order_id=_optional_str(buy_order.get("id")),
                            message=(
                                f"{lifecycle_issue}; cancellation was not requested because durable local "
                                "quarantine ownership changed"
                            ),
                            required_failure=True,
                        )
                        continue
                    persisted_buy_status = "pending_cancel"
                    persisted_buy_intent_quarantined = True
                    position["buy_status"] = "pending_cancel"
                    position["buy_cancellation_alpaca_order_ids"] = json.dumps(sorted(set(lineage_order_ids)))
                if buy_identity_issue is not None and not attributed_intent_mismatch:
                    quarantine_status, attributed_order_id, cancellation_message = (
                        _quarantine_attributed_buy_identity_mismatch(
                            client,
                            buy_order,
                            identity_issue=buy_identity_issue,
                            expected_client_order_id=buy_client_order_id,
                            expected_symbol=symbol,
                            expected_alpaca_asset_id=expected_buy_identity_asset_id,
                            expected_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                            replacement_chain=buy_replacement_chain,
                        )
                    )
                    persisted_quarantine_status = (
                        "pending_cancel" if persisted_buy_status == "pending_cancel" else quarantine_status
                    )
                    status_updated = update_alpaca_managed_buy_status_if_current(
                        conn,
                        position_id,
                        expected_buy_status=str(position.get("buy_status", "submission_pending")).lower(),
                        expected_buy_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                        expected_filled_qty=prior_filled_qty,
                        expected_sell_client_order_id=sell_client_order_id,
                        expected_buy_submission_attempt_count=buy_submission_attempt_count,
                        buy_status=persisted_quarantine_status,
                        buy_alpaca_order_id=attributed_order_id,
                        buy_submitted_at=_optional_alpaca_datetime_str(buy_order.get("submitted_at")),
                        notes=durable_note(
                            f"{buy_identity_issue}; {cancellation_message}; fill accounting is blocked pending review"
                        ),
                    )
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="buy",
                        status=quarantine_status if status_updated else "superseded",
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=None,
                        limit_price=None,
                        alpaca_order_id=_optional_str(buy_order.get("id")),
                        message=(
                            f"{buy_identity_issue}; {cancellation_message}"
                            if status_updated
                            else "buy-order identity observation was superseded by concurrent managed state"
                        ),
                        required_failure=status_updated,
                    )
                    continue

                if attributed_intent_mismatch:
                    assert buy_identity_issue is not None
                    pending_buy_intent_issue = buy_identity_issue

                deferred_buy_cancellation = False
                if persisted_buy_intent_quarantined or attributed_intent_mismatch or tracked_buy_cancellation_ids:
                    if tracked_buy_cancellation_ids:
                        retain_pending_buy_cancellation = tracked_buy_cancellation_pending
                        pending_buy_cancellation_message = tracked_buy_cancellation_message
                    elif persisted_buy_status == "pending_cancel":
                        retain_pending_buy_cancellation, pending_buy_cancellation_message = (
                            _retry_pending_buy_lineage_cancellation(
                                client,
                                buy_order,
                                expected_client_order_id=buy_client_order_id,
                                expected_symbol=symbol,
                                expected_alpaca_asset_id=expected_buy_identity_asset_id,
                                expected_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                                replacement_chain=buy_replacement_chain,
                            )
                        )
                    else:
                        attributed_lineage = _safely_attributed_buy_order_lineage(
                            buy_order,
                            expected_client_order_id=buy_client_order_id,
                            expected_symbol=symbol,
                            expected_alpaca_asset_id=expected_buy_identity_asset_id,
                            expected_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                            replacement_chain=buy_replacement_chain,
                        )
                        retain_pending_buy_cancellation = bool(
                            attributed_lineage is not None
                            and _attributed_lineage_requires_cancellation(attributed_lineage)
                        )
                        deferred_buy_cancellation = retain_pending_buy_cancellation
                        pending_buy_cancellation_message = (
                            "broker cancellation awaits durable local quarantine ownership"
                            if retain_pending_buy_cancellation
                            else "all attributed buy replacement generations are terminal"
                        )
                    if pending_buy_intent_issue is not None:
                        pending_buy_cancellation_message = (
                            f"{pending_buy_intent_issue}; {pending_buy_cancellation_message}"
                        )

                deferred_buy_cancellation_kwargs = {
                    "cancellation_deferred": deferred_buy_cancellation,
                    "identity_issue": pending_buy_intent_issue,
                    "client": client,
                    "buy_order": buy_order,
                    "expected_client_order_id": buy_client_order_id,
                    "expected_symbol": symbol,
                    "expected_alpaca_asset_id": expected_buy_identity_asset_id,
                    "expected_alpaca_order_id": _optional_str(position.get("buy_alpaca_order_id")),
                    "replacement_chain": buy_replacement_chain,
                }

                buy_status = _broker_order_status(buy_order, default="unknown")
                buy_alpaca_order_id = _optional_str(buy_order.get("id"))
                buy_submitted_at = _optional_alpaca_datetime_str(buy_order.get("submitted_at"))
                buy_position_intent_issue = _buy_replacement_chain_position_intent_issue(buy_accounting_orders)
                if buy_position_intent_issue is not None:
                    attributed_buy_orders = buy_accounting_orders
                    compatible_buy_fill_orders = [
                        node
                        for node in attributed_buy_orders
                        if _optional_alpaca_position_intent_matches(
                            node.get("position_intent"),
                            expected=_ALPACA_MANAGED_BUY_POSITION_INTENT,
                        )
                    ]
                    cancellation_order_ids = [
                        order_id
                        for node in attributed_buy_orders
                        if (order_id := _optional_alpaca_broker_identifier(node.get("id"))) is not None
                    ]
                    diagnostic_status = "pending_cancel" if retain_pending_buy_cancellation else "identity_mismatch"
                    diagnostic_notes = (
                        f"{buy_position_intent_issue}; broker fills with an explicit "
                        "non-opening intent were excluded from managed-long accounting"
                    )
                    quarantine_premise_revision: int | None = int(position["state_revision"])
                    if (
                        not tracked_buy_cancellation_ids
                        and buy_alpaca_order_id is not None
                        and buy_alpaca_order_id != _optional_str(position.get("buy_alpaca_order_id"))
                    ):
                        # Preserve the authoritative replacement leaf just as
                        # other attributable intent mismatches do. The
                        # follow-up snapshot helper below still owns the full
                        # cancellation-ID fence before any DELETE.
                        leaf_update_owned = update_alpaca_managed_buy_status_if_current(
                            conn,
                            position_id,
                            expected_buy_status=str(position.get("buy_status", "submission_pending")).lower(),
                            expected_buy_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                            expected_filled_qty=prior_filled_qty,
                            expected_sell_client_order_id=sell_client_order_id,
                            expected_buy_submission_attempt_count=buy_submission_attempt_count,
                            expected_state_revision=int(position["state_revision"]),
                            buy_status=diagnostic_status,
                            buy_alpaca_order_id=buy_alpaca_order_id,
                            buy_submitted_at=buy_submitted_at,
                            notes=durable_note(diagnostic_notes),
                        )
                        expected_leaf_revision = int(position["state_revision"]) + 1
                        refreshed_leaf_position = _managed_position_snapshot(conn, position_id)
                        if (
                            not leaf_update_owned
                            or refreshed_leaf_position is None
                            or int(refreshed_leaf_position.get("state_revision", -1)) != expected_leaf_revision
                            or (_optional_str(refreshed_leaf_position.get("buy_status")) or "").lower()
                            != diagnostic_status
                            or _optional_str(refreshed_leaf_position.get("buy_alpaca_order_id")) != buy_alpaca_order_id
                            or _optional_str(refreshed_leaf_position.get("sell_client_order_id"))
                            != sell_client_order_id
                            or _optional_str(refreshed_leaf_position.get("closed_at")) is not None
                        ):
                            quarantine_premise_revision = None
                        else:
                            quarantine_premise_revision = expected_leaf_revision
                    exact_quarantine_owned = bool(
                        quarantine_premise_revision is not None
                        and _quarantine_managed_buy_side_effect_from_current_snapshot(
                            conn=conn,
                            position_id=position_id,
                            buy_status=diagnostic_status,
                            observed_buy_alpaca_order_id=buy_alpaca_order_id,
                            observed_buy_submitted_at=buy_submitted_at,
                            notes=durable_note(diagnostic_notes),
                            observed_buy_cancellation_alpaca_order_ids=cancellation_order_ids,
                            required_state_revision=quarantine_premise_revision,
                        )
                    )
                    quarantine_owned = exact_quarantine_owned or (
                        _quarantine_managed_buy_side_effect_from_current_snapshot(
                            conn=conn,
                            position_id=position_id,
                            buy_status=diagnostic_status,
                            observed_buy_alpaca_order_id=buy_alpaca_order_id,
                            observed_buy_submitted_at=buy_submitted_at,
                            notes=durable_note(diagnostic_notes),
                            observed_buy_cancellation_alpaca_order_ids=cancellation_order_ids,
                        )
                    )
                    sell_fence_state_revision = (
                        quarantine_premise_revision + 1
                        if exact_quarantine_owned and quarantine_premise_revision is not None
                        else None
                    )
                    compatible_filled_qty = _replacement_chain_nonnegative_filled_qty(compatible_buy_fill_orders)
                    compatible_opening_fill = bool(
                        compatible_buy_fill_orders and compatible_filled_qty is not None and compatible_filled_qty > 0.0
                    )
                    if not quarantine_owned or not compatible_opening_fill:
                        pending_buy_cancellation_message = _request_deferred_buy_cancellation_if_owned(
                            durable_quarantine_owned=quarantine_owned,
                            current_message=pending_buy_cancellation_message,
                            **deferred_buy_cancellation_kwargs,
                        )
                        attached_sell_cancellation_message = (
                            _fence_attached_sell_after_unproven_buy(
                                conn=conn,
                                client=client,
                                position=position,
                                expected_buy_status=diagnostic_status,
                                expected_state_revision=sell_fence_state_revision,
                            )
                            if sell_fence_state_revision is not None and not compatible_opening_fill
                            else None
                        )
                        if quarantine_owned and not compatible_opening_fill and sell_fence_state_revision is None:
                            attached_sell_cancellation_message = (
                                "attached managed sell cancellation was not requested because the exact "
                                "no-opening-fill quarantine premise changed"
                            )
                        _append_reconciliation_result(
                            rows,
                            position_id=position_id,
                            symbol=symbol,
                            action="buy",
                            status=diagnostic_status if quarantine_owned else "superseded",
                            buy_client_order_id=buy_client_order_id,
                            sell_client_order_id=sell_client_order_id,
                            qty=None,
                            limit_price=None,
                            alpaca_order_id=buy_alpaca_order_id,
                            message=(
                                diagnostic_notes
                                + (f"; {pending_buy_cancellation_message}" if pending_buy_cancellation_message else "")
                                + (
                                    f"; {attached_sell_cancellation_message}"
                                    if attached_sell_cancellation_message
                                    else ""
                                )
                                if quarantine_owned
                                else (
                                    f"{diagnostic_notes}; durable local buy quarantine "
                                    "persistence failed and requires retry"
                                )
                            ),
                            required_failure=quarantine_owned,
                        )
                        continue
                    # Attribute economics per generation: a prior opening fill
                    # remains real managed-long exposure even when a later
                    # broker-created successor reports a non-opening intent.
                    # Only compatible generations may feed cost basis and the
                    # protective-sell quantity below.
                    buy_accounting_orders = compatible_buy_fill_orders
                    quarantined_positions = load_alpaca_managed_positions(
                        conn,
                        active_only=True,
                    )
                    quarantined_match = quarantined_positions.loc[quarantined_positions["id"].eq(position_id)]
                    if quarantined_match.empty:
                        _append_reconciliation_result(
                            rows,
                            position_id=position_id,
                            symbol=symbol,
                            action="buy",
                            status="superseded",
                            buy_client_order_id=buy_client_order_id,
                            sell_client_order_id=sell_client_order_id,
                            qty=None,
                            limit_price=None,
                            alpaca_order_id=buy_alpaca_order_id,
                            message=(
                                "wrong-intent buy quarantine closed concurrently before compatible "
                                "managed-long fills could be recorded"
                            ),
                        )
                        continue
                    quarantined_position = quarantined_match.iloc[0].to_dict()
                    position["buy_status"] = quarantined_position["buy_status"]
                    position["buy_alpaca_order_id"] = quarantined_position["buy_alpaca_order_id"]
                    position["state_revision"] = quarantined_position["state_revision"]
                raw_order_filled_qty = _replacement_chain_nonnegative_filled_qty(buy_accounting_orders)
                if (
                    prior_filled_qty is not None
                    and raw_order_filled_qty is not None
                    and raw_order_filled_qty
                    < prior_filled_qty - _managed_qty_tolerance(raw_order_filled_qty, prior_filled_qty)
                ):
                    regression_quarantine_owned = _quarantine_buy_fill_quantity_regression(
                        conn=conn,
                        client=client,
                        rows=rows,
                        position=position,
                        observed_buy_order=buy_order,
                        observed_buy_lineage=buy_accounting_orders,
                        observed_filled_qty=raw_order_filled_qty,
                        retained_buy_status=(
                            "pending_cancel" if retain_pending_buy_cancellation else "fill_quantity_regression"
                        ),
                    )
                    pending_buy_cancellation_message = _request_deferred_buy_cancellation_if_owned(
                        durable_quarantine_owned=regression_quarantine_owned,
                        current_message=pending_buy_cancellation_message,
                        **deferred_buy_cancellation_kwargs,
                    )
                    continue
                order_filled_qty, order_filled_avg_price, _ = _replacement_chain_fill_metadata(buy_accounting_orders)
                expected_buy_qty = expected_buy_order_qty or _optional_positive_float(
                    buy_replacement_chain[0].get("qty")
                )
                assert expected_buy_qty is not None
                exact_order_filled_qty = _replacement_chain_nonnegative_filled_qty_decimal(
                    buy_accounting_orders,
                )
                exact_expected_buy_qty = _optional_positive_decimal(expected_buy_qty)
                tracked_buy_fill_exceeds_intent = bool(
                    tracked_buy_cancellation_ids
                    and exact_order_filled_qty is not None
                    and exact_expected_buy_qty is not None
                    and exact_order_filled_qty > exact_expected_buy_qty
                )
                if tracked_buy_fill_exceeds_intent:
                    assert exact_order_filled_qty is not None
                    aggregate_fill_issue = (
                        f"aggregate fills across independently accepted buys ({exact_order_filled_qty}) "
                        f"exceed the immutable managed buy quantity ({expected_buy_qty:g})"
                    )
                    pending_buy_intent_issue = "; ".join(
                        dict.fromkeys(
                            issue
                            for issue in (
                                pending_buy_intent_issue,
                                aggregate_fill_issue,
                            )
                            if issue is not None
                        )
                    )
                    if retain_pending_buy_cancellation:
                        pending_buy_cancellation_message = (
                            f"{pending_buy_intent_issue}; {pending_buy_cancellation_message}"
                        )
                fill_issue_message = _buy_replacement_chain_fill_metadata_issue(
                    buy_accounting_orders,
                    expected_buy_qty=(
                        None
                        if pending_buy_intent_issue is not None or tracked_buy_cancellation_ids
                        else expected_buy_qty
                    ),
                )
                if fill_issue_message is not None:
                    diagnostic_status = (
                        "pending_cancel" if retain_pending_buy_cancellation else "incomplete_fill_metadata"
                    )
                    status_updated = update_alpaca_managed_buy_status_if_current(
                        conn,
                        position_id,
                        expected_buy_status=str(position.get("buy_status", "submission_pending")).lower(),
                        expected_buy_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                        expected_filled_qty=prior_filled_qty,
                        expected_sell_client_order_id=sell_client_order_id,
                        expected_buy_submission_attempt_count=buy_submission_attempt_count,
                        buy_status=diagnostic_status,
                        buy_alpaca_order_id=buy_alpaca_order_id,
                        buy_submitted_at=buy_submitted_at,
                        notes=durable_note(
                            f"{fill_issue_message}; protective-sell automation is quarantined pending reconciliation"
                            + (
                                f"; {pending_buy_cancellation_message}"
                                if pending_buy_cancellation_message is not None
                                else ""
                            )
                        ),
                    )
                    pending_buy_cancellation_message = _request_deferred_buy_cancellation_if_owned(
                        durable_quarantine_owned=status_updated,
                        current_message=pending_buy_cancellation_message,
                        **deferred_buy_cancellation_kwargs,
                    )
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="buy",
                        status=diagnostic_status if status_updated else "superseded",
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=None,
                        limit_price=None,
                        alpaca_order_id=buy_alpaca_order_id,
                        message=(
                            (
                                f"{fill_issue_message}; {pending_buy_cancellation_message}"
                                if pending_buy_cancellation_message is not None
                                else fill_issue_message
                            )
                            if status_updated
                            else "incomplete buy-fill observation was superseded by concurrent managed state"
                        ),
                        required_failure=status_updated,
                    )
                    continue
                buy_is_open = buy_status not in {"filled", *BUY_TERMINAL_STATUSES}
                if order_filled_qty > 0.0:
                    if order_filled_avg_price is None:
                        raise ValueError("filled Alpaca buy order is missing filled_qty or filled_avg_price")
                    parent_buy_fill_increased = (
                        prior_filled_qty is not None
                        and order_filled_qty
                        > prior_filled_qty + _managed_qty_tolerance(order_filled_qty, prior_filled_qty)
                    )
                    filled_qty = order_filled_qty
                    filled_avg_price = order_filled_avg_price
                    target_sell_price = _target_sell_price(
                        filled_avg_price,
                        float(position["profit_target_multiple"]),
                    )
                    buy_filled_at = next(
                        (
                            observed_filled_at
                            for node in reversed(buy_accounting_orders)
                            if (observed_filled_at := _optional_alpaca_datetime_str(node.get("filled_at"))) is not None
                        ),
                        None,
                    )
                    reconciled_buy_status = (
                        "pending_cancel"
                        if retain_pending_buy_cancellation
                        else "identity_mismatch"
                        if pending_buy_intent_issue is not None
                        else buy_status
                    )
                    buy_fill_result = mark_alpaca_managed_buy_filled(
                        conn,
                        position_id,
                        buy_status=reconciled_buy_status,
                        filled_qty=filled_qty,
                        filled_avg_price=filled_avg_price,
                        filled_at=buy_filled_at,
                        target_sell_price=target_sell_price,
                        buy_fill_broker_updated_at=(_replacement_chain_latest_broker_updated_at(buy_accounting_orders)),
                        buy_fill_broker_oldest_updated_at=(
                            _replacement_chain_oldest_broker_updated_at(buy_accounting_orders)
                        ),
                        buy_fill_component_revisions=(
                            _replacement_chain_broker_component_revisions(buy_accounting_orders)
                        ),
                        buy_alpaca_order_id=buy_alpaca_order_id,
                        buy_submitted_at=buy_submitted_at,
                        expected_buy_status=str(position.get("buy_status", "submission_pending")).lower(),
                        expected_buy_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                        expected_filled_qty=prior_filled_qty,
                        expected_filled_avg_price=prior_filled_avg_price,
                        expected_target_sell_price=prior_target_sell_price,
                        expected_sell_client_order_id=sell_client_order_id,
                        expected_buy_submission_attempt_count=buy_submission_attempt_count,
                        notes=durable_note(
                            f"pending buy cancellation remains unconfirmed; {pending_buy_cancellation_message}"
                            if retain_pending_buy_cancellation
                            else (
                                f"core-attributed buy intent mismatch remains quarantined: {pending_buy_intent_issue}"
                                if pending_buy_intent_issue is not None
                                else None
                            )
                        ),
                        return_state_revision=True,
                    )
                    assert isinstance(buy_fill_result, tuple)
                    buy_fill_is_current, buy_fill_state_revision = buy_fill_result
                    if not buy_fill_is_current:
                        current_positions = load_alpaca_managed_positions(conn, active_only=True)
                        current_match = current_positions.loc[current_positions["id"].eq(position_id)]
                        if not current_match.empty:
                            current_position = current_match.iloc[0].to_dict()
                            current_filled_qty = _optional_float(current_position.get("filled_qty"))
                            if (
                                current_filled_qty is not None
                                and order_filled_qty
                                < current_filled_qty - _managed_qty_tolerance(order_filled_qty, current_filled_qty)
                            ):
                                regression_quarantine_owned = _quarantine_buy_fill_quantity_regression(
                                    conn=conn,
                                    client=client,
                                    rows=rows,
                                    position=current_position,
                                    observed_buy_order=buy_order,
                                    observed_buy_lineage=buy_accounting_orders,
                                    observed_filled_qty=order_filled_qty,
                                    retained_buy_status=(
                                        "pending_cancel"
                                        if retain_pending_buy_cancellation
                                        else "fill_quantity_regression"
                                    ),
                                )
                                pending_buy_cancellation_message = _request_deferred_buy_cancellation_if_owned(
                                    durable_quarantine_owned=regression_quarantine_owned,
                                    current_message=pending_buy_cancellation_message,
                                    **deferred_buy_cancellation_kwargs,
                                )
                                continue
                        _append_reconciliation_result(
                            rows,
                            position_id=position_id,
                            symbol=symbol,
                            action="buy",
                            status="superseded",
                            buy_client_order_id=buy_client_order_id,
                            sell_client_order_id=sell_client_order_id,
                            qty=order_filled_qty,
                            limit_price=None,
                            alpaca_order_id=buy_alpaca_order_id,
                            message=("parent-buy fill observation was superseded by concurrent managed state"),
                        )
                        continue
                    position["filled_qty"] = filled_qty
                    position["filled_avg_price"] = filled_avg_price
                    position["target_sell_price"] = target_sell_price
                    position["buy_status"] = reconciled_buy_status
                    # Storage returns the exact revision owned by either a
                    # mutating fill observation or an accounting-identical
                    # replay. Carry that generation into downstream sell CAS
                    # without guessing whether the row changed or adopting a
                    # concurrent revision through an unfenced reload.
                    if buy_fill_state_revision is None:
                        raise RuntimeError("Current managed buy fill observation did not return its state revision.")
                    position["state_revision"] = buy_fill_state_revision
                    pending_buy_cancellation_message = _request_deferred_buy_cancellation_if_owned(
                        durable_quarantine_owned=True,
                        current_message=pending_buy_cancellation_message,
                        **deferred_buy_cancellation_kwargs,
                    )
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="buy",
                        status=(
                            "pending_cancel"
                            if retain_pending_buy_cancellation
                            else "identity_mismatch"
                            if pending_buy_intent_issue is not None
                            else "partially_filled"
                            if buy_is_open
                            else buy_status
                        ),
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=filled_qty,
                        limit_price=target_sell_price,
                        alpaca_order_id=buy_alpaca_order_id,
                        message=(
                            (
                                "buy cancellation remains unconfirmed; confirmed fills continue into "
                                f"protective-sell reconciliation; {pending_buy_cancellation_message}"
                            )
                            if retain_pending_buy_cancellation
                            else (
                                "core-attributed mismatched buy is terminal; confirmed fills continue into "
                                f"protective-sell reconciliation; {pending_buy_intent_issue}"
                            )
                            if pending_buy_intent_issue is not None
                            else "buy partially filled; managed target sell covers the confirmed shares"
                            if buy_is_open
                            else "buy filled; target sell price frozen from actual fill"
                        ),
                        required_failure=bool(retain_pending_buy_cancellation or pending_buy_intent_issue is not None),
                    )
                elif retain_pending_buy_cancellation:
                    status_updated = update_alpaca_managed_buy_status_if_current(
                        conn,
                        position_id,
                        expected_buy_status=str(position.get("buy_status", "submission_pending")).lower(),
                        expected_buy_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                        expected_filled_qty=prior_filled_qty,
                        expected_sell_client_order_id=sell_client_order_id,
                        expected_buy_submission_attempt_count=buy_submission_attempt_count,
                        buy_status="pending_cancel",
                        buy_alpaca_order_id=buy_alpaca_order_id,
                        buy_submitted_at=buy_submitted_at,
                        notes=durable_note(
                            f"pending buy cancellation remains unconfirmed; {pending_buy_cancellation_message}"
                        ),
                    )
                    pending_buy_cancellation_message = _request_deferred_buy_cancellation_if_owned(
                        durable_quarantine_owned=status_updated,
                        current_message=pending_buy_cancellation_message,
                        **deferred_buy_cancellation_kwargs,
                    )
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="buy",
                        status="pending_cancel" if status_updated else "superseded",
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=None,
                        limit_price=None,
                        alpaca_order_id=buy_alpaca_order_id,
                        message=(
                            f"buy cancellation remains unconfirmed; {pending_buy_cancellation_message}"
                            if status_updated
                            else "pending-buy cancellation observation was superseded by concurrent managed state"
                        ),
                        required_failure=status_updated,
                    )
                    continue
                elif pending_buy_intent_issue is not None:
                    status_updated = update_alpaca_managed_buy_status_if_current(
                        conn,
                        position_id,
                        expected_buy_status=str(position.get("buy_status", "submission_pending")).lower(),
                        expected_buy_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                        expected_filled_qty=prior_filled_qty,
                        expected_sell_client_order_id=sell_client_order_id,
                        expected_buy_submission_attempt_count=(buy_submission_attempt_count),
                        buy_status="identity_mismatch",
                        buy_alpaca_order_id=buy_alpaca_order_id,
                        buy_submitted_at=buy_submitted_at,
                        notes=durable_note(
                            "terminal tracked buy has frozen-intent mismatch and remains "
                            f"quarantined: {pending_buy_intent_issue}"
                        ),
                    )
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="buy",
                        status="identity_mismatch" if status_updated else "superseded",
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=None,
                        limit_price=None,
                        alpaca_order_id=buy_alpaca_order_id,
                        message=(
                            pending_buy_intent_issue
                            if status_updated
                            else "terminal buy intent mismatch was superseded by concurrent managed state"
                        ),
                        required_failure=status_updated,
                    )
                    continue
                elif buy_status in BUY_TERMINAL_STATUSES:
                    closed = close_alpaca_managed_buy_if_current_and_unfilled(
                        conn,
                        position_id,
                        expected_buy_status=str(position.get("buy_status", "submission_pending")).lower(),
                        expected_buy_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                        expected_buy_submission_attempt_count=buy_submission_attempt_count,
                        expected_state_revision=int(position["state_revision"]),
                        buy_status=buy_status,
                        buy_alpaca_order_id=buy_alpaca_order_id,
                        buy_submitted_at=buy_submitted_at,
                        closed_at=_optional_alpaca_datetime_str(buy_order.get("updated_at")),
                        buy_broker_updated_at=_optional_alpaca_datetime_str(buy_order.get("updated_at")),
                        notes=durable_note("buy order terminated without a filled position"),
                    )
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="buy",
                        status=buy_status if closed else "superseded",
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=None,
                        limit_price=None,
                        alpaca_order_id=buy_alpaca_order_id,
                        message=(
                            "buy order terminated without a filled position"
                            if closed
                            else "terminal buy observation was superseded by concurrent managed state"
                        ),
                    )
                    continue
                else:
                    status_updated = update_alpaca_managed_buy_status_if_current(
                        conn,
                        position_id,
                        expected_buy_status=str(position.get("buy_status", "submission_pending")).lower(),
                        expected_buy_alpaca_order_id=_optional_str(position.get("buy_alpaca_order_id")),
                        expected_filled_qty=prior_filled_qty,
                        expected_sell_client_order_id=sell_client_order_id,
                        expected_buy_submission_attempt_count=buy_submission_attempt_count,
                        buy_status=buy_status,
                        buy_alpaca_order_id=buy_alpaca_order_id,
                        buy_submitted_at=buy_submitted_at,
                        buy_broker_updated_at=_optional_alpaca_datetime_str(buy_order.get("updated_at")),
                    )
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="buy",
                        status=buy_status if status_updated else "superseded",
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=order_filled_qty if order_filled_qty > 0 else None,
                        limit_price=None,
                        alpaca_order_id=buy_alpaca_order_id,
                        message=(
                            "buy order is not filled yet"
                            if status_updated
                            else "buy-order observation was superseded by concurrent managed state"
                        ),
                    )
                    continue

            if not cfg.sell_enabled:
                _append_reconciliation_result(
                    rows,
                    position_id=position_id,
                    symbol=symbol,
                    action="sell",
                    status="disabled",
                    buy_client_order_id=buy_client_order_id,
                    sell_client_order_id=sell_client_order_id,
                    qty=filled_qty,
                    limit_price=target_sell_price,
                    alpaca_order_id=None,
                    message="managed limit sell submission is disabled",
                )
                continue

            position_aliases = alpaca_managed_position_aliases(conn, position_id)

            def load_live_position_qty(
                managed_symbol: str = symbol,
                expected_asset_id: str | None = _optional_str(position.get("alpaca_asset_id")),
                aliases: set[str] = position_aliases,
            ) -> float:
                return _managed_live_position_qty(
                    client.positions(),
                    symbol=managed_symbol,
                    expected_alpaca_asset_id=expected_asset_id,
                    symbol_aliases=aliases,
                )

            if sell_client_order_id:
                try:
                    sell_order, sell_replacement_chain = _fetch_order_payload(
                        client,
                        _optional_str(position.get("sell_alpaca_order_id")),
                        sell_client_order_id,
                    )
                except _OrderLookupIdentityError as exc:
                    _append_incomplete_sell_order_identity_result(
                        conn=conn,
                        rows=rows,
                        position_id=position_id,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        observed_sell_qty=_sell_fill_metadata(exc.payload)[0],
                        target_sell_price=float(target_sell_price),
                        sell_alpaca_order_id=_optional_str(exc.payload.get("id")),
                        identity_issue=str(exc),
                        expected_sell_status=_optional_str(position.get("sell_status")),
                        expected_sell_alpaca_order_id=_optional_str(position.get("sell_alpaca_order_id")),
                        expected_sell_filled_qty=_optional_float(position.get("sell_filled_qty")),
                        expected_sell_renewal_count=int(position.get("sell_renewal_count") or 0),
                        expected_sell_state_revision=int(position["state_revision"]),
                    )
                    continue
                except _InvalidAlpacaOrderTimestampError as exc:
                    _append_incomplete_sell_order_metadata_result(
                        conn=conn,
                        rows=rows,
                        position_id=position_id,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        target_sell_price=float(target_sell_price),
                        sell_alpaca_order_id=_optional_str(exc.payload.get("id")),
                        metadata_issue=str(exc),
                        expected_sell_status=_optional_str(position.get("sell_status")),
                        expected_sell_alpaca_order_id=_optional_str(position.get("sell_alpaca_order_id")),
                        expected_sell_filled_qty=_optional_float(position.get("sell_filled_qty")),
                        expected_sell_renewal_count=int(position.get("sell_renewal_count") or 0),
                        expected_sell_state_revision=int(position["state_revision"]),
                    )
                    continue
                except HTTPError as exc:
                    if (
                        (
                            current_sell_status
                            in {
                                "broker_inactive",
                                "submission_failed",
                                "submission_pending",
                                "submission_unknown",
                                "submission_not_found",
                                "submission_retrying",
                            }
                            or (
                                current_sell_status == "pending_cancel"
                                and _optional_str(position.get("sell_alpaca_order_id")) is None
                            )
                        )
                        and exc.response is not None
                        and exc.response.status_code == 404
                    ):
                        historical_cancellation_was_fenced = bool(
                            current_sell_status == "pending_cancel"
                            and _optional_str(position.get("sell_submission_retry_claimed_at")) is not None
                            and _optional_str(position.get("sell_renewal_requested_at")) is not None
                        )
                        if current_sell_status == "pending_cancel":
                            pending_retry_token = _optional_str(position.get("sell_submission_retry_claimed_at"))
                            if not historical_cancellation_was_fenced or pending_retry_token is None:
                                _append_reconciliation_result(
                                    rows,
                                    position_id=position_id,
                                    symbol=symbol,
                                    action="sell",
                                    status="pending_cancel",
                                    buy_client_order_id=buy_client_order_id,
                                    sell_client_order_id=sell_client_order_id,
                                    qty=None,
                                    limit_price=target_sell_price,
                                    alpaca_order_id=None,
                                    message=(
                                        "missing managed sell has an incomplete historical-cancellation "
                                        "fence and requires review"
                                    ),
                                    required_failure=True,
                                )
                                continue
                            try:
                                pending_historical_leaves, pending_historical_issue = (
                                    _missing_sell_retry_historical_exposure_audit(
                                        conn=conn,
                                        client=client,
                                        position=position,
                                        allow_fenced_inactive_intent_mismatch=True,
                                    )
                                )
                            except (SellOrderIdentityError, RuntimeError, ValueError) as audit_exc:
                                pending_historical_leaves = []
                                pending_historical_issue = f"historical managed sell audit failed: {audit_exc}"
                            if pending_historical_leaves:
                                cancellation_requested_at = (
                                    _utc_now()
                                    .isoformat()
                                    .replace(
                                        "+00:00",
                                        "Z",
                                    )
                                )
                                cancellation_owned = update_alpaca_managed_sell_status_if_current(
                                    conn,
                                    position_id,
                                    expected_sell_client_order_id=sell_client_order_id,
                                    expected_sell_status="pending_cancel",
                                    expected_sell_alpaca_order_id=None,
                                    expected_sell_filled_qty=_optional_float(position.get("sell_filled_qty")),
                                    expected_sell_renewal_count=int(position.get("sell_renewal_count") or 0),
                                    expected_sell_submission_retry_claimed_at=pending_retry_token,
                                    expected_sell_renewal_requested_at=_optional_str(
                                        position.get("sell_renewal_requested_at")
                                    ),
                                    expected_state_revision=int(position["state_revision"]),
                                    sell_status="pending_cancel",
                                    sell_renewal_requested_at=cancellation_requested_at,
                                    notes=durable_note(
                                        "missing managed sell retry retained its durable historical-exposure "
                                        "cancellation fence"
                                    ),
                                )
                                cancellation_message = (
                                    "broker cancellation was not requested because the durable "
                                    "historical-exposure fence changed"
                                )
                                if cancellation_owned:
                                    _, cancellation_messages = _request_managed_sell_leaf_cancellations(
                                        client,
                                        pending_historical_leaves,
                                    )
                                    cancellation_message = "; ".join(cancellation_messages)
                                _append_reconciliation_result(
                                    rows,
                                    position_id=position_id,
                                    symbol=symbol,
                                    action="sell",
                                    status="pending_cancel" if cancellation_owned else "superseded",
                                    buy_client_order_id=buy_client_order_id,
                                    sell_client_order_id=sell_client_order_id,
                                    qty=None,
                                    limit_price=target_sell_price,
                                    alpaca_order_id=None,
                                    message=(
                                        "missing-sell retry remains blocked by executable historical "
                                        f"exposure; {cancellation_message}"
                                    ),
                                    required_failure=True,
                                )
                                continue
                            if pending_historical_issue is not None:
                                _append_reconciliation_result(
                                    rows,
                                    position_id=position_id,
                                    symbol=symbol,
                                    action="sell",
                                    status="pending_cancel",
                                    buy_client_order_id=buy_client_order_id,
                                    sell_client_order_id=sell_client_order_id,
                                    qty=None,
                                    limit_price=target_sell_price,
                                    alpaca_order_id=None,
                                    message=(
                                        "missing-sell retry remains blocked after its historical-exposure "
                                        f"cancellation fence: {pending_historical_issue}"
                                    ),
                                    required_failure=True,
                                )
                                continue
                            if not release_alpaca_managed_sell_submission_fence(
                                conn,
                                position_id,
                                sell_client_order_id=sell_client_order_id,
                                claimed_at=pending_retry_token,
                                expected_sell_status="pending_cancel",
                                expected_state_revision=int(position["state_revision"]),
                                allow_current_intent_rebase=True,
                                sell_status="submission_not_found",
                                notes=durable_note(
                                    "historical managed sell cancellation was authoritatively confirmed before retry"
                                ),
                            ):
                                _append_reconciliation_result(
                                    rows,
                                    position_id=position_id,
                                    symbol=symbol,
                                    action="sell",
                                    status="superseded",
                                    buy_client_order_id=buy_client_order_id,
                                    sell_client_order_id=sell_client_order_id,
                                    qty=None,
                                    limit_price=target_sell_price,
                                    alpaca_order_id=None,
                                    message=(
                                        "historical managed sell cancellation confirmation was superseded before retry"
                                    ),
                                )
                                continue

                        retry_now = _utc_now()
                        retry_claimed_at = retry_now.isoformat().replace("+00:00", "Z")
                        recovery_intent = claim_alpaca_managed_sell_submission_retry_with_revision(
                            conn,
                            position_id,
                            sell_client_order_id=sell_client_order_id,
                            expected_target_sell_price=float(target_sell_price),
                            claimed_at=retry_claimed_at,
                            reclaim_before=(retry_now - _SELL_SUBMISSION_RETRY_CLAIM_LEASE)
                            .isoformat()
                            .replace("+00:00", "Z"),
                            notes=durable_note(
                                "managed sell submission was not found by client order ID after recovery"
                            ),
                        )
                        if recovery_intent is None:
                            _append_reconciliation_result(
                                rows,
                                position_id=position_id,
                                symbol=symbol,
                                action="sell",
                                status="superseded",
                                buy_client_order_id=buy_client_order_id,
                                sell_client_order_id=sell_client_order_id,
                                qty=None,
                                limit_price=target_sell_price,
                                alpaca_order_id=None,
                                message="404 recovery was superseded or its safe retry quantity changed",
                            )
                            continue
                        recovery_qty = recovery_intent.remaining_qty
                        recovery_target_sell_price = recovery_intent.target_sell_price
                        retry_claim_state_revision = recovery_intent.state_revision
                        claimed_buy_is_open = str(recovery_intent.buy_status or "").lower() not in {
                            "filled",
                            *BUY_TERMINAL_STATUSES,
                        }
                        try:
                            active_historical_leaves, historical_audit_issue = (
                                _missing_sell_retry_historical_exposure_audit(
                                    conn=conn,
                                    client=client,
                                    position=position,
                                    allow_fenced_inactive_intent_mismatch=(historical_cancellation_was_fenced),
                                )
                            )
                        except (SellOrderIdentityError, RuntimeError, ValueError) as audit_exc:
                            active_historical_leaves = []
                            historical_audit_issue = f"historical managed sell audit failed: {audit_exc}"
                        if active_historical_leaves:
                            issue = historical_audit_issue or "historical managed sell exposure is still executable"
                            cancellation_requested_at = (
                                _utc_now()
                                .isoformat()
                                .replace(
                                    "+00:00",
                                    "Z",
                                )
                            )
                            cancellation_owned = update_alpaca_managed_sell_status_if_current(
                                conn=conn,
                                position_id=position_id,
                                expected_sell_client_order_id=sell_client_order_id,
                                expected_sell_submission_retry_claimed_at=retry_claimed_at,
                                expected_state_revision=retry_claim_state_revision,
                                sell_status="pending_cancel",
                                sell_renewal_requested_at=cancellation_requested_at,
                                notes=durable_note(
                                    "missing managed sell retry found executable historical exposure; "
                                    "cancellation ownership was durably fenced before broker requests"
                                ),
                            )
                            cancellation_message = (
                                "broker cancellation was not requested because durable historical-exposure "
                                "ownership changed"
                            )
                            if cancellation_owned:
                                _, cancellation_messages = _request_managed_sell_leaf_cancellations(
                                    client,
                                    active_historical_leaves,
                                )
                                cancellation_message = "; ".join(cancellation_messages)
                            _append_reconciliation_result(
                                rows,
                                position_id=position_id,
                                symbol=symbol,
                                action="sell",
                                status="pending_cancel" if cancellation_owned else "superseded",
                                buy_client_order_id=buy_client_order_id,
                                sell_client_order_id=sell_client_order_id,
                                qty=0.0,
                                limit_price=recovery_target_sell_price,
                                alpaca_order_id=None,
                                message=(f"missing-sell retry blocked: {issue}; {cancellation_message}"),
                                required_failure=True,
                            )
                            continue
                        if historical_audit_issue is not None:
                            _append_incomplete_sell_order_identity_result(
                                conn=conn,
                                rows=rows,
                                position_id=position_id,
                                symbol=symbol,
                                buy_client_order_id=buy_client_order_id,
                                sell_client_order_id=sell_client_order_id,
                                observed_sell_qty=0.0,
                                target_sell_price=recovery_target_sell_price,
                                identity_issue=f"missing-sell retry blocked: {historical_audit_issue}",
                                expected_sell_submission_retry_claimed_at=retry_claimed_at,
                                expected_sell_state_revision=retry_claim_state_revision,
                                clear_sell_submission_claim=True,
                            )
                            continue

                        live_position_asset_id, live_position_qty = _managed_live_position_identity_and_qty(
                            client.positions(),
                            symbol=symbol,
                            expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
                            symbol_aliases=position_aliases,
                        )
                        open_order_asset_ids = tuple(
                            asset_id
                            for asset_id in (
                                _optional_str(position.get("alpaca_asset_id")),
                                live_position_asset_id,
                            )
                            if asset_id is not None
                        )
                        try:
                            open_orders = client.open_orders(
                                equity_scope_asset_ids=open_order_asset_ids,
                            )
                        except _OpenOrderSnapshotError as exc:
                            _append_incomplete_sell_order_identity_result(
                                conn=conn,
                                rows=rows,
                                position_id=position_id,
                                symbol=symbol,
                                buy_client_order_id=buy_client_order_id,
                                sell_client_order_id=sell_client_order_id,
                                observed_sell_qty=0.0,
                                target_sell_price=recovery_target_sell_price,
                                identity_issue=f"missing-sell retry account snapshot was contradictory: {exc}",
                                expected_sell_submission_retry_claimed_at=retry_claimed_at,
                                expected_sell_state_revision=retry_claim_state_revision,
                                clear_sell_submission_claim=True,
                            )
                            continue
                        if _orders_have_open_order(
                            open_orders,
                            symbol,
                            "sell",
                            expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
                            symbol_aliases=position_aliases,
                        ):
                            _append_incomplete_sell_order_identity_result(
                                conn=conn,
                                rows=rows,
                                position_id=position_id,
                                symbol=symbol,
                                buy_client_order_id=buy_client_order_id,
                                sell_client_order_id=sell_client_order_id,
                                observed_sell_qty=0.0,
                                target_sell_price=recovery_target_sell_price,
                                identity_issue=(
                                    "missing-sell retry conflicts with an existing same-asset open sell order"
                                ),
                                expected_sell_submission_retry_claimed_at=retry_claimed_at,
                                expected_sell_state_revision=retry_claim_state_revision,
                                clear_sell_submission_claim=True,
                            )
                            continue

                        if current_sell_status in {"broker_inactive", "submission_failed"}:
                            expected_asset_id = _optional_str(position.get("alpaca_asset_id"))
                            try:
                                asset = client.asset(expected_asset_id or symbol)
                                observed_asset_id = _validated_alpaca_asset_id(
                                    asset,
                                    expected_symbol=symbol,
                                )
                            except Exception:
                                release_alpaca_managed_sell_submission_fence(
                                    conn,
                                    position_id,
                                    sell_client_order_id=sell_client_order_id,
                                    claimed_at=retry_claimed_at,
                                    expected_sell_status="submission_retrying",
                                    expected_state_revision=retry_claim_state_revision,
                                    sell_status=current_sell_status,
                                    notes=durable_note(
                                        "managed sell retry could not verify the current Alpaca asset state"
                                    ),
                                )
                                raise
                            asset_is_confirmed_inactive = bool(
                                expected_asset_id is not None
                                and observed_asset_id == expected_asset_id
                                and asset.get("status") == "inactive"
                                and asset.get("tradable") is False
                            )
                            same_asset_buy_is_open = _orders_have_open_order(
                                open_orders,
                                symbol,
                                "buy",
                                expected_alpaca_asset_id=expected_asset_id,
                                symbol_aliases=position_aliases,
                            )
                            live_qty_matches = _managed_sell_quantities_match(
                                recovery_qty,
                                live_position_qty,
                                mark_price=recovery_target_sell_price,
                            )
                            if asset_is_confirmed_inactive and live_qty_matches and not same_asset_buy_is_open:
                                quarantined = release_alpaca_managed_sell_submission_fence(
                                    conn,
                                    position_id,
                                    sell_client_order_id=sell_client_order_id,
                                    claimed_at=retry_claimed_at,
                                    expected_sell_status="submission_retrying",
                                    expected_state_revision=retry_claim_state_revision,
                                    sell_status="broker_inactive",
                                    notes=durable_note(
                                        "Alpaca paper account reports the exact held asset inactive and "
                                        "non-tradable; the holding remains broker-retained, blocks duplicate "
                                        "buys, and is monitored until Alpaca makes it tradable again"
                                    ),
                                )
                                _append_reconciliation_result(
                                    rows,
                                    position_id=position_id,
                                    symbol=symbol,
                                    action="sell",
                                    status="broker_inactive" if quarantined else "superseded",
                                    buy_client_order_id=buy_client_order_id,
                                    sell_client_order_id=sell_client_order_id,
                                    qty=recovery_qty,
                                    limit_price=recovery_target_sell_price,
                                    alpaca_order_id=None,
                                    message=(
                                        "Inactive, non-tradable paper holding retained at Alpaca; no "
                                        "executable sell is available, so the workflow records it "
                                        "separately, blocks new buys, and monitors for "
                                        "reactivation"
                                        if quarantined
                                        else "inactive-asset quarantine was superseded by concurrent managed state"
                                    ),
                                )
                                continue
                            if current_sell_status == "submission_failed" or same_asset_buy_is_open:
                                released = release_alpaca_managed_sell_submission_fence(
                                    conn,
                                    position_id,
                                    sell_client_order_id=sell_client_order_id,
                                    claimed_at=retry_claimed_at,
                                    expected_sell_status="submission_retrying",
                                    expected_state_revision=retry_claim_state_revision,
                                    sell_status=current_sell_status,
                                    notes=durable_note(
                                        "managed sell submission remains failed and requires review"
                                        if current_sell_status == "submission_failed"
                                        else (
                                            "inactive paper-position recovery is blocked by an open "
                                            "same-asset buy order"
                                        )
                                    ),
                                )
                                _append_reconciliation_result(
                                    rows,
                                    position_id=position_id,
                                    symbol=symbol,
                                    action="sell",
                                    status=current_sell_status if released else "superseded",
                                    buy_client_order_id=buy_client_order_id,
                                    sell_client_order_id=sell_client_order_id,
                                    qty=recovery_qty,
                                    limit_price=recovery_target_sell_price,
                                    alpaca_order_id=None,
                                    message=(
                                        "prior managed sell submission failed; the asset is not confirmed "
                                        "inactive and non-tradable, so automatic resubmission remains disabled"
                                        if current_sell_status == "submission_failed"
                                        else (
                                            "broker-inactive position has an open same-asset buy order; "
                                            "automatic recovery remains quarantined"
                                        )
                                    ),
                                    required_failure=released,
                                )
                                continue

                        confirmed_retry_state_revision = confirm_alpaca_managed_sell_submission_retry(
                            conn,
                            position_id,
                            sell_client_order_id=sell_client_order_id,
                            claimed_at=retry_claimed_at,
                            expected_state_revision=retry_claim_state_revision,
                            expected_remaining_qty=recovery_qty,
                            expected_target_sell_price=recovery_target_sell_price,
                        )
                        if confirmed_retry_state_revision is None:
                            released = release_alpaca_managed_sell_submission_fence(
                                conn,
                                position_id,
                                sell_client_order_id=sell_client_order_id,
                                claimed_at=retry_claimed_at,
                                expected_sell_status="submission_retrying",
                                expected_state_revision=retry_claim_state_revision,
                                allow_current_intent_rebase=True,
                                sell_status="submission_not_found",
                                notes=durable_note(
                                    "missing-sell retry changed during final broker exposure checks; "
                                    "no broker request was sent"
                                ),
                            )
                            _append_reconciliation_result(
                                rows,
                                position_id=position_id,
                                symbol=symbol,
                                action="sell",
                                status="superseded",
                                buy_client_order_id=buy_client_order_id,
                                sell_client_order_id=sell_client_order_id,
                                qty=None,
                                limit_price=recovery_target_sell_price,
                                alpaca_order_id=None,
                                message=(
                                    "missing-sell retry was superseded because its quantity, target, or managed "
                                    "state changed during final broker exposure checks"
                                    + ("; the in-flight token was released" if released else "")
                                ),
                            )
                            continue

                        _submit_managed_gtc_sell(
                            conn=conn,
                            client=client,
                            rows=rows,
                            position_id=position_id,
                            symbol=symbol,
                            buy_client_order_id=buy_client_order_id,
                            sell_client_order_id=sell_client_order_id,
                            filled_qty=recovery_qty,
                            target_sell_price=recovery_target_sell_price,
                            increment_renewal_count=False,
                            replacement_message=(
                                "resubmitted managed GTC limit sell after prior submission was not found"
                            ),
                            live_position_qty=live_position_qty,
                            close_on_complete=not claimed_buy_is_open,
                            intent_already_persisted=True,
                            sell_order_namespace=_optional_str(position.get("sell_order_namespace")),
                            intent_not_before=_optional_str(position.get("created_at")),
                            sell_submission_retry_claimed_at=retry_claimed_at,
                            expected_sell_state_revision=confirmed_retry_state_revision,
                            expected_sell_submission_status="submission_retrying",
                            expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
                            allow_fenced_inactive_historical_intent_mismatch=(historical_cancellation_was_fenced),
                        )
                        continue
                    raise
                broker_sell_status = _broker_order_status(sell_order, default="unknown")
                persisted_sell_alpaca_order_id = _optional_str(position.get("sell_alpaca_order_id"))
                sell_lineage_asset_id = _replacement_chain_stable_asset_id(sell_replacement_chain)
                accepted_position_asset_ids = frozenset(alpaca_managed_position_asset_ids(position))
                expected_sell_identity_asset_id = _optional_str(position.get("alpaca_asset_id"))
                if sell_lineage_asset_id in accepted_position_asset_ids:
                    expected_sell_identity_asset_id = sell_lineage_asset_id
                if not _sell_order_identity_is_consistent(
                    sell_order,
                    expected_sell_client_order_id=sell_client_order_id,
                    expected_sell_alpaca_order_id=persisted_sell_alpaca_order_id,
                    expected_symbol=symbol,
                    expected_alpaca_asset_id=expected_sell_identity_asset_id,
                    replacement_chain=sell_replacement_chain,
                ):
                    _append_incomplete_sell_order_identity_result(
                        conn=conn,
                        rows=rows,
                        position_id=position_id,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        observed_sell_qty=_sell_fill_metadata(sell_order)[0],
                        target_sell_price=float(target_sell_price),
                        sell_alpaca_order_id=_optional_str(sell_order.get("id")),
                        identity_issue="broker response does not match the persisted managed sell order",
                        expected_sell_status=_optional_str(position.get("sell_status")),
                        expected_sell_alpaca_order_id=persisted_sell_alpaca_order_id,
                        expected_sell_filled_qty=_optional_float(position.get("sell_filled_qty")),
                        expected_sell_renewal_count=int(position.get("sell_renewal_count") or 0),
                        expected_sell_state_revision=int(position["state_revision"]),
                    )
                    continue
                sell_alpaca_order_id = _optional_str(sell_order.get("id")) or persisted_sell_alpaca_order_id
                sell_expires_at = _optional_alpaca_datetime_str(sell_order.get("expires_at"))
                terminal_sell_filled_qty, _, terminal_fill_metadata_is_valid = _sell_fill_metadata(sell_order)
                sell_order_qty = _optional_positive_float(sell_order.get("qty"))
                sell_order_limit_price = _optional_positive_float(sell_order.get("limit_price"))
                submitted_sell_qty = _optional_positive_float(position.get("sell_order_qty"))
                if submitted_sell_qty is None:
                    submitted_sell_qty = _optional_positive_float(sell_replacement_chain[0].get("qty"))
                if submitted_sell_qty is None:
                    submitted_sell_qty = _managed_remaining_qty(position, float(filled_qty))
                submitted_sell_limit_price = _optional_positive_float(position.get("sell_order_limit_price"))
                if submitted_sell_limit_price is None:
                    submitted_sell_limit_price = _optional_positive_float(sell_replacement_chain[0].get("limit_price"))
                if submitted_sell_limit_price is None:
                    submitted_sell_limit_price = float(target_sell_price)
                sell_intent_issue = _sell_replacement_chain_intent_issue(
                    sell_replacement_chain,
                    requested_qty=submitted_sell_qty,
                    target_sell_price=submitted_sell_limit_price,
                )
                sell_position_intent_issue = _sell_replacement_chain_position_intent_issue(sell_replacement_chain)
                sell_non_fill_intent_issue = _sell_replacement_chain_non_fill_intent_issue(
                    sell_replacement_chain,
                    requested_qty=submitted_sell_qty,
                    target_sell_price=submitted_sell_limit_price,
                )
                attributed_lineage_requires_cancellation = _attributed_lineage_requires_cancellation(
                    sell_replacement_chain
                )
                non_fill_intent_cancellation_pending = bool(
                    sell_non_fill_intent_issue is not None and attributed_lineage_requires_cancellation
                )
                inherited_cancellation_pending = bool(
                    str(position.get("sell_status") or "").lower() == "pending_cancel"
                    and _optional_str(position.get("sell_renewal_requested_at")) is not None
                    and _attributed_lineage_has_cancellable_order(sell_replacement_chain)
                )
                cancellation_retry_pending = bool(
                    non_fill_intent_cancellation_pending or inherited_cancellation_pending
                )
                cancellation_intent_issue = (
                    sell_non_fill_intent_issue
                    or sell_intent_issue
                    or "managed sell cancellation remains pending from an earlier exact recovery fence"
                )
                verified_persisted_replacement_successor = bool(
                    persisted_sell_alpaca_order_id is not None
                    and sell_alpaca_order_id is not None
                    and sell_alpaca_order_id != persisted_sell_alpaca_order_id
                    and persisted_sell_alpaca_order_id
                    in {
                        order_id
                        for node in sell_replacement_chain
                        if (order_id := _optional_str(node.get("id"))) is not None
                    }
                )
                sell_status = _sell_status_after_pending_cancel(
                    persisted_status=position.get("sell_status"),
                    observed_status=broker_sell_status,
                    observed_is_verified_replacement_successor=(verified_persisted_replacement_successor),
                )
                non_fill_cancellation_requested_at = None
                if cancellation_retry_pending:
                    sell_status = "pending_cancel"
                    non_fill_cancellation_requested_at = _optional_str(
                        position.get("sell_renewal_requested_at")
                    ) or _utc_now().isoformat().replace("+00:00", "Z")
                observation_is_current = update_alpaca_managed_sell_status_if_current(
                    conn,
                    position_id,
                    expected_sell_client_order_id=sell_client_order_id,
                    expected_sell_status=_optional_str(position.get("sell_status")),
                    expected_sell_alpaca_order_id=persisted_sell_alpaca_order_id,
                    expected_sell_filled_qty=_optional_float(position.get("sell_filled_qty")),
                    expected_sell_renewal_count=int(position.get("sell_renewal_count") or 0),
                    expected_buy_status=_optional_str(position.get("buy_status")),
                    expected_buy_filled_qty=_optional_float(position.get("filled_qty")),
                    expected_buy_filled_avg_price=_optional_float(position.get("filled_avg_price")),
                    expected_target_sell_price=_optional_float(position.get("target_sell_price")),
                    expected_remaining_qty=_managed_remaining_qty(position, float(filled_qty)),
                    expected_state_revision=int(position["state_revision"]),
                    sell_status=sell_status,
                    sell_alpaca_order_id=sell_alpaca_order_id,
                    sell_submitted_at=_optional_alpaca_datetime_str(sell_order.get("submitted_at")),
                    sell_expires_at=sell_expires_at,
                    sell_order_qty=submitted_sell_qty,
                    sell_order_limit_price=submitted_sell_limit_price,
                    sell_renewal_requested_at=non_fill_cancellation_requested_at,
                    notes=durable_note(
                        f"{sell_non_fill_intent_issue}; cancellation ownership was fenced before any broker request"
                        if cancellation_retry_pending
                        else None
                    ),
                    observed_sell_filled_qty=(
                        terminal_sell_filled_qty
                        if terminal_fill_metadata_is_valid and not cancellation_retry_pending
                        else _STORAGE_UNSET
                    ),
                    sell_broker_updated_at=(
                        _STORAGE_UNSET
                        if cancellation_retry_pending
                        else _optional_alpaca_datetime_str(sell_order.get("updated_at"))
                    ),
                    allow_verified_replaced_successor=verified_persisted_replacement_successor,
                )
                if not observation_is_current:
                    sticky_status = alpaca_managed_sell_sticky_status_if_current(
                        conn,
                        position_id,
                        expected_sell_client_order_id=sell_client_order_id,
                    )
                    if sticky_status is not None:
                        _append_reconciliation_result(
                            rows,
                            position_id=position_id,
                            symbol=symbol,
                            action="sell",
                            status=sticky_status,
                            buy_client_order_id=buy_client_order_id,
                            sell_client_order_id=sell_client_order_id,
                            qty=None,
                            limit_price=target_sell_price,
                            alpaca_order_id=sell_alpaca_order_id,
                            message=(
                                f"managed sell remains in sticky state {sticky_status}; "
                                f"broker status {sell_status} cannot clear a sticky local state"
                            ),
                            required_failure=True,
                        )
                        continue
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="sell",
                        status="superseded",
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=None,
                        limit_price=target_sell_price,
                        alpaca_order_id=sell_alpaca_order_id,
                        message="broker observation belongs to a superseded managed GTC sell generation",
                    )
                    continue
                position["sell_alpaca_order_id"] = sell_alpaca_order_id
                position["sell_status"] = sell_status
                position["sell_order_qty"] = submitted_sell_qty
                position["sell_order_limit_price"] = submitted_sell_limit_price
                if non_fill_cancellation_requested_at is not None:
                    position["sell_renewal_requested_at"] = non_fill_cancellation_requested_at
                if observed_submitted_at := _optional_alpaca_datetime_str(sell_order.get("submitted_at")):
                    position["sell_submitted_at"] = observed_submitted_at
                if sell_expires_at is not None:
                    position["sell_expires_at"] = sell_expires_at
                remaining_qty = _managed_remaining_qty(position, float(filled_qty))
                observed_sell_qty, observed_sell_avg_price, fill_metadata_is_valid = _replacement_chain_fill_metadata(
                    sell_replacement_chain
                )
                sell_residual_mark_price = _managed_sell_residual_mark_price(
                    target_sell_price,
                    filled_avg_price,
                    sell_order_limit_price,
                    submitted_sell_limit_price,
                    observed_sell_avg_price,
                    *(order.get("limit_price") for order in sell_replacement_chain),
                )
                observation_snapshot = (
                    None
                    if filled_avg_price is None
                    else _managed_sell_replacement_snapshot_if_current(
                        conn,
                        position_id=position_id,
                        sell_client_order_id=sell_client_order_id,
                        sell_alpaca_order_id=sell_alpaca_order_id,
                        sell_renewal_requested_at=_optional_str(position.get("sell_renewal_requested_at")),
                        expected_buy_status=_optional_str(position.get("buy_status")),
                        expected_buy_filled_qty=float(filled_qty),
                        expected_buy_filled_avg_price=float(filled_avg_price),
                        expected_target_sell_price=float(target_sell_price),
                        expected_remaining_qty=remaining_qty,
                        expected_sell_status=sell_status,
                        expected_sell_renewal_count=_optional_int(position.get("sell_renewal_count")),
                    )
                )
                if observation_snapshot is None:
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="sell",
                        status="superseded",
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=observed_sell_qty,
                        limit_price=target_sell_price,
                        alpaca_order_id=sell_alpaca_order_id,
                        message="managed sell observation lost its exact post-persistence snapshot",
                    )
                    continue
                if sell_position_intent_issue is not None:
                    _append_sell_submission_intent_mismatch_result(
                        conn=conn,
                        client=client,
                        rows=rows,
                        position_id=position_id,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        requested_qty=submitted_sell_qty,
                        target_sell_price=submitted_sell_limit_price,
                        sell_order=sell_order,
                        replacement_chain=sell_replacement_chain,
                        intent_issue=sell_position_intent_issue,
                        expected_renewal_snapshot=observation_snapshot,
                    )
                    continue
                if not fill_metadata_is_valid or (sell_status == "filled" and observed_sell_qty == 0.0):
                    if cancellation_retry_pending:
                        _append_sell_submission_intent_mismatch_result(
                            conn=conn,
                            client=client,
                            rows=rows,
                            position_id=position_id,
                            symbol=symbol,
                            buy_client_order_id=buy_client_order_id,
                            sell_client_order_id=sell_client_order_id,
                            requested_qty=submitted_sell_qty,
                            target_sell_price=submitted_sell_limit_price,
                            sell_order=sell_order,
                            replacement_chain=sell_replacement_chain,
                            intent_issue=cancellation_intent_issue,
                            expected_renewal_snapshot=observation_snapshot,
                        )
                        continue
                    _append_incomplete_sell_fill_result(
                        conn=conn,
                        rows=rows,
                        position_id=position_id,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        observed_sell_qty=observed_sell_qty,
                        target_sell_price=float(target_sell_price),
                        sell_alpaca_order_id=sell_alpaca_order_id,
                        expected_renewal_snapshot=observation_snapshot,
                    )
                    continue
                if observed_sell_qty > 0.0 and not sell_alpaca_order_id:
                    _append_incomplete_sell_order_identity_result(
                        conn=conn,
                        rows=rows,
                        position_id=position_id,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        observed_sell_qty=observed_sell_qty,
                        target_sell_price=float(target_sell_price),
                        sell_alpaca_order_id=sell_alpaca_order_id,
                        expected_renewal_snapshot=observation_snapshot,
                    )
                    continue
                try:
                    remaining_qty, fill_generation_is_current = _record_replacement_chain_sell_fills(
                        conn=conn,
                        position_id=position_id,
                        sell_client_order_id=sell_client_order_id,
                        replacement_chain=sell_replacement_chain,
                        initial_remaining_qty=remaining_qty,
                        expected_renewal_snapshot=observation_snapshot,
                        preserve_pending_cancel=cancellation_retry_pending,
                    )
                except SellFillQuantityRegressionError:
                    if cancellation_retry_pending:
                        _append_sell_submission_intent_mismatch_result(
                            conn=conn,
                            client=client,
                            rows=rows,
                            position_id=position_id,
                            symbol=symbol,
                            buy_client_order_id=buy_client_order_id,
                            sell_client_order_id=sell_client_order_id,
                            requested_qty=submitted_sell_qty,
                            target_sell_price=submitted_sell_limit_price,
                            sell_order=sell_order,
                            replacement_chain=sell_replacement_chain,
                            intent_issue=(
                                f"{cancellation_intent_issue}; Alpaca sell filled quantity "
                                "moved backwards for a managed order"
                            ),
                            expected_renewal_snapshot=observation_snapshot,
                        )
                        continue
                    _append_sell_fill_quantity_regression_result(
                        conn=conn,
                        rows=rows,
                        position_id=position_id,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        observed_sell_qty=observed_sell_qty,
                        target_sell_price=float(target_sell_price),
                        sell_alpaca_order_id=sell_alpaca_order_id,
                        expected_renewal_snapshot=observation_snapshot,
                    )
                    continue
                if not fill_generation_is_current:
                    if cancellation_retry_pending:
                        post_accounting_snapshot = alpaca_managed_sell_renewal_snapshot_if_current(
                            conn,
                            position_id,
                            expected_sell_client_order_id=sell_client_order_id,
                            expected_sell_alpaca_order_id=sell_alpaca_order_id,
                            expected_sell_renewal_requested_at=observation_snapshot.requested_at,
                        )
                        cancellation_snapshot = (
                            post_accounting_snapshot
                            if post_accounting_snapshot is not None
                            and _managed_sell_snapshots_have_same_premise(
                                post_accounting_snapshot,
                                observation_snapshot,
                            )
                            else None
                        )
                        _append_sell_submission_intent_mismatch_result(
                            conn=conn,
                            client=client,
                            rows=rows,
                            position_id=position_id,
                            symbol=symbol,
                            buy_client_order_id=buy_client_order_id,
                            sell_client_order_id=sell_client_order_id,
                            requested_qty=submitted_sell_qty,
                            target_sell_price=submitted_sell_limit_price,
                            sell_order=sell_order,
                            replacement_chain=sell_replacement_chain,
                            intent_issue=(
                                f"{cancellation_intent_issue}; broker fill revision was not newer "
                                "than persisted accounting"
                            ),
                            expected_renewal_snapshot=cancellation_snapshot,
                        )
                        continue
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="sell",
                        status="superseded",
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=observed_sell_qty,
                        limit_price=target_sell_price,
                        alpaca_order_id=sell_alpaca_order_id,
                        message="fill observation belongs to a superseded managed GTC sell generation",
                    )
                    continue
                post_fill_snapshot = (
                    None
                    if sell_alpaca_order_id is None or filled_avg_price is None
                    else _managed_sell_replacement_snapshot_if_current(
                        conn,
                        position_id=position_id,
                        sell_client_order_id=sell_client_order_id,
                        sell_alpaca_order_id=sell_alpaca_order_id,
                        sell_renewal_requested_at=_optional_str(position.get("sell_renewal_requested_at")),
                        expected_buy_status=_optional_str(position.get("buy_status")),
                        expected_buy_filled_qty=float(filled_qty),
                        expected_buy_filled_avg_price=float(filled_avg_price),
                        expected_target_sell_price=float(target_sell_price),
                        expected_remaining_qty=remaining_qty,
                        expected_sell_status=(
                            "pending_cancel"
                            if cancellation_retry_pending
                            else "quantity_mismatch"
                            if _managed_sell_is_overfilled(
                                remaining_qty,
                                filled_qty,
                                observed_sell_qty,
                                mark_price=sell_residual_mark_price,
                            )
                            else sell_status
                        ),
                        expected_sell_renewal_count=_optional_int(position.get("sell_renewal_count")),
                    )
                )
                if post_fill_snapshot is None:
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="sell",
                        status="superseded",
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=observed_sell_qty,
                        limit_price=target_sell_price,
                        alpaca_order_id=sell_alpaca_order_id,
                        message="managed sell fill observation lost its exact post-accounting snapshot",
                    )
                    continue
                if cancellation_retry_pending:
                    _append_sell_submission_intent_mismatch_result(
                        conn=conn,
                        client=client,
                        rows=rows,
                        position_id=position_id,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        requested_qty=submitted_sell_qty,
                        target_sell_price=submitted_sell_limit_price,
                        sell_order=sell_order,
                        replacement_chain=sell_replacement_chain,
                        intent_issue=cancellation_intent_issue,
                        expected_renewal_snapshot=post_fill_snapshot,
                    )
                    continue
                remaining_qty_before_historical_audit = remaining_qty
                try:
                    (
                        remaining_qty,
                        active_historical_leaves,
                        historical_intent_issue,
                        resolved_historical_audit,
                        historical_sell_mark_price,
                    ) = _record_active_historical_sell_fills(
                        conn=conn,
                        client=client,
                        position=position,
                        current_replacement_chain=sell_replacement_chain,
                        initial_remaining_qty=remaining_qty,
                    )
                    sell_residual_mark_price = max(
                        sell_residual_mark_price,
                        historical_sell_mark_price,
                    )
                except SellFillQuantityRegressionError:
                    _append_sell_fill_quantity_regression_result(
                        conn=conn,
                        rows=rows,
                        position_id=position_id,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        observed_sell_qty=observed_sell_qty,
                        target_sell_price=float(target_sell_price),
                        sell_alpaca_order_id=sell_alpaca_order_id,
                        expected_renewal_snapshot=post_fill_snapshot,
                    )
                    continue
                except SellFillMetadataError as exc:
                    _append_incomplete_sell_fill_result(
                        conn=conn,
                        rows=rows,
                        position_id=position_id,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        observed_sell_qty=exc.observed_qty,
                        target_sell_price=float(target_sell_price),
                        sell_alpaca_order_id=sell_alpaca_order_id,
                        expected_renewal_snapshot=post_fill_snapshot,
                    )
                    continue
                except (SellOrderIdentityError, RuntimeError, ValueError) as exc:
                    _append_incomplete_sell_order_identity_result(
                        conn=conn,
                        rows=rows,
                        position_id=position_id,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        observed_sell_qty=observed_sell_qty,
                        target_sell_price=float(target_sell_price),
                        sell_alpaca_order_id=sell_alpaca_order_id,
                        identity_issue=f"historical managed sell audit failed: {exc}",
                        expected_renewal_snapshot=post_fill_snapshot,
                    )
                    continue

                replacement_snapshot = (
                    None
                    if sell_alpaca_order_id is None or filled_avg_price is None
                    else _managed_sell_replacement_snapshot_if_current(
                        conn,
                        position_id=position_id,
                        sell_client_order_id=sell_client_order_id,
                        sell_alpaca_order_id=sell_alpaca_order_id,
                        sell_renewal_requested_at=_optional_str(position.get("sell_renewal_requested_at")),
                        expected_buy_status=_optional_str(position.get("buy_status")),
                        expected_buy_filled_qty=float(filled_qty),
                        expected_buy_filled_avg_price=float(filled_avg_price),
                        expected_target_sell_price=float(target_sell_price),
                        expected_remaining_qty=remaining_qty,
                        expected_sell_status=(
                            "quantity_mismatch"
                            if _managed_sell_is_overfilled(
                                remaining_qty,
                                filled_qty,
                                observed_sell_qty,
                                mark_price=sell_residual_mark_price,
                            )
                            else sell_status
                        ),
                        expected_sell_renewal_count=_optional_int(position.get("sell_renewal_count")),
                    )
                )

                current_leaf = sell_replacement_chain[-1]
                current_leaf_is_active = _broker_order_status(current_leaf) in _ORDER_MAY_BE_ACTIVE_STATUSES
                unexpected_active_current_orders = [
                    order
                    for order in sell_replacement_chain[:-1]
                    if _broker_order_status(order) in _ORDER_MAY_BE_ACTIVE_STATUSES
                ]
                current_leaf_qty = _optional_positive_float(current_leaf.get("qty"))
                current_leaf_filled_qty, _, current_leaf_fill_is_valid = _sell_fill_metadata(current_leaf)
                current_leaf_open_qty = (
                    None
                    if current_leaf_qty is None or not current_leaf_fill_is_valid
                    else max(current_leaf_qty - current_leaf_filled_qty, 0.0)
                )
                historical_fill_lowered_remaining = (
                    remaining_qty < remaining_qty_before_historical_audit
                    and not _managed_sell_quantities_match(
                        remaining_qty,
                        remaining_qty_before_historical_audit,
                        filled_qty,
                        observed_sell_qty,
                        mark_price=sell_residual_mark_price,
                    )
                )
                current_leaf_is_oversized = bool(
                    current_leaf_is_active
                    and (
                        current_leaf_open_qty is None
                        or (
                            current_leaf_open_qty > max(remaining_qty, 0.0)
                            and not _managed_sell_quantities_match(
                                current_leaf_open_qty,
                                max(remaining_qty, 0.0),
                                mark_price=sell_residual_mark_price,
                            )
                        )
                    )
                )
                if active_historical_leaves or unexpected_active_current_orders or current_leaf_is_oversized:
                    unsafe_leaves = _deduplicated_managed_sell_leaves(
                        [current_leaf]
                        if current_leaf_is_active
                        and (active_historical_leaves or unexpected_active_current_orders or current_leaf_is_oversized)
                        else [],
                        {
                            str(leaf["id"]): leaf
                            for leaf in [*active_historical_leaves, *unexpected_active_current_orders]
                            if _optional_str(leaf.get("id")) is not None
                        },
                    )
                    exposure_issue = (
                        "historical managed sell exposure is still executable"
                        if active_historical_leaves
                        else "a non-leaf managed sell replacement generation is still executable"
                        if unexpected_active_current_orders
                        else (
                            "a historical sell fill lowered remaining managed quantity and left the "
                            "current sell oversized"
                            if historical_fill_lowered_remaining
                            else "the current managed sell has executable quantity above the remaining position"
                        )
                    )
                    if replacement_snapshot is None:
                        _append_reconciliation_result(
                            rows,
                            position_id=position_id,
                            symbol=symbol,
                            action="sell",
                            status="superseded",
                            buy_client_order_id=buy_client_order_id,
                            sell_client_order_id=sell_client_order_id,
                            qty=remaining_qty,
                            limit_price=target_sell_price,
                            alpaca_order_id=sell_alpaca_order_id,
                            message=(
                                f"{exposure_issue}; managed cancellation premise changed before any broker request"
                            ),
                        )
                        continue
                    active_unsafe_leaves = _active_managed_sell_leaves(unsafe_leaves)
                    cancellation_requested_at = _utc_now().isoformat().replace("+00:00", "Z")
                    diagnostic_status = "pending_cancel"
                    status_updated = update_alpaca_managed_sell_status_if_current(
                        conn,
                        position_id,
                        expected_sell_client_order_id=sell_client_order_id,
                        **_renewal_snapshot_cas_kwargs(replacement_snapshot),
                        sell_status=diagnostic_status,
                        sell_renewal_requested_at=cancellation_requested_at,
                        notes=durable_note(
                            f"{exposure_issue}; cancellation ownership was fenced before broker requests"
                        ),
                    )
                    cancellation_messages = ["broker cancellation was not requested because managed ownership changed"]
                    if status_updated:
                        _pending, cancellation_messages = _request_managed_sell_leaf_cancellations(
                            client,
                            active_unsafe_leaves,
                        )
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="sell",
                        status=diagnostic_status if status_updated else "superseded",
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=remaining_qty,
                        limit_price=target_sell_price,
                        alpaca_order_id=sell_alpaca_order_id,
                        message=(
                            "attributed managed sell cancellation was fenced before coverage could be trusted; "
                            + "; ".join(cancellation_messages)
                            if status_updated
                            else "managed sell cancellation was superseded by concurrent managed state"
                        ),
                        required_failure=status_updated,
                    )
                    continue
                if historical_intent_issue is not None:
                    if replacement_snapshot is None:
                        _append_reconciliation_result(
                            rows,
                            position_id=position_id,
                            symbol=symbol,
                            action="sell",
                            status="superseded",
                            buy_client_order_id=buy_client_order_id,
                            sell_client_order_id=sell_client_order_id,
                            qty=observed_sell_qty,
                            limit_price=target_sell_price,
                            alpaca_order_id=sell_alpaca_order_id,
                            message="historical sell-intent audit was superseded by concurrent managed state",
                        )
                        continue
                    _append_incomplete_sell_order_identity_result(
                        conn=conn,
                        rows=rows,
                        position_id=position_id,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        observed_sell_qty=observed_sell_qty,
                        target_sell_price=float(target_sell_price),
                        sell_alpaca_order_id=sell_alpaca_order_id,
                        identity_issue=f"historical managed sell intent mismatch: {historical_intent_issue}",
                        expected_renewal_snapshot=replacement_snapshot,
                    )
                    continue
                cancellation_replacement_ready = bool(
                    sell_status in SELL_REPLACEMENT_SAFE_STATUSES
                    and _optional_str(position.get("sell_renewal_requested_at")) is not None
                )

                if _managed_sell_is_overfilled(
                    remaining_qty,
                    filled_qty,
                    observed_sell_qty,
                    mark_price=sell_residual_mark_price,
                ):
                    _append_overfilled_sell_result(
                        conn=conn,
                        rows=rows,
                        position_id=position_id,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        observed_sell_qty=observed_sell_qty,
                        target_sell_price=float(target_sell_price),
                        sell_alpaca_order_id=sell_alpaca_order_id,
                        expected_renewal_snapshot=replacement_snapshot,
                    )
                    continue

                if (
                    sell_intent_issue is not None
                    and not cancellation_replacement_ready
                    and not _managed_sell_is_complete(
                        remaining_qty,
                        filled_qty,
                        observed_sell_qty,
                        mark_price=sell_residual_mark_price,
                    )
                ):
                    if replacement_snapshot is None:
                        _append_reconciliation_result(
                            rows,
                            position_id=position_id,
                            symbol=symbol,
                            action="sell",
                            status="superseded",
                            buy_client_order_id=buy_client_order_id,
                            sell_client_order_id=sell_client_order_id,
                            qty=submitted_sell_qty,
                            limit_price=submitted_sell_limit_price,
                            alpaca_order_id=sell_alpaca_order_id,
                            message=(
                                "managed sell intent-mismatch premise changed before any broker cancellation request"
                            ),
                        )
                        continue
                    _append_sell_submission_intent_mismatch_result(
                        conn=conn,
                        client=client,
                        rows=rows,
                        position_id=position_id,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        requested_qty=submitted_sell_qty,
                        target_sell_price=submitted_sell_limit_price,
                        sell_order=sell_order,
                        replacement_chain=sell_replacement_chain,
                        intent_issue=sell_intent_issue,
                        expected_renewal_snapshot=replacement_snapshot,
                    )
                    continue
                confirmed_closed_sell_shortfall = bool(
                    sell_status in {"filled", *SELL_REPLACEMENT_SAFE_STATUSES}
                    and bool(position.get("closed_sell_shortfall_reopen_pending"))
                    and _managed_sell_has_shortfall(
                        remaining_qty,
                        filled_qty,
                        observed_sell_qty,
                        mark_price=sell_residual_mark_price,
                    )
                    and sell_intent_issue is None
                )
                if confirmed_closed_sell_shortfall:
                    # Fill recording above returns the authoritative remaining
                    # quantity across every historical sell generation.  Do not
                    # compare a current replacement chain's fill to global sold
                    # quantity: that strands reopened shares after two renewals.
                    position["sell_status"] = sell_status
                    if replacement_snapshot is None:
                        _append_reconciliation_result(
                            rows,
                            position_id=position_id,
                            symbol=symbol,
                            action="sell",
                            status="superseded",
                            buy_client_order_id=buy_client_order_id,
                            sell_client_order_id=sell_client_order_id,
                            qty=remaining_qty,
                            limit_price=target_sell_price,
                            alpaca_order_id=sell_alpaca_order_id,
                            message=("managed sell replacement premise changed before its exact submission claim"),
                        )
                        continue
                    _submit_replacement_gtc_sell(
                        conn=conn,
                        client=client,
                        rows=rows,
                        position=position,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        filled_qty=remaining_qty,
                        target_sell_price=float(target_sell_price),
                        quantity_mark_price=sell_residual_mark_price,
                        replacement_message=(
                            "an authoritative closed-position broker correction exposed uncovered shares; "
                            "submitted replacement protection for the uncovered shares"
                        ),
                        check_open_order=True,
                        live_position_qty=load_live_position_qty(),
                        close_on_complete=not buy_is_open,
                        expected_renewal_snapshot=replacement_snapshot,
                    )
                    continue
                if _managed_sell_is_complete(
                    remaining_qty,
                    filled_qty,
                    observed_sell_qty,
                    mark_price=sell_residual_mark_price,
                ):
                    active_sell_leaves, exposure_close_issue = _managed_sell_exposure_close_audit(
                        conn=conn,
                        client=client,
                        position=position,
                        current_replacement_chain=sell_replacement_chain,
                        current_intent_issue=sell_intent_issue,
                        resolved_historical_audit=resolved_historical_audit,
                    )
                    if exposure_close_issue is not None and not active_sell_leaves:
                        if sell_intent_issue is not None:
                            if replacement_snapshot is None:
                                _append_reconciliation_result(
                                    rows,
                                    position_id=position_id,
                                    symbol=symbol,
                                    action="sell",
                                    status="superseded",
                                    buy_client_order_id=buy_client_order_id,
                                    sell_client_order_id=sell_client_order_id,
                                    qty=submitted_sell_qty,
                                    limit_price=submitted_sell_limit_price,
                                    alpaca_order_id=sell_alpaca_order_id,
                                    message=(
                                        "balanced-position intent-mismatch premise changed before any "
                                        "broker cancellation request"
                                    ),
                                )
                                continue
                            _append_sell_submission_intent_mismatch_result(
                                conn=conn,
                                client=client,
                                rows=rows,
                                position_id=position_id,
                                symbol=symbol,
                                buy_client_order_id=buy_client_order_id,
                                sell_client_order_id=sell_client_order_id,
                                requested_qty=submitted_sell_qty,
                                target_sell_price=submitted_sell_limit_price,
                                sell_order=sell_order,
                                replacement_chain=sell_replacement_chain,
                                intent_issue=sell_intent_issue,
                                expected_renewal_snapshot=replacement_snapshot,
                            )
                            continue
                        status_updated = bool(replacement_snapshot) and (
                            update_alpaca_managed_sell_status_if_current(
                                conn,
                                position_id,
                                expected_sell_client_order_id=sell_client_order_id,
                                **_renewal_snapshot_cas_kwargs(replacement_snapshot),
                                sell_status="incomplete_order_metadata",
                                notes=durable_note(
                                    "managed sell closure remains quarantined because all attributed sell "
                                    f"exposure could not be confirmed: {exposure_close_issue}"
                                ),
                            )
                        )
                        _append_reconciliation_result(
                            rows,
                            position_id=position_id,
                            symbol=symbol,
                            action="sell",
                            status="incomplete_order_metadata" if status_updated else "superseded",
                            buy_client_order_id=buy_client_order_id,
                            sell_client_order_id=sell_client_order_id,
                            qty=observed_sell_qty,
                            limit_price=target_sell_price,
                            alpaca_order_id=sell_alpaca_order_id,
                            message=(
                                "balanced managed position remains active because complete inactive sell "
                                f"exposure could not be proven: {exposure_close_issue}"
                            ),
                            required_failure=status_updated,
                        )
                        continue
                    if active_sell_leaves:
                        if replacement_snapshot is None:
                            _append_reconciliation_result(
                                rows,
                                position_id=position_id,
                                symbol=symbol,
                                action="sell",
                                status="superseded",
                                buy_client_order_id=buy_client_order_id,
                                sell_client_order_id=sell_client_order_id,
                                qty=observed_sell_qty,
                                limit_price=target_sell_price,
                                alpaca_order_id=sell_alpaca_order_id,
                                message=("balanced-position cancellation premise changed before any broker request"),
                            )
                            continue
                        cancellation_requested_at = _utc_now().isoformat().replace("+00:00", "Z")
                        status_updated = update_alpaca_managed_sell_status_if_current(
                            conn,
                            position_id,
                            expected_sell_client_order_id=sell_client_order_id,
                            **_renewal_snapshot_cas_kwargs(replacement_snapshot),
                            sell_status="pending_cancel",
                            sell_renewal_requested_at=cancellation_requested_at,
                            notes=durable_note(
                                "managed quantity is fully sold but attributed sell exposure remains active; "
                                "cancellation ownership was fenced before broker requests"
                            ),
                        )
                        if not status_updated:
                            _append_reconciliation_result(
                                rows,
                                position_id=position_id,
                                symbol=symbol,
                                action="sell",
                                status="superseded",
                                buy_client_order_id=buy_client_order_id,
                                sell_client_order_id=sell_client_order_id,
                                qty=observed_sell_qty,
                                limit_price=target_sell_price,
                                alpaca_order_id=sell_alpaca_order_id,
                                message=("balanced-position cancellation ownership changed before any broker request"),
                            )
                            continue
                        _cancellation_pending, cancellation_messages = _request_managed_sell_leaf_cancellations(
                            client, active_sell_leaves
                        )
                        if exposure_close_issue is not None:
                            cancellation_messages.append(f"closure remains quarantined: {exposure_close_issue}")
                        _append_reconciliation_result(
                            rows,
                            position_id=position_id,
                            symbol=symbol,
                            action="sell",
                            status="pending_cancel",
                            buy_client_order_id=buy_client_order_id,
                            sell_client_order_id=sell_client_order_id,
                            qty=observed_sell_qty,
                            limit_price=target_sell_price,
                            alpaca_order_id=sell_alpaca_order_id,
                            message=(
                                "balanced managed position remains active until every attributed sell leaf is "
                                f"inactive; {'; '.join(cancellation_messages)}"
                            ),
                            required_failure=True,
                        )
                        continue
                    if not buy_is_open:
                        assert sell_alpaca_order_id is not None
                        if replacement_snapshot is None:
                            _append_reconciliation_result(
                                rows,
                                position_id=position_id,
                                symbol=symbol,
                                action="sell",
                                status="superseded",
                                buy_client_order_id=buy_client_order_id,
                                sell_client_order_id=sell_client_order_id,
                                qty=observed_sell_qty,
                                limit_price=target_sell_price,
                                alpaca_order_id=sell_alpaca_order_id,
                                message="position closure premise changed before the exact close claim",
                            )
                            continue
                        closed = close_alpaca_managed_position_if_current_and_complete(
                            conn,
                            position_id,
                            expected_sell_client_order_id=sell_client_order_id,
                            expected_sell_alpaca_order_id=sell_alpaca_order_id,
                            closed_at=_optional_alpaca_datetime_str(sell_order.get("filled_at")),
                            expected_sell_status=sell_status,
                            expected_sell_filled_qty=replacement_snapshot.sell_filled_qty,
                            expected_sell_renewal_count=replacement_snapshot.sell_renewal_count,
                            expected_sell_renewal_requested_at=replacement_snapshot.requested_at,
                            expected_state_revision=replacement_snapshot.state_revision,
                            notes=durable_note("managed target sell filled"),
                        )
                        if not closed:
                            _append_reconciliation_result(
                                rows,
                                position_id=position_id,
                                symbol=symbol,
                                action="sell",
                                status="superseded",
                                buy_client_order_id=buy_client_order_id,
                                sell_client_order_id=sell_client_order_id,
                                qty=observed_sell_qty,
                                limit_price=target_sell_price,
                                alpaca_order_id=sell_alpaca_order_id,
                                message="position closure belongs to a superseded managed GTC sell generation",
                            )
                            continue
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="sell",
                        status="filled" if sell_status == "filled" else "closed",
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=observed_sell_qty,
                        limit_price=target_sell_price,
                        alpaca_order_id=sell_alpaca_order_id,
                        message=(
                            "managed sell filled; awaiting final status of the still-open parent buy"
                            if buy_is_open
                            else "managed target sell exposure is inactive and fully accounted; position closed"
                        ),
                    )
                    continue
                if sell_status == "filled":
                    if buy_is_open or parent_buy_fill_increased:
                        if replacement_snapshot is None:
                            _append_reconciliation_result(
                                rows,
                                position_id=position_id,
                                symbol=symbol,
                                action="sell",
                                status="superseded",
                                buy_client_order_id=buy_client_order_id,
                                sell_client_order_id=sell_client_order_id,
                                qty=remaining_qty,
                                limit_price=target_sell_price,
                                alpaca_order_id=sell_alpaca_order_id,
                                message=("managed sell replacement premise changed before its exact submission claim"),
                            )
                            continue
                        _submit_replacement_gtc_sell(
                            conn=conn,
                            client=client,
                            rows=rows,
                            position=position,
                            symbol=symbol,
                            buy_client_order_id=buy_client_order_id,
                            filled_qty=remaining_qty,
                            target_sell_price=float(target_sell_price),
                            quantity_mark_price=sell_residual_mark_price,
                            replacement_message=(
                                "parent buy filled additional shares after the prior managed sell completed; "
                                "submitted a replacement for the remaining shares"
                            ),
                            check_open_order=True,
                            live_position_qty=load_live_position_qty(),
                            close_on_complete=not buy_is_open,
                            expected_renewal_snapshot=replacement_snapshot,
                        )
                        continue
                    mismatch_generation_is_current = bool(replacement_snapshot) and (
                        update_alpaca_managed_sell_status_if_current(
                            conn,
                            position_id,
                            expected_sell_client_order_id=sell_client_order_id,
                            **_renewal_snapshot_cas_kwargs(replacement_snapshot),
                            sell_status="quantity_mismatch",
                            notes=durable_note(
                                "filled sell quantity did not close the managed buy quantity; manual review required"
                            ),
                        )
                    )
                    if not mismatch_generation_is_current:
                        _append_reconciliation_result(
                            rows,
                            position_id=position_id,
                            symbol=symbol,
                            action="sell",
                            status="superseded",
                            buy_client_order_id=buy_client_order_id,
                            sell_client_order_id=sell_client_order_id,
                            qty=observed_sell_qty,
                            limit_price=target_sell_price,
                            alpaca_order_id=sell_alpaca_order_id,
                            message="quantity mismatch belongs to a superseded managed GTC sell generation",
                        )
                        continue
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="sell",
                        status=sell_status,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=observed_sell_qty,
                        limit_price=target_sell_price,
                        alpaca_order_id=sell_alpaca_order_id,
                        message=(
                            "managed sell fill quantity does not match the managed buy; "
                            "position remains active for review"
                        ),
                        required_failure=True,
                    )
                    continue
                if sell_status in SELL_RENEWABLE_STATUSES and (
                    sell_order_qty is None or sell_order_limit_price is None
                ):
                    if replacement_snapshot is None:
                        _append_reconciliation_result(
                            rows,
                            position_id=position_id,
                            symbol=symbol,
                            action="sell",
                            status="superseded",
                            buy_client_order_id=buy_client_order_id,
                            sell_client_order_id=sell_client_order_id,
                            qty=None,
                            limit_price=target_sell_price,
                            alpaca_order_id=sell_alpaca_order_id,
                            message="order-metadata audit was superseded by concurrent managed state",
                        )
                        continue
                    _append_incomplete_sell_order_metadata_result(
                        conn=conn,
                        rows=rows,
                        position_id=position_id,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        target_sell_price=float(target_sell_price),
                        sell_alpaca_order_id=sell_alpaca_order_id,
                        expected_renewal_snapshot=replacement_snapshot,
                    )
                    continue
                open_sell_remaining_qty = (
                    None if sell_order_qty is None else max(sell_order_qty - terminal_sell_filled_qty, 0.0)
                )
                needs_sell_replacement = (
                    open_sell_remaining_qty is not None
                    and not _managed_sell_quantities_match(
                        open_sell_remaining_qty,
                        remaining_qty,
                        mark_price=sell_residual_mark_price,
                    )
                ) or (
                    sell_order_limit_price is not None
                    and abs(sell_order_limit_price - float(target_sell_price))
                    > _alpaca_limit_price_tolerance(float(target_sell_price))
                )
                if sell_status in SELL_RENEWABLE_STATUSES and sell_alpaca_order_id and needs_sell_replacement:
                    _request_gtc_sell_renewal(
                        conn=conn,
                        client=client,
                        rows=rows,
                        position=position,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        filled_qty=float(filled_qty),
                        target_sell_price=float(target_sell_price),
                        sell_alpaca_order_id=sell_alpaca_order_id,
                        replacement_chain=sell_replacement_chain,
                        replacement_message=(
                            "updated managed GTC sell after the managed buy fill quantity or price changed"
                        ),
                        renewal_note="managed GTC sell replacement requested after managed buy fill changed",
                        pending_message=(
                            "managed GTC sell replacement requested; awaiting Alpaca cancellation confirmation"
                        ),
                        live_position_qty=load_live_position_qty(),
                        close_on_complete=not buy_is_open,
                    )
                    continue
                renewal_was_requested = _optional_str(position.get("sell_renewal_requested_at")) is not None
                if sell_status in SELL_INACTIVE_STATUSES:
                    should_resubmit = (
                        sell_status == "expired" and (cfg.gtc_sell_renewal_enabled or renewal_was_requested)
                    ) or (sell_status == "canceled" and renewal_was_requested)
                    if should_resubmit:
                        if replacement_snapshot is None:
                            _append_reconciliation_result(
                                rows,
                                position_id=position_id,
                                symbol=symbol,
                                action="sell",
                                status="superseded",
                                buy_client_order_id=buy_client_order_id,
                                sell_client_order_id=sell_client_order_id,
                                qty=remaining_qty,
                                limit_price=target_sell_price,
                                alpaca_order_id=sell_alpaca_order_id,
                                message=("managed sell replacement premise changed before its exact submission claim"),
                            )
                            continue
                        _submit_replacement_gtc_sell(
                            conn=conn,
                            client=client,
                            rows=rows,
                            position=position,
                            symbol=symbol,
                            buy_client_order_id=buy_client_order_id,
                            filled_qty=remaining_qty,
                            target_sell_price=float(target_sell_price),
                            quantity_mark_price=sell_residual_mark_price,
                            replacement_message=(
                                "prior managed GTC sell expired; submitted replacement at frozen target price"
                                if sell_status == "expired"
                                else "renewed managed GTC limit sell after Alpaca confirmed cancellation"
                            ),
                            check_open_order=True,
                            live_position_qty=load_live_position_qty(),
                            close_on_complete=not buy_is_open,
                            expected_renewal_snapshot=replacement_snapshot,
                        )
                        continue
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="sell",
                        status=sell_status,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=filled_qty,
                        limit_price=target_sell_price,
                        alpaca_order_id=sell_alpaca_order_id,
                        message="managed GTC sell is no longer active; no automatic resubmission",
                        required_failure=True,
                    )
                    continue
                if sell_status in SELL_CANCEL_PENDING_STATUSES:
                    if (
                        (cfg.gtc_sell_renewal_enabled or renewal_was_requested)
                        and sell_alpaca_order_id
                        and not _sell_renewal_claim_lease_active(position)
                    ):
                        _request_gtc_sell_renewal(
                            conn=conn,
                            client=client,
                            rows=rows,
                            position=position,
                            symbol=symbol,
                            buy_client_order_id=buy_client_order_id,
                            filled_qty=float(filled_qty),
                            target_sell_price=float(target_sell_price),
                            sell_alpaca_order_id=sell_alpaca_order_id,
                            replacement_chain=sell_replacement_chain,
                            live_position_qty=load_live_position_qty(),
                            pending_message=(
                                "managed GTC sell cancellation is still pending after retry; "
                                "replacement not submitted yet"
                            ),
                            close_on_complete=not buy_is_open,
                        )
                        continue
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="sell",
                        status="pending_cancel",
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=filled_qty,
                        limit_price=target_sell_price,
                        alpaca_order_id=sell_alpaca_order_id,
                        message="managed GTC sell cancellation is pending; replacement not submitted yet",
                        required_failure=True,
                    )
                    continue
                if (
                    cfg.gtc_sell_renewal_enabled
                    and cfg.gtc_sell_renewal_days_before_expiration >= 0
                    and sell_status in SELL_RENEWABLE_STATUSES
                    and sell_alpaca_order_id
                    and _parse_alpaca_broker_datetime(sell_expires_at) is None
                    and _parse_alpaca_datetime(position.get("sell_expires_at")) is None
                ):
                    _append_incomplete_sell_expiration_metadata_result(
                        conn=conn,
                        rows=rows,
                        position_id=position_id,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        target_sell_price=float(target_sell_price),
                        sell_alpaca_order_id=sell_alpaca_order_id,
                        expected_renewal_snapshot=replacement_snapshot,
                    )
                    continue
                if sell_alpaca_order_id and _gtc_sell_renewal_due(
                    sell_order,
                    cfg,
                    persisted_expires_at=position.get("sell_expires_at"),
                ):
                    _request_gtc_sell_renewal(
                        conn=conn,
                        client=client,
                        rows=rows,
                        position=position,
                        symbol=symbol,
                        buy_client_order_id=buy_client_order_id,
                        filled_qty=float(filled_qty),
                        target_sell_price=float(target_sell_price),
                        sell_alpaca_order_id=sell_alpaca_order_id,
                        replacement_chain=sell_replacement_chain,
                        live_position_qty=load_live_position_qty(),
                        close_on_complete=not buy_is_open,
                    )
                    continue
                if sell_status not in SELL_RENEWABLE_STATUSES:
                    _append_reconciliation_result(
                        rows,
                        position_id=position_id,
                        symbol=symbol,
                        action="sell",
                        status=sell_status,
                        buy_client_order_id=buy_client_order_id,
                        sell_client_order_id=sell_client_order_id,
                        qty=filled_qty,
                        limit_price=target_sell_price,
                        alpaca_order_id=sell_alpaca_order_id,
                        message=(
                            "managed sell has a recognized but unresolved broker status; "
                            "active protective coverage cannot be confirmed"
                        ),
                        required_failure=True,
                    )
                    continue
                _append_reconciliation_result(
                    rows,
                    position_id=position_id,
                    symbol=symbol,
                    action="sell",
                    status=sell_status,
                    buy_client_order_id=buy_client_order_id,
                    sell_client_order_id=sell_client_order_id,
                    qty=filled_qty,
                    limit_price=target_sell_price,
                    alpaca_order_id=sell_alpaca_order_id,
                    message="managed GTC sell order already submitted",
                )
                continue

            expected_position_asset_id = _optional_str(position.get("alpaca_asset_id"))
            open_orders = client.open_orders(
                equity_scope_asset_ids=((expected_position_asset_id,) if expected_position_asset_id is not None else ())
            )
            matching_orders = _matching_managed_open_sell_orders(
                open_orders,
                symbol,
                position_id,
                sell_order_namespace=_optional_str(position.get("sell_order_namespace")),
                legacy_sell_client_order_id=_optional_str(position.get("sell_client_order_id")),
                expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
            )
            if len(matching_orders) > 1:
                _append_multiple_managed_open_sells_result(
                    rows=rows,
                    position_id=position_id,
                    symbol=symbol,
                    buy_client_order_id=buy_client_order_id,
                    sell_client_order_id=sell_client_order_id,
                    filled_qty=float(filled_qty),
                    target_sell_price=float(target_sell_price),
                )
                continue
            if len(matching_orders) == 1:
                open_recovery_snapshot = (
                    None
                    if filled_avg_price is None
                    else _managed_sell_replacement_snapshot_if_current(
                        conn,
                        position_id=position_id,
                        sell_client_order_id=_optional_str(position.get("sell_client_order_id")),
                        sell_alpaca_order_id=_optional_str(position.get("sell_alpaca_order_id")),
                        sell_renewal_requested_at=_optional_str(position.get("sell_renewal_requested_at")),
                        expected_buy_status=_optional_str(position.get("buy_status")),
                        expected_buy_filled_qty=float(filled_qty),
                        expected_buy_filled_avg_price=float(filled_avg_price),
                        expected_target_sell_price=float(target_sell_price),
                        expected_remaining_qty=_managed_remaining_qty(position, float(filled_qty)),
                        expected_sell_status=_optional_str(position.get("sell_status")),
                        expected_sell_renewal_count=_optional_int(position.get("sell_renewal_count")),
                    )
                )
                _append_recovered_open_sell_result(
                    conn=conn,
                    client=client,
                    rows=rows,
                    position_id=position_id,
                    symbol=symbol,
                    buy_client_order_id=buy_client_order_id,
                    sell_order=matching_orders[0],
                    filled_qty=float(filled_qty),
                    target_sell_price=float(target_sell_price),
                    expected_sell_client_order_id=_optional_str(position.get("sell_client_order_id")),
                    expected_sell_alpaca_order_id=_optional_str(position.get("sell_alpaca_order_id")),
                    expected_renewal_count=_optional_int(position.get("sell_renewal_count")),
                    cfg=cfg,
                    sell_order_namespace=_optional_str(position.get("sell_order_namespace")),
                    expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
                    expected_state_snapshot=open_recovery_snapshot,
                )
                continue

            if _orders_have_open_order(
                open_orders,
                symbol,
                "sell",
                expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
                symbol_aliases=position_aliases,
            ):
                _append_open_sell_result(
                    rows=rows,
                    position_id=position_id,
                    symbol=symbol,
                    buy_client_order_id=buy_client_order_id,
                    sell_client_order_id=sell_client_order_id,
                    filled_qty=float(filled_qty),
                    target_sell_price=float(target_sell_price),
                )
                continue

            if not _is_whole_share_qty(float(filled_qty)):
                fractional_snapshot = (
                    None
                    if filled_avg_price is None
                    else _managed_sell_replacement_snapshot_if_current(
                        conn,
                        position_id=position_id,
                        sell_client_order_id=_optional_str(position.get("sell_client_order_id")),
                        sell_alpaca_order_id=_optional_str(position.get("sell_alpaca_order_id")),
                        sell_renewal_requested_at=_optional_str(position.get("sell_renewal_requested_at")),
                        expected_buy_status=_optional_str(position.get("buy_status")),
                        expected_buy_filled_qty=float(filled_qty),
                        expected_buy_filled_avg_price=float(filled_avg_price),
                        expected_target_sell_price=float(target_sell_price),
                        expected_remaining_qty=_managed_remaining_qty(position, float(filled_qty)),
                        expected_sell_status=_optional_str(position.get("sell_status")),
                        expected_sell_renewal_count=_optional_int(position.get("sell_renewal_count")),
                    )
                )
                _append_fractional_sell_result(
                    conn=conn,
                    rows=rows,
                    position_id=position_id,
                    symbol=symbol,
                    buy_client_order_id=buy_client_order_id,
                    sell_client_order_id=None,
                    filled_qty=float(filled_qty),
                    target_sell_price=float(target_sell_price),
                    expected_state_snapshot=fractional_snapshot,
                )
                continue

            sell_order_namespace = _optional_str(position.get("sell_order_namespace"))
            sell_client_order_id = _alpaca_exit_client_order_id(
                symbol,
                position_id,
                order_namespace=sell_order_namespace,
            )
            _submit_managed_gtc_sell(
                conn=conn,
                client=client,
                rows=rows,
                position_id=position_id,
                symbol=symbol,
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                filled_qty=float(filled_qty),
                target_sell_price=float(target_sell_price),
                increment_renewal_count=False,
                replacement_message="submitted managed GTC limit sell at frozen target price",
                live_position_qty=load_live_position_qty(),
                close_on_complete=not buy_is_open,
                sell_order_namespace=sell_order_namespace,
                intent_not_before=_optional_str(position.get("created_at")),
                expected_alpaca_asset_id=_optional_str(position.get("alpaca_asset_id")),
            )
        except HTTPError as exc:
            error_message = _http_error_message(exc, sensitive_values=sensitive_values)
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="reconcile",
                status="error",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=None,
                limit_price=None,
                alpaca_order_id=None,
                message=error_message,
                systemic_failure=(
                    _authentication_http_error(exc, sensitive_values=sensitive_values)
                    or _transient_broker_http_error(exc)
                ),
                required_failure=True,
            )
        except Exception as exc:
            error_message = _alpaca_exception_diagnostic(
                exc,
                cfg=cfg,
                sensitive_values=sensitive_values,
            )
            _append_reconciliation_result(
                rows,
                position_id=position_id,
                symbol=symbol,
                action="reconcile",
                status="error",
                buy_client_order_id=buy_client_order_id,
                sell_client_order_id=sell_client_order_id,
                qty=None,
                limit_price=None,
                alpaca_order_id=None,
                message=error_message,
                systemic_failure=isinstance(exc, requests.RequestException),
                required_failure=True,
            )

    raw_result = pd.DataFrame(rows)
    if raw_result.empty:
        return pd.DataFrame(columns=columns)
    systemic_position_ids = set(
        raw_result.loc[raw_result["_Systemic Failure"].eq(True), "Position ID"].astype(int).tolist()
    )
    required_failure_rows = raw_result["_Required Failure"].eq(True)
    result = raw_result.drop(columns=["_Systemic Failure", "_Required Failure"])
    result.insert(1, "Workflow", result["Position ID"].map(workflow_by_position_id))
    result = result.reindex(columns=columns)
    if len(systemic_position_ids) == len(reconciliation_candidates):
        raise AlpacaReconciliationError(
            "every Alpaca managed position failed reconciliation because of broker authentication, "
            "availability, or transport",
            result,
        )
    if required_failure_rows.any():
        raise AlpacaReconciliationError(
            "one or more Alpaca managed positions could not confirm required protective reconciliation",
            result,
        )
    return result


def _reconcile_alpaca_managed_positions_impl(
    conn: sqlite3.Connection,
    cfg: AlpacaOrderConfig,
    *,
    migrate_closed_symbols: bool = False,
) -> pd.DataFrame:
    """Reconcile active exposure before performing any closed-position audit.

    Closed corrections can reopen shares, so the second pass audits the rows
    that were closed at invocation time and then reconciles only newly active
    positions. Results and required failures from both phases are retained.
    """
    if cfg.enabled or cfg.sell_enabled:
        _require_clean_broker_side_effect_connection(
            conn,
            operation="Managed Alpaca reconciliation",
        )
    validate_alpaca_reconciliation_configuration(cfg)
    sensitive_values = _alpaca_config_sensitive_values(cfg)
    if not (cfg.enabled or cfg.sell_enabled):
        return _reconcile_alpaca_managed_positions_pass(
            conn,
            cfg,
            audit_closed=False,
        )

    columns = [
        "Position ID",
        "Workflow",
        "Asset",
        "Action",
        "Status",
        "Buy Client Order ID",
        "Sell Client Order ID",
        "Qty",
        "Limit Price",
        "Alpaca Order ID",
        "Message",
    ]
    initial_active_positions = load_alpaca_managed_positions(conn, active_only=True)
    initial_active_position_ids = frozenset(
        int(position_id) for position_id in initial_active_positions.get("id", pd.Series(dtype=int)).tolist()
    )
    phase_results: list[pd.DataFrame] = []
    phase_failures: list[str] = []
    closed_audit_blocked = False
    order_snapshot = _ReconciliationOrderSnapshot()

    def combined_phase_results() -> pd.DataFrame:
        nonempty_results = [result for result in phase_results if not result.empty]
        return (
            pd.concat(nonempty_results, ignore_index=True).reindex(columns=columns)
            if nonempty_results
            else pd.DataFrame(columns=columns)
        )

    try:
        phase_results.append(
            _reconcile_alpaca_managed_positions_pass(
                conn,
                cfg,
                audit_closed=False,
                order_snapshot=order_snapshot,
            )
        )
    except AlpacaReconciliationError as exc:
        phase_results.append(exc.results)
        phase_failures.append(str(exc))

    try:
        if migrate_closed_symbols:
            closed_migration_applied = False
            closed_migration_commit_completed = False
            try:
                closed_migrations = migrate_alpaca_managed_position_symbols(
                    conn,
                    cfg,
                    include_active=False,
                    include_closed=True,
                    exclude_position_ids=initial_active_position_ids,
                )
                closed_migration_applied = bool(closed_migrations)
                if closed_migration_applied:
                    # The closed audit can reopen exposure and dispatch a new
                    # protective sell. Make its symbol premise durable before
                    # any of those broker effects become possible.
                    revalidate_active_sqlite_runtime_file()
                    conn.commit()
                    closed_migration_commit_completed = True
                    revalidate_active_sqlite_runtime_file()
            except Exception as exc:
                if closed_migration_applied and not closed_migration_commit_completed:
                    _rollback_owned_symbol_migration_transaction(conn, exc)
                migration_detail = _alpaca_exception_diagnostic(
                    exc,
                    cfg=cfg,
                    sensitive_values=sensitive_values,
                )
                try:
                    closed_positions = load_recently_closed_alpaca_managed_positions(
                        conn,
                        audit_days=_CLOSED_POSITION_CORRECTION_AUDIT_DAYS,
                        audit_limit=_CLOSED_POSITION_CORRECTION_AUDIT_LIMIT,
                    )
                    if initial_active_position_ids and not closed_positions.empty:
                        closed_positions = closed_positions.loc[
                            ~closed_positions["id"].isin(initial_active_position_ids)
                        ].reset_index(drop=True)
                except Exception as diagnostic_exc:
                    closed_audit_blocked = True
                    diagnostic_detail = _alpaca_exception_diagnostic(
                        diagnostic_exc,
                        cfg=cfg,
                        sensitive_values=sensitive_values,
                    )
                    migration_detail += (
                        f"; closed-position migration diagnostics could not be loaded: {diagnostic_detail}"
                    )
                    closed_positions = pd.DataFrame()
                migration_rows = [
                    {
                        "Position ID": int(position["id"]),
                        "Workflow": _optional_str(position.get("workflow")),
                        "Asset": position.get("symbol"),
                        "Action": "symbol",
                        "Status": "error",
                        "Buy Client Order ID": position.get("buy_client_order_id"),
                        "Sell Client Order ID": position.get("sell_client_order_id"),
                        "Qty": position.get("filled_qty"),
                        "Limit Price": position.get("target_sell_price"),
                        "Alpaca Order ID": position.get("sell_alpaca_order_id"),
                        "Message": (
                            "audit-only managed Alpaca symbol migration failed after active reconciliation: "
                            f"{migration_detail}"
                        ),
                    }
                    for position in closed_positions.to_dict("records")
                ]
                if not migration_rows:
                    migration_rows.append(
                        {
                            "Position ID": None,
                            "Workflow": None,
                            "Asset": None,
                            "Action": "symbol",
                            "Status": "error",
                            "Buy Client Order ID": None,
                            "Sell Client Order ID": None,
                            "Qty": None,
                            "Limit Price": None,
                            "Alpaca Order ID": None,
                            "Message": (
                                "audit-only managed Alpaca symbol migration failed after active reconciliation: "
                                f"{migration_detail}"
                            ),
                        }
                    )
                phase_results.append(pd.DataFrame(migration_rows, columns=columns))
                phase_failures.append("audit-only managed Alpaca symbol migration failed")
                if closed_migration_applied:
                    # A failed commit or post-commit runtime validation leaves
                    # no safe premise for the broker-active closed audit.
                    raise
            except BaseException as exc:
                # Caller interruptions must not leak the transaction opened by
                # a completed migration write. Once commit has returned, the
                # rename is durable and cannot safely be undone here.
                if closed_migration_applied and not closed_migration_commit_completed:
                    _rollback_owned_symbol_migration_transaction(conn, exc)
                raise

        if not closed_audit_blocked:
            revalidate_active_sqlite_runtime_file()
            _require_clean_broker_side_effect_connection(
                conn,
                operation="Closed-position Alpaca correction audit",
            )
            try:
                phase_results.append(
                    _reconcile_alpaca_managed_positions_pass(
                        conn,
                        cfg,
                        audit_closed=True,
                        skip_active_position_ids=initial_active_position_ids,
                        order_snapshot=order_snapshot,
                    )
                )
            except AlpacaReconciliationError as exc:
                phase_results.append(exc.results)
                phase_failures.append(str(exc))
    except Exception as exc:
        detail = _alpaca_exception_diagnostic(
            exc,
            cfg=cfg,
            sensitive_values=sensitive_values,
        )
        phase_results.append(
            pd.DataFrame(
                [
                    {
                        "Position ID": None,
                        "Workflow": None,
                        "Asset": None,
                        "Action": "reconcile",
                        "Status": "error",
                        "Buy Client Order ID": None,
                        "Sell Client Order ID": None,
                        "Qty": None,
                        "Limit Price": None,
                        "Alpaca Order ID": None,
                        "Message": (f"closed-position correction audit failed after active reconciliation: {detail}"),
                    }
                ],
                columns=columns,
            )
        )
        public_cause = _alpaca_public_exception_cause(
            exc,
            cfg=cfg,
            sensitive_values=sensitive_values,
        )
        raise AlpacaReconciliationError(
            (
                phase_failures[0]
                if phase_failures
                else "closed-position correction audit failed after active reconciliation"
            ),
            combined_phase_results(),
        ) from public_cause

    combined_results = combined_phase_results()
    if phase_failures:
        raise AlpacaReconciliationError(phase_failures[0], combined_results)
    return combined_results


def reconcile_alpaca_managed_positions(
    conn: sqlite3.Connection,
    cfg: AlpacaOrderConfig,
    *,
    migrate_closed_symbols: bool = False,
) -> pd.DataFrame:
    """Publish credential-safe managed-position reconciliation diagnostics."""
    boundary_sensitive_values: tuple[str, ...] = ()
    publication_sensitive_values: tuple[str, ...] = ()
    public_failure: BaseException | None = None
    original_failure: BaseException | None = None
    try:
        boundary_sensitive_values = _alpaca_config_sensitive_values(cfg)
        publication_sensitive_values = boundary_sensitive_values
        with _alpaca_public_durable_diagnostic_scope(cfg, boundary_sensitive_values):
            try:
                result = _reconcile_alpaca_managed_positions_impl(
                    conn,
                    cfg,
                    migrate_closed_symbols=migrate_closed_symbols,
                )
            finally:
                publication_sensitive_values = _merged_alpaca_sensitive_values(
                    boundary_sensitive_values,
                    _ALPACA_PUBLIC_DURABLE_SENSITIVE_VALUES.get() or (),
                    _alpaca_scoped_sensitive_values(),
                    _alpaca_config_sensitive_values(cfg),
                )
    except BaseException as exc:
        if not isinstance(exc, Exception) and not publication_sensitive_values:
            raise
        original_failure = exc
        public_failure = _alpaca_public_exception(
            exc,
            cfg=cfg,
            sensitive_values=publication_sensitive_values,
        )
    else:
        return _alpaca_public_result(
            result,
            cfg=cfg,
            sensitive_values=publication_sensitive_values,
        )

    assert public_failure is not None
    if public_failure is original_failure:
        raise public_failure
    public_cause = _alpaca_public_exception_cause(
        original_failure,
        cfg=cfg,
        sensitive_values=publication_sensitive_values,
    )
    raise public_failure from public_cause


def _rollback_and_release_symbol_migration_savepoint(
    conn: sqlite3.Connection,
    savepoint_name: str,
    failure: BaseException,
) -> bool:
    """Best-effort savepoint cleanup without replacing the original failure."""
    cleanup_failures: list[tuple[str, BaseException]] = []
    rollback_succeeded = False
    try:
        conn.execute(f"ROLLBACK TO SAVEPOINT {savepoint_name}")
    except BaseException as exc:
        cleanup_failures.append(("roll back", exc))
    else:
        rollback_succeeded = True

    if rollback_succeeded:
        try:
            conn.execute(f"RELEASE SAVEPOINT {savepoint_name}")
        except BaseException as exc:
            cleanup_failures.append(("release", exc))

    if cleanup_failures:
        try:
            conn.rollback()
        except BaseException as exc:
            cleanup_failures.append(("roll back the connection", exc))
            # Never return a connection whose partial migration could still be
            # committed. Closing SQLite discards the pending transaction and
            # makes accidental caller reuse fail closed.
            try:
                conn.close()
            except BaseException as close_exc:
                cleanup_failures.append(("close the connection after rollback failure", close_exc))

    for action, cleanup_failure in cleanup_failures:
        with suppress(BaseException):
            failure.add_note(f"Failed to {action} while cleaning SQLite savepoint {savepoint_name}: {cleanup_failure}")
    return not cleanup_failures


def _rollback_owned_symbol_migration_transaction(
    conn: sqlite3.Connection,
    failure: BaseException,
) -> None:
    """Discard a failed transaction started by symbol migration itself."""
    try:
        transaction_active = conn.in_transaction
    except sqlite3.ProgrammingError:
        # Savepoint cleanup already closes a connection when it cannot make a
        # partial migration safe. There is nothing further to roll back.
        return
    except BaseException as state_failure:
        failure.add_note(
            f"Failed to inspect the SQLite transaction after managed Alpaca symbol migration failed: {state_failure}"
        )
        transaction_active = True
    if not transaction_active:
        return
    try:
        conn.rollback()
    except BaseException as rollback_failure:
        failure.add_note(
            f"Failed to roll back the transaction owned by managed Alpaca symbol migration: {rollback_failure}"
        )
        try:
            conn.close()
        except BaseException as close_failure:
            failure.add_note(
                f"Failed to close the connection after managed Alpaca symbol migration rollback failed: {close_failure}"
            )


def _migrate_alpaca_managed_position_symbols_impl(
    conn: sqlite3.Connection,
    cfg: AlpacaOrderConfig,
    *,
    include_active: bool = True,
    include_closed: bool = True,
    exclude_position_ids: frozenset[int] = frozenset(),
) -> dict[str, str]:
    """Migrate selected managed tickers using stable asset IDs.

    Returns an old-to-current symbol mapping. Existing broker order and client
    IDs are intentionally retained; only future submissions use the new ticker.
    Active and audit-eligible closed rows can be phased independently so
    closed-row broker lookups never delay current protective reconciliation.
    """
    validate_alpaca_reconciliation_configuration(cfg)
    if not (cfg.enabled or cfg.sell_enabled) or not (include_active or include_closed):
        return {}
    active_positions = load_alpaca_managed_positions(conn, active_only=True) if include_active else pd.DataFrame()
    recently_closed_positions = (
        load_recently_closed_alpaca_managed_positions(
            conn,
            audit_days=_CLOSED_POSITION_CORRECTION_AUDIT_DAYS,
            audit_limit=_CLOSED_POSITION_CORRECTION_AUDIT_LIMIT,
        )
        if include_closed
        else pd.DataFrame()
    )
    if exclude_position_ids:
        if not active_positions.empty:
            active_positions = active_positions.loc[~active_positions["id"].isin(exclude_position_ids)].reset_index(
                drop=True
            )
        if not recently_closed_positions.empty:
            recently_closed_positions = recently_closed_positions.loc[
                ~recently_closed_positions["id"].isin(exclude_position_ids)
            ].reset_index(drop=True)
    if active_positions.empty and recently_closed_positions.empty:
        return {}
    client = AlpacaClient(cfg)
    live_by_asset_id: dict[str, str] = {}
    live_asset_id_by_symbol: dict[str, str] = {}
    with _retain_alpaca_client_exception_diagnostic(client):
        live_positions = client.positions()
    for item in live_positions:
        live_asset_id = _optional_str(item.get("asset_id"))
        live_symbol = _optional_str(item.get("symbol"))
        if live_asset_id is None or live_symbol is None:
            raise ValueError("Alpaca positions returned an incomplete stable asset identity")
        normalized_live_symbol = _optional_alpaca_equity_symbol(live_symbol)
        if normalized_live_symbol is None:
            raise ValueError("Alpaca positions returned a non-canonical equity symbol")
        prior_symbol = live_by_asset_id.get(live_asset_id)
        if prior_symbol is not None and prior_symbol != normalized_live_symbol:
            raise ValueError("Alpaca positions returned conflicting symbols for the same stable asset identity")
        prior_asset_id = live_asset_id_by_symbol.get(normalized_live_symbol)
        if prior_asset_id is not None and prior_asset_id != live_asset_id:
            raise ValueError("Alpaca positions returned conflicting stable asset identities for the same symbol")
        live_by_asset_id[live_asset_id] = normalized_live_symbol
        live_asset_id_by_symbol[normalized_live_symbol] = live_asset_id

    def migration_candidate(position: dict) -> tuple[int, str, str, str, str | None] | None:
        prior_symbol = str(position["symbol"]).upper()
        closed_at = position.get("closed_at")
        expected_closed_at = None if closed_at is None or pd.isna(closed_at) else str(closed_at)
        asset_id = _optional_str(position.get("alpaca_asset_id"))
        accepted_asset_ids = frozenset(alpaca_managed_position_asset_ids(position))
        current_symbol = live_by_asset_id.get(asset_id) if asset_id is not None else None
        if current_symbol is not None and current_symbol.upper() == prior_symbol:
            return None
        attached_order_asset_id: str | None = None
        for order_id, expected_client_order_id, order_role in (
            (
                _optional_str(position.get("sell_alpaca_order_id")),
                _optional_str(position.get("sell_client_order_id")),
                "sell",
            ),
            (
                _optional_str(position.get("buy_alpaca_order_id")),
                _optional_str(position.get("buy_client_order_id")),
                "buy",
            ),
        ):
            if order_id is None:
                continue
            response = client.get_order(order_id)
            if response.status_code == 404:
                continue
            _require_2xx_response(response)
            payload = _response_json(response)
            observed_order_id = _optional_str(payload.get("id"))
            if expected_client_order_id is None or observed_order_id != order_id:
                raise ValueError(
                    f"Managed position {int(position['id'])} {order_role} order identity "
                    "does not match the persisted order; symbol migration is blocked for review"
                )
            try:
                _leaf, lineage = _resolve_order_replacement_chain(client, payload)
                if _optional_str(lineage[0].get("client_order_id")) != expected_client_order_id:
                    raise ValueError("replacement root does not match the persisted client order ID")
            except (HTTPError, RuntimeError, ValueError) as exc:
                raise ValueError(
                    f"Managed position {int(position['id'])} {order_role} replacement lineage identity "
                    "does not match the persisted client order; symbol migration is blocked for review"
                ) from exc
            observed_asset_id = _optional_str(payload.get("asset_id"))
            if observed_asset_id is None or (asset_id is not None and observed_asset_id not in accepted_asset_ids):
                raise ValueError(
                    f"Managed position {int(position['id'])} {order_role} order asset identity "
                    "does not match the persisted asset; symbol migration is blocked for review"
                )
            expected_time_in_force = "gtc" if order_role == "sell" else "day"
            if not all(
                _order_matches_core_intent(
                    lineage_order,
                    expected_symbol=None,
                    expected_alpaca_asset_id=observed_asset_id,
                    expected_side=order_role,
                    expected_order_type="limit",
                    expected_time_in_force=expected_time_in_force,
                    require_complete=True,
                )
                for lineage_order in lineage
            ):
                raise ValueError(
                    f"Managed position {int(position['id'])} {order_role} replacement lineage conflicts "
                    "with its required side, limit-order role, time in force, or stable asset identity; "
                    "symbol migration is blocked for review"
                )
            if (
                order_role == "sell"
                and _alpaca_exit_client_order_generation(
                    str(position["symbol"]),
                    int(position["id"]),
                    expected_client_order_id,
                    order_namespace=_optional_str(position.get("sell_order_namespace")),
                    allow_legacy_position_id=True,
                )
                is None
            ):
                raise ValueError(
                    f"Managed position {int(position['id'])} sell client order generation "
                    "is invalid; symbol migration is blocked for review"
                )
            if attached_order_asset_id is None:
                attached_order_asset_id = observed_asset_id
            elif observed_asset_id != attached_order_asset_id and asset_id is None:
                raise ValueError(
                    f"Managed position {int(position['id'])} attached orders report conflicting "
                    "stable asset identities; symbol migration is blocked for review"
                )
        if asset_id is None:
            asset_id = attached_order_asset_id
        if asset_id is None:
            return None
        current_symbol = live_by_asset_id.get(asset_id)
        if current_symbol is None:
            try:
                asset = client.asset(asset_id)
            except HTTPError as exc:
                status_code = exc.response.status_code if exc.response is not None else None
                if expected_closed_at is not None and status_code == 404:
                    # Delisted audit-only rows must not prevent unrelated
                    # active holdings from reaching protective reconciliation.
                    # Retain their last known symbol; their own order audit
                    # still reports any unresolved broker identity failure.
                    return None
                raise
            observed_asset_id = _optional_str(asset.get("id"))
            current_symbol = _optional_alpaca_equity_symbol(asset.get("symbol"))
            if observed_asset_id != asset_id or current_symbol is None:
                raise ValueError(
                    f"Alpaca asset lookup for managed position {int(position['id'])} "
                    "does not match the persisted asset identity; symbol migration is blocked for review"
                )
            _require_alpaca_us_equity_asset_class(asset)
        if current_symbol is None:
            return None
        return (
            int(position["id"]),
            prior_symbol,
            asset_id,
            current_symbol.upper(),
            expected_closed_at,
        )

    # Active positions are safety-critical: every identity check must succeed
    # before any active rename is applied. Closed rows are audit-only and are
    # independently re-read by ``reconcile_alpaca_managed_positions``, which
    # records their broker/identity failures without skipping active coverage.
    with _retain_alpaca_client_exception_diagnostic(client):
        active_migration_plan = [
            candidate
            for position in active_positions.to_dict("records")
            if (candidate := migration_candidate(position)) is not None
        ]
    closed_migration_plan: list[tuple[int, str, str, str, str | None]] = []
    for position in recently_closed_positions.to_dict("records"):
        try:
            with _retain_alpaca_client_exception_diagnostic(client):
                candidate = migration_candidate(position)
        except Exception:
            continue
        if candidate is not None:
            closed_migration_plan.append(candidate)

    asset_owners: dict[str, int] = {}
    symbol_owners: dict[str, int] = {}
    for position_id, _prior_symbol, asset_id, current_symbol, _expected_closed_at in active_migration_plan:
        conflicting_position_id = asset_owners.get(asset_id) or symbol_owners.get(current_symbol)
        if conflicting_position_id is not None and conflicting_position_id != position_id:
            raise ValueError(
                f"Managed positions {conflicting_position_id} and {position_id} resolve to the same "
                f"Alpaca asset or current symbol ({current_symbol}); symbol migration was not applied"
            )
        asset_owners[asset_id] = position_id
        symbol_owners[current_symbol] = position_id

    if not active_migration_plan and not closed_migration_plan:
        return {}

    migrations: dict[str, str] = {}
    owns_transaction = not conn.in_transaction
    active_savepoint = False
    try:
        if owns_transaction:
            # RELEASE commits an outermost savepoint. Keep a real transaction
            # underneath every migration savepoint so the workflow's explicit
            # final commit remains the only durability boundary.
            conn.execute("BEGIN")
        conn.execute("SAVEPOINT alpaca_symbol_migration")
        active_savepoint = True
        for position_id, prior_symbol, asset_id, current_symbol, expected_closed_at in active_migration_plan:
            migrated = migrate_alpaca_managed_position_symbol(
                conn,
                position_id,
                alpaca_asset_id=asset_id,
                current_symbol=current_symbol,
                expected_closed_at=expected_closed_at,
                commit=False,
            )
            if not migrated:
                raise ValueError(
                    f"Could not safely migrate managed position {position_id} "
                    f"from {prior_symbol} to {current_symbol}; conflicting active symbol or asset identity"
                )
            if prior_symbol != current_symbol:
                migrations[prior_symbol] = current_symbol
        conn.execute("RELEASE SAVEPOINT alpaca_symbol_migration")
        active_savepoint = False
    except BaseException as exc:
        if active_savepoint:
            _rollback_and_release_symbol_migration_savepoint(
                conn,
                "alpaca_symbol_migration",
                exc,
            )
        if owns_transaction:
            _rollback_owned_symbol_migration_transaction(conn, exc)
        raise

    # A closed row is not an authority for current exposure. Apply each proven
    # rename in its own savepoint so a stale snapshot or local alias conflict
    # cannot roll back active migrations or prevent protective reconciliation.
    try:
        for position_id, prior_symbol, asset_id, current_symbol, expected_closed_at in closed_migration_plan:
            closed_savepoint = False
            try:
                conn.execute("SAVEPOINT alpaca_closed_symbol_migration")
                closed_savepoint = True
                migrated = migrate_alpaca_managed_position_symbol(
                    conn,
                    position_id,
                    alpaca_asset_id=asset_id,
                    current_symbol=current_symbol,
                    expected_closed_at=expected_closed_at,
                    commit=False,
                )
                if not migrated:
                    raise ValueError("closed managed-position symbol snapshot changed concurrently")
                conn.execute("RELEASE SAVEPOINT alpaca_closed_symbol_migration")
                closed_savepoint = False
            except Exception as exc:
                if not closed_savepoint:
                    raise
                cleanup_succeeded = _rollback_and_release_symbol_migration_savepoint(
                    conn,
                    "alpaca_closed_symbol_migration",
                    exc,
                )
                if not cleanup_succeeded:
                    raise
                continue
            except BaseException as exc:
                if closed_savepoint:
                    _rollback_and_release_symbol_migration_savepoint(
                        conn,
                        "alpaca_closed_symbol_migration",
                        exc,
                    )
                raise
            if prior_symbol != current_symbol:
                migrations[prior_symbol] = current_symbol
    except BaseException as exc:
        if owns_transaction:
            _rollback_owned_symbol_migration_transaction(conn, exc)
        raise

    if owns_transaction and not migrations:
        # Every audit-only closed candidate may lose its snapshot race. The
        # workflow commits only when this mapping is non-empty, so do not leak
        # the otherwise empty transaction owned by this helper.
        try:
            conn.rollback()
        except BaseException as exc:
            _rollback_owned_symbol_migration_transaction(conn, exc)
            raise
    return migrations


def migrate_alpaca_managed_position_symbols(
    conn: sqlite3.Connection,
    cfg: AlpacaOrderConfig,
    *,
    include_active: bool = True,
    include_closed: bool = True,
    exclude_position_ids: frozenset[int] = frozenset(),
) -> dict[str, str]:
    """Publish credential-safe symbol-migration failures."""
    boundary_sensitive_values: tuple[str, ...] = ()
    publication_sensitive_values: tuple[str, ...] = ()
    public_failure: BaseException | None = None
    try:
        boundary_sensitive_values = _alpaca_config_sensitive_values(cfg)
        publication_sensitive_values = boundary_sensitive_values
        with _alpaca_public_durable_diagnostic_scope(cfg, boundary_sensitive_values):
            try:
                return _migrate_alpaca_managed_position_symbols_impl(
                    conn,
                    cfg,
                    include_active=include_active,
                    include_closed=include_closed,
                    exclude_position_ids=exclude_position_ids,
                )
            finally:
                publication_sensitive_values = _merged_alpaca_sensitive_values(
                    boundary_sensitive_values,
                    _ALPACA_PUBLIC_DURABLE_SENSITIVE_VALUES.get() or (),
                    _alpaca_scoped_sensitive_values(),
                    _alpaca_config_sensitive_values(cfg),
                )
    except BaseException as exc:
        if not isinstance(exc, Exception) and not publication_sensitive_values:
            raise
        public_failure = _alpaca_public_exception(
            exc,
            cfg=cfg,
            sensitive_values=publication_sensitive_values,
        )

    assert public_failure is not None
    raise public_failure


def _release_unsubmitted_managed_buy_claim(
    conn: sqlite3.Connection | None,
    *,
    position_id: int | None,
    submission_attempt_count: int | None,
    notes: str,
) -> bool:
    if position_id is None:
        return True
    if conn is None or submission_attempt_count is None:
        raise RuntimeError("Managed Alpaca buy claim is missing its local submission identity")
    return fail_alpaca_managed_buy_submission_if_pending(
        conn,
        position_id,
        expected_buy_submission_attempt_count=submission_attempt_count,
        notes=notes,
    )


def _release_known_undispatched_managed_buy_claim(
    conn: sqlite3.Connection | None,
    *,
    position_id: int | None,
    submission_attempt_count: int | None,
    state_revision: int | None,
    notes: str,
) -> bool:
    """Close a proven no-request generation in the existing retryable state."""
    if position_id is None:
        return True
    if conn is None or submission_attempt_count is None or state_revision is None:
        raise RuntimeError("Managed Alpaca buy claim is missing its local submission generation")
    return close_alpaca_managed_buy_if_current_and_unfilled(
        conn,
        position_id,
        expected_buy_status="submission_pending",
        expected_buy_alpaca_order_id=None,
        expected_buy_submission_attempt_count=submission_attempt_count,
        expected_state_revision=state_revision,
        buy_status="submission_not_found",
        closed_at=_utc_now().isoformat().replace("+00:00", "Z"),
        notes=notes,
    )


def _submit_alpaca_paper_buy_orders_impl(
    buy_signals: pd.DataFrame,
    cfg: AlpacaOrderConfig,
    conn: sqlite3.Connection | None = None,
    *,
    failure_context: _BuyBatchFailureContext | None = None,
    boundary_sensitive_values: tuple[str, ...] = (),
) -> pd.DataFrame:
    columns = list(_ALPACA_BUY_RESULT_COLUMNS)
    sensitive_values = _merged_alpaca_sensitive_values(
        boundary_sensitive_values,
        _alpaca_config_sensitive_values(cfg),
    )
    if not cfg.enabled:
        return pd.DataFrame(columns=columns)
    if buy_signals.empty:
        return pd.DataFrame(columns=columns)

    managed_symbols = active_alpaca_managed_symbols(conn) if conn is not None else set()
    active_managed_positions = (
        load_alpaca_managed_positions(conn, active_only=True) if conn is not None else pd.DataFrame()
    )
    managed_equity_scope_asset_ids = {
        asset_id
        for position in active_managed_positions.to_dict("records")
        if (asset_id := _optional_alpaca_broker_identifier(position.get("alpaca_asset_id"))) is not None
    }
    client: AlpacaClient | None = None
    market_clock: dict | None = None
    prior_session: date | None = None
    calendar_loaded = False
    if failure_context is None:
        failure_context = _BuyBatchFailureContext()
    rows = failure_context.rows
    eligible_orders: list[dict[str, object]] = []
    pending_batch_symbols: set[str] = set()
    pending_batch_client_order_ids: set[str] = set()
    workflow_by_signal_index: dict[int, str | None] = {}
    fatal_batch_messages: list[str] = []
    preflight_attempts = 0
    preflight_exception_failures = 0
    submission_attempts = 0
    submission_successes = 0
    submission_transport_failures = 0
    phase_one_deterministic_broker_order_observed = False

    def durable_note(value: str | None) -> str | None:
        return _alpaca_durable_diagnostic_note(
            value,
            cfg=cfg,
            sensitive_values=sensitive_values,
            client=client,
        )

    def append_preflight_result(
        signal_index: int,
        *,
        symbol: str,
        signal_date: str,
        client_order_id: str,
        status: str,
        message: str,
        alpaca_order_id: str | None = None,
        notional: float | None = None,
        qty: int | None = None,
        limit_price: float | None = None,
    ) -> None:
        rows.append(
            {
                "Workflow": workflow_by_signal_index.get(signal_index),
                "Asset": symbol,
                "Date": signal_date,
                "Client Order ID": client_order_id,
                "Notional": notional,
                "Qty": qty,
                "Limit Price": limit_price,
                "Status": status,
                "Alpaca Order ID": alpaca_order_id,
                "Message": message,
                "_signal_index": signal_index,
            }
        )

    # Phase one performs every per-symbol safety check, including quoting a
    # protected limit.  Only signals that can actually reach submission share
    # the account-level batch budget below.
    for signal_index, signal in enumerate(buy_signals.to_dict("records")):
        workflow_by_signal_index[signal_index] = _signal_workflow(signal)
        symbol = str(signal["Asset"])
        symbol_key = symbol.upper()
        signal_date = str(signal["Date"])
        client_order_id = _alpaca_buy_client_order_id_for_signal(conn, symbol, signal_date)
        failure_context.current_row = {
            "Workflow": workflow_by_signal_index[signal_index],
            "Asset": symbol,
            "Date": signal_date,
            "Client Order ID": client_order_id,
            "Notional": None,
            "Qty": None,
            "Limit Price": None,
            "Alpaca Order ID": None,
            "_signal_index": signal_index,
        }
        managed_observation_in_progress = False
        deterministic_broker_order_observed = False
        observed_deterministic_order_id: str | None = None
        observed_deterministic_order_status: str | None = None
        has_managed_signal_details = conn is not None and _ALPACA_MANAGED_BUY_SIGNAL_FIELDS.issubset(signal)

        try:
            if not signal_observation_is_fresh(
                signal_date,
                signal.get("RSI Observation Date"),
            ):
                append_preflight_result(
                    signal_index,
                    symbol=symbol,
                    signal_date=signal_date,
                    client_order_id=client_order_id,
                    status="stale_observation",
                    message=(
                        "RSI observation date is missing, invalid, or outside the accepted window around "
                        "the asset signal date; order skipped"
                    ),
                )
                continue
            if symbol_key in pending_batch_symbols or client_order_id in pending_batch_client_order_ids:
                append_preflight_result(
                    signal_index,
                    symbol=symbol,
                    signal_date=signal_date,
                    client_order_id=client_order_id,
                    status="duplicate_signal",
                    message="duplicate buy signal for symbol or client order ID in this batch; order skipped",
                )
                continue

            if symbol_key in managed_symbols:
                append_preflight_result(
                    signal_index,
                    symbol=symbol,
                    signal_date=signal_date,
                    client_order_id=client_order_id,
                    status="managed",
                    message="symbol already has an active managed Alpaca position",
                )
                continue

            preflight_attempts += 1
            if client is None:
                client = AlpacaClient(
                    cfg,
                    equity_scope_asset_ids=managed_equity_scope_asset_ids,
                )
                sensitive_values = _merged_alpaca_sensitive_values(
                    sensitive_values,
                    _alpaca_client_sensitive_values(client),
                )
            existing_resp = client.get_order_by_client_order_id(client_order_id)
            existing_payload: dict | None = None
            open_orders: list[dict] | None = None
            if existing_resp.status_code == 200:
                # The exact deterministic lookup is already affirmative broker
                # evidence.  Preserve it before resolving replacement lineage,
                # because payload validation or a successor lookup can fail
                # independently.
                deterministic_broker_order_observed = True
                phase_one_deterministic_broker_order_observed = True
                existing_payload = _response_json(existing_resp)
            elif existing_resp.status_code == 404:
                try:
                    open_orders = client.open_orders(
                        equity_scope_asset_ids=managed_equity_scope_asset_ids,
                    )
                except _OpenOrderSnapshotError as exc:
                    malformed_deterministic_orders = [
                        order
                        for order in exc.observed_orders
                        if _optional_str(order.get("client_order_id")) == client_order_id
                    ]
                    if malformed_deterministic_orders:
                        deterministic_broker_order_observed = True
                        phase_one_deterministic_broker_order_observed = True
                        observed_order_ids = {
                            order_id
                            for order in malformed_deterministic_orders
                            if (order_id := _optional_str(order.get("id"))) is not None
                        }
                        if len(observed_order_ids) == 1:
                            observed_deterministic_order_id = next(iter(observed_order_ids))
                        observed_statuses = {
                            status
                            for order in malformed_deterministic_orders
                            if (status := _broker_order_status(order))
                        }
                        if len(observed_statuses) == 1:
                            observed_deterministic_order_status = next(iter(observed_statuses))
                    raise
                deterministic_orders = [
                    order for order in open_orders if _optional_str(order.get("client_order_id")) == client_order_id
                ]
                if len(deterministic_orders) > 1:
                    deterministic_broker_order_observed = True
                    phase_one_deterministic_broker_order_observed = True
                    duplicate_message = "Alpaca returned multiple open orders for the deterministic buy ID"
                    fatal_batch_messages.append(duplicate_message)
                    raise ValueError(duplicate_message)
                if deterministic_orders:
                    existing_payload = deterministic_orders[0]
                    deterministic_broker_order_observed = True
                    phase_one_deterministic_broker_order_observed = True
            else:
                _require_2xx_response(existing_resp)
                raise ValueError(f"Alpaca buy-order lookup returned unexpected HTTP status {existing_resp.status_code}")

            if existing_payload is not None:
                observed_deterministic_order_id = _optional_str(existing_payload.get("id"))
                observed_deterministic_order_status = _broker_order_status(existing_payload) or None
                existing, existing_replacement_chain = _fetch_order_replacement_chain(
                    client,
                    existing_payload,
                    client_order_id,
                )
                existing_root = existing_replacement_chain[0]
                existing_qty = _optional_positive_float(existing_root.get("qty"))
                existing_limit_price = _optional_positive_float(existing_root.get("limit_price"))
                try:
                    _validate_buy_order_identity(
                        buy_order=existing,
                        expected_client_order_id=client_order_id,
                        expected_symbol=None,
                        expected_qty=existing_qty,
                        expected_limit_price=existing_limit_price,
                        replacement_chain=existing_replacement_chain,
                        require_expected_intent=True,
                    )
                except BuyOrderIdentityError as exc:
                    identity_message = (
                        f"Alpaca already contains an accepted buy with an identity mismatch: {exc}; "
                        "the broker order was not adopted and requires immediate review"
                    )
                    fatal_batch_messages.append(identity_message)
                    append_preflight_result(
                        signal_index,
                        symbol=symbol,
                        signal_date=signal_date,
                        client_order_id=client_order_id,
                        status="identity_mismatch",
                        alpaca_order_id=_optional_str(existing.get("id")),
                        message=identity_message,
                    )
                    continue
                # The account contains the requested deterministic client ID
                # with a structurally valid buy intent.  Stable-asset lookup is
                # still required before adoption, but a lookup failure cannot
                # make the already-visible broker side effect disappear.
                phase_one_deterministic_broker_order_observed = True
                try:
                    visible_asset_id = _validated_alpaca_asset_id(
                        client.asset(symbol),
                        expected_symbol=symbol,
                    )
                    managed_equity_scope_asset_ids.add(visible_asset_id)
                except Exception as exc:
                    safe_detail = _alpaca_exception_diagnostic(
                        exc,
                        cfg=cfg,
                        sensitive_values=sensitive_values,
                    )
                    fatal_batch_messages.append(
                        "Alpaca already contains the deterministic buy, but its independent stable asset "
                        f"identity could not be verified: {safe_detail}"
                    )
                    raise
                try:
                    _validate_buy_order_identity(
                        buy_order=existing,
                        expected_client_order_id=client_order_id,
                        expected_symbol=None,
                        expected_alpaca_asset_id=visible_asset_id,
                        expected_qty=existing_qty,
                        expected_limit_price=existing_limit_price,
                        replacement_chain=existing_replacement_chain,
                        require_expected_intent=True,
                    )
                except BuyOrderIdentityError as exc:
                    identity_message = (
                        f"Alpaca already contains an accepted buy with an identity mismatch: {exc}; "
                        "the broker order was not adopted and requires immediate review"
                    )
                    if has_managed_signal_details:
                        assert conn is not None
                        durable_intent = conn.execute(
                            """
                            SELECT id
                            FROM alpaca_managed_positions
                            WHERE buy_client_order_id = ?
                              AND UPPER(symbol) = UPPER(?)
                              AND buy_signal_date = ?
                              AND (alpaca_asset_id IS NULL OR alpaca_asset_id = ?)
                            """,
                            (client_order_id, symbol, signal_date, visible_asset_id),
                        ).fetchone()
                        if durable_intent is not None:
                            identity_message = (
                                f"{identity_message}; protective-sell automation is quarantined pending review"
                            )
                            managed_observation_in_progress = True
                            mismatch_persisted = _quarantine_managed_buy_side_effect_from_current_snapshot(
                                conn=conn,
                                position_id=int(durable_intent[0]),
                                buy_status="identity_mismatch",
                                # A stable-asset mismatch proves that this
                                # deterministic broker order is not safely
                                # attributable to the durable local intent.
                                # Fence the intent without binding the foreign
                                # broker order ID to it.
                                observed_buy_alpaca_order_id=None,
                                observed_buy_submitted_at=None,
                                notes=durable_note(identity_message),
                            )
                            managed_observation_in_progress = False
                            if not mismatch_persisted:
                                raise RuntimeError(
                                    "managed buy stable-asset identity mismatch lost its diagnostic persistence race"
                                ) from exc
                    fatal_batch_messages.append(identity_message)
                    append_preflight_result(
                        signal_index,
                        symbol=symbol,
                        signal_date=signal_date,
                        client_order_id=client_order_id,
                        status="identity_mismatch",
                        alpaca_order_id=_optional_str(existing.get("id")),
                        message=identity_message,
                    )
                    continue
                if has_managed_signal_details:
                    assert conn is not None
                    durable_intent = conn.execute(
                        """
                        SELECT id, buy_order_qty, buy_order_limit_price
                        FROM alpaca_managed_positions
                        WHERE buy_client_order_id = ?
                          AND UPPER(symbol) = UPPER(?)
                          AND buy_signal_date = ?
                          AND (alpaca_asset_id IS NULL OR alpaca_asset_id = ?)
                        """,
                        (client_order_id, symbol, signal_date, visible_asset_id),
                    ).fetchone()
                    if durable_intent is None:
                        ownership_message = (
                            "Alpaca already contains the deterministic buy, but this database has no durable "
                            "matching managed-buy intent; the broker order remains unowned and requires "
                            "immediate review"
                        )
                        fatal_batch_messages.append(ownership_message)
                        append_preflight_result(
                            signal_index,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            status="unowned_existing",
                            alpaca_order_id=_optional_str(existing.get("id")),
                            message=ownership_message,
                        )
                        continue
                    durable_qty = _canonical_whole_share_qty(durable_intent[1])
                    durable_limit_price = _canonical_alpaca_limit_price(durable_intent[2])
                    durable_identity_issue = _buy_order_identity_issue(
                        existing,
                        expected_client_order_id=client_order_id,
                        expected_symbol=symbol,
                        expected_alpaca_asset_id=visible_asset_id,
                        expected_qty=durable_qty,
                        expected_limit_price=durable_limit_price,
                        replacement_chain=existing_replacement_chain,
                        require_expected_intent=True,
                    )
                    if durable_identity_issue is not None:
                        identity_message = (
                            "Alpaca already contains the deterministic buy, but its quantity or limit price "
                            f"conflicts with the durable immutable intent: {durable_identity_issue}; "
                            "the broker order could not be safely managed or adopted and requires immediate review"
                        )
                        fatal_batch_messages.append(identity_message)
                        append_preflight_result(
                            signal_index,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            status="identity_mismatch",
                            alpaca_order_id=_optional_str(existing.get("id")),
                            message=identity_message,
                        )
                        continue
                fill_metadata_issue = _buy_replacement_chain_fill_metadata_issue(
                    existing_replacement_chain,
                    expected_buy_qty=existing_qty,
                )
                persisted_buy_status = (
                    "incomplete_fill_metadata"
                    if fill_metadata_issue is not None
                    else _broker_order_status(existing, default="existing")
                )
                if has_managed_signal_details:
                    assert conn is not None
                    # From this point the deterministic broker order and its
                    # stable asset have both been verified.  A local adoption
                    # failure is systemic: do not add more account exposure,
                    # and ensure the workflow immediately reconciles any state
                    # that was committed before the failure surfaced.
                    managed_observation_in_progress = True
                    existing_order_id = _optional_str(existing.get("id"))
                    assert existing_order_id is not None
                    assert existing_qty is not None
                    assert existing_limit_price is not None
                    adopt_alpaca_managed_buy_order_if_submission_not_found(
                        conn,
                        workflow=_signal_workflow(signal),
                        symbol=symbol,
                        signal_symbol=str(signal["RSI Symbol"]),
                        buy_rsi=float(signal["Buy RSI"]),
                        profit_target_multiple=float(signal["Sell Return Multiple"]),
                        buy_signal_date=signal_date,
                        buy_client_order_id=client_order_id,
                        buy_alpaca_order_id=existing_order_id,
                        buy_submitted_at=_optional_alpaca_datetime_str(existing.get("submitted_at")),
                        buy_status=persisted_buy_status,
                        buy_order_qty=existing_qty,
                        buy_order_limit_price=existing_limit_price,
                        alpaca_asset_id=visible_asset_id,
                    )
                    observation_issue = alpaca_managed_buy_order_observation_issue(
                        conn,
                        workflow=_signal_workflow(signal),
                        symbol=symbol,
                        signal_symbol=str(signal["RSI Symbol"]),
                        buy_rsi=float(signal["Buy RSI"]),
                        profit_target_multiple=float(signal["Sell Return Multiple"]),
                        buy_signal_date=signal_date,
                        buy_client_order_id=client_order_id,
                        buy_alpaca_order_id=existing_order_id,
                        buy_order_qty=existing_qty,
                        buy_order_limit_price=existing_limit_price,
                        alpaca_asset_id=visible_asset_id,
                    )
                    if observation_issue is not None:
                        identity_message = (
                            "Visible Alpaca buy order could not be safely managed: "
                            f"{observation_issue}; the broker order was not adopted and requires immediate review"
                        )
                        fatal_batch_messages.append(identity_message)
                        append_preflight_result(
                            signal_index,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            status="identity_mismatch",
                            alpaca_order_id=existing_order_id,
                            message=identity_message,
                        )
                        continue
                    observation_notes = (
                        "visible managed buy replacement chain reported a fill without positive, complete metadata; "
                        "protective-sell automation is quarantined pending reconciliation"
                        if fill_metadata_issue is not None
                        else None
                    )
                    if fill_metadata_issue is not None:
                        save_alpaca_managed_buy_order(
                            conn,
                            workflow=_signal_workflow(signal),
                            symbol=symbol,
                            alpaca_asset_id=visible_asset_id,
                            signal_symbol=str(signal["RSI Symbol"]),
                            buy_rsi=float(signal["Buy RSI"]),
                            profit_target_multiple=float(signal["Sell Return Multiple"]),
                            buy_signal_date=signal_date,
                            buy_client_order_id=client_order_id,
                            buy_alpaca_order_id=existing.get("id"),
                            buy_submitted_at=_optional_alpaca_datetime_str(existing.get("submitted_at")),
                            buy_status=persisted_buy_status,
                            notes=durable_note(observation_notes),
                            buy_order_qty=existing_qty,
                            buy_order_limit_price=existing_limit_price,
                            require_applied=True,
                            require_existing=True,
                        )
                        observed_filled_qty = 0.0
                    else:
                        _, observed_filled_qty, _ = _persist_managed_buy_observation(
                            conn=conn,
                            signal=signal,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            buy_order=existing,
                            replacement_chain=existing_replacement_chain,
                            order_qty=existing_qty,
                            limit_price=existing_limit_price,
                            notes=durable_note(observation_notes),
                            expected_alpaca_asset_id=visible_asset_id,
                            require_existing_intent=True,
                            cfg=cfg,
                            sensitive_values=sensitive_values,
                            client=client,
                        )
                    managed_symbols.add(symbol.upper())
                    managed_observation_in_progress = False
                else:
                    observed_filled_qty, _, _ = _replacement_chain_fill_metadata(existing_replacement_chain)
                if fill_metadata_issue is not None:
                    fatal_batch_messages.append(fill_metadata_issue)
                    append_preflight_result(
                        signal_index,
                        symbol=symbol,
                        signal_date=signal_date,
                        client_order_id=client_order_id,
                        status="incomplete_fill_metadata",
                        alpaca_order_id=_optional_str(existing.get("id")),
                        message=fill_metadata_issue,
                    )
                    continue
                append_preflight_result(
                    signal_index,
                    symbol=symbol,
                    signal_date=signal_date,
                    client_order_id=client_order_id,
                    status=(
                        "filled"
                        if _broker_order_status(existing) == "filled"
                        else "partially_filled"
                        if observed_filled_qty > 0.0
                        else _broker_order_status(existing)
                        if _broker_order_status(existing)
                        in {
                            *BUY_TERMINAL_STATUSES,
                            *BUY_NONTERMINAL_PAUSED_STATUSES,
                        }
                        else "existing"
                    ),
                    alpaca_order_id=existing.get("id"),
                    message=_broker_order_status(existing, default="order already exists"),
                )
                continue

            if open_orders is None:
                open_orders = client.open_orders(
                    equity_scope_asset_ids=managed_equity_scope_asset_ids,
                )
            open_buy_order = _orders_have_open_order(open_orders, symbol, "buy")
            open_sell_order = _orders_have_open_order(open_orders, symbol, "sell")
            asset: dict | None = None
            alpaca_asset_id: str | None = None
            if open_orders and not (open_buy_order or open_sell_order):
                asset = client.asset(symbol)
                alpaca_asset_id = _validated_alpaca_asset_id(asset, expected_symbol=symbol)
                open_buy_order = _orders_have_open_order(
                    open_orders,
                    symbol,
                    "buy",
                    expected_alpaca_asset_id=alpaca_asset_id,
                )
                open_sell_order = _orders_have_open_order(
                    open_orders,
                    symbol,
                    "sell",
                    expected_alpaca_asset_id=alpaca_asset_id,
                )
            if open_buy_order:
                append_preflight_result(
                    signal_index,
                    symbol=symbol,
                    signal_date=signal_date,
                    client_order_id=client_order_id,
                    status="open_order",
                    message="open buy order already exists for symbol in Alpaca account",
                )
                continue

            if open_sell_order:
                append_preflight_result(
                    signal_index,
                    symbol=symbol,
                    signal_date=signal_date,
                    client_order_id=client_order_id,
                    status="open_sell_order",
                    message="open sell order already exists for symbol in Alpaca account",
                )
                continue

            if asset is None:
                asset = client.asset(symbol)
            if alpaca_asset_id is None:
                alpaca_asset_id = _validated_alpaca_asset_id(asset, expected_symbol=symbol)
            managed_equity_scope_asset_ids.add(alpaca_asset_id)

            position_qty = client.position_qty(alpaca_asset_id)
            if position_qty != 0:
                append_preflight_result(
                    signal_index,
                    symbol=symbol,
                    signal_date=signal_date,
                    client_order_id=client_order_id,
                    status="held",
                    message=f"symbol already has an Alpaca position: qty={position_qty}",
                )
                continue

            asset_status_diagnostic = (
                _safe_alpaca_diagnostic_text(
                    asset.get("status"),
                    max_chars=_ALPACA_ASSET_STATUS_DIAGNOSTIC_MAX_CHARS,
                    sensitive_values=sensitive_values,
                )
                or "unknown"
            )
            if asset.get("tradable") is not True:
                append_preflight_result(
                    signal_index,
                    symbol=symbol,
                    signal_date=signal_date,
                    client_order_id=client_order_id,
                    status="not_tradable",
                    message=f"symbol is not tradable through Alpaca: status={asset_status_diagnostic}",
                )
                continue
            if asset.get("status") != "active":
                append_preflight_result(
                    signal_index,
                    symbol=symbol,
                    signal_date=signal_date,
                    client_order_id=client_order_id,
                    status="inactive",
                    message=f"symbol is not active through Alpaca: status={asset_status_diagnostic}",
                )
                continue
            if market_clock is None:
                market_clock = client.market_clock()
            market_is_open = _validated_market_clock_is_open(market_clock)
            next_open, clock_timestamp = _validated_market_clock_times(
                market_clock,
                require_current=True,
            )
            if not market_is_open:
                next_open_date = next_open.astimezone(_NEW_YORK).date()
                clock_date = clock_timestamp.astimezone(_NEW_YORK).date()
                if not calendar_loaded and next_open_date == clock_date:
                    calendar = client.calendar(
                        start=clock_timestamp.astimezone(_NEW_YORK).date() - timedelta(days=14),
                        end=next_open.astimezone(_NEW_YORK).date(),
                    )
                    prior_session = _prior_calendar_session(calendar, next_open)
                    calendar_loaded = True
            can_submit, defer_message = _buy_submission_window(market_clock, signal_date, prior_session)
            if not can_submit:
                append_preflight_result(
                    signal_index,
                    symbol=symbol,
                    signal_date=signal_date,
                    client_order_id=client_order_id,
                    status="deferred",
                    message=defer_message,
                )
                continue
            if prior_session is None:
                raise RuntimeError("Authorized Alpaca buy has no validated prior trading session")
            latest_price = _latest_market_price(
                symbol,
                timeout_seconds=cfg.timeout_seconds,
                expected_session=prior_session,
            )
            if latest_price <= 0:
                raise ValueError(f"Latest market price must be positive; got {latest_price} for {symbol}.")
            limit_price = buffered_buy_limit_price(latest_price, cfg.buy_limit_buffer_bps)
            if limit_price <= 0:
                raise ValueError(f"Calculated buy limit price must be positive; got {limit_price} for {symbol}.")
            pending_batch_symbols.add(symbol_key)
            pending_batch_client_order_ids.add(client_order_id)
            eligible_orders.append(
                {
                    "signal_index": signal_index,
                    "signal": signal,
                    "symbol": symbol,
                    "signal_date": signal_date,
                    "client_order_id": client_order_id,
                    "limit_price": limit_price,
                    "alpaca_asset_id": alpaca_asset_id,
                    "authorized_next_open": next_open,
                    "authorized_clock_timestamp": clock_timestamp,
                }
            )
        except HTTPError as exc:
            preflight_exception_failures += 1
            error_message = _http_error_message(exc, sensitive_values=sensitive_values)
            result_message = (
                f"{error_message}{_deterministic_broker_observation_suffix(observed_deterministic_order_status)}"
            )
            result_message = _safe_alpaca_diagnostic_text(
                result_message,
                max_chars=_ALPACA_HTTP_ERROR_MESSAGE_MAX_CHARS,
                sensitive_values=_merged_alpaca_sensitive_values(
                    sensitive_values,
                    _alpaca_config_sensitive_values(cfg),
                ),
            )
            if deterministic_broker_order_observed or _authentication_http_error(
                exc,
                sensitive_values=sensitive_values,
            ):
                fatal_batch_messages.append(result_message)
            append_preflight_result(
                signal_index,
                symbol=symbol,
                signal_date=signal_date,
                client_order_id=client_order_id,
                status="error",
                alpaca_order_id=observed_deterministic_order_id,
                message=result_message,
            )
        except requests.RequestException as exc:
            preflight_exception_failures += 1
            detail = _alpaca_exception_diagnostic(
                exc,
                cfg=cfg,
                sensitive_values=sensitive_values,
            )
            result_message = f"{detail}{_deterministic_broker_observation_suffix(observed_deterministic_order_status)}"
            result_message = _safe_alpaca_diagnostic_text(
                result_message,
                max_chars=_ALPACA_HTTP_ERROR_MESSAGE_MAX_CHARS,
                sensitive_values=_merged_alpaca_sensitive_values(
                    sensitive_values,
                    _alpaca_config_sensitive_values(cfg),
                ),
            )
            if deterministic_broker_order_observed:
                fatal_batch_messages.append(result_message)
            append_preflight_result(
                signal_index,
                symbol=symbol,
                signal_date=signal_date,
                client_order_id=client_order_id,
                status="error",
                alpaca_order_id=observed_deterministic_order_id,
                message=result_message,
            )
        except Exception as exc:
            preflight_exception_failures += 1
            diagnostic_sensitive_values = _merged_alpaca_sensitive_values(
                sensitive_values,
                _alpaca_config_sensitive_values(cfg),
            )
            safe_detail = _alpaca_exception_diagnostic(
                exc,
                cfg=cfg,
                sensitive_values=diagnostic_sensitive_values,
            ) or _safe_alpaca_diagnostic_text(
                type(exc).__name__,
                max_chars=_ALPACA_HTTP_ERROR_MESSAGE_MAX_CHARS,
                sensitive_values=diagnostic_sensitive_values,
            )
            fatal_preflight_failure = managed_observation_in_progress
            if managed_observation_in_progress:
                result_message = (
                    "Alpaca already contains the verified deterministic buy, but local managed-state "
                    f"persistence failed: {safe_detail}"
                    f"{_deterministic_broker_observation_suffix(observed_deterministic_order_status)}"
                )
            else:
                result_message = (
                    f"{safe_detail}{_deterministic_broker_observation_suffix(observed_deterministic_order_status)}"
                )
                fatal_preflight_failure = deterministic_broker_order_observed or _credential_configuration_error(exc)
            result_message = _safe_alpaca_diagnostic_text(
                result_message,
                max_chars=_ALPACA_HTTP_ERROR_MESSAGE_MAX_CHARS,
                sensitive_values=diagnostic_sensitive_values,
            )
            if fatal_preflight_failure:
                fatal_batch_messages.append(result_message)
            append_preflight_result(
                signal_index,
                symbol=symbol,
                signal_date=signal_date,
                client_order_id=client_order_id,
                status="error",
                alpaca_order_id=observed_deterministic_order_id,
                message=result_message,
            )

    if fatal_batch_messages and eligible_orders:
        for order in eligible_orders:
            append_preflight_result(
                int(order["signal_index"]),
                symbol=str(order["symbol"]),
                signal_date=str(order["signal_date"]),
                client_order_id=str(order["client_order_id"]),
                status="batch_aborted",
                message="buy submission skipped because another phase-one safety check made the batch fatal",
                limit_price=float(order["limit_price"]),
            )
        eligible_orders = []

    if eligible_orders:
        assert client is not None
        try:
            batch_notional = client.cash_notional(eligible_buy_signal_count=len(eligible_orders))
        except HTTPError as exc:
            error_message = _http_error_message(exc, sensitive_values=sensitive_values)
            fatal_batch_messages.append(f"Alpaca buy-batch account lookup failed: {error_message}")
            for order in eligible_orders:
                append_preflight_result(
                    int(order["signal_index"]),
                    symbol=str(order["symbol"]),
                    signal_date=str(order["signal_date"]),
                    client_order_id=str(order["client_order_id"]),
                    status="error",
                    message=error_message,
                    limit_price=float(order["limit_price"]),
                )
        except requests.RequestException as exc:
            error_message = _alpaca_exception_diagnostic(
                exc,
                cfg=cfg,
                sensitive_values=sensitive_values,
            )
            fatal_batch_messages.append(f"Alpaca buy-batch account lookup failed: {error_message}")
            for order in eligible_orders:
                append_preflight_result(
                    int(order["signal_index"]),
                    symbol=str(order["symbol"]),
                    signal_date=str(order["signal_date"]),
                    client_order_id=str(order["client_order_id"]),
                    status="error",
                    message=error_message,
                    limit_price=float(order["limit_price"]),
                )
        except Exception as exc:
            error_message = _alpaca_exception_diagnostic(
                exc,
                cfg=cfg,
                sensitive_values=sensitive_values,
            )
            fatal_batch_messages.append(f"Alpaca buy-batch account lookup failed: {error_message}")
            for order in eligible_orders:
                append_preflight_result(
                    int(order["signal_index"]),
                    symbol=str(order["symbol"]),
                    signal_date=str(order["signal_date"]),
                    client_order_id=str(order["client_order_id"]),
                    status="error",
                    message=error_message,
                    limit_price=float(order["limit_price"]),
                )
        else:
            remaining_batch_notional = batch_notional
            per_signal_budget = batch_notional / len(eligible_orders)
            for order in eligible_orders:
                signal_index = int(order["signal_index"])
                signal = order["signal"]
                assert isinstance(signal, dict)
                symbol = str(order["symbol"])
                signal_date = str(order["signal_date"])
                client_order_id = str(order["client_order_id"])
                limit_price = float(order["limit_price"])
                alpaca_asset_id = str(order["alpaca_asset_id"])
                authorized_next_open = order["authorized_next_open"]
                if not isinstance(authorized_next_open, datetime):
                    raise RuntimeError("Eligible Alpaca buy has no validated next-open timestamp")
                authorized_clock_timestamp = order["authorized_clock_timestamp"]
                if not isinstance(authorized_clock_timestamp, datetime):
                    raise RuntimeError("Eligible Alpaca buy has no validated market-clock timestamp")
                if fatal_batch_messages:
                    append_preflight_result(
                        signal_index,
                        symbol=symbol,
                        signal_date=signal_date,
                        client_order_id=client_order_id,
                        status="batch_aborted",
                        message="buy submission skipped because an earlier order made the batch fatal",
                        limit_price=limit_price,
                    )
                    continue
                order_notional = min(per_signal_budget, remaining_batch_notional)
                order_qty: int | None = None
                if order_notional <= 0:
                    append_preflight_result(
                        signal_index,
                        symbol=symbol,
                        signal_date=signal_date,
                        client_order_id=client_order_id,
                        notional=0.0,
                        limit_price=limit_price,
                        status="batch_budget_exhausted",
                        message="the configured Alpaca buy-batch budget is exhausted",
                    )
                    continue

                order_qty = floor(order_notional / limit_price)
                if order_qty < 1:
                    append_preflight_result(
                        signal_index,
                        symbol=symbol,
                        signal_date=signal_date,
                        client_order_id=client_order_id,
                        notional=order_notional,
                        qty=order_qty,
                        limit_price=limit_price,
                        status="insufficient_notional",
                        message=(
                            "allocated buy-batch budget is below one whole share "
                            f"at protected limit price {limit_price:.4f}; buy order skipped"
                        ),
                    )
                    continue

                order_notional = round(order_qty * limit_price, 2)
                failure_context.current_row = {
                    "Workflow": workflow_by_signal_index.get(signal_index),
                    "Asset": symbol,
                    "Date": signal_date,
                    "Client Order ID": client_order_id,
                    "Notional": order_notional,
                    "Qty": order_qty,
                    "Limit Price": limit_price,
                    "Alpaca Order ID": None,
                    "_signal_index": signal_index,
                }
                # Reserve capacity before the API request.  If the response is
                # ambiguous or fails after Alpaca accepted it, retrying cannot
                # accidentally over-allocate the configured batch budget.
                remaining_batch_notional = max(remaining_batch_notional - order_notional, 0.0)
                is_managed_signal = conn is not None and {"RSI Symbol", "Buy RSI", "Sell Return Multiple"}.issubset(
                    signal
                )
                managed_position_id: int | None = None
                managed_submission_attempt_count: int | None = None
                managed_submission_state_revision: int | None = None
                submission_claimed = False
                if is_managed_signal:
                    managed_claim = claim_alpaca_managed_buy_intent(
                        conn,
                        workflow=_signal_workflow(signal),
                        symbol=symbol,
                        alpaca_asset_id=alpaca_asset_id,
                        signal_symbol=str(signal["RSI Symbol"]),
                        buy_rsi=float(signal["Buy RSI"]),
                        profit_target_multiple=float(signal["Sell Return Multiple"]),
                        buy_signal_date=signal_date,
                        buy_client_order_id=client_order_id,
                        buy_order_qty=order_qty,
                        buy_order_limit_price=limit_price,
                        sell_order_namespace=alpaca_exit_order_namespace(client_order_id),
                        # Phase one already looked up this deterministic ID and
                        # received a 404, so only a previously verified missing
                        # intent may be reclaimed here.
                        allow_retry_after_not_found=True,
                    )
                    if managed_claim.symbol_conflict:
                        remaining_batch_notional = min(
                            remaining_batch_notional + order_notional,
                            batch_notional,
                        )
                        managed_symbols.add(symbol.upper())
                        append_preflight_result(
                            signal_index,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            notional=order_notional,
                            qty=order_qty,
                            limit_price=limit_price,
                            status="managed",
                            message=("symbol was claimed concurrently by another active managed Alpaca position"),
                        )
                        continue
                    managed_position_id, submission_claimed = managed_claim
                    assert managed_position_id is not None
                    managed_submission_attempt_count = managed_claim.attempt_count
                    managed_submission_state_revision = managed_claim.state_revision
                    managed_symbols.add(symbol.upper())

                if is_managed_signal and not submission_claimed:
                    try:
                        existing_resp = client.get_order_by_client_order_id(client_order_id)
                    except requests.RequestException as exc:
                        error_message = _alpaca_exception_diagnostic(
                            exc,
                            cfg=cfg,
                            sensitive_values=sensitive_values,
                        )
                        remaining_batch_notional = min(
                            remaining_batch_notional + order_notional,
                            batch_notional,
                        )
                        append_preflight_result(
                            signal_index,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            notional=order_notional,
                            qty=order_qty,
                            limit_price=limit_price,
                            status="submission_pending",
                            message=(
                                "another workflow owns this managed buy intent; broker lookup is pending: "
                                f"{error_message}"
                            ),
                        )
                        continue
                    if managed_claim.intent_conflict:
                        remaining_batch_notional = min(
                            remaining_batch_notional + order_notional,
                            batch_notional,
                        )
                        append_preflight_result(
                            signal_index,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            notional=order_notional,
                            qty=order_qty,
                            limit_price=limit_price,
                            status="managed",
                            message=(
                                "another workflow owns this deterministic managed buy with different "
                                "immutable strategy economics"
                            ),
                        )
                        continue
                    if existing_resp.status_code == 200:
                        existing, existing_replacement_chain = _fetch_order_replacement_chain(
                            client,
                            _response_json(existing_resp),
                            client_order_id,
                        )
                        identity_issue = _buy_order_identity_issue(
                            existing,
                            expected_client_order_id=client_order_id,
                            expected_symbol=symbol,
                            expected_alpaca_asset_id=alpaca_asset_id,
                            expected_qty=order_qty,
                            expected_limit_price=limit_price,
                            replacement_chain=existing_replacement_chain,
                        )
                        if identity_issue is not None:
                            (
                                quarantine_status,
                                attributed_order_id,
                                cancellation_lineage,
                                cancellation_message,
                            ) = _attributed_buy_identity_mismatch_quarantine_plan(
                                existing,
                                identity_issue=identity_issue,
                                expected_client_order_id=client_order_id,
                                expected_symbol=symbol,
                                expected_alpaca_asset_id=alpaca_asset_id,
                                replacement_chain=existing_replacement_chain,
                            )
                            identity_message = (
                                f"another workflow's broker lookup found an identity mismatch: {identity_issue}; "
                                f"{cancellation_message}; the managed intent is quarantined and requires "
                                "immediate review"
                            )
                            assert managed_position_id is not None
                            assert managed_submission_attempt_count is not None
                            status_updated = update_alpaca_managed_buy_status_if_current(
                                conn,
                                managed_position_id,
                                expected_buy_status="submission_pending",
                                expected_buy_alpaca_order_id=None,
                                expected_filled_qty=None,
                                expected_sell_client_order_id=None,
                                expected_buy_submission_attempt_count=managed_submission_attempt_count,
                                expected_state_revision=managed_submission_state_revision,
                                buy_status=quarantine_status,
                                buy_alpaca_order_id=attributed_order_id,
                                buy_submitted_at=_optional_alpaca_datetime_str(existing.get("submitted_at")),
                                notes=durable_note(identity_message),
                            )
                            if cancellation_lineage is not None:
                                status_updated = _quarantine_managed_buy_side_effect_from_current_snapshot(
                                    conn=conn,
                                    position_id=managed_position_id,
                                    buy_status=quarantine_status,
                                    observed_buy_alpaca_order_id=attributed_order_id,
                                    observed_buy_submitted_at=_optional_alpaca_datetime_str(
                                        existing.get("submitted_at")
                                    ),
                                    notes=durable_note(identity_message),
                                    observed_buy_cancellation_alpaca_order_ids=[
                                        order_id
                                        for node in cancellation_lineage
                                        if (order_id := _optional_alpaca_broker_identifier(node.get("id"))) is not None
                                    ],
                                )
                            if (
                                status_updated
                                and quarantine_status == "pending_cancel"
                                and cancellation_lineage is not None
                            ):
                                _pending, cancellation_message = _request_safely_attributed_lineage_cancellations(
                                    client,
                                    cancellation_lineage,
                                )
                                identity_message = (
                                    "another workflow's broker lookup found an identity mismatch: "
                                    f"{identity_issue}; {cancellation_message}; the managed intent is "
                                    "quarantined and requires immediate review"
                                )
                            fatal_batch_messages.append(identity_message)
                            append_preflight_result(
                                signal_index,
                                symbol=symbol,
                                signal_date=signal_date,
                                client_order_id=client_order_id,
                                notional=order_notional,
                                qty=order_qty,
                                limit_price=limit_price,
                                status=quarantine_status if status_updated else "superseded",
                                alpaca_order_id=_optional_str(existing.get("id")),
                                message=(
                                    identity_message
                                    if status_updated
                                    else (
                                        f"{identity_message}; managed state changed concurrently, but the "
                                        "confirmed broker mismatch remains fatal"
                                    )
                                ),
                            )
                            continue
                        fill_metadata_issue = _buy_replacement_chain_fill_metadata_issue(
                            existing_replacement_chain,
                            expected_buy_qty=order_qty,
                        )
                        persisted_buy_status = (
                            "incomplete_fill_metadata"
                            if fill_metadata_issue is not None
                            else _broker_order_status(existing, default="existing")
                        )
                        existing_order_id = _optional_str(existing.get("id"))
                        assert existing_order_id is not None
                        observation_issue = alpaca_managed_buy_order_observation_issue(
                            conn,
                            workflow=_signal_workflow(signal),
                            symbol=symbol,
                            signal_symbol=str(signal["RSI Symbol"]),
                            buy_rsi=float(signal["Buy RSI"]),
                            profit_target_multiple=float(signal["Sell Return Multiple"]),
                            buy_signal_date=signal_date,
                            buy_client_order_id=client_order_id,
                            buy_alpaca_order_id=existing_order_id,
                            buy_order_qty=order_qty,
                            buy_order_limit_price=limit_price,
                            alpaca_asset_id=_optional_str(existing.get("asset_id")),
                        )
                        if observation_issue is not None:
                            identity_message = (
                                f"visible broker order was not adopted: {observation_issue}; "
                                "the managed intent is quarantined and requires immediate review"
                            )
                            assert managed_position_id is not None
                            assert managed_submission_attempt_count is not None
                            status_updated = update_alpaca_managed_buy_status_if_current(
                                conn,
                                managed_position_id,
                                expected_buy_status="submission_pending",
                                expected_buy_alpaca_order_id=None,
                                expected_filled_qty=None,
                                expected_sell_client_order_id=None,
                                expected_buy_submission_attempt_count=managed_submission_attempt_count,
                                expected_state_revision=managed_submission_state_revision,
                                buy_status="identity_mismatch",
                                notes=durable_note(identity_message),
                            )
                            fatal_batch_messages.append(identity_message)
                            append_preflight_result(
                                signal_index,
                                symbol=symbol,
                                signal_date=signal_date,
                                client_order_id=client_order_id,
                                notional=order_notional,
                                qty=order_qty,
                                limit_price=limit_price,
                                status="identity_mismatch" if status_updated else "superseded",
                                alpaca_order_id=existing_order_id,
                                message=(
                                    identity_message
                                    if status_updated
                                    else (
                                        f"{identity_message}; managed state changed concurrently, but the "
                                        "confirmed broker mismatch remains fatal"
                                    )
                                ),
                            )
                            continue
                        try:
                            observation_notes = (
                                "visible managed buy replacement chain reported a fill without positive, complete "
                                "metadata; protective-sell automation is quarantined pending reconciliation"
                                if fill_metadata_issue is not None
                                else "managed buy recovered by client order ID after another workflow claimed it"
                            )
                            if fill_metadata_issue is not None:
                                save_alpaca_managed_buy_order(
                                    conn,
                                    workflow=_signal_workflow(signal),
                                    symbol=symbol,
                                    alpaca_asset_id=alpaca_asset_id,
                                    signal_symbol=str(signal["RSI Symbol"]),
                                    buy_rsi=float(signal["Buy RSI"]),
                                    profit_target_multiple=float(signal["Sell Return Multiple"]),
                                    buy_signal_date=signal_date,
                                    buy_client_order_id=client_order_id,
                                    buy_alpaca_order_id=_optional_str(existing.get("id")),
                                    buy_submitted_at=_optional_alpaca_datetime_str(existing.get("submitted_at")),
                                    buy_status=persisted_buy_status,
                                    notes=durable_note(observation_notes),
                                    buy_order_qty=order_qty,
                                    buy_order_limit_price=limit_price,
                                    require_applied=True,
                                    expected_buy_submission_attempt_count=managed_submission_attempt_count,
                                    expected_state_revision=managed_submission_state_revision,
                                )
                                observed_filled_qty = 0.0
                            else:
                                _, observed_filled_qty, _ = _persist_managed_buy_observation(
                                    conn=conn,
                                    signal=signal,
                                    symbol=symbol,
                                    signal_date=signal_date,
                                    client_order_id=client_order_id,
                                    buy_order=existing,
                                    replacement_chain=existing_replacement_chain,
                                    order_qty=order_qty,
                                    limit_price=limit_price,
                                    notes=durable_note(observation_notes),
                                    expected_alpaca_asset_id=alpaca_asset_id,
                                    expected_buy_submission_attempt_count=managed_submission_attempt_count,
                                    expected_state_revision=managed_submission_state_revision,
                                    cfg=cfg,
                                    sensitive_values=sensitive_values,
                                    client=client,
                                )
                        except RuntimeError as exc:
                            if fill_metadata_issue is None and _managed_buy_lineage_is_durably_adopted(
                                conn=conn,
                                position_id=managed_position_id,
                                client_order_id=client_order_id,
                                expected_symbol=symbol,
                                expected_alpaca_asset_id=alpaca_asset_id,
                                expected_qty=order_qty,
                                expected_limit_price=limit_price,
                                replacement_chain=existing_replacement_chain,
                            ):
                                append_preflight_result(
                                    signal_index,
                                    symbol=symbol,
                                    signal_date=signal_date,
                                    client_order_id=client_order_id,
                                    notional=order_notional,
                                    qty=order_qty,
                                    limit_price=limit_price,
                                    status="existing",
                                    alpaca_order_id=existing_order_id,
                                    message=("concurrent managed state already adopted the exact visible buy lineage"),
                                )
                                continue
                            accepted_message = _append_accepted_buy_processing_failure(
                                conn=conn,
                                client=client,
                                rows=rows,
                                workflow=workflow_by_signal_index.get(signal_index),
                                signal_index=signal_index,
                                symbol=symbol,
                                signal_date=signal_date,
                                client_order_id=client_order_id,
                                notional=order_notional,
                                qty=order_qty,
                                limit_price=limit_price,
                                managed_position_id=managed_position_id,
                                managed_submission_attempt_count=managed_submission_attempt_count,
                                accepted_response_payload=existing,
                                expected_alpaca_asset_id=alpaca_asset_id,
                                accepted_replacement_chain=existing_replacement_chain,
                                detail=f"visible managed-buy recovery lost its persistence race: {exc}",
                            )
                            fatal_batch_messages.append(accepted_message)
                            continue
                        if fill_metadata_issue is not None:
                            fatal_batch_messages.append(fill_metadata_issue)
                            append_preflight_result(
                                signal_index,
                                symbol=symbol,
                                signal_date=signal_date,
                                client_order_id=client_order_id,
                                notional=order_notional,
                                qty=order_qty,
                                limit_price=limit_price,
                                status="incomplete_fill_metadata",
                                alpaca_order_id=existing_order_id,
                                message=fill_metadata_issue,
                            )
                            continue
                        append_preflight_result(
                            signal_index,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            notional=order_notional,
                            qty=order_qty,
                            limit_price=limit_price,
                            status=(
                                "filled"
                                if _broker_order_status(existing) == "filled"
                                else "partially_filled"
                                if observed_filled_qty > 0.0
                                else _broker_order_status(existing)
                                if _broker_order_status(existing)
                                in {
                                    *BUY_TERMINAL_STATUSES,
                                    *BUY_NONTERMINAL_PAUSED_STATUSES,
                                }
                                else "existing"
                            ),
                            alpaca_order_id=_optional_str(existing.get("id")),
                            message="another workflow already submitted this managed buy",
                        )
                    elif existing_resp.status_code == 404:
                        append_preflight_result(
                            signal_index,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            notional=order_notional,
                            qty=order_qty,
                            limit_price=limit_price,
                            status="submission_pending",
                            message=(
                                "another workflow owns this managed buy intent; "
                                "waiting for its broker submission to become visible"
                            ),
                        )
                    else:
                        try:
                            _require_2xx_response(existing_resp)
                        except HTTPError as exc:
                            lookup_message = _http_error_message(
                                exc,
                                sensitive_values=sensitive_values,
                            )
                        else:
                            lookup_message = (
                                "Alpaca managed-buy recovery lookup returned unexpected "
                                f"HTTP status {existing_resp.status_code}"
                            )
                        fatal_batch_messages.append(lookup_message)
                        append_preflight_result(
                            signal_index,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            notional=order_notional,
                            qty=order_qty,
                            limit_price=limit_price,
                            status="error",
                            message=lookup_message,
                        )
                    continue

                # Validate the broker clock before taking the final exposure
                # snapshot.  Nothing that can add broker exposure may happen
                # between that snapshot (and the managed SQLite fence below)
                # and POST.
                dispatch_authorization: _BuySubmissionDispatchAuthorization | None = None
                try:
                    final_clock_request_started_monotonic = _monotonic_now()
                    if not math.isfinite(final_clock_request_started_monotonic):
                        raise RuntimeError("Current monotonic time must be finite")
                    final_market_clock = client.market_clock()
                    final_can_submit, final_defer_message = _buy_submission_window(
                        final_market_clock,
                        signal_date,
                        prior_session,
                    )
                    if final_can_submit:
                        final_next_open, final_clock_timestamp = _validated_market_clock_times(
                            final_market_clock,
                            require_current=True,
                        )
                        if final_clock_timestamp < authorized_clock_timestamp:
                            raise ValueError("Alpaca final market-clock timestamp moved backwards")
                        if final_next_open != authorized_next_open:
                            final_can_submit = False
                            final_defer_message = "market submission window changed after buy preflight; order deferred"
                        else:
                            dispatch_authorization = _buy_submission_dispatch_authorization(
                                next_open=final_next_open,
                                broker_clock_timestamp=final_clock_timestamp,
                                request_timeout_seconds=cfg.timeout_seconds,
                                broker_clock_request_started_monotonic=final_clock_request_started_monotonic,
                            )
                except Exception as exc:
                    detail = _alpaca_exception_diagnostic(
                        exc,
                        cfg=cfg,
                        sensitive_values=sensitive_values,
                    )
                    cleanup_applied = _release_unsubmitted_managed_buy_claim(
                        conn,
                        position_id=managed_position_id,
                        submission_attempt_count=managed_submission_attempt_count,
                        notes=durable_note(
                            f"managed buy final market-clock validation failed before submission: {detail}"
                        ),
                    )
                    remaining_batch_notional = min(
                        remaining_batch_notional + order_notional,
                        batch_notional,
                    )
                    if cleanup_applied and is_managed_signal:
                        managed_symbols.discard(symbol.upper())
                    clock_failure_message = f"Alpaca final buy market-clock validation failed: {detail}"
                    fatal_batch_messages.append(clock_failure_message)
                    append_preflight_result(
                        signal_index,
                        symbol=symbol,
                        signal_date=signal_date,
                        client_order_id=client_order_id,
                        notional=order_notional,
                        qty=order_qty,
                        limit_price=limit_price,
                        status="error" if cleanup_applied else "superseded",
                        message=(
                            clock_failure_message
                            if cleanup_applied
                            else (
                                f"{clock_failure_message}; the managed generation changed concurrently and "
                                "requires reconciliation"
                            )
                        ),
                    )
                    continue

                if not final_can_submit:
                    cleanup_applied = _release_unsubmitted_managed_buy_claim(
                        conn,
                        position_id=managed_position_id,
                        submission_attempt_count=managed_submission_attempt_count,
                        notes=durable_note(
                            f"managed buy deferred by final market-clock validation: {final_defer_message}"
                        ),
                    )
                    remaining_batch_notional = min(
                        remaining_batch_notional + order_notional,
                        batch_notional,
                    )
                    if cleanup_applied and is_managed_signal:
                        managed_symbols.discard(symbol.upper())
                    append_preflight_result(
                        signal_index,
                        symbol=symbol,
                        signal_date=signal_date,
                        client_order_id=client_order_id,
                        notional=order_notional,
                        qty=order_qty,
                        limit_price=limit_price,
                        status="deferred" if cleanup_applied else "superseded",
                        message=(
                            final_defer_message
                            if cleanup_applied
                            else (
                                f"{final_defer_message}; the managed generation changed concurrently and "
                                "requires reconciliation"
                            )
                        ),
                    )
                    continue

                # Every supported public buy path gets a fresh broker snapshot
                # immediately before POST.  Only the SQLite generation fence
                # below is conditional on managed strategy state.
                if client is not None:
                    final_visible_payload: dict | None = None
                    final_visible_payloads: list[dict] = []
                    deterministic_order_was_visible = False
                    try:
                        final_existing_resp = client.get_order_by_client_order_id(client_order_id)
                        if final_existing_resp.status_code == 200:
                            deterministic_order_was_visible = True
                            final_visible_payload = _response_json(final_existing_resp)
                            final_visible_payloads = [final_visible_payload]
                            final_open_orders: list[dict] = []
                        else:
                            if final_existing_resp.status_code != 404:
                                _require_2xx_response(final_existing_resp)
                                raise ValueError(
                                    "Alpaca final buy lookup returned unexpected HTTP status "
                                    f"{final_existing_resp.status_code}"
                                )
                            # This is a complete, paginated snapshot. Stable asset
                            # identity prevents a ticker rename from hiding a
                            # conflicting manual or external order.
                            try:
                                final_open_orders = client.open_orders(
                                    equity_scope_asset_ids=managed_equity_scope_asset_ids,
                                )
                            except _OpenOrderSnapshotError as exc:
                                # The snapshot is not complete enough for ordinary
                                # exposure checks, but an exact deterministic
                                # client ID is still affirmative evidence that
                                # this managed buy may already exist. Preserve
                                # that evidence for the fenced quarantine path
                                # in the outer exception handler.
                                deterministic_orders = [
                                    open_order
                                    for open_order in exc.observed_orders
                                    if _optional_str(open_order.get("client_order_id")) == client_order_id
                                ]
                                if deterministic_orders:
                                    deterministic_order_was_visible = True
                                    final_visible_payload = deterministic_orders[0]
                                    final_visible_payloads = deterministic_orders
                                raise
                            deterministic_orders = [
                                open_order
                                for open_order in final_open_orders
                                if _optional_str(open_order.get("client_order_id")) == client_order_id
                            ]
                            if deterministic_orders:
                                deterministic_order_was_visible = True
                                final_visible_payload = deterministic_orders[0]
                                final_visible_payloads = deterministic_orders
                            if len(deterministic_orders) > 1:
                                raise ValueError("Alpaca returned multiple open orders for the deterministic buy ID")

                        if final_visible_payload is not None:
                            if not is_managed_signal:
                                visible, visible_replacement_chain = _fetch_order_replacement_chain(
                                    client,
                                    final_visible_payload,
                                    client_order_id,
                                )
                                identity_issue = _buy_order_identity_issue(
                                    visible,
                                    expected_client_order_id=client_order_id,
                                    expected_symbol=symbol,
                                    expected_alpaca_asset_id=alpaca_asset_id,
                                    expected_qty=order_qty,
                                    expected_limit_price=limit_price,
                                    replacement_chain=visible_replacement_chain,
                                )
                                if identity_issue is not None:
                                    identity_message = (
                                        "the deterministic buy became visible during final validation with an "
                                        f"identity mismatch: {identity_issue}; broker cancellation was not requested "
                                        "because this invocation has no durable ownership of the concurrently created "
                                        "order; review required"
                                    )
                                    fatal_batch_messages.append(identity_message)
                                    append_preflight_result(
                                        signal_index,
                                        symbol=symbol,
                                        signal_date=signal_date,
                                        client_order_id=client_order_id,
                                        notional=order_notional,
                                        qty=order_qty,
                                        limit_price=limit_price,
                                        status="identity_mismatch",
                                        alpaca_order_id=_optional_str(visible.get("id")),
                                        message=identity_message,
                                    )
                                    continue
                                fill_metadata_issue = _buy_replacement_chain_fill_metadata_issue(
                                    visible_replacement_chain,
                                    expected_buy_qty=order_qty,
                                )
                                observed_filled_qty, _, _ = _replacement_chain_fill_metadata(visible_replacement_chain)
                                if fill_metadata_issue is not None:
                                    fatal_batch_messages.append(fill_metadata_issue)
                                visible_status = _broker_order_status(visible, default="existing")
                                append_preflight_result(
                                    signal_index,
                                    symbol=symbol,
                                    signal_date=signal_date,
                                    client_order_id=client_order_id,
                                    notional=order_notional,
                                    qty=order_qty,
                                    limit_price=limit_price,
                                    status=(
                                        "incomplete_fill_metadata"
                                        if fill_metadata_issue is not None
                                        else "filled"
                                        if visible_status == "filled"
                                        else "partially_filled"
                                        if observed_filled_qty > 0.0
                                        else visible_status
                                        if visible_status
                                        in {
                                            *BUY_TERMINAL_STATUSES,
                                            *BUY_NONTERMINAL_PAUSED_STATUSES,
                                        }
                                        else "existing"
                                    ),
                                    alpaca_order_id=_optional_str(visible.get("id")),
                                    message=fill_metadata_issue or "buy became visible during final pre-submit checks",
                                )
                                continue

                            assert managed_position_id is not None
                            assert managed_submission_attempt_count is not None
                            recovery_outcome = _recover_managed_buy_submission(
                                conn=conn,
                                client=client,
                                rows=rows,
                                signal_index=signal_index,
                                signal=signal,
                                symbol=symbol,
                                signal_date=signal_date,
                                client_order_id=client_order_id,
                                notional=order_notional,
                                qty=order_qty,
                                limit_price=limit_price,
                                expected_alpaca_asset_id=alpaca_asset_id,
                                message="final pre-submit deterministic-ID check",
                                submission_attempt_count=managed_submission_attempt_count,
                                managed_position_id=managed_position_id,
                                expected_state_revision=managed_submission_state_revision,
                                observed_payload=final_visible_payload,
                            )
                            if recovery_outcome is None:
                                recovery_message = _append_accepted_buy_processing_failure(
                                    conn=conn,
                                    client=client,
                                    rows=rows,
                                    workflow=workflow_by_signal_index.get(signal_index),
                                    signal_index=signal_index,
                                    symbol=symbol,
                                    signal_date=signal_date,
                                    client_order_id=client_order_id,
                                    notional=order_notional,
                                    qty=order_qty,
                                    limit_price=limit_price,
                                    managed_position_id=managed_position_id,
                                    managed_submission_attempt_count=managed_submission_attempt_count,
                                    accepted_response_payload=final_visible_payload,
                                    expected_alpaca_asset_id=alpaca_asset_id,
                                    detail=(
                                        "deterministic managed buy became visible during final validation but "
                                        "its lineage could not be resolved"
                                    ),
                                )
                                fatal_batch_messages.append(recovery_message)
                            elif recovery_outcome == "incomplete_fill_metadata":
                                fatal_batch_messages.append(
                                    "Recovered managed buy has incomplete fill metadata and requires reconciliation"
                                )
                            elif recovery_outcome == "identity_mismatch":
                                fatal_batch_messages.append(
                                    "Recovered managed buy has a broker order identity mismatch and requires review"
                                )
                            elif recovery_outcome == "submission_unknown":
                                fatal_batch_messages.append(
                                    "Recovered managed buy exposure lost its persistence race and requires review"
                                )
                            continue

                        final_open_buy = _orders_have_open_order(
                            final_open_orders,
                            symbol,
                            "buy",
                            expected_alpaca_asset_id=alpaca_asset_id,
                        )
                        final_open_sell = _orders_have_open_order(
                            final_open_orders,
                            symbol,
                            "sell",
                            expected_alpaca_asset_id=alpaca_asset_id,
                        )
                        final_position_qty = client.position_qty(alpaca_asset_id)
                    except Exception as exc:
                        detail = _alpaca_exception_diagnostic(
                            exc,
                            cfg=cfg,
                            sensitive_values=sensitive_values,
                        )
                        if deterministic_order_was_visible:
                            duplicate_message = ""
                            payload_for_quarantine = final_visible_payload
                            additional_payloads_for_quarantine: list[dict] | None = None
                            if len(final_visible_payloads) > 1:
                                duplicate_attributions: list[str] = []
                                for duplicate in final_visible_payloads:
                                    attributed = _safely_attributed_buy_order_lineage(
                                        duplicate,
                                        expected_client_order_id=client_order_id,
                                        expected_symbol=symbol,
                                        expected_alpaca_asset_id=alpaca_asset_id,
                                    )
                                    if attributed:
                                        attribution = (
                                            "core identity was proven for fenced cancellation"
                                            if is_managed_signal
                                            else "core identity was proven"
                                        )
                                    else:
                                        attribution = "core identity was not safe enough for cancellation"
                                    duplicate_attributions.append(
                                        f"{_optional_str(duplicate.get('id'))}: {attribution}"
                                    )
                                duplicate_message = (
                                    f"; {len(final_visible_payloads)} duplicate deterministic orders were visible; "
                                    + "; ".join(duplicate_attributions)
                                )
                                payload_for_quarantine = None
                                additional_payloads_for_quarantine = final_visible_payloads
                            if not is_managed_signal:
                                recovery_message = (
                                    "final validation failed after deterministic broker exposure became visible: "
                                    f"{detail}{duplicate_message}; broker cancellation was not requested because "
                                    "this invocation has no durable ownership of the concurrently created order; "
                                    "review required"
                                )
                                fatal_batch_messages.append(recovery_message)
                                append_preflight_result(
                                    signal_index,
                                    symbol=symbol,
                                    signal_date=signal_date,
                                    client_order_id=client_order_id,
                                    notional=order_notional,
                                    qty=order_qty,
                                    limit_price=limit_price,
                                    status="submission_unknown",
                                    alpaca_order_id=(
                                        _optional_str(final_visible_payload.get("id"))
                                        if final_visible_payload is not None and len(final_visible_payloads) == 1
                                        else None
                                    ),
                                    message=recovery_message,
                                )
                                continue
                            recovery_message = _append_accepted_buy_processing_failure(
                                conn=conn,
                                client=client,
                                rows=rows,
                                workflow=workflow_by_signal_index.get(signal_index),
                                signal_index=signal_index,
                                symbol=symbol,
                                signal_date=signal_date,
                                client_order_id=client_order_id,
                                notional=order_notional,
                                qty=order_qty,
                                limit_price=limit_price,
                                managed_position_id=managed_position_id,
                                managed_submission_attempt_count=managed_submission_attempt_count,
                                accepted_response_payload=payload_for_quarantine,
                                expected_alpaca_asset_id=alpaca_asset_id,
                                additional_accepted_payloads=additional_payloads_for_quarantine,
                                detail=(
                                    "final validation failed after deterministic broker exposure became visible: "
                                    f"{detail}{duplicate_message}"
                                ),
                            )
                            if is_managed_signal:
                                managed_symbols.add(symbol.upper())
                            fatal_batch_messages.append(recovery_message)
                            continue
                        cleanup_applied = True
                        if is_managed_signal:
                            assert conn is not None
                            assert managed_position_id is not None
                            assert managed_submission_attempt_count is not None
                            cleanup_applied = fail_alpaca_managed_buy_submission_if_pending(
                                conn,
                                managed_position_id,
                                expected_buy_submission_attempt_count=managed_submission_attempt_count,
                                notes=durable_note(
                                    f"managed buy final broker-exposure validation failed before submission: {detail}"
                                ),
                            )
                        remaining_batch_notional = min(
                            remaining_batch_notional + order_notional,
                            batch_notional,
                        )
                        if cleanup_applied and is_managed_signal:
                            managed_symbols.discard(symbol.upper())
                        fatal_batch_messages.append(f"Alpaca final buy exposure validation failed: {detail}")
                        append_preflight_result(
                            signal_index,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            notional=order_notional,
                            qty=order_qty,
                            limit_price=limit_price,
                            status="error" if cleanup_applied else "superseded",
                            message=(
                                f"final broker-exposure validation failed before submission: {detail}"
                                if cleanup_applied
                                else (
                                    "final broker-exposure validation failed after the managed generation "
                                    f"changed concurrently: {detail}"
                                )
                            ),
                        )
                        continue

                    conflict_status: str | None = None
                    conflict_message: str | None = None
                    if final_open_buy:
                        conflict_status = "open_order"
                        conflict_message = "a buy order for the stable asset appeared before submission"
                    elif final_open_sell:
                        conflict_status = "open_sell_order"
                        conflict_message = "a sell order for the stable asset appeared before submission"
                    elif final_position_qty != 0:
                        conflict_status = "held"
                        conflict_message = (
                            f"a position for the stable asset appeared before submission: qty={final_position_qty}"
                        )
                    if conflict_status is not None:
                        assert conflict_message is not None
                        cleanup_applied = True
                        if is_managed_signal:
                            assert conn is not None
                            assert managed_position_id is not None
                            assert managed_submission_attempt_count is not None
                            cleanup_applied = fail_alpaca_managed_buy_submission_if_pending(
                                conn,
                                managed_position_id,
                                expected_buy_submission_attempt_count=managed_submission_attempt_count,
                                notes=durable_note(
                                    f"managed buy skipped after final exposure validation: {conflict_message}"
                                ),
                            )
                        remaining_batch_notional = min(
                            remaining_batch_notional + order_notional,
                            batch_notional,
                        )
                        if cleanup_applied and is_managed_signal:
                            managed_symbols.discard(symbol.upper())
                        append_preflight_result(
                            signal_index,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            notional=order_notional,
                            qty=order_qty,
                            limit_price=limit_price,
                            status=conflict_status if cleanup_applied else "superseded",
                            message=(
                                conflict_message
                                if cleanup_applied
                                else f"{conflict_message}; the managed generation changed concurrently"
                            ),
                        )
                        continue

                    if is_managed_signal:
                        assert conn is not None
                        assert managed_position_id is not None
                        assert managed_submission_attempt_count is not None
                        assert managed_submission_state_revision is not None
                        confirmed_state_revision = confirm_alpaca_managed_buy_submission(
                            conn,
                            managed_position_id,
                            expected_buy_submission_attempt_count=managed_submission_attempt_count,
                            expected_state_revision=managed_submission_state_revision,
                            expected_buy_order_qty=order_qty,
                            expected_buy_order_limit_price=limit_price,
                            claimed_at=_utc_now().isoformat().replace("+00:00", "Z"),
                        )
                        if confirmed_state_revision is None:
                            remaining_batch_notional = min(
                                remaining_batch_notional + order_notional,
                                batch_notional,
                            )
                            append_preflight_result(
                                signal_index,
                                symbol=symbol,
                                signal_date=signal_date,
                                client_order_id=client_order_id,
                                notional=order_notional,
                                qty=order_qty,
                                limit_price=limit_price,
                                status="superseded",
                                message=(
                                    "managed buy submission generation changed before the final local fence; "
                                    "no broker order was submitted"
                                ),
                            )
                            continue
                        managed_submission_state_revision = confirmed_state_revision

                try:
                    if dispatch_authorization is None:
                        raise RuntimeError("Eligible Alpaca buy has no final dispatch authorization")
                    final_window_elapsed = _buy_submission_authorization_window_elapsed(dispatch_authorization)
                except Exception as exc:
                    detail = _alpaca_exception_diagnostic(
                        exc,
                        cfg=cfg,
                        sensitive_values=sensitive_values,
                    )
                    cleanup_applied = _release_unsubmitted_managed_buy_claim(
                        conn,
                        position_id=managed_position_id,
                        submission_attempt_count=managed_submission_attempt_count,
                        notes=durable_note(
                            f"managed buy final local-time validation failed before submission: {detail}"
                        ),
                    )
                    remaining_batch_notional = min(
                        remaining_batch_notional + order_notional,
                        batch_notional,
                    )
                    if cleanup_applied and is_managed_signal:
                        managed_symbols.discard(symbol.upper())
                    local_time_failure_message = f"Alpaca final buy local-time validation failed: {detail}"
                    fatal_batch_messages.append(local_time_failure_message)
                    append_preflight_result(
                        signal_index,
                        symbol=symbol,
                        signal_date=signal_date,
                        client_order_id=client_order_id,
                        notional=order_notional,
                        qty=order_qty,
                        limit_price=limit_price,
                        status="error" if cleanup_applied else "superseded",
                        message=(
                            local_time_failure_message
                            if cleanup_applied
                            else (
                                f"{local_time_failure_message}; the managed generation changed concurrently and "
                                "requires reconciliation"
                            )
                        ),
                    )
                    continue

                if final_window_elapsed:
                    elapsed_message = (
                        "market submission window elapsed during final exposure validation; order deferred"
                    )
                    cleanup_applied = _release_unsubmitted_managed_buy_claim(
                        conn,
                        position_id=managed_position_id,
                        submission_attempt_count=managed_submission_attempt_count,
                        notes=durable_note(f"managed buy deferred by final local-time validation: {elapsed_message}"),
                    )
                    remaining_batch_notional = min(
                        remaining_batch_notional + order_notional,
                        batch_notional,
                    )
                    if cleanup_applied and is_managed_signal:
                        managed_symbols.discard(symbol.upper())
                    append_preflight_result(
                        signal_index,
                        symbol=symbol,
                        signal_date=signal_date,
                        client_order_id=client_order_id,
                        notional=order_notional,
                        qty=order_qty,
                        limit_price=limit_price,
                        status="deferred" if cleanup_applied else "superseded",
                        message=(
                            elapsed_message
                            if cleanup_applied
                            else (
                                f"{elapsed_message}; the managed generation changed concurrently and "
                                "requires reconciliation"
                            )
                        ),
                    )
                    continue

                submission_accepted_2xx = False
                accepted_response_payload: dict | None = None
                accepted_replacement_chain: list[dict] | None = None

                try:
                    submission_attempts += 1
                    submit_resp = client.submit_limit_buy_order(
                        symbol=alpaca_asset_id,
                        qty=order_qty,
                        limit_price=limit_price,
                        client_order_id=client_order_id,
                        authorized_next_open=authorized_next_open,
                        dispatch_authorization=dispatch_authorization,
                    )
                    _require_2xx_response(submit_resp)
                    submission_accepted_2xx = True
                    submitted_payload = _response_json(submit_resp)
                    accepted_response_payload = submitted_payload
                    submitted_replacement_chain = [submitted_payload]
                    accepted_replacement_chain = submitted_replacement_chain
                    try:
                        submitted, submitted_replacement_chain = _fetch_order_replacement_chain(
                            client,
                            submitted_payload,
                            client_order_id,
                        )
                        accepted_replacement_chain = submitted_replacement_chain
                    except (requests.RequestException, RuntimeError, ValueError) as exc:
                        detail = _alpaca_exception_diagnostic(
                            exc,
                            cfg=cfg,
                            sensitive_values=sensitive_values,
                        )
                        accepted_message = _append_accepted_buy_processing_failure(
                            conn=conn,
                            client=client,
                            rows=rows,
                            workflow=workflow_by_signal_index.get(signal_index),
                            signal_index=signal_index,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            notional=order_notional,
                            qty=order_qty,
                            limit_price=limit_price,
                            managed_position_id=managed_position_id,
                            managed_submission_attempt_count=managed_submission_attempt_count,
                            accepted_response_payload=accepted_response_payload,
                            expected_alpaca_asset_id=alpaca_asset_id,
                            accepted_replacement_chain=accepted_replacement_chain,
                            detail=f"replacement lineage could not be resolved: {detail}",
                        )
                        if managed_position_id is not None:
                            managed_symbols.add(symbol.upper())
                        fatal_batch_messages.append(accepted_message)
                        continue
                    failure_context.current_row["Alpaca Order ID"] = _optional_str(submitted.get("id"))
                    _validate_buy_order_identity(
                        buy_order=submitted,
                        expected_client_order_id=client_order_id,
                        expected_symbol=symbol,
                        expected_alpaca_asset_id=alpaca_asset_id,
                        expected_qty=order_qty,
                        expected_limit_price=limit_price,
                        replacement_chain=submitted_replacement_chain,
                    )
                    submitted_status = _broker_order_status(submitted, default="submitted")
                    submitted_filled_qty, _submitted_fill_price, submitted_fill_is_valid = (
                        _replacement_chain_fill_metadata(submitted_replacement_chain)
                    )
                    submitted_fill_issue = _buy_replacement_chain_fill_metadata_issue(
                        submitted_replacement_chain,
                        expected_buy_qty=order_qty,
                    )
                    if submitted_fill_issue is not None:
                        diagnostic_persisted = True
                        if managed_position_id is not None:
                            assert managed_submission_attempt_count is not None
                            diagnostic_persisted = update_alpaca_managed_buy_status_if_current(
                                conn,
                                managed_position_id,
                                expected_buy_status="submission_pending",
                                expected_buy_alpaca_order_id=None,
                                expected_filled_qty=None,
                                expected_sell_client_order_id=None,
                                expected_buy_submission_attempt_count=managed_submission_attempt_count,
                                expected_state_revision=managed_submission_state_revision,
                                buy_status="incomplete_fill_metadata",
                                buy_alpaca_order_id=_optional_str(submitted.get("id")),
                                buy_submitted_at=_optional_alpaca_datetime_str(submitted.get("submitted_at")),
                                notes=durable_note(
                                    f"{submitted_fill_issue}; protective-sell automation is quarantined pending "
                                    "reconciliation"
                                ),
                            )
                        metadata_message = submitted_fill_issue
                        if not diagnostic_persisted:
                            accepted_message = _append_accepted_buy_processing_failure(
                                conn=conn,
                                client=client,
                                rows=rows,
                                workflow=workflow_by_signal_index.get(signal_index),
                                signal_index=signal_index,
                                symbol=symbol,
                                signal_date=signal_date,
                                client_order_id=client_order_id,
                                notional=order_notional,
                                qty=order_qty,
                                limit_price=limit_price,
                                managed_position_id=managed_position_id,
                                managed_submission_attempt_count=managed_submission_attempt_count,
                                accepted_response_payload=accepted_response_payload,
                                expected_alpaca_asset_id=alpaca_asset_id,
                                accepted_replacement_chain=accepted_replacement_chain,
                                detail=(
                                    f"the incomplete-fill diagnostic lost its persistence race: {metadata_message}"
                                ),
                            )
                            if managed_position_id is not None:
                                managed_symbols.add(symbol.upper())
                            fatal_batch_messages.append(accepted_message)
                            continue
                        fatal_batch_messages.append(metadata_message)
                        append_preflight_result(
                            signal_index,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            notional=order_notional,
                            qty=order_qty,
                            limit_price=limit_price,
                            status="incomplete_fill_metadata",
                            alpaca_order_id=_optional_str(submitted.get("id")),
                            message=metadata_message,
                        )
                        continue
                    if (
                        submitted_status in BUY_TERMINAL_STATUSES
                        and submitted_fill_is_valid
                        and submitted_filled_qty == 0.0
                    ):
                        terminal_state_persisted = True
                        if managed_position_id is not None:
                            assert managed_submission_attempt_count is not None
                            terminal_state_persisted = close_alpaca_managed_buy_if_current_and_unfilled(
                                conn,
                                managed_position_id,
                                expected_buy_status="submission_pending",
                                expected_buy_alpaca_order_id=None,
                                expected_buy_submission_attempt_count=managed_submission_attempt_count,
                                expected_state_revision=managed_submission_state_revision,
                                buy_status=submitted_status,
                                buy_alpaca_order_id=_optional_str(submitted.get("id")),
                                buy_submitted_at=_optional_alpaca_datetime_str(submitted.get("submitted_at")),
                                closed_at=_optional_alpaca_datetime_str(submitted.get("updated_at")),
                                buy_broker_updated_at=_optional_alpaca_datetime_str(submitted.get("updated_at")),
                                notes=durable_note("Alpaca rejected or terminated the submitted buy without a fill"),
                            )
                        append_preflight_result(
                            signal_index,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            notional=order_notional,
                            qty=order_qty,
                            limit_price=limit_price,
                            status=submitted_status if terminal_state_persisted else "superseded",
                            alpaca_order_id=_optional_str(submitted.get("id")),
                            message=(
                                f"Alpaca returned {submitted_status}; buy ended without a fill"
                                if terminal_state_persisted
                                else "terminal buy response was superseded by concurrent managed state"
                            ),
                        )
                        continue
                    if is_managed_signal:
                        try:
                            assert managed_submission_attempt_count is not None
                            _persist_managed_buy_observation(
                                conn=conn,
                                signal=signal,
                                symbol=symbol,
                                signal_date=signal_date,
                                client_order_id=client_order_id,
                                buy_order=submitted,
                                replacement_chain=submitted_replacement_chain,
                                order_qty=order_qty,
                                limit_price=limit_price,
                                notes=durable_note("managed buy accepted from the submission response"),
                                expected_alpaca_asset_id=alpaca_asset_id,
                                expected_buy_submission_attempt_count=managed_submission_attempt_count,
                                expected_state_revision=managed_submission_state_revision,
                                cfg=cfg,
                                sensitive_values=sensitive_values,
                                client=client,
                            )
                        except RuntimeError as exc:
                            concurrently_adopted = _managed_buy_lineage_is_durably_adopted(
                                conn=conn,
                                position_id=managed_position_id,
                                client_order_id=client_order_id,
                                expected_symbol=symbol,
                                expected_alpaca_asset_id=alpaca_asset_id,
                                expected_qty=order_qty,
                                expected_limit_price=limit_price,
                                replacement_chain=submitted_replacement_chain,
                            )
                            if concurrently_adopted:
                                submission_successes += 1
                                managed_symbols.add(symbol.upper())
                                append_preflight_result(
                                    signal_index,
                                    symbol=symbol,
                                    signal_date=signal_date,
                                    client_order_id=client_order_id,
                                    notional=order_notional,
                                    qty=order_qty,
                                    limit_price=limit_price,
                                    status="existing",
                                    alpaca_order_id=_optional_str(submitted.get("id")),
                                    message=("concurrent managed state already adopted the exact accepted buy lineage"),
                                )
                                continue
                            accepted_message = _append_accepted_buy_processing_failure(
                                conn=conn,
                                client=client,
                                rows=rows,
                                workflow=workflow_by_signal_index.get(signal_index),
                                signal_index=signal_index,
                                symbol=symbol,
                                signal_date=signal_date,
                                client_order_id=client_order_id,
                                notional=order_notional,
                                qty=order_qty,
                                limit_price=limit_price,
                                managed_position_id=managed_position_id,
                                managed_submission_attempt_count=managed_submission_attempt_count,
                                accepted_response_payload=accepted_response_payload,
                                expected_alpaca_asset_id=alpaca_asset_id,
                                accepted_replacement_chain=accepted_replacement_chain,
                                detail=f"managed observation lost its persistence race: {exc}",
                            )
                            managed_symbols.add(symbol.upper())
                            fatal_batch_messages.append(accepted_message)
                            continue
                        managed_symbols.add(symbol.upper())
                    submission_successes += 1
                    result_status = (
                        "filled"
                        if submitted_status == "filled"
                        else "partially_filled"
                        if submitted_filled_qty > 0.0
                        else submitted_status
                        if submitted_status in BUY_NONTERMINAL_PAUSED_STATUSES
                        else "submitted"
                    )
                    append_preflight_result(
                        signal_index,
                        symbol=symbol,
                        signal_date=signal_date,
                        client_order_id=client_order_id,
                        notional=order_notional,
                        qty=order_qty,
                        limit_price=limit_price,
                        status=result_status,
                        alpaca_order_id=submitted.get("id"),
                        message=(f"{submitted_status}; whole-share day limit protected by the configured price buffer"),
                    )
                except _BuySubmissionNotDispatchedError as exc:
                    submission_attempts -= 1
                    detail = _alpaca_exception_diagnostic(
                        exc,
                        cfg=cfg,
                        sensitive_values=sensitive_values,
                    )
                    undispatched_message = f"Alpaca buy submission failed its local runtime fence: {detail}"
                    cleanup_applied = _release_known_undispatched_managed_buy_claim(
                        conn,
                        position_id=managed_position_id,
                        submission_attempt_count=managed_submission_attempt_count,
                        state_revision=managed_submission_state_revision,
                        notes=durable_note(
                            "managed buy was proven not dispatched because its final local runtime fence failed: "
                            f"{detail}"
                        ),
                    )
                    remaining_batch_notional = min(
                        remaining_batch_notional + order_notional,
                        batch_notional,
                    )
                    if cleanup_applied and is_managed_signal:
                        managed_symbols.discard(symbol.upper())
                    fatal_batch_messages.append(undispatched_message)
                    append_preflight_result(
                        signal_index,
                        symbol=symbol,
                        signal_date=signal_date,
                        client_order_id=client_order_id,
                        notional=order_notional,
                        qty=order_qty,
                        limit_price=limit_price,
                        status="error" if cleanup_applied else "superseded",
                        message=(
                            undispatched_message
                            if cleanup_applied
                            else (
                                f"{undispatched_message}; the managed generation changed concurrently and "
                                "requires reconciliation"
                            )
                        ),
                    )
                except _BuySubmissionWindowElapsedError as exc:
                    submission_attempts -= 1
                    elapsed_message = str(exc)
                    cleanup_applied = _release_unsubmitted_managed_buy_claim(
                        conn,
                        position_id=managed_position_id,
                        submission_attempt_count=managed_submission_attempt_count,
                        notes=durable_note(f"managed buy deferred at the broker POST boundary: {elapsed_message}"),
                    )
                    remaining_batch_notional = min(
                        remaining_batch_notional + order_notional,
                        batch_notional,
                    )
                    if cleanup_applied and is_managed_signal:
                        managed_symbols.discard(symbol.upper())
                    append_preflight_result(
                        signal_index,
                        symbol=symbol,
                        signal_date=signal_date,
                        client_order_id=client_order_id,
                        notional=order_notional,
                        qty=order_qty,
                        limit_price=limit_price,
                        status="deferred" if cleanup_applied else "superseded",
                        message=(
                            elapsed_message
                            if cleanup_applied
                            else (
                                f"{elapsed_message}; the managed generation changed concurrently and "
                                "requires reconciliation"
                            )
                        ),
                    )
                except BuyOrderIdentityError as exc:
                    (
                        quarantine_status,
                        attributed_order_id,
                        cancellation_lineage,
                        cancellation_message,
                    ) = _attributed_buy_identity_mismatch_quarantine_plan(
                        submitted,
                        identity_issue=str(exc),
                        expected_client_order_id=client_order_id,
                        expected_symbol=symbol,
                        expected_alpaca_asset_id=alpaca_asset_id,
                        replacement_chain=submitted_replacement_chain,
                    )
                    identity_message = (
                        f"Alpaca accepted a buy but returned an identity-mismatched order: {exc}; "
                        f"{cancellation_message}; the managed intent is quarantined and requires immediate review"
                    )
                    status_updated = True
                    if managed_position_id is not None:
                        assert managed_submission_attempt_count is not None
                        status_updated = update_alpaca_managed_buy_status_if_current(
                            conn,
                            managed_position_id,
                            expected_buy_status="submission_pending",
                            expected_buy_alpaca_order_id=None,
                            expected_filled_qty=None,
                            expected_sell_client_order_id=None,
                            expected_buy_submission_attempt_count=managed_submission_attempt_count,
                            expected_state_revision=managed_submission_state_revision,
                            buy_status=quarantine_status,
                            buy_alpaca_order_id=attributed_order_id,
                            buy_submitted_at=_optional_alpaca_datetime_str(submitted.get("submitted_at")),
                            notes=durable_note(identity_message),
                        )
                        if cancellation_lineage is not None or not status_updated:
                            status_updated = _quarantine_managed_buy_side_effect_from_current_snapshot(
                                conn=conn,
                                position_id=managed_position_id,
                                buy_status=quarantine_status,
                                observed_buy_alpaca_order_id=attributed_order_id,
                                observed_buy_submitted_at=_optional_alpaca_datetime_str(submitted.get("submitted_at")),
                                notes=durable_note(identity_message),
                                observed_buy_cancellation_alpaca_order_ids=(
                                    sorted(
                                        {
                                            order_id
                                            for order in cancellation_lineage
                                            if (order_id := _optional_str(order.get("id"))) is not None
                                        }
                                        | ({attributed_order_id} if attributed_order_id is not None else set())
                                    )
                                    if cancellation_lineage is not None
                                    else None
                                ),
                            )
                    if status_updated and quarantine_status == "pending_cancel" and cancellation_lineage is not None:
                        _pending, cancellation_message = _request_safely_attributed_lineage_cancellations(
                            client,
                            cancellation_lineage,
                        )
                        identity_message = (
                            f"Alpaca accepted a buy but returned an identity-mismatched order: {exc}; "
                            f"{cancellation_message}; the managed intent is quarantined and requires "
                            "immediate review"
                        )
                    fatal_batch_messages.append(identity_message)
                    append_preflight_result(
                        signal_index,
                        symbol=symbol,
                        signal_date=signal_date,
                        client_order_id=client_order_id,
                        notional=order_notional,
                        qty=order_qty,
                        limit_price=limit_price,
                        status=quarantine_status,
                        alpaca_order_id=_optional_str(submitted.get("id")),
                        message=(
                            identity_message
                            if status_updated
                            else (
                                f"{identity_message}; managed state kept changing concurrently, so durable "
                                "local quarantine persistence also requires retry"
                            )
                        ),
                    )
                except HTTPError as exc:
                    error_message = _http_error_message(exc, sensitive_values=sensitive_values)
                    if submission_accepted_2xx:
                        accepted_message = _append_accepted_buy_processing_failure(
                            conn=conn,
                            client=client,
                            rows=rows,
                            workflow=workflow_by_signal_index.get(signal_index),
                            signal_index=signal_index,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            notional=order_notional,
                            qty=order_qty,
                            limit_price=limit_price,
                            managed_position_id=managed_position_id,
                            managed_submission_attempt_count=managed_submission_attempt_count,
                            accepted_response_payload=accepted_response_payload,
                            expected_alpaca_asset_id=alpaca_asset_id,
                            accepted_replacement_chain=accepted_replacement_chain,
                            detail=error_message,
                        )
                        if managed_position_id is not None:
                            managed_symbols.add(symbol.upper())
                        fatal_batch_messages.append(accepted_message)
                        continue
                    if _authentication_http_error(exc, sensitive_values=sensitive_values):
                        fatal_batch_messages.append(error_message)
                    if managed_position_id is not None and _ambiguous_submission_http_error(
                        exc,
                        sensitive_values=sensitive_values,
                    ):
                        assert managed_submission_attempt_count is not None
                        recovery_outcome = _recover_managed_buy_submission(
                            conn=conn,
                            client=client,
                            rows=rows,
                            signal_index=signal_index,
                            signal=signal,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            notional=order_notional,
                            qty=order_qty,
                            limit_price=limit_price,
                            expected_alpaca_asset_id=alpaca_asset_id,
                            message=error_message,
                            submission_attempt_count=managed_submission_attempt_count,
                            managed_position_id=managed_position_id,
                            expected_state_revision=managed_submission_state_revision,
                        )
                        if recovery_outcome is not None:
                            if recovery_outcome == "recovered":
                                submission_successes += 1
                            elif recovery_outcome == "incomplete_fill_metadata":
                                fatal_batch_messages.append(
                                    "Recovered managed buy has incomplete fill metadata and requires reconciliation"
                                )
                            elif recovery_outcome == "identity_mismatch":
                                fatal_batch_messages.append(
                                    "Recovered managed buy has a broker order identity mismatch and requires review"
                                )
                            elif recovery_outcome == "submission_unknown":
                                fatal_batch_messages.append(
                                    "Recovered managed buy exposure lost its persistence race and requires review"
                                )
                            continue
                        status_updated = update_alpaca_managed_buy_status_if_current(
                            conn,
                            managed_position_id,
                            expected_buy_status="submission_pending",
                            expected_buy_alpaca_order_id=None,
                            expected_filled_qty=None,
                            expected_sell_client_order_id=None,
                            expected_buy_submission_attempt_count=managed_submission_attempt_count,
                            expected_state_revision=managed_submission_state_revision,
                            buy_status="submission_unknown",
                            notes=durable_note(
                                "broker returned an ambiguous error after managed buy submission; recovery is pending"
                            ),
                        )
                        append_preflight_result(
                            signal_index,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            notional=order_notional,
                            qty=order_qty,
                            limit_price=limit_price,
                            status="submission_unknown" if status_updated else "superseded",
                            message=(
                                "broker response is ambiguous; managed order recovery will retry by client order ID: "
                                f"{error_message}"
                                if status_updated
                                else (
                                    "ambiguous buy response was superseded by concurrent managed state: "
                                    f"{error_message}"
                                )
                            ),
                        )
                        if status_updated:
                            fatal_batch_messages.append(
                                "Managed buy submission remains ambiguous after its broker HTTP response; "
                                "protective reconciliation is required"
                            )
                        if _transient_broker_http_error(exc):
                            submission_transport_failures += 1
                        continue
                    if _ambiguous_submission_http_error(exc, sensitive_values=sensitive_values):
                        fatal_batch_messages.append(
                            "Buy submission remains ambiguous after its broker HTTP response; "
                            "manual reconciliation is required"
                        )
                    if managed_position_id is not None:
                        assert managed_submission_attempt_count is not None
                        fail_alpaca_managed_buy_submission_if_pending(
                            conn,
                            managed_position_id,
                            expected_buy_submission_attempt_count=managed_submission_attempt_count,
                            notes=durable_note("managed buy submission failed before an Alpaca order was accepted"),
                        )
                    append_preflight_result(
                        signal_index,
                        symbol=symbol,
                        signal_date=signal_date,
                        client_order_id=client_order_id,
                        notional=order_notional,
                        qty=order_qty,
                        limit_price=limit_price,
                        status="error",
                        message=error_message,
                    )
                except requests.RequestException as exc:
                    error_message = _alpaca_exception_diagnostic(
                        exc,
                        cfg=cfg,
                        sensitive_values=sensitive_values,
                    )
                    if submission_accepted_2xx:
                        accepted_message = _append_accepted_buy_processing_failure(
                            conn=conn,
                            client=client,
                            rows=rows,
                            workflow=workflow_by_signal_index.get(signal_index),
                            signal_index=signal_index,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            notional=order_notional,
                            qty=order_qty,
                            limit_price=limit_price,
                            managed_position_id=managed_position_id,
                            managed_submission_attempt_count=managed_submission_attempt_count,
                            accepted_response_payload=accepted_response_payload,
                            expected_alpaca_asset_id=alpaca_asset_id,
                            accepted_replacement_chain=accepted_replacement_chain,
                            detail=error_message,
                        )
                        if managed_position_id is not None:
                            managed_symbols.add(symbol.upper())
                        fatal_batch_messages.append(accepted_message)
                        continue
                    if managed_position_id is not None:
                        assert managed_submission_attempt_count is not None
                    recovery_outcome = (
                        _recover_managed_buy_submission(
                            conn=conn,
                            client=client,
                            rows=rows,
                            signal_index=signal_index,
                            signal=signal,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            notional=order_notional,
                            qty=order_qty,
                            limit_price=limit_price,
                            expected_alpaca_asset_id=alpaca_asset_id,
                            message=error_message,
                            submission_attempt_count=managed_submission_attempt_count,
                            managed_position_id=managed_position_id,
                            expected_state_revision=managed_submission_state_revision,
                        )
                        if managed_position_id is not None
                        else None
                    )
                    if recovery_outcome is not None:
                        if recovery_outcome == "recovered":
                            submission_successes += 1
                        elif recovery_outcome == "incomplete_fill_metadata":
                            fatal_batch_messages.append(
                                "Recovered managed buy has incomplete fill metadata and requires reconciliation"
                            )
                        elif recovery_outcome == "identity_mismatch":
                            fatal_batch_messages.append(
                                "Recovered managed buy has a broker order identity mismatch and requires review"
                            )
                        elif recovery_outcome == "submission_unknown":
                            fatal_batch_messages.append(
                                "Recovered managed buy exposure lost its persistence race and requires review"
                            )
                        continue
                    submission_transport_failures += 1
                    if managed_position_id is not None:
                        status_updated = update_alpaca_managed_buy_status_if_current(
                            conn,
                            managed_position_id,
                            expected_buy_status="submission_pending",
                            expected_buy_alpaca_order_id=None,
                            expected_filled_qty=None,
                            expected_sell_client_order_id=None,
                            expected_buy_submission_attempt_count=managed_submission_attempt_count,
                            expected_state_revision=managed_submission_state_revision,
                            buy_status="submission_unknown",
                            notes=durable_note("managed buy submission transport failed; recovery is pending"),
                        )
                    append_preflight_result(
                        signal_index,
                        symbol=symbol,
                        signal_date=signal_date,
                        client_order_id=client_order_id,
                        notional=order_notional,
                        qty=order_qty,
                        limit_price=limit_price,
                        status=(
                            "submission_unknown"
                            if managed_position_id is not None and status_updated
                            else "superseded"
                            if managed_position_id is not None
                            else "error"
                        ),
                        message=(
                            "managed order submission is ambiguous; recovery will retry by client order ID"
                            if managed_position_id is not None and status_updated
                            else "ambiguous buy response was superseded by concurrent managed state"
                            if managed_position_id is not None
                            else error_message
                        ),
                    )
                    if managed_position_id is None or status_updated:
                        fatal_batch_messages.append(
                            "Buy submission remains ambiguous after a transport failure; reconciliation is required"
                        )
                except Exception as exc:
                    error_message = _alpaca_exception_diagnostic(
                        exc,
                        cfg=cfg,
                        sensitive_values=sensitive_values,
                    )
                    if submission_accepted_2xx:
                        accepted_message = _append_accepted_buy_processing_failure(
                            conn=conn,
                            client=client,
                            rows=rows,
                            workflow=workflow_by_signal_index.get(signal_index),
                            signal_index=signal_index,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            notional=order_notional,
                            qty=order_qty,
                            limit_price=limit_price,
                            managed_position_id=managed_position_id,
                            managed_submission_attempt_count=managed_submission_attempt_count,
                            accepted_response_payload=accepted_response_payload,
                            expected_alpaca_asset_id=alpaca_asset_id,
                            accepted_replacement_chain=accepted_replacement_chain,
                            detail=error_message,
                        )
                        if managed_position_id is not None:
                            managed_symbols.add(symbol.upper())
                        fatal_batch_messages.append(accepted_message)
                        continue
                    if managed_position_id is not None:
                        assert managed_submission_attempt_count is not None
                    recovery_outcome = (
                        _recover_managed_buy_submission(
                            conn=conn,
                            client=client,
                            rows=rows,
                            signal_index=signal_index,
                            signal=signal,
                            symbol=symbol,
                            signal_date=signal_date,
                            client_order_id=client_order_id,
                            notional=order_notional,
                            qty=order_qty,
                            limit_price=limit_price,
                            expected_alpaca_asset_id=alpaca_asset_id,
                            message=error_message,
                            submission_attempt_count=managed_submission_attempt_count,
                            managed_position_id=managed_position_id,
                            expected_state_revision=managed_submission_state_revision,
                        )
                        if managed_position_id is not None
                        else None
                    )
                    if recovery_outcome is not None:
                        if recovery_outcome == "incomplete_fill_metadata":
                            fatal_batch_messages.append(
                                "Recovered managed buy has incomplete fill metadata and requires reconciliation"
                            )
                        elif recovery_outcome == "identity_mismatch":
                            fatal_batch_messages.append(
                                "Recovered managed buy has a broker order identity mismatch and requires review"
                            )
                        elif recovery_outcome == "submission_unknown":
                            fatal_batch_messages.append(
                                "Recovered managed buy exposure lost its persistence race and requires review"
                            )
                        continue
                    if managed_position_id is not None:
                        status_updated = update_alpaca_managed_buy_status_if_current(
                            conn,
                            managed_position_id,
                            expected_buy_status="submission_pending",
                            expected_buy_alpaca_order_id=None,
                            expected_filled_qty=None,
                            expected_sell_client_order_id=None,
                            expected_buy_submission_attempt_count=managed_submission_attempt_count,
                            expected_state_revision=managed_submission_state_revision,
                            buy_status="submission_unknown",
                            notes=durable_note("managed buy submission ended unexpectedly; recovery is pending"),
                        )
                    append_preflight_result(
                        signal_index,
                        symbol=symbol,
                        signal_date=signal_date,
                        client_order_id=client_order_id,
                        notional=order_notional,
                        qty=order_qty,
                        limit_price=limit_price,
                        status=(
                            "submission_unknown"
                            if managed_position_id is not None and status_updated
                            else "superseded"
                            if managed_position_id is not None
                            else "error"
                        ),
                        message=(
                            "managed order submission is ambiguous; recovery will retry by client order ID"
                            if managed_position_id is not None and status_updated
                            else "ambiguous buy response was superseded by concurrent managed state"
                            if managed_position_id is not None
                            else error_message
                        ),
                    )
                    if managed_position_id is None or status_updated:
                        fatal_batch_messages.append(
                            "Buy submission remains ambiguous after an unexpected failure; reconciliation is required"
                        )

    result = _alpaca_buy_result_frame(rows)

    every_preflight_attempt_raised = preflight_attempts > 0 and preflight_exception_failures == preflight_attempts
    every_submission_transport_failed = (
        submission_attempts > 0 and submission_transport_failures == submission_attempts and submission_successes == 0
    )
    if fatal_batch_messages or every_preflight_attempt_raised or every_submission_transport_failed:
        reasons = list(dict.fromkeys(fatal_batch_messages))
        if every_preflight_attempt_raised:
            reasons.append("every Alpaca buy preflight failed before order eligibility could be determined")
        if every_submission_transport_failed:
            reasons.append("every Alpaca buy submission failed at the transport layer")
        raise AlpacaBuyBatchError(
            "; ".join(reasons),
            result,
            # Any phase-two POST can have reached Alpaca even when its response
            # was unusable.  Phase-one recovery can also discover a managed
            # order that needs immediate protective reconciliation, which is
            # represented by the reconciliation-requiring result statuses.
            broker_side_effects_possible=(
                submission_attempts > 0
                or phase_one_deterministic_broker_order_observed
                or ("Status" in result and result["Status"].isin(BUY_RESULTS_REQUIRING_RECONCILIATION).any())
            ),
        )
    return result


def _submit_alpaca_paper_buy_orders_public_impl(
    buy_signals: pd.DataFrame,
    cfg: AlpacaOrderConfig,
    conn: sqlite3.Connection | None = None,
    *,
    boundary_sensitive_values: tuple[str, ...] = (),
) -> pd.DataFrame:
    """Submit a buy batch while preserving a structured public failure contract."""
    if cfg.enabled and not buy_signals.empty:
        if "Asset" not in buy_signals:
            raise ValueError("Alpaca buy signals require an Asset column")
        if "Date" not in buy_signals:
            raise ValueError("Alpaca buy signals require a Date column")
        if "RSI Observation Date" not in buy_signals:
            raise ValueError("Alpaca buy signals require an RSI Observation Date column")
        for asset, signal_date, observation_date in buy_signals[["Asset", "Date", "RSI Observation Date"]].itertuples(
            index=False, name=None
        ):
            if _optional_alpaca_equity_symbol(asset) is None:
                raise ValueError("Alpaca buy signal Asset values must be canonical uppercase equity ticker strings")
            _canonical_alpaca_signal_date(signal_date, field="Date")
            _canonical_alpaca_signal_date(observation_date, field="RSI Observation Date")
        _validate_alpaca_managed_buy_signal_metadata(buy_signals)
        if conn is not None:
            _require_clean_broker_side_effect_connection(
                conn,
                operation="Alpaca buy submission",
            )
    validate_alpaca_buy_configuration(cfg)
    sensitive_values = _alpaca_config_sensitive_values(cfg)
    failure_context = _BuyBatchFailureContext()
    try:
        return _submit_alpaca_paper_buy_orders_impl(
            buy_signals,
            cfg,
            conn,
            failure_context=failure_context,
            boundary_sensitive_values=boundary_sensitive_values,
        )
    except AlpacaBuyBatchError:
        raise
    except Exception as exc:
        # This boundary deliberately catches ordinary exceptions only. A POST
        # may already have reached Alpaca even when an internal response or
        # persistence handler failed before it could append its per-signal row,
        # so publish a fresh batch diagnostic and force protective
        # reconciliation. Never reuse output from a prior call or run.
        safe_detail = _alpaca_exception_diagnostic(
            exc,
            cfg=cfg,
            sensitive_values=sensitive_values,
        )
        diagnostic_sensitive_values = _merged_alpaca_sensitive_values(
            sensitive_values,
            _alpaca_config_sensitive_values(cfg),
        )
        detail = _safe_alpaca_diagnostic_text(
            f"{type(exc).__name__}: {safe_detail}",
            max_chars=_ALPACA_HTTP_ERROR_MESSAGE_MAX_CHARS,
            sensitive_values=diagnostic_sensitive_values,
        )
        failure_message = _safe_alpaca_diagnostic_text(
            f"unexpected Alpaca buy-batch failure: {detail}",
            max_chars=_ALPACA_HTTP_ERROR_MESSAGE_MAX_CHARS,
            sensitive_values=diagnostic_sensitive_values,
        )
        current_row = dict(failure_context.current_row or {})
        current_row.update(
            {
                "Status": "error",
                "Message": failure_message,
            }
        )
        result = _alpaca_buy_result_frame([*failure_context.rows, current_row])
        public_cause = _alpaca_public_exception_cause(
            exc,
            cfg=cfg,
            sensitive_values=sensitive_values,
        )
        raise AlpacaBuyBatchError(
            failure_message,
            result,
            broker_side_effects_possible=True,
        ) from public_cause


def submit_alpaca_paper_buy_orders(
    buy_signals: pd.DataFrame,
    cfg: AlpacaOrderConfig,
    conn: sqlite3.Connection | None = None,
) -> pd.DataFrame:
    """Publish credential-safe buy-batch results and typed failures."""
    boundary_sensitive_values: tuple[str, ...] = ()
    publication_sensitive_values: tuple[str, ...] = ()
    public_failure: BaseException | None = None
    original_failure: BaseException | None = None
    try:
        boundary_sensitive_values = _alpaca_config_sensitive_values(cfg)
        publication_sensitive_values = boundary_sensitive_values
        with _alpaca_public_durable_diagnostic_scope(cfg, boundary_sensitive_values):
            try:
                result = _submit_alpaca_paper_buy_orders_public_impl(
                    buy_signals,
                    cfg,
                    conn,
                    boundary_sensitive_values=boundary_sensitive_values,
                )
            finally:
                publication_sensitive_values = _merged_alpaca_sensitive_values(
                    boundary_sensitive_values,
                    _ALPACA_PUBLIC_DURABLE_SENSITIVE_VALUES.get() or (),
                    _alpaca_scoped_sensitive_values(),
                    _alpaca_config_sensitive_values(cfg),
                )
    except BaseException as exc:
        if not isinstance(exc, Exception) and not publication_sensitive_values:
            raise
        original_failure = exc
        public_failure = _alpaca_public_exception(
            exc,
            cfg=cfg,
            sensitive_values=publication_sensitive_values,
        )
    else:
        return _alpaca_public_result(
            result,
            cfg=cfg,
            sensitive_values=publication_sensitive_values,
        )

    assert public_failure is not None
    if public_failure is original_failure:
        raise public_failure
    public_cause = _alpaca_public_exception_cause(
        original_failure,
        cfg=cfg,
        sensitive_values=publication_sensitive_values,
    )
    raise public_failure from public_cause


def _submit_alpaca_paper_sell_orders_impl(
    sell_signals: pd.DataFrame,
    cfg: AlpacaOrderConfig,
) -> pd.DataFrame:
    columns = [
        "Asset",
        "Date",
        "Client Order ID",
        "Qty",
        "Status",
        "Alpaca Order ID",
        "Message",
    ]
    if not cfg.sell_enabled:
        return pd.DataFrame(columns=columns)
    if sell_signals.empty:
        return pd.DataFrame(columns=columns)

    rows = []
    for signal in sell_signals.itertuples(index=False):
        symbol = str(signal.Asset)
        signal_date = str(signal.Date)
        client_order_id = _alpaca_client_order_id("sell", symbol, signal_date)
        _append_result(
            rows,
            symbol=symbol,
            signal_date=signal_date,
            client_order_id=client_order_id,
            amount_key="Qty",
            amount=None,
            status="managed_only",
            alpaca_order_id=None,
            message=("direct sell-signal submissions are disabled; managed reconciliation handles GTC limit sells"),
        )

    return pd.DataFrame(rows, columns=columns)


def submit_alpaca_paper_sell_orders(
    sell_signals: pd.DataFrame,
    cfg: AlpacaOrderConfig,
) -> pd.DataFrame:
    """Publish credential-safe direct-sell diagnostics."""
    boundary_sensitive_values: tuple[str, ...] = ()
    publication_sensitive_values: tuple[str, ...] = ()
    public_failure: BaseException | None = None
    try:
        boundary_sensitive_values = _alpaca_config_sensitive_values(cfg)
        publication_sensitive_values = boundary_sensitive_values
        with _alpaca_public_durable_diagnostic_scope(cfg, boundary_sensitive_values):
            try:
                result = _submit_alpaca_paper_sell_orders_impl(sell_signals, cfg)
            finally:
                publication_sensitive_values = _merged_alpaca_sensitive_values(
                    boundary_sensitive_values,
                    _ALPACA_PUBLIC_DURABLE_SENSITIVE_VALUES.get() or (),
                    _alpaca_scoped_sensitive_values(),
                    _alpaca_config_sensitive_values(cfg),
                )
    except BaseException as exc:
        if not isinstance(exc, Exception) and not publication_sensitive_values:
            raise
        public_failure = _alpaca_public_exception(
            exc,
            cfg=cfg,
            sensitive_values=publication_sensitive_values,
        )
    else:
        return _alpaca_public_result(
            result,
            cfg=cfg,
            sensitive_values=publication_sensitive_values,
        )

    assert public_failure is not None
    raise public_failure
